const printStation = window.printStation;

// Track intentionally open modals to prevent auto-cleanup from closing them
// Declared early so showPrompt() can use it
const intentionallyOpenModals = new Set();

(() => {
  const MAX_LIBRARY_IMG_RETRIES = 3;
  const PARAM_KEY = 'libraryRetry';
  const isLibraryAsset = (value) => typeof value === 'string' && value.includes('/api/library/');
  const withRetryToken = (value, attempt) => {
    if (!value) return value;
    const sep = value.includes('?') ? '&' : '?';
    return `${value}${sep}${PARAM_KEY}=${Date.now()}-${attempt}`;
  };
  window.addEventListener('error', (event) => {
    const target = event.target;
    if (!(target && target.tagName && target.tagName.toUpperCase() === 'IMG')) return;
    const src = target.dataset.libraryRetryBase || target.currentSrc || target.src || '';
    if (!isLibraryAsset(src)) return;
    const attempts = Number(target.dataset.libraryRetryAttempts || 0);
    if (attempts >= MAX_LIBRARY_IMG_RETRIES) return;
    event.preventDefault();
    target.dataset.libraryRetryBase = src;
    target.dataset.libraryRetryAttempts = String(attempts + 1);
    setTimeout(() => {
      target.src = withRetryToken(src, attempts + 1);
    }, 100 * (attempts + 1));
  }, true);
  window.addEventListener('load', (event) => {
    const target = event.target;
    if (!(target && target.tagName && target.tagName.toUpperCase() === 'IMG')) return;
    const base = target.dataset.libraryRetryBase || '';
    if (!isLibraryAsset(base)) return;
    delete target.dataset.libraryRetryBase;
    delete target.dataset.libraryRetryAttempts;
  }, true);
})();

/**
 * Custom prompt dialog (replacement for native prompt() which doesn't work in Electron)
 * @param {string} message - The prompt message/title
 * @param {string} defaultValue - Optional default value
 * @returns {Promise<string|null>} - The entered value or null if cancelled
 */
function showPrompt(message, defaultValue = '') {
  console.log('[showPrompt] Called with message:', message);
  return new Promise((resolve) => {
    const modal = document.getElementById('customPromptModal');
    const title = document.getElementById('customPromptTitle');
    const input = document.getElementById('customPromptInput');
    const okBtn = document.getElementById('customPromptOk');
    const cancelBtn = document.getElementById('customPromptCancel');

    console.log('[showPrompt] Modal element:', modal);
    console.log('[showPrompt] Modal current display:', modal?.style?.display);

    if (!modal || !input || !okBtn || !cancelBtn) {
      console.error('Custom prompt modal elements not found', { modal, input, okBtn, cancelBtn });
      resolve(null);
      return;
    }

    // Mark as intentionally open to prevent auto-cleanup from closing it
    intentionallyOpenModals.add('customPromptModal');

    title.textContent = message;
    input.value = defaultValue;
    modal.style.display = 'flex';
    modal.style.pointerEvents = 'auto';
    modal.style.visibility = 'visible';
    modal.removeAttribute('hidden');
    console.log('[showPrompt] Modal display set to flex, now:', modal.style.display);
    input.focus();
    input.select();

    const cleanup = () => {
      modal.style.display = 'none';
      modal.style.pointerEvents = 'none';
      intentionallyOpenModals.delete('customPromptModal');
      okBtn.removeEventListener('click', handleOk);
      cancelBtn.removeEventListener('click', handleCancel);
      input.removeEventListener('keydown', handleKeydown);
    };

    const handleOk = () => {
      cleanup();
      resolve(input.value);
    };

    const handleCancel = () => {
      cleanup();
      resolve(null);
    };

    const handleKeydown = (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleOk();
      } else if (e.key === 'Escape') {
        e.preventDefault();
        handleCancel();
      }
    };

    okBtn.addEventListener('click', handleOk);
    cancelBtn.addEventListener('click', handleCancel);
    input.addEventListener('keydown', handleKeydown);
  });
}

/**
 * Native confirm dialog using Electron's showMessageBox.
 * This avoids focus issues that occur with window.confirm() in Electron.
 * @param {string} message - The confirmation message
 * @param {string} [title] - Optional dialog title
 * @returns {Promise<boolean>} - true if confirmed, false if cancelled
 */
async function nativeConfirm(message, title) {
  try {
    return await printStation.showConfirm(message, title || 'Confirm');
  } catch (e) {
    // Fallback to window.confirm if native fails
    console.warn('Native confirm failed, falling back to window.confirm:', e);
    return window.confirm(message);
  }
}

/**
 * Clean AI-generated filenames by removing common prefixes and UUID suffixes.
 * Example: "Lucid Origin a cinematic photo of 2008 Subaru Impreza WRX STI 3 74ee28cc 669d 470d ba39 2e97d6052182"
 * becomes: "2008 Subaru Impreza WRX STI"
 * @param {string} name - The AI-generated filename
 * @returns {string} - Cleaned name
 */
function cleanAiGeneratedName(name) {
  if (!name || typeof name !== 'string') return name;

  let cleaned = name;

  // Remove file extension first if present
  cleaned = cleaned.replace(/\.(png|jpg|jpeg|webp|gif|svg)$/i, '');

  // Remove common AI generation prefixes (case-insensitive)
  const prefixPatterns = [
    /^Lucid\s+Origin\s*/i,
    /^a\s+cinematic\s+photo\s+of\s*/i,
    /^a\s+photo\s+of\s*/i,
    /^a\s+realistic\s+photo\s+of\s*/i,
    /^an?\s+image\s+of\s*/i,
    /^photo\s+of\s*/i,
    /^cinematic\s+shot\s+of\s*/i,
    /^professional\s+photo\s+of\s*/i,
  ];

  for (const pattern of prefixPatterns) {
    cleaned = cleaned.replace(pattern, '');
  }

  // Remove AI platform identifiers and their trailing IDs
  // Leonardo: "Leonardo_Phoenix_description_0" or "image_leonardo_v1_xl_20231215_123456"
  cleaned = cleaned.replace(/^Leonardo[_\s]*(Phoenix|Kino|Lightning|Vision)?[_\s]*/i, '');
  cleaned = cleaned.replace(/^image[_\s]*leonardo[_\s]*v\d+[_\s]*/i, '');

  // Midjourney: Often has "_1234567890" or " 1234567890" at end
  // Ideogram: "ideogram_abc123def456" or alphanumeric IDs
  cleaned = cleaned.replace(/^ideogram[_\s]*/i, '');

  // Remove trailing UUID pattern (8-4-4-4-12 hex format with or without dashes, with spaces)
  // Pattern: optional number, then UUID parts like "74ee28cc 669d 470d ba39 2e97d6052182" or "74ee28cc-669d-470d-ba39-2e97d6052182"
  cleaned = cleaned.replace(/[_\s]+\d*\s*[a-f0-9]{8}[\s_-][a-f0-9]{4}[\s_-][a-f0-9]{4}[\s_-][a-f0-9]{4}[\s_-][a-f0-9]{12}\s*$/i, '');

  // Also handle compact UUID without separators (32 hex chars at end)
  cleaned = cleaned.replace(/[_\s]+\d*\s*[a-f0-9]{32}\s*$/i, '');

  // Remove trailing alphanumeric IDs common in AI outputs (8+ chars hex/alphanumeric)
  // E.g., "_abc123de" or "_12ab34cd56ef"
  cleaned = cleaned.replace(/[_\s]+[a-f0-9]{8,}\s*$/i, '');

  // Remove trailing timestamps (like _20231215_123456 or _1702658400)
  cleaned = cleaned.replace(/[_\s]+\d{8,14}\s*$/i, '');
  cleaned = cleaned.replace(/[_\s]+\d{10}\s*$/i, ''); // Unix timestamp

  // Remove trailing sequence numbers with underscores (like _0, _1, _001)
  cleaned = cleaned.replace(/[_\s]+\d{1,4}\s*$/, '');

  // Remove trailing numbers that might be sequence numbers (like " 3" at end)
  cleaned = cleaned.replace(/\s+\d+\s*$/, '');

  // Replace underscores with spaces for readability
  cleaned = cleaned.replace(/_/g, ' ');

  // Clean up multiple spaces
  cleaned = cleaned.replace(/\s+/g, ' ');

  // Capitalize first letter of each word
  cleaned = cleaned.split(' ').map(word =>
    word.charAt(0).toUpperCase() + word.slice(1).toLowerCase()
  ).join(' ');

  return cleaned.trim();
}

