function showToast(message, variant = 'info', timeout = 4000) {
  const toast = document.createElement('div');
  toast.className = `toast toast-${variant}`;
  toast.textContent = message;
  elements.toastContainer.appendChild(toast);
  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateY(10px)';
    setTimeout(() => {
      toast.remove();
    }, 300);
  }, timeout);
}

function setConnectionStatus(connected, message) {
  elements.connectionStatus.textContent = message;
  elements.connectionStatus.classList.toggle('connected', connected);
}

// ============== Navigation Dropdown Helpers ==============
function closeAllDropdowns() {
  document.querySelectorAll('.nav-dropdown.open').forEach((dropdown) => {
    dropdown.classList.remove('open');
  });
}

function toggleDropdown(dropdown) {
  const isOpen = dropdown.classList.contains('open');
  closeAllDropdowns();
  if (!isOpen) {
    dropdown.classList.add('open');
  }
}

function initNavDropdowns() {
  // Handle dropdown toggle clicks
  document.querySelectorAll('.dropdown-toggle').forEach((toggle) => {
    toggle.addEventListener('click', (e) => {
      e.stopPropagation();
      const dropdown = toggle.closest('.nav-dropdown');
      if (dropdown) {
        toggleDropdown(dropdown);
      }
    });
  });

  // Handle dropdown item clicks
  document.querySelectorAll('.dropdown-item').forEach((item) => {
    item.addEventListener('click', (e) => {
      e.stopPropagation();
      const viewId = item.dataset.view;
      if (viewId) {
        switchView(viewId);
      }
    });
  });

  // Close dropdowns when clicking outside
  document.addEventListener('click', (e) => {
    if (!e.target.closest('.nav-dropdown')) {
      closeAllDropdowns();
    }
  });

  // Close dropdowns on Escape key
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      closeAllDropdowns();
    }
  });

  // Mark initial active state for dropdown parent toggles
  const activeView = document.querySelector('.view.active');
  if (activeView) {
    const activeViewId = activeView.id;
    document.querySelectorAll('.nav-dropdown').forEach((dropdown) => {
      const toggle = dropdown.querySelector('.dropdown-toggle');
      const hasActiveItem = dropdown.querySelector(`.dropdown-item[data-view="${activeViewId}"]`);
      if (toggle && hasActiveItem) {
        toggle.classList.add('has-active');
        hasActiveItem.classList.add('active');
      }
    });
  }
}

window.switchView = switchView;
// Expose for campaign-view.js
window.state = state;
window.showToast = showToast;
window.openSsawVisual = openSsawVisual;
window.openInventoryApparelModal = openInventoryApparelModal;
window.handleCampaignSaveSilently = handleCampaignSaveSilently;
function switchView(viewId) {
  // Force close any blocking modals when switching views
  try { forceCloseAllBlockingModals(); } catch (_) {}

  // Memory cleanup when leaving certain views
  const previousView = document.querySelector('.view.active')?.id;
  if (previousView && previousView !== viewId) {
    // Clear preview cache when leaving catalog-heavy views to free memory
    if (['catalogView', 'customArtView', 'fbScheduleManagerView'].includes(previousView)) {
      clearPreviewCache();
    }
    // Stop camera preview when leaving inventory input
    if (previousView === 'inventoryInputView' && typeof window.cleanupInventoryInputView === 'function') {
      window.cleanupInventoryInputView();
    }
  }

  elements.views.forEach((view) => {
    view.classList.toggle('active', view.id === viewId);
  });

  // Handle standalone tab buttons
  elements.tabButtons.forEach((button) => {
    // Only mark active if it's a direct view button (not a dropdown toggle)
    if (button.dataset.view) {
      button.classList.toggle('active', button.dataset.view === viewId);
    }
  });

  // Handle dropdown items and parent toggles
  document.querySelectorAll('.dropdown-item').forEach((item) => {
    item.classList.toggle('active', item.dataset.view === viewId);
  });

  // Mark dropdown toggles as "has-active" if one of their items is active
  document.querySelectorAll('.nav-dropdown').forEach((dropdown) => {
    const toggle = dropdown.querySelector('.dropdown-toggle');
    const hasActiveItem = dropdown.querySelector('.dropdown-item.active');
    if (toggle) {
      toggle.classList.toggle('has-active', !!hasActiveItem);
    }
  });

  // Close any open dropdowns
  closeAllDropdowns();
  if (viewId === 'quotesView' && !state.quotesLoading && !state.quotes.length) {
    refreshQuotes({ silent: true });
  }
  if (viewId === 'inventoryView' && !state.inventoryInitialized && !state.inventoryLoading) {
    loadInventory(state.inventoryMaterial);
  }
  if (viewId === 'inventoryView') {
    try {
      const frontThumb = elements.inventoryApparelImageFrontThumb;
      const frontInput = elements.inventoryApparelImageFrontInput;
      if (frontThumb && frontInput) {
        const url = frontInput.value.trim();
        frontThumb.src = url || '';
        frontThumb.style.display = url ? '' : 'none';
      }
      const backThumb = elements.inventoryApparelImageBackThumb;
      const backInput = elements.inventoryApparelImageBackInput;
      if (backThumb && backInput) {
        const url = backInput.value.trim();
        backThumb.src = url || '';
        backThumb.style.display = url ? '' : 'none';
      }
    } catch (_) {}
  }
  if (viewId === 'mockupsView') {
    ensureMockupsLoaded();
  }
  if (viewId === 'apparelMockupView') {
    if (typeof window.initApparelMockupView === 'function') {
      window.initApparelMockupView();
    }
  }
  if (viewId === 'campaignsView') {
    if (typeof window.initCampaignView === 'function') window.initCampaignView();
    renderCampaignItems();
    refreshCampaignList();
    try { marketingLoadTemplates(); } catch (_) {}
    try { loadPricingUI({ silent: true }); } catch (_) {}
    try {
      if (elements.campaignCreateButton && elements.campaignSaveButton) {
        const hasSlug = Boolean(state.campaign?.slug);
        elements.campaignCreateButton.style.display = hasSlug ? 'none' : '';
        elements.campaignSaveButton.style.display = hasSlug ? '' : 'none';
      }
      // Show delete button only when a campaign is loaded
      if (elements.campaignDeleteButton) {
        elements.campaignDeleteButton.style.display = state.campaign?.slug ? '' : 'none';
      }
    } catch (_) {}
  }
  if (viewId === 'mockupBackgroundsView') {
    initMockupBackgroundsView();
  }
  if (viewId === 'adminView') {
    try { elements.inboundRefreshButton?.click(); } catch (_) {}
    try { marketingLoadTemplates(); } catch (_) {}
    try { refreshAdsPerformance(); } catch (_) {}
    try { loadShopifyTestCarts(); } catch (_) {}
  }
  if (viewId === 'localCatalogView') {
    loadLocalItems();
    populateLocalCategoriesOptions();
    populateLocalFilterCategories();
  }
  if (viewId === 'socialMarketingView') {
    // Load campaigns for the dropdown (only if not already loaded)
    if (!state.socialMarketing.campaigns || state.socialMarketing.campaigns.length === 0) {
      loadSocialMarketingCampaigns();
    }
  }
  if (viewId === 'tiktokPostView') {
    // Initialize TikTok view - check connection status
    initTikTokView();
  }
  if (viewId === 'tiktokMarketingView') {
    if (typeof window.initTiktokMarketingView === 'function') window.initTiktokMarketingView();
  }
  if (viewId === 'reelStudioView') {
    try { initReelStudioView(); } catch (err) { console.error('[reelStudio]', err); }
  }
  if (viewId === 'inventoryInputView') {
    if (typeof window.initInventoryInputView === 'function') window.initInventoryInputView();
  }
  if (viewId === 'printerView') {
    // Initialize Printer view - load printers
    initPrinterView();
  }
  if (viewId === 'fbScheduleManagerView') {
    // Load campaigns and templates for schedule manager
    loadFbScheduleCampaigns();
    loadFbScheduleTemplates();
    loadScheduledPosts();
  }
  if (viewId === 'customArtView') {
    console.log('[Custom Art] View opened');
    // Initialize Custom Art elements (get fresh DOM references)
    initCustomArtElements();
    console.log('[Custom Art] Elements initialized:', Object.keys(customArtElements).filter(k => customArtElements[k] !== null).length, 'of', Object.keys(customArtElements).length);
    // Initialize Custom Art event listeners (only runs once)
    initCustomArtEventListeners();
    // Initialize Saved Mockups event listeners
    initSavedMockupsEventListeners();

    // Use event delegation for sub-tab clicks
    const toolbar = document.querySelector('#customArtView .view-toolbar');
    if (toolbar && !toolbar.dataset.delegated) {
      toolbar.dataset.delegated = 'true';
      toolbar.addEventListener('click', (e) => {
        const btn = e.target.closest('[data-subtab]');
        if (btn) {
          e.preventDefault();
          e.stopPropagation();
          console.log('[Custom Art] Tab clicked via delegation:', btn.dataset.subtab);
          switchCustomArtSubtab(btn.dataset.subtab);
        }
      });
    }

    // Load data for current subtab
    switchCustomArtSubtab(customArtState.currentSubtab || 'rooms');
  }

  // Leonardo AI Generator view
  if (viewId === 'leonardoView') {
    initLeonardoView();
  }

  // Human Models view
  if (viewId === 'humanModelsView') {
    initHumanModelsView();
  }

  // Model Groups view
  if (viewId === 'modelGroupsView') {
    if (typeof window.initModelGroupsView === 'function') window.initModelGroupsView();
  }

  // Room Groups view
  if (viewId === 'roomGroupsView') {
    if (typeof window.initRoomGroupsView === 'function') window.initRoomGroupsView();
  }

  // Sticker Sheets view
  if (viewId === 'stickerSheetsView') {
    initStickerSheetsView();
  }

  // Dashboard view
  if (viewId === 'dashboardView') {
    loadDashboardData();
    startTaskMonitor(); // Start task monitor auto-refresh
  } else {
    stopTaskMonitor(); // Stop when leaving dashboard
  }

  // Shopify Manager view
  if (viewId === 'shopifyManagerView') {
    initShopifyManager();
  }

  // TikTok Shop Manager view
  if (viewId === 'tiktokShopView') {
    initTikTokShopManager();
  }

  // AI Sales Agent view
  if (viewId === 'aiAgentView') {
    loadAiAgentDashboard();
  }

  // Trend Monitor view
  if (viewId === 'trendMonitorView') {
    if (typeof window.initTrendMonitorView === 'function') window.initTrendMonitorView();
  }

  // Footage Library view
  if (viewId === 'footageLibraryView') {
    if (typeof window.initFootageLibraryView === 'function') window.initFootageLibraryView();
  }

  // External view files (loaded as regular scripts, accessed via window)
  if (viewId === 'slicerView') {
    if (typeof window.initSlicerView === 'function') window.initSlicerView();
  }
  if (viewId === 'multiboardDesignerView') {
    if (typeof window.initMultiboardDesignerView === 'function') window.initMultiboardDesignerView();
  }
  if (viewId === 'multiboardPartsBrowserView') {
    if (typeof window.initMultiboardPartsBrowserView === 'function') window.initMultiboardPartsBrowserView();
  }
  if (viewId === 'printerFleetView') {
    if (typeof window.initPrinterFleetView === 'function') window.initPrinterFleetView();
  }
  if (viewId === 'inkjetFleetView') {
    if (typeof window.initInkjetFleetView === 'function') window.initInkjetFleetView();
  }
  if (viewId === 'skuCatalogView') {
    if (typeof window.initSkuCatalogView === 'function') window.initSkuCatalogView();
  }
  if (viewId === 'qrScannerView') {
    if (typeof window.initQrScannerView === 'function') window.initQrScannerView();
  }
  if (viewId === 'productCatalogView') {
    if (typeof window.initProductCatalogView === 'function') window.initProductCatalogView();
  }
  if (viewId === 'b2bManagementView') {
    if (typeof window.initB2BManagementView === 'function') window.initB2BManagementView();
  }
  if (viewId === 'stickersView') {
    if (typeof window.initStickersView === 'function') window.initStickersView();
  }
  if (viewId === 'etsyListingsView') {
    if (typeof window.initEtsyListingsView === 'function') window.initEtsyListingsView();
  }
  if (viewId === 'dogTagsView') {
    if (typeof window.initDogTagsView === 'function') window.initDogTagsView();
  }
}

// =============== Dashboard ===============
const dashboardState = {
  loading: false,
  lastUpdated: null,
  salesPeriod: 'week',
  socialPeriod: '7d'
};

// Task Monitor State
const taskMonitorState = {
  refreshInterval: null,
  active: []
};

/**
 * Load and display task status from the server
 */
async function loadTaskStatus() {
  try {
    const serverUrl = window.APP_CONFIG?.serverUrl || 'https://store.swayzecustomvinyl.com';
    const response = await fetch(`${serverUrl}/api/tasks/status`, {
      headers: { 'x-api-key': window.APP_CONFIG?.internalKey || '' }
    });

    if (!response.ok) throw new Error('Failed to fetch task status');

    const data = await response.json();
    if (data.success) {
      updateTasksDisplay(data);
    }
  } catch (err) {
    console.error('[TaskMonitor] Error loading tasks:', err);
  }
}

/**
 * Update the tasks display in the dashboard
 */
function updateTasksDisplay(data) {
  const container = document.getElementById('runningTasksContainer');
  const badge = document.getElementById('tasksStatusBadge');

  if (!container) return;

  taskMonitorState.active = data.active || [];

  // Update badge
  if (badge) {
    const count = data.activeCount || 0;
    badge.textContent = count > 0 ? count : '-';
    badge.className = `dashboard-status ${count > 0 ? 'active' : ''}`;
    badge.title = count > 0 ? `${count} task(s) running` : 'No active tasks';
  }

  // Build tasks HTML
  if (data.active && data.active.length > 0) {
    container.innerHTML = data.active.map(task => {
      const progressBar = task.progress > 0
        ? `<div class="task-progress-bar">
             <div class="task-progress-fill" style="width: ${task.progress}%"></div>
           </div>`
        : '';

      return `
        <div class="task-item ${task.state}">
          <div class="task-header">
            <span class="task-type">${formatTaskType(task.type)}</span>
            <span class="task-elapsed">${task.elapsed || '--'}</span>
          </div>
          <div class="task-description">${escapeHtml(task.description)}</div>
          <div class="task-status">
            <span class="task-progress-text">${task.current}/${task.total} (${task.progress}%)</span>
            ${task.estimatedRemaining ? `<span class="task-eta">ETA: ${task.estimatedRemaining}</span>` : ''}
          </div>
          ${progressBar}
          ${task.currentItem ? `<div class="task-current-item">${escapeHtml(task.currentItem)}</div>` : ''}
        </div>
      `;
    }).join('');
  } else if (data.recentCompleted && data.recentCompleted.length > 0) {
    // Show recently completed tasks if no active tasks
    const recent = data.recentCompleted.slice(0, 3);
    container.innerHTML = `
      <div class="tasks-empty">No active tasks</div>
      <div class="tasks-recent-header">Recent:</div>
      ${recent.map(task => `
        <div class="task-item completed">
          <div class="task-header">
            <span class="task-type">${formatTaskType(task.type)}</span>
            <span class="task-state ${task.state}">${task.state}</span>
          </div>
          <div class="task-description">${escapeHtml(task.description)}</div>
        </div>
      `).join('')}
    `;
  } else {
    container.innerHTML = '<div class="tasks-empty">No active tasks</div>';
  }
}

/**
 * Format task type for display
 */
function formatTaskType(type) {
  const typeMap = {
    'sticker-sheets': 'Sticker Sheets',
    'mask-generation': 'Mask Generation',
    'shopify-sync': 'Shopify Sync',
    'image-processing': 'Image Processing',
    'bulk-upload': 'Bulk Upload',
    'collection-sync': 'Collection Sync'
  };
  return typeMap[type] || type;
}

/**
 * Start the task monitor auto-refresh (15 seconds)
 */
function startTaskMonitor() {
  // Load immediately
  loadTaskStatus();

  // Clear any existing interval
  if (taskMonitorState.refreshInterval) {
    clearInterval(taskMonitorState.refreshInterval);
  }

  // Refresh every 15 seconds
  taskMonitorState.refreshInterval = setInterval(loadTaskStatus, 15000);
}

/**
 * Stop the task monitor
 */
function stopTaskMonitor() {
  if (taskMonitorState.refreshInterval) {
    clearInterval(taskMonitorState.refreshInterval);
    taskMonitorState.refreshInterval = null;
  }
}

async function loadDashboardData() {
  if (dashboardState.loading) return;
  dashboardState.loading = true;

  try {
    // Load all dashboard data in parallel
    const [statsResult, serverResult, socialResult] = await Promise.all([
      printStation.dashboard.getStats(dashboardState.salesPeriod).catch(e => ({ error: e.message })),
      printStation.dashboard.getServerStats().catch(e => ({ error: e.message })),
      printStation.dashboard.getSocialStats(dashboardState.socialPeriod).catch(e => ({ error: e.message }))
    ]);

    // Update server health
    if (serverResult && !serverResult.error) {
      updateServerHealth(serverResult);
    }

    // Update stats
    if (statsResult && !statsResult.error) {
      updateCatalogStats(statsResult.catalog);
      updateOrdersStats(statsResult.orders);
      updateSalesStats(statsResult.sales);
      updateInventoryStats(statsResult.inventory);
    }

    // Update social stats
    if (socialResult && !socialResult.error) {
      updateSocialStats(socialResult);
    }

    // Update last updated time
    dashboardState.lastUpdated = new Date();
    const lastUpdatedEl = document.getElementById('dashboardLastUpdated');
    if (lastUpdatedEl) {
      lastUpdatedEl.textContent = `Last updated: ${dashboardState.lastUpdated.toLocaleTimeString()}`;
    }

  } catch (e) {
    console.error('[Dashboard] Error loading data:', e);
  } finally {
    dashboardState.loading = false;
  }
}

function updateServerHealth(data) {
  const statusBadge = document.getElementById('serverStatusBadge');
  const cpuBar = document.getElementById('serverCpuBar');
  const cpuValue = document.getElementById('serverCpuValue');
  const memoryBar = document.getElementById('serverMemoryBar');
  const memoryValue = document.getElementById('serverMemoryValue');
  const diskBar = document.getElementById('serverDiskBar');
  const diskValue = document.getElementById('serverDiskValue');
  const uptimeEl = document.getElementById('serverUptime');

  // Status badge
  if (statusBadge) {
    statusBadge.className = 'dashboard-status online';
    statusBadge.title = 'Server is online';
  }

  // CPU
  if (cpuBar && cpuValue && data.cpu) {
    const cpuPct = data.cpu.usagePercent || 0;
    cpuBar.style.width = `${cpuPct}%`;
    cpuBar.className = `progress-bar ${cpuPct > 80 ? 'danger' : cpuPct > 60 ? 'warning' : ''}`;
    cpuValue.textContent = `${cpuPct}%`;
  }

  // Memory
  if (memoryBar && memoryValue && data.memory) {
    const memPct = data.memory.usagePercent || 0;
    memoryBar.style.width = `${memPct}%`;
    memoryBar.className = `progress-bar ${memPct > 85 ? 'danger' : memPct > 70 ? 'warning' : ''}`;
    memoryValue.textContent = `${data.memory.usedGB || 0} / ${data.memory.totalGB || 0} GB`;
  }

  // Drives - render all drives dynamically
  const drivesContainer = document.getElementById('serverDrivesContainer');
  if (drivesContainer && data.drives && data.drives.length > 0) {
    drivesContainer.innerHTML = data.drives.map(drive => {
      const pct = drive.usagePercent || 0;
      const barClass = pct > 90 ? 'danger' : pct > 75 ? 'warning' : '';
      return `
        <div class="server-stat">
          <label>${escapeHtml(drive.name)} (${escapeHtml(drive.mountPoint)})</label>
          <div class="progress-bar-container">
            <div class="progress-bar ${barClass}" style="width:${pct}%"></div>
          </div>
          <span>${drive.usedGB || 0} / ${drive.totalGB || 0} GB</span>
        </div>
      `;
    }).join('');
  } else if (drivesContainer && data.disk) {
    // Fallback to single disk if drives array not available
    const diskPct = data.disk.usagePercent || 0;
    const barClass = diskPct > 90 ? 'danger' : diskPct > 75 ? 'warning' : '';
    drivesContainer.innerHTML = `
      <div class="server-stat">
        <label>Disk Space</label>
        <div class="progress-bar-container">
          <div class="progress-bar ${barClass}" style="width:${diskPct}%"></div>
        </div>
        <span>${data.disk.usedGB || 0} / ${data.disk.totalGB || 0} GB</span>
      </div>
    `;
  }

  // Uptime
  if (uptimeEl) {
    uptimeEl.textContent = data.uptime || '--';
  }
}

function updateCatalogStats(catalog) {
  if (!catalog) return;

  const setVal = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.textContent = val;
  };

  setVal('catalogTotalDesigns', catalog.totalDesigns || 0);
  setVal('catalogCategories', catalog.categories || 0);
  setVal('catalogLocalItems', catalog.localItems || 0);
  setVal('catalogActiveCampaigns', catalog.campaigns || 0);

  // Top categories
  const topCatsEl = document.getElementById('catalogTopCategories');
  if (topCatsEl && catalog.topCategories?.length) {
    topCatsEl.innerHTML = `
      <h4>Top Categories</h4>
      <ul>
        ${catalog.topCategories.map(c => `
          <li>
            <span class="item-name">${escapeHtml(c.name)}</span>
            <span class="item-value">${c.count} designs</span>
          </li>
        `).join('')}
      </ul>
    `;
  } else if (topCatsEl) {
    topCatsEl.innerHTML = '<h4>Top Categories</h4><div class="placeholder">No categories found</div>';
  }
}

function updateOrdersStats(orders) {
  if (!orders) return;

  const setVal = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.textContent = val;
  };

  setVal('ordersPending', orders.pending || 0);
  setVal('ordersProcessing', orders.processing || 0);
  setVal('ordersCompleted', orders.completed || 0);
  setVal('ordersTotal', orders.total || 0);

  // Recent orders
  const recentEl = document.getElementById('ordersRecent');
  if (recentEl && orders.recentOrders?.length) {
    recentEl.innerHTML = `
      <h4>Recent Orders</h4>
      <ul>
        ${orders.recentOrders.map(o => `
          <li>
            <span class="item-name">#${o.id} - ${escapeHtml(o.design || 'Unknown')}</span>
            <span class="item-badge ${o.status === 'completed' ? 'success' : o.status === 'pending' ? 'warning' : ''}">${o.status || 'new'}</span>
          </li>
        `).join('')}
      </ul>
    `;
  } else if (recentEl) {
    recentEl.innerHTML = '<h4>Recent Orders</h4><div class="placeholder">No recent orders</div>';
  }
}

function updateSalesStats(sales) {
  if (!sales) return;

  const setVal = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.textContent = val;
  };

  setVal('salesTotalRevenue', `$${(sales.revenue || 0).toFixed(2)}`);
  setVal('salesOrderCount', sales.orderCount || 0);
  setVal('salesAvgOrder', `$${(sales.avgOrder || 0).toFixed(2)}`);
  setVal('salesItemsSold', sales.itemsSold || 0);

  // Top products
  const topEl = document.getElementById('salesTopProducts');
  if (topEl && sales.topProducts?.length) {
    topEl.innerHTML = `
      <h4>Top Selling Products</h4>
      <ul>
        ${sales.topProducts.map(p => `
          <li>
            <span class="item-name">${escapeHtml(p.name)}</span>
            <span class="item-value">${p.sold} sold</span>
          </li>
        `).join('')}
      </ul>
    `;
  } else if (topEl) {
    topEl.innerHTML = '<h4>Top Selling Products</h4><div class="placeholder">No sales data</div>';
  }
}

function updateInventoryStats(inventory) {
  if (!inventory) return;

  const setVal = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.textContent = val;
  };

  setVal('inventoryTotalItems', inventory.totalItems || 0);
  setVal('inventoryLowStock', inventory.lowStock || 0);
  setVal('inventoryOutOfStock', inventory.outOfStock || 0);
  setVal('inventoryTotalValue', `$${(inventory.totalValue || 0).toFixed(2)}`);

  // Stock alerts
  const alertsEl = document.getElementById('inventoryAlerts');
  if (alertsEl && inventory.alerts?.length) {
    alertsEl.innerHTML = `
      <h4>Stock Alerts</h4>
      <ul>
        ${inventory.alerts.map(a => `
          <li>
            <span class="item-name">${escapeHtml(a.name)}</span>
            <span class="item-badge ${a.status === 'out' ? 'danger' : 'warning'}">${a.status === 'out' ? 'Out of Stock' : `${a.quantity} left`}</span>
          </li>
        `).join('')}
      </ul>
    `;
  } else if (alertsEl) {
    alertsEl.innerHTML = '<h4>Stock Alerts</h4><div class="placeholder">No alerts</div>';
  }
}

function updateSocialStats(social) {
  if (!social) return;

  const setVal = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.textContent = val;
  };

  setVal('socialPageViews', formatNumber(social.pageViews || 0));
  setVal('socialVisitors', formatNumber(social.visitors || 0));
  setVal('socialAddToCart', formatNumber(social.addToCart || 0));
  setVal('socialConversions', formatNumber(social.conversions || 0));
  setVal('socialAdSpend', `$${(social.adSpend || 0).toFixed(2)}`);
  setVal('socialRoas', `${(social.roas || 0).toFixed(1)}x`);
  setVal('socialCpc', `$${(social.cpc || 0).toFixed(2)}`);
  setVal('socialCtr', `${(social.ctr || 0).toFixed(1)}%`);
}

function formatNumber(num) {
  if (num >= 1000000) return (num / 1000000).toFixed(1) + 'M';
  if (num >= 1000) return (num / 1000).toFixed(1) + 'K';
  return String(num);
}

function initDashboardEventListeners() {
  // Refresh button
  const refreshBtn = document.getElementById('dashboardRefreshBtn');
  if (refreshBtn) {
    refreshBtn.addEventListener('click', loadDashboardData);
  }

  // Sales period selector
  const salesPeriod = document.getElementById('salesPeriodSelect');
  if (salesPeriod) {
    salesPeriod.addEventListener('change', () => {
      dashboardState.salesPeriod = salesPeriod.value;
      loadDashboardData();
    });
  }

  // Social period selector
  const socialPeriod = document.getElementById('socialPeriodSelect');
  if (socialPeriod) {
    socialPeriod.addEventListener('change', () => {
      dashboardState.socialPeriod = socialPeriod.value;
      loadDashboardData();
    });
  }
}

