// =============== Pricing sheet UI ===============
async function loadPricingUI({ silent } = {}) {
  if (!elements.pricingTextarea) return;
  try {
    if (!silent && elements.pricingStatus) { elements.pricingStatus.textContent = 'Loading pricing…'; elements.pricingStatus.className = 'status-bar muted'; }
    const data = await printStation.getPricing();
    const pricing = data?.pricing || {};
    elements.pricingTextarea.value = JSON.stringify(pricing, null, 2);
    if (elements.pricingSource) elements.pricingSource.textContent = data?.source ? data.source.replace(/^.*\//, '') : '';
    if (elements.pricingStatus) { elements.pricingStatus.textContent = 'Pricing loaded'; elements.pricingStatus.className = 'status-bar success'; }
    state.pricingDraft = pricing;
    renderPricingTable(pricing);
  } catch (e) {
    if (elements.pricingStatus) { elements.pricingStatus.textContent = e?.message || 'Unable to load pricing'; elements.pricingStatus.className = 'status-bar error'; }
  }
}

// --- Admin: Shopify carts (test) ---
async function loadShopifyTestCarts() {
  const status = elements.shopifyCartsStatus;
  const tbody = elements.shopifyCartsTableBody;
  if (!tbody) return;
  try {
    if (status) { status.textContent = 'Loading…'; status.className = 'status-bar muted'; }
    tbody.innerHTML = '<tr><td colspan="5" class="placeholder">Loading…</td></tr>';
    const data = await printStation.listShopifyTestCarts();
    const items = Array.isArray(data?.items) ? data.items : [];
    if (!items.length) {
      tbody.innerHTML = '<tr><td colspan="5" class="placeholder">No events captured.</td></tr>';
      if (status) { status.textContent = 'No events.'; status.className = 'status-bar muted'; }
      return;
    }
    const rows = items
      .slice()
      .reverse()
      .map((e, idx) => {
        const when = escapeHtml(new Date(e.receivedAt || Date.now()).toLocaleString());
        const shop = escapeHtml(e?.meta?.shop || '');
        const tok = escapeHtml(String(e?.meta?.token || ''));
        const id = escapeHtml(String(e?.meta?.id || ''));
        return `<tr data-index="${idx}"><td>${when}</td><td>${shop}</td><td><code>${tok}</code></td><td>${id}</td><td><button type="button" class="secondary shopify-cart-view">View</button></td></tr>`;
      })
      .join('');
    tbody.innerHTML = rows;
    Array.from(tbody.querySelectorAll('.shopify-cart-view')).forEach((btn) => {
      btn.addEventListener('click', () => {
        const tr = btn.closest('tr');
        const revIndex = Number(tr?.dataset.index || 0);
        const list = Array.isArray(data?.items) ? data.items : [];
        const item = list.slice().reverse()[revIndex] || null;
        const modal = document.getElementById('jobDetailsModal');
        const body = document.getElementById('jobDetailsBody');
        if (body) body.textContent = item ? JSON.stringify(item, null, 2) : '—';
        if (modal) modal.removeAttribute('hidden');
      });
    });
    if (status) { status.textContent = `Loaded ${items.length} event(s).`; status.className = 'status-bar success'; }
  } catch (error) {
    if (tbody) tbody.innerHTML = `<tr><td colspan="5" class="placeholder error">${escapeHtml(error?.message || 'Unable to load')}</td></tr>`;
    if (status) { status.textContent = error?.message || 'Error'; status.className = 'status-bar error'; }
  }
}

function formatPricingUI() {
  if (!elements.pricingTextarea) return;
  try {
    const obj = JSON.parse(elements.pricingTextarea.value || '{}');
    elements.pricingTextarea.value = JSON.stringify(obj, null, 2);
    showToast('Formatted pricing JSON', 'success');
  } catch (e) {
    showToast('Invalid JSON: ' + (e?.message || ''), 'error');
  }
}

async function savePricingUI() {
  if (!elements.pricingTextarea) return;
  try {
    // Prefer collecting from table
    const obj = collectPricingFromTable();
    elements.pricingTextarea.value = JSON.stringify(obj, null, 2);
    await printStation.savePricing({ pricing: obj });
    if (elements.pricingStatus) { elements.pricingStatus.textContent = 'Saved'; elements.pricingStatus.className = 'status-bar success'; }
    showToast('Pricing saved', 'success');
  } catch (e) {
    if (elements.pricingStatus) { elements.pricingStatus.textContent = e?.message || 'Save failed'; elements.pricingStatus.className = 'status-bar error'; }
    showToast('Save failed: ' + (e?.message || ''), 'error');
  }
}

function normalizeTypeKey(value) {
  const v = String(value || '').trim().toLowerCase();
  if (!v) return '';
  if (v === 't-shirt' || v === 'tee' || v === 'shirt' || v === 'tee-shirt' || v === 'apparel') return 'tshirt';
  if (v === 'cap') return 'hat';
  return v.replace(/[^a-z0-9]+/g, '');
}

function toDollarString(cents) {
  const n = Number(cents);
  if (!Number.isFinite(n)) return '';
  return (n / 100).toFixed(2);
}

function toCents(value) {
  const n = Number(String(value || '').trim());
  if (!Number.isFinite(n)) return null;
  return Math.round(n * 100);
}

function renderPricingTable(pricing) {
  const tbody = elements.pricingTableBody;
  if (!tbody) return;
  const entries = Object.entries(pricing || {});
  if (!entries.length) {
    tbody.innerHTML = '<tr><td colspan="5" class="placeholder">No pricing yet.</td></tr>';
    return;
  }
  const rowHtml = entries.map(([type, cfg]) => {
    const basePrice = cfg?.base?.priceCents != null ? toDollarString(cfg.base.priceCents) : '';
    const baseMat = cfg?.base?.costMaterialCents != null ? toDollarString(cfg.base.costMaterialCents) : (cfg?.base?.costCents != null ? toDollarString(cfg.base.costCents) : '');
    const baseLab = cfg?.base?.costLaborCents != null ? toDollarString(cfg.base.costLaborCents) : '';
    const sizes = cfg?.sizes && typeof cfg.sizes === 'object' ? Object.entries(cfg.sizes) : [];
    const sizeRows = sizes.map(([size, scfg]) => {
      const sp = scfg?.priceCents != null ? toDollarString(scfg.priceCents) : '';
      const sm = scfg?.costMaterialCents != null ? toDollarString(scfg.costMaterialCents) : (scfg?.costCents != null ? toDollarString(scfg.costCents) : '');
      const sl = scfg?.costLaborCents != null ? toDollarString(scfg.costLaborCents) : '';
      return `<tr data-size-row="true"><td><input class="pricing-size-key" value="${escapeHtml(size)}" placeholder="e.g. L" /></td><td><input class="pricing-size-price" inputmode="decimal" value="${escapeHtml(sp)}" placeholder="25.00" /></td><td><input class="pricing-size-material" inputmode="decimal" value="${escapeHtml(sm)}" placeholder="6.00" /></td><td><input class="pricing-size-labor" inputmode="decimal" value="${escapeHtml(sl)}" placeholder="3.00" /></td><td><button type="button" class="secondary" data-action="del-size">Remove</button></td></tr>`;
    }).join('');
    const sizesTable = `
      <table class="inventory-table" style="margin:6px 0;">
        <thead><tr><th style="width:80px;">Size</th><th style="width:120px;">Price ($)</th><th style="width:120px;">Material ($)</th><th style="width:120px;">Labor ($)</th><th style="width:80px;"></th></tr></thead>
        <tbody>
          ${sizeRows || ''}
          <tr><td colspan="5"><button type="button" class="secondary" data-action="add-size">Add size</button></td></tr>
        </tbody>
      </table>`;
    return `
      <tr data-type-row="true">
        <td><input class="pricing-type" value="${escapeHtml(type)}" placeholder="tshirt" /></td>
        <td><input class="pricing-base-price" inputmode="decimal" value="${escapeHtml(basePrice)}" placeholder="25.00" /></td>
        <td><input class="pricing-base-material" inputmode="decimal" value="${escapeHtml(baseMat)}" placeholder="6.00" /></td>
        <td><input class="pricing-base-labor" inputmode="decimal" value="${escapeHtml(baseLab)}" placeholder="3.00" /></td>
        <td>${sizesTable}</td>
        <td><button type="button" class="secondary" data-action="del-type">Remove</button></td>
      </tr>`;
  }).join('');
  tbody.innerHTML = rowHtml;
}

function addEmptyTypeRow() {
  const tbody = elements.pricingTableBody;
  if (!tbody) return;
  if (tbody.querySelector('.placeholder')) tbody.innerHTML = '';
  const html = `
    <tr data-type-row="true">
      <td><input class="pricing-type" value="" placeholder="tshirt" /></td>
      <td><input class="pricing-base-price" inputmode="decimal" value="" placeholder="25.00" /></td>
      <td><input class="pricing-base-material" inputmode="decimal" value="" placeholder="6.00" /></td>
      <td><input class="pricing-base-labor" inputmode="decimal" value="" placeholder="3.00" /></td>
      <td>
        <table class="inventory-table" style="margin:6px 0;">
          <thead><tr><th style="width:80px;">Size</th><th style="width:120px;">Price ($)</th><th style="width:120px;">Material ($)</th><th style="width:120px;">Labor ($)</th><th style="width:80px;"></th></tr></thead>
          <tbody>
            <tr><td colspan="5"><button type="button" class="secondary" data-action="add-size">Add size</button></td></tr>
          </tbody>
        </table>
      </td>
      <td><button type="button" class="secondary" data-action="del-type">Remove</button></td>
    </tr>`;
  const temp = document.createElement('tbody');
  temp.innerHTML = html;
  tbody.appendChild(temp.firstElementChild);
}

function collectPricingFromTable() {
  const tbody = elements.pricingTableBody;
  const pricing = {};
  if (!tbody) return pricing;
  tbody.querySelectorAll('tr[data-type-row="true"]').forEach((tr) => {
    const typeRaw = tr.querySelector('.pricing-type')?.value || '';
    const type = normalizeTypeKey(typeRaw);
    if (!type) return;
    const basePrice = toCents(tr.querySelector('.pricing-base-price')?.value);
    const baseMat = toCents(tr.querySelector('.pricing-base-material')?.value);
    const baseLab = toCents(tr.querySelector('.pricing-base-labor')?.value);
    const cfg = {};
    if (basePrice != null || baseMat != null || baseLab != null) {
      cfg.base = {};
      if (basePrice != null) cfg.base.priceCents = basePrice;
      if (baseMat != null) cfg.base.costMaterialCents = baseMat;
      if (baseLab != null) cfg.base.costLaborCents = baseLab;
    }
    const sizes = {};
    tr.querySelectorAll('tbody tr[data-size-row="true"]').forEach((sr) => {
      const key = String(sr.querySelector('.pricing-size-key')?.value || '').trim().toUpperCase();
      if (!key) return;
      const sp = toCents(sr.querySelector('.pricing-size-price')?.value);
      const sm = toCents(sr.querySelector('.pricing-size-material')?.value);
      const sl = toCents(sr.querySelector('.pricing-size-labor')?.value);
      const sCfg = {};
      if (sp != null) sCfg.priceCents = sp;
      if (sm != null) sCfg.costMaterialCents = sm;
      if (sl != null) sCfg.costLaborCents = sl;
      if (Object.keys(sCfg).length) sizes[key] = sCfg;
    });
    if (Object.keys(sizes).length) cfg.sizes = sizes;
    if (Object.keys(cfg).length) pricing[type] = cfg; else pricing[type] = {};
  });
  state.pricingDraft = pricing;
  return pricing;
}



