function parseMarketingTagsLocal(raw) {
  try {
    const list = Array.isArray(raw)
      ? raw
      : typeof raw === 'string'
      ? raw.split(',').map((t) => t.trim()).filter(Boolean)
      : [];
    const profile = {};
    list.forEach((tag) => {
      if (!/^marketing:/i.test(tag)) return;
      const body = tag.replace(/^marketing:/i, '');
      const eq = body.indexOf('=');
      const keyRaw = eq >= 0 ? body.slice(0, eq).trim() : body.trim();
      const valRaw = eq >= 0 ? body.slice(eq + 1).trim() : '';
      const key = keyRaw.toLowerCase();
      const value = valRaw;
      const setStr = (k, v) => { if (v) profile[k] = v; };
      const setList = (k, v) => {
        const parts = String(v || '').split(/[|;,]+/).map((s) => s.trim()).filter(Boolean);
        if (parts.length) profile[k] = parts;
      };
      if (key === 'audience_segment') setStr('audience_segment', value);
      else if (key === 'tone') setStr('tone', value);
      else if (key === 'generation') setStr('generation', value);
      else if (key === 'template' || key === 'ad_template') setStr('ad_template', value);
      else if (key === 'audience_id' || key === 'ad_audience_id') setStr('ad_audience_id', value);
      else if (key === 'campaign_priority') { const n = Number(value); if (Number.isFinite(n)) profile.campaign_priority = Math.round(n); }
      else if (key === 'interests') setList('interests', value);
      else if (key === 'keywords') setList('keywords', value);
    });
    return profile;
  } catch { return {}; }
}

function marketingParseTagsIntoProfile() {
  if (!elements.marketingTagsInput || !elements.marketingProfileTextarea) return;
  try {
    const raw = elements.marketingTagsInput.value || '';
    const parsed = parseMarketingTagsLocal(raw);
    let current = {};
    try { current = JSON.parse(elements.marketingProfileTextarea.value || '{}'); } catch (_) {}
    // Tags provide defaults; existing JSON overrides if set
    const merged = { ...parsed, ...current };
    elements.marketingProfileTextarea.value = JSON.stringify(merged, null, 2);
    if (elements.marketingStatus) { elements.marketingStatus.textContent = 'Tags parsed into profile.'; elements.marketingStatus.className = 'status-bar success'; }
  } catch (e) {
    if (elements.marketingStatus) { elements.marketingStatus.textContent = e?.message || 'Unable to parse tags'; elements.marketingStatus.className = 'status-bar error'; }
  }
}

