function renderPerfCharts(byAudience) {
  const ctrCanvas = elements.adsPerfChartCtr;
  const cpaCanvas = elements.adsPerfChartCpa;
  if (!ctrCanvas || !cpaCanvas) return;
  const labels = Object.keys(byAudience || {});
  const ctrData = labels.map((k) => {
    const v = byAudience[k]?.avgCtr; return Number.isFinite(v) ? v : 0;
  });
  const cpaData = labels.map((k) => {
    const v = byAudience[k]?.avgCpaCents; return Number.isFinite(v) ? v/100 : 0;
  });
  drawBarChart(ctrCanvas, labels, ctrData, { title: 'Avg CTR', valueFormat: (v) => `${(v*100).toFixed(1)}%` });
  drawBarChart(cpaCanvas, labels, cpaData, { title: 'Avg CPA ($)', valueFormat: (v) => `$${v.toFixed(2)}` });
}

function drawBarChart(canvas, labels, values, opts = {}) {
  const ctx = canvas.getContext('2d');
  const dpr = window.devicePixelRatio || 1;
  const container = canvas.parentElement;
  const widthCss = Math.max(300, (container?.clientWidth || 600)/2);
  const heightCss = canvas.getAttribute('height') ? Number(canvas.getAttribute('height')) : 120;
  canvas.width = Math.round(widthCss * dpr);
  canvas.height = Math.round(heightCss * dpr);
  canvas.style.width = widthCss + 'px';
  canvas.style.height = heightCss + 'px';
  ctx.setTransform(dpr,0,0,dpr,0,0);
  ctx.clearRect(0,0,widthCss,heightCss);
  ctx.fillStyle = '#0b1220'; ctx.clearRect(0,0,widthCss,heightCss);
  const padding = { left: 36, right: 8, top: 18, bottom: 30 };
  const plotW = widthCss - padding.left - padding.right;
  const plotH = heightCss - padding.top - padding.bottom;
  const maxV = Math.max(0.001, ...values);
  // Axes
  ctx.strokeStyle = 'rgba(148,163,184,0.35)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(padding.left, padding.top); ctx.lineTo(padding.left, padding.top+plotH); ctx.lineTo(padding.left+plotW, padding.top+plotH); ctx.stroke();
  // Bars
  const n = Math.max(1, values.length);
  const barGap = 4;
  const barW = Math.max(2, Math.floor((plotW - barGap*(n-1))/n));
  values.forEach((v, i) => {
    const h = Math.round((v/maxV) * (plotH-2));
    const x = padding.left + i*(barW+barGap);
    const y = padding.top + (plotH - h);
    ctx.fillStyle = '#22d3ee';
    ctx.fillRect(x, y, barW, h);
    // Labels
    ctx.fillStyle = '#94a3b8'; ctx.font = '11px system-ui';
    const lbl = labels[i] || '';
    const valueText = opts.valueFormat ? opts.valueFormat(v) : String(v);
    ctx.save();
    ctx.translate(x + barW/2, padding.top + plotH + 12);
    ctx.rotate(-Math.PI/10);
    ctx.fillText(lbl, -Math.min(40, ctx.measureText(lbl).width)/2, 0);
    ctx.restore();
    ctx.fillText(valueText, x, y-2);
  });
  // Title
  if (opts.title) { ctx.fillStyle = '#cbd5e1'; ctx.font = '12px system-ui'; ctx.fillText(opts.title, padding.left, 12); }
}

function buildCampaignProductForIndex(index) {
  const items = state.campaign.items || [];
  const it = items[index];
  const product = {
    title: it?.name || 'Campaign Item',
    description: elements.campaignSubtitleInput?.value || '',
    image: it?.image || ''
  };
  return product;
}

async function previewCampaignItem(index) {
  const product = buildCampaignProductForIndex(index);
  // Auto-classify to get a marketing profile, then preview
  let profile = {};
  try { profile = (await printStation.marketingClassify(product))?.marketing_profile || {}; } catch (_) {}
  const globalTemplate = (elements.campaignAdTemplateSelect?.value || '').trim();
  const itemTmpl = (state.campaign.items?.[index]?.adTemplate || '').trim();
  const template = itemTmpl || globalTemplate || '';
  const product_url = buildCampaignShareUrl(state.campaign?.slug || '');
  const res = await printStation.marketingPreview({ product, marketing_profile: profile, template, product_url });
  const creative = res?.creative || null;
  if (creative) {
    // Re-use marketing preview area in Admin view? Render a toast and a temporary dialog?
    showToast('Preview generated. See Admin → Marketing for details.', 'success');
  }
}

async function launchCampaignItem(index) {
  const product = buildCampaignProductForIndex(index);
  let profile = {};
  try { profile = (await printStation.marketingClassify(product))?.marketing_profile || {}; } catch (_) {}
  const globalTemplate = (elements.campaignAdTemplateSelect?.value || '').trim();
  const itemTmpl = (state.campaign.items?.[index]?.adTemplate || '').trim();
  const template = itemTmpl || globalTemplate || '';
  if (template) profile.ad_template = template;
  const product_url = buildCampaignShareUrl(state.campaign?.slug || '');
  await printStation.marketingLaunch({ product, marketing_profile: profile, product_url });
  showToast('Ad launch submitted (paused by default).', 'success');
}

