// Guided Export Human Model State
const guidedHumanModelState = {
  models: [],
  categories: [],
  loaded: false,
  selectedModel: null,
  clothingColor: '#ffffff'
};

async function loadGuidedHumanModels() {
  if (guidedHumanModelState.loaded && guidedHumanModelState.models.length > 0) return;
  try {
    if (elements.guidedHumanModelStatus) elements.guidedHumanModelStatus.textContent = 'Loading models...';
    const result = await printStation.humanModels.list({ activeOnly: true, limit: 500 });
    guidedHumanModelState.models = result?.models || [];
    guidedHumanModelState.categories = [...new Set(guidedHumanModelState.models.map(m => m.category).filter(Boolean))];
    guidedHumanModelState.loaded = true;
    populateGuidedHumanModelCategories();
    renderGuidedHumanModelGrid();
    if (elements.guidedHumanModelStatus) elements.guidedHumanModelStatus.textContent = `${guidedHumanModelState.models.length} models available`;
  } catch (err) {
    console.error('[Guided Human Model] Failed to load:', err);
    guidedHumanModelState.models = [];
    guidedHumanModelState.loaded = false;
    if (elements.guidedHumanModelStatus) elements.guidedHumanModelStatus.textContent = 'Failed to load models';
  }
}

function populateGuidedHumanModelCategories() {
  const select = elements.guidedHumanModelCategoryFilter;
  if (!select) return;
  select.innerHTML = '<option value="">All Categories</option>' +
    guidedHumanModelState.categories.map(c => `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`).join('');
}

function renderGuidedHumanModelGrid() {
  const grid = elements.guidedHumanModelGrid;
  if (!grid) return;

  const categoryFilter = elements.guidedHumanModelCategoryFilter?.value || '';
  const genderFilter = elements.guidedHumanModelGenderFilter?.value || '';
  const searchTerm = (elements.guidedHumanModelSearch?.value || '').toLowerCase().trim();

  let filtered = guidedHumanModelState.models;
  if (categoryFilter) filtered = filtered.filter(m => m.category === categoryFilter);
  if (genderFilter) filtered = filtered.filter(m => m.gender === genderFilter);
  if (searchTerm) filtered = filtered.filter(m =>
    (m.title || '').toLowerCase().includes(searchTerm) ||
    (m.tags || '').toLowerCase().includes(searchTerm) ||
    (m.category || '').toLowerCase().includes(searchTerm)
  );

  if (!filtered.length) {
    grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:40px;color:var(--muted);">No models found</div>';
    return;
  }

  grid.innerHTML = filtered.map(model => {
    const thumbUrl = model.thumbnailPath || model.optimizedPath || model.filePath || '';
    const fullUrl = thumbUrl.startsWith('http') ? thumbUrl : resolveAssetUrl(thumbUrl, { width: 300, quality: 80 });
    const isSelected = guidedHumanModelState.selectedModel?.id === model.id;
    return `
      <div class="custom-art-card ${isSelected ? 'selected' : ''}" data-model-id="${model.id}" style="cursor:pointer;">
        <img src="${escapeHtml(fullUrl)}" alt="${escapeHtml(model.title || 'Model')}" style="display:block;width:100%;height:135px;object-fit:cover;background:#1a1a2e;" onerror="this.src='data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 75%22><rect fill=%22%231a1a2e%22 width=%22100%22 height=%2275%22/><text x=%2250%22 y=%2240%22 fill=%22%23666%22 text-anchor=%22middle%22 font-size=%228%22>No Image</text></svg>'" />
        <div class="custom-art-card-body">
          <div class="custom-art-card-title">${escapeHtml(model.title || 'Untitled')}</div>
        </div>
      </div>
    `;
  }).join('');
}

