/**
 * Apply clothing color tint to an image using canvas (client-side preview)
 * Tints white/light areas of the image with the specified color
 * @param {string} imageUrl - Source image URL
 * @param {string} targetColor - Hex color to tint to (e.g., '#ff0000')
 * @returns {Promise<string>} - Data URL of the tinted image
 */
/**
 * Tint clothing in a human model image using an optional mask
 * @param {string} imageUrl - The human model image URL
 * @param {string} targetColor - Hex color to tint to (e.g., '#ff0000')
 * @param {string} [maskUrl] - Optional mask image URL (white = tint, black = preserve)
 * @returns {Promise<string>} Data URL of tinted image
 */
async function tintClothingPreview(imageUrl, targetColor, maskUrl = null) {
  return new Promise((resolve, reject) => {
    // If no tinting needed (white), just return the original URL
    if (!targetColor || targetColor === '#ffffff' || targetColor === '#FFFFFF') {
      resolve(imageUrl);
      return;
    }

    const img = new Image();
    img.crossOrigin = 'anonymous';

    img.onload = () => {
      // If we have a mask URL, load it too
      if (maskUrl) {
        const maskImg = new Image();
        maskImg.crossOrigin = 'anonymous';
        maskImg.onload = () => {
          try {
            resolve(applyMaskTint(img, maskImg, targetColor));
          } catch (err) {
            console.error('[tintClothingPreview] Mask tinting failed:', err);
            resolve(imageUrl);
          }
        };
        maskImg.onerror = () => {
          console.warn('[tintClothingPreview] Failed to load mask, falling back to heuristic');
          try {
            resolve(applyHeuristicTint(img, targetColor));
          } catch (err) {
            resolve(imageUrl);
          }
        };
        maskImg.src = maskUrl;
      } else {
        // No mask - use heuristic tinting
        try {
          resolve(applyHeuristicTint(img, targetColor));
        } catch (err) {
          console.error('[tintClothingPreview] Error processing image:', err);
          resolve(imageUrl);
        }
      }
    };

    img.onerror = () => {
      console.warn('[tintClothingPreview] Failed to load image, returning original');
      resolve(imageUrl);
    };

    img.src = imageUrl;
  });
}

/**
 * Apply tinting using a mask image (white areas get tinted)
 */
function applyMaskTint(img, maskImg, targetColor) {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');
  canvas.width = img.width;
  canvas.height = img.height;

  // Draw original image
  ctx.drawImage(img, 0, 0);
  const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const data = imageData.data;

  // Draw mask to separate canvas (scaled to match)
  const maskCanvas = document.createElement('canvas');
  const maskCtx = maskCanvas.getContext('2d');
  maskCanvas.width = img.width;
  maskCanvas.height = img.height;
  maskCtx.drawImage(maskImg, 0, 0, img.width, img.height);
  const maskData = maskCtx.getImageData(0, 0, img.width, img.height).data;

  // Parse target color
  const hex = targetColor.replace('#', '');
  const tR = parseInt(hex.substring(0, 2), 16) / 255;
  const tG = parseInt(hex.substring(2, 4), 16) / 255;
  const tB = parseInt(hex.substring(4, 6), 16) / 255;

  // Process pixels - use mask to determine tinting
  for (let i = 0; i < data.length; i += 4) {
    // Mask brightness (0-255) determines tint strength
    // White (255) = full tint, Black (0) = no tint
    const maskBrightness = (maskData[i] + maskData[i + 1] + maskData[i + 2]) / 3 / 255;

    if (maskBrightness > 0.1) { // Threshold to avoid tinting near-black mask areas
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];

      // Multiplicative blend preserves shadows naturally
      // Blend between original and tinted based on mask brightness
      data[i] = Math.round(r * (1 - maskBrightness) + r * tR * maskBrightness);
      data[i + 1] = Math.round(g * (1 - maskBrightness) + g * tG * maskBrightness);
      data[i + 2] = Math.round(b * (1 - maskBrightness) + b * tB * maskBrightness);
    }
  }

  ctx.putImageData(imageData, 0, 0);
  return canvas.toDataURL('image/png');
}

/**
 * Apply tinting using heuristics (fallback when no mask available)
 */
function applyHeuristicTint(img, targetColor) {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');
  canvas.width = img.width;
  canvas.height = img.height;

  ctx.drawImage(img, 0, 0);
  const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const data = imageData.data;

  const hex = targetColor.replace('#', '');
  const tR = parseInt(hex.substring(0, 2), 16) / 255;
  const tG = parseInt(hex.substring(2, 4), 16) / 255;
  const tB = parseInt(hex.substring(4, 6), 16) / 255;

  for (let i = 0; i < data.length; i += 4) {
    const r = data[i];
    const g = data[i + 1];
    const b = data[i + 2];

    const rgbDiff = Math.max(Math.abs(r - g), Math.abs(g - b), Math.abs(r - b));
    const isNeutral = rgbDiff <= 10;

    const isPureWhiteBg = r >= 248 && g >= 248 && b >= 248 && isNeutral;
    const isGrayBg = r >= 190 && r <= 215 && g >= 190 && g <= 215 && b >= 190 && b <= 215 && isNeutral;
    const isBackground = isPureWhiteBg || isGrayBg;

    if (!isBackground) {
      const brightness = (r + g + b) / 3;
      const isWhiteClothing = brightness > 220 && isNeutral;
      const isShadowedWhite = brightness >= 150 && brightness <= 220 && rgbDiff <= 20;

      if (isWhiteClothing || isShadowedWhite) {
        data[i] = Math.round(r * tR);
        data[i + 1] = Math.round(g * tG);
        data[i + 2] = Math.round(b * tB);
      }
    }
  }

  ctx.putImageData(imageData, 0, 0);
  return canvas.toDataURL('image/png');
}

function openGuidedHumanModelModal() {
  loadGuidedHumanModels().then(() => {
    if (elements.guidedHumanModelModal) {
      // Use openModal for proper z-index stacking above guidedExportModal
      openModal(elements.guidedHumanModelModal);
      if (elements.guidedHumanModelApplyBtn) elements.guidedHumanModelApplyBtn.disabled = !guidedHumanModelState.selectedModel;
    }
  });
}

function closeGuidedHumanModelModal() {
  if (elements.guidedHumanModelModal) {
    // Use closeModal for proper stack management
    closeModal(elements.guidedHumanModelModal);
  }
}

async function applyGuidedHumanModel() {
  if (!guidedHumanModelState.selectedModel) return;

  const model = guidedHumanModelState.selectedModel;
  const imageUrl = model.optimizedPath || model.filePath || '';
  const fullUrl = imageUrl.startsWith('http') ? imageUrl : resolveAssetUrl(imageUrl, { width: 2400, quality: 92 });
  const clothingColor = guidedHumanModelState.clothingColor || '#ffffff';

  // Get mask URL if available
  const maskPath = model.maskPath || model.mask_path || '';
  const maskUrl = maskPath ? (maskPath.startsWith('http') ? maskPath : resolveAssetUrl(maskPath)) : null;

  // Store human model info in guided state
  state.guided = state.guided || {};
  state.guided.humanModelId = model.id;
  state.guided.clothingColor = clothingColor;
  state.guided.garmentType = model.apparel_type || model.apparelType || 't-shirt';
  state.guided.baseUrl = fullUrl;
  state.guided.originalHumanModelUrl = fullUrl; // Store original for re-tinting
  state.guided.maskUrl = maskUrl; // Store mask for re-tinting

  // Update the base image in the guided export preview with tinted version
  if (elements.guidedBaseImg) {
    if (clothingColor && clothingColor !== '#ffffff' && clothingColor !== '#FFFFFF') {
      // Apply tinting for preview (with mask if available)
      elements.guidedBaseImg.style.opacity = '0.5'; // Show loading state
      try {
        const tintedUrl = await tintClothingPreview(fullUrl, clothingColor, maskUrl);
        elements.guidedBaseImg.src = tintedUrl;
      } catch (err) {
        console.warn('[applyGuidedHumanModel] Tinting failed, using original:', err);
        elements.guidedBaseImg.src = fullUrl;
      }
      elements.guidedBaseImg.style.opacity = '1';
    } else {
      elements.guidedBaseImg.src = fullUrl;
    }
  }
  if (elements.guidedBaseStatus) {
    const colorLabel = clothingColor !== '#ffffff' ? ` (${clothingColor})` : '';
    elements.guidedBaseStatus.textContent = `Human Model: ${model.title || 'Selected'}${colorLabel}`;
  }

  // Also update the current item's mockupParams so it persists
  const idx = state.guided.index;
  if (idx >= 0 && state.campaign?.items?.[idx]) {
    state.campaign.items[idx].mockupParams = {
      ...(state.campaign.items[idx].mockupParams || {}),
      humanModelId: model.id,
      clothingColor: clothingColor
    };
  }

  // Show the clothing color row in guided export
  showGuidedClothingColorRow(clothingColor);

  closeGuidedHumanModelModal();
}

