/**
 * Handle decal size change
 */
function handleGuidedDecalSizeChange(value) {
  const size = parseInt(value, 10) || 100;
  state.guided = state.guided || {};
  state.guided.decalSize = size;
  if (elements.guidedDecalSizeLabel) elements.guidedDecalSizeLabel.textContent = size + '%';
  updateGuidedPreview();
}

/**
 * Handle decal rotation change
 */
function handleGuidedDecalRotationChange(value) {
  let rotation = parseInt(value, 10) || 0;
  // Normalize to -180 to 180
  while (rotation > 180) rotation -= 360;
  while (rotation < -180) rotation += 360;
  state.guided = state.guided || {};
  state.guided.decalRotation = rotation;
  if (elements.guidedDecalRotationInput) elements.guidedDecalRotationInput.value = rotation;
  if (elements.guidedDecalRotationLabel) elements.guidedDecalRotationLabel.textContent = rotation + '°';
  updateGuidedPreview();
}

/**
 * Handle decal color change (just stores the color, doesn't apply yet)
 */
function handleGuidedDecalColorChange(color) {
  state.guided = state.guided || {};
  state.guided.decalColor = color;
}

/**
 * Apply decal color recoloring to the overlay image
 * This recolors the decal in real-time using canvas
 */
async function applyGuidedDecalColor() {
  if (!state.guided?.originalOverlayUrl) return;

  const color = state.guided.decalColor || '#ffffff';
  if (color === '#ffffff') {
    // White means no recolor, reset to original
    resetGuidedDecalColor();
    return;
  }

  try {
    if (elements.guidedDecalApplyColorBtn) {
      elements.guidedDecalApplyColorBtn.disabled = true;
      elements.guidedDecalApplyColorBtn.textContent = 'Applying...';
    }

    // Load the original overlay image
    const img = new Image();
    img.crossOrigin = 'anonymous';

    await new Promise((resolve, reject) => {
      img.onload = resolve;
      img.onerror = reject;
      img.src = state.guided.originalOverlayUrl;
    });

    // Create canvas and draw image
    const canvas = document.createElement('canvas');
    canvas.width = img.naturalWidth;
    canvas.height = img.naturalHeight;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(img, 0, 0);

    // Get pixel data
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const data = imageData.data;

    // Parse target color
    const r = parseInt(color.slice(1, 3), 16);
    const g = parseInt(color.slice(3, 5), 16);
    const b = parseInt(color.slice(5, 7), 16);

    // Use the same algorithm as the original web decal creator (recolorCanvasToVinyl):
    // - Calculate brightness for each pixel
    // - If brightness > threshold (near white), make transparent
    // - Otherwise, replace with target color at full opacity
    const BRIGHTNESS_THRESHOLD = 230;

    for (let i = 0; i < data.length; i += 4) {
      const origR = data[i];
      const origG = data[i + 1];
      const origB = data[i + 2];
      const alpha = data[i + 3];

      // Skip fully transparent pixels
      if (alpha === 0) continue;

      // Calculate brightness using standard luminance formula
      const brightness = 0.2126 * origR + 0.7152 * origG + 0.0722 * origB;

      if (brightness > BRIGHTNESS_THRESHOLD) {
        // Near-white pixel - make transparent (background removal)
        data[i + 3] = 0;
      } else {
        // Non-white pixel - replace with target color at full opacity
        data[i] = r;
        data[i + 1] = g;
        data[i + 2] = b;
        data[i + 3] = 255;
      }
    }

    // Put recolored data back
    ctx.putImageData(imageData, 0, 0);

    // Convert to data URL and update overlay
    const recoloredUrl = canvas.toDataURL('image/png');
    state.guided.overlayUrl = recoloredUrl;
    state.guided.decalColorEnabled = true;

    // Update the overlay image in the preview
    if (elements.guidedOverlayImg) {
      elements.guidedOverlayImg.src = recoloredUrl;
    }

    if (elements.guidedDecalApplyColorBtn) {
      elements.guidedDecalApplyColorBtn.disabled = false;
      elements.guidedDecalApplyColorBtn.textContent = 'Applied ✓';
      setTimeout(() => {
        if (elements.guidedDecalApplyColorBtn) {
          elements.guidedDecalApplyColorBtn.textContent = 'Apply Color';
        }
      }, 1500);
    }

    // Trigger server preview update
    scheduleServerPreview();

    console.log(`[applyGuidedDecalColor] Applied color ${color} to decal`);
  } catch (err) {
    console.error('[applyGuidedDecalColor] Error:', err);
    if (elements.guidedDecalApplyColorBtn) {
      elements.guidedDecalApplyColorBtn.disabled = false;
      elements.guidedDecalApplyColorBtn.textContent = 'Apply Color';
    }
  }
}

/**
 * Reset decal color to original
 */
function resetGuidedDecalColor() {
  if (!state.guided?.originalOverlayUrl) return;

  // Restore original overlay
  state.guided.overlayUrl = state.guided.originalOverlayUrl;
  state.guided.decalColorEnabled = false;

  // Update the overlay image in the preview
  if (elements.guidedOverlayImg) {
    elements.guidedOverlayImg.src = state.guided.originalOverlayUrl;
  }

  // Reset color picker to white
  state.guided.decalColor = '#ffffff';
  if (elements.guidedDecalColorInput) {
    elements.guidedDecalColorInput.value = '#ffffff';
  }

  // Trigger server preview update
  scheduleServerPreview();

  console.log('[resetGuidedDecalColor] Reset to original decal');
}

/**
 * Handle vectorize decal button click
 */
async function handleGuidedDecalVectorize() {
  if (!state.guided?.overlayUrl) return;
  try {
    if (elements.guidedDecalVectorizeBtn) {
      elements.guidedDecalVectorizeBtn.disabled = true;
      elements.guidedDecalVectorizeBtn.textContent = 'Vectorizing...';
    }
    // Call vectorize API via IPC
    const result = await printStation.vectorizeImage(state.guided.originalOverlayUrl || state.guided.overlayUrl);
    if (result && result.svgPath) {
      // Store the vectorized version
      state.guided.vectorizedUrl = resolveAssetUrl(result.svgPath);
      state.guided.isVectorized = true;
      if (elements.guidedDecalVectorizeBtn) {
        elements.guidedDecalVectorizeBtn.textContent = 'Vectorized ✓';
      }
      updateGuidedPreview();
    } else {
      throw new Error('No SVG returned');
    }
  } catch (err) {
    console.error('[handleGuidedDecalVectorize] Error:', err);
    if (elements.guidedDecalVectorizeBtn) {
      elements.guidedDecalVectorizeBtn.disabled = false;
      elements.guidedDecalVectorizeBtn.textContent = 'Vectorize Failed';
      setTimeout(() => {
        if (elements.guidedDecalVectorizeBtn) {
          elements.guidedDecalVectorizeBtn.textContent = 'Vectorize Decal';
        }
      }, 2000);
    }
  }
}

/**
 * Handle clothing color change in guided export
 */
async function handleGuidedClothingColorChange(newColor) {
  // Update UI
  if (elements.guidedClothingColorInput) elements.guidedClothingColorInput.value = newColor;
  if (elements.guidedClothingColorLabel) elements.guidedClothingColorLabel.textContent = newColor;
  elements.guidedClothingColorPresets?.querySelectorAll('.guided-color-preset').forEach(btn => {
    btn.style.border = btn.dataset.color === newColor ? '2px solid #3b82f6' : '1px solid var(--border)';
  });

  // Update state
  if (state.guided) {
    state.guided.clothingColor = newColor;
  }

  // Update mockupParams for current item
  const idx = state.guided?.index;
  if (idx >= 0 && state.campaign?.items?.[idx]) {
    state.campaign.items[idx].mockupParams = {
      ...(state.campaign.items[idx].mockupParams || {}),
      clothingColor: newColor
    };
  }

  // Update status text
  if (elements.guidedBaseStatus && state.guided?.humanModelId) {
    const model = guidedHumanModelState.models.find(m => m.id === state.guided.humanModelId);
    const colorLabel = newColor !== '#ffffff' ? ` (${newColor})` : '';
    elements.guidedBaseStatus.textContent = `Human Model: ${model?.title || 'Selected'}${colorLabel}`;
  }

  // Re-render the server preview with new color (this applies the actual tinting)
  scheduleServerPreview();
}

/**
 * Update the clothing color tint on the current human model preview
 * Used when user changes color after a human model is already applied
 */
async function updateGuidedHumanModelTint() {
  if (!state.guided?.humanModelId || !state.guided?.originalHumanModelUrl) return;

  const clothingColor = state.guided.clothingColor || '#ffffff';
  const originalUrl = state.guided.originalHumanModelUrl;
  const maskUrl = state.guided.maskUrl || null;

  if (elements.guidedBaseImg) {
    if (clothingColor && clothingColor !== '#ffffff' && clothingColor !== '#FFFFFF') {
      elements.guidedBaseImg.style.opacity = '0.5';
      try {
        const tintedUrl = await tintClothingPreview(originalUrl, clothingColor, maskUrl);
        elements.guidedBaseImg.src = tintedUrl;
      } catch (err) {
        console.warn('[updateGuidedHumanModelTint] Tinting failed:', err);
        elements.guidedBaseImg.src = originalUrl;
      }
      elements.guidedBaseImg.style.opacity = '1';
    } else {
      elements.guidedBaseImg.src = originalUrl;
    }
  }

  // Update status text
  if (elements.guidedBaseStatus && state.guided.humanModelId) {
    const model = guidedHumanModelState.models.find(m => m.id === state.guided.humanModelId);
    const colorLabel = clothingColor !== '#ffffff' ? ` (${clothingColor})` : '';
    elements.guidedBaseStatus.textContent = `Human Model: ${model?.title || 'Selected'}${colorLabel}`;
  }

  // Update mockupParams
  const idx = state.guided?.index;
  if (idx >= 0 && state.campaign?.items?.[idx]) {
    state.campaign.items[idx].mockupParams = {
      ...(state.campaign.items[idx].mockupParams || {}),
      clothingColor: clothingColor
    };
  }
}

function openCampaignMockupSettings(index) {
  // Redirect to new apparel mockup view in campaign mode
  campaignMockupEditIndex = Number(index);
  const items = state.campaign.items || [];
  if (!items.length) return;

  switchView('apparelMockupView');

  // Give the view a tick to render, then init in campaign mode
  setTimeout(() => {
    if (typeof window.initApparelMockupView === 'function') {
      window.initApparelMockupView({
        campaignMode: true,
        campaignItems: items,
        startIndex: campaignMockupEditIndex,
        onComplete: (itemIndex, data) => {
          // Update campaign item with mockup result
          const item = state.campaign.items[itemIndex];
          if (item && data) {
            const serverBase = (state.config?.serverBaseUrl || '').replace(/\/$/, '');
            item.mockupImage = data.front ? `${serverBase}${data.front.imagePath}` : (data.back ? `${serverBase}${data.back.imagePath}` : '');
            item.mockupParams = data.mockupParams || item.mockupParams;
            printStation.updateCampaign(state.campaign);
            renderCampaignItems();
          }
        }
      });
    }
  }, 100);
}

function closeCampaignMockupSettings() {
  const modal = elements.campaignMockupSettingsModal;
  if (!modal) return;
  modal.setAttribute('hidden', '');
}

function renderCampaignItems() {
  const tbody = elements.campaignItemsBody;
  if (!tbody) return;
  const items = state.campaign.items;
  if (!items.length) {
    tbody.innerHTML = '<tr><td colspan="6" class="placeholder">Use "Add to campaign" in Catalog to add items.</td></tr>';
    return;
  }
  tbody.innerHTML = items
    .map((item, idx) => {
      if (!item.uid) {
        item.uid = `ci-${Date.now()}-${idx}-${Math.random().toString(36).slice(2)}`;
      }
      const selected = state.campaign.selection ? state.campaign.selection.has(item.uid) : false;
      const safeName = escapeHtml(cleanAiGeneratedName(item.name) || 'Item');
      const price = item.priceCents != null ? (item.priceCents / 100).toFixed(2) : (item.price || '');
      let imgSrc = item.image ? resolveAssetUrl(item.image, { width: 120, quality: 80 }) : '';
      if (imgSrc && imgSrc.includes('/api/library/')) {
        imgSrc = imgSrc.replace('/api/library/', '/api/library-black-bg/');
      }
      const imgHtml = imgSrc
        ? `<img src="${escapeHtml(imgSrc)}" alt="${safeName}" style="max-height:56px;border-radius:6px;border:1px solid var(--border);background:#000;object-fit:contain;"/>`
        : '<span class="muted" style="font-size:12px;">No image</span>';
      const typeLabel = { tshirt: 'T-shirt', hoodie: 'Hoodie', sticker: 'Sticker', 'metal-print': 'Metal Print', 'sticker-pack': 'Sticker Pack' }[item.productType] || item.productType || 'T-shirt';
      return `
        <tr data-index="${idx}" data-uid="${item.uid}">
          <td><input type="checkbox" class="campaign-select-item" data-uid="${item.uid}" ${selected ? 'checked' : ''}></td>
          <td><div style="display:flex;align-items:center;justify-content:center;">${imgHtml}</div></td>
          <td><input type="text" class="campaign-name" value="${safeName}" style="width:100%;"></td>
          <td><span style="font-size:12px;">${escapeHtml(typeLabel)}</span></td>
          <td><input type="text" class="campaign-price" inputmode="decimal" value="${escapeHtml(String(price))}" placeholder="0.00" style="width:70px;"></td>
          <td><button type="button" class="danger campaign-remove" style="padding:2px 8px;font-size:12px;" title="Remove">x</button></td>
        </tr>
      `;
    })
    .join('');

  // Remove button handlers
  tbody.querySelectorAll('.campaign-remove').forEach((btn) => {
    btn.addEventListener('click', () => {
      const tr = btn.closest('tr');
      const index = Number(tr?.dataset.index || -1);
      if (index >= 0) {
        removeCampaignItem(index);
        renderCampaignItems();
      }
    });
  });

  // Checkbox selection
  const checkboxes = tbody.querySelectorAll('.campaign-select-item');
  checkboxes.forEach((checkbox) => {
    checkbox.addEventListener('change', () => {
      handleCampaignSelectItem(checkbox.dataset.uid, checkbox.checked);
    });
  });

  const selectAllToggle = elements.campaignSelectAllToggle;
  if (selectAllToggle) {
    const total = items.length;
    const selectedCount = state.campaign.selection ? state.campaign.selection.size : 0;
    selectAllToggle.checked = total > 0 && selectedCount === total;
    selectAllToggle.indeterminate = selectedCount > 0 && selectedCount < total;
    selectAllToggle.onchange = (event) => {
      const checked = Boolean(event.target.checked);
      applyCampaignSelectionForAll(checked);
      renderCampaignItems();
    };
  }

  try { updateCampaignBulkStatus(); } catch (_) {}
  try { renderCampaignApparelSummary(); } catch (_) {}
}

function renderCampaignMockupControls() {
  const strategy = ensureCampaignMockupStrategy();
  const mode = strategy.mode || 'perItem';
  if (elements.campaignMockupModeRadios && elements.campaignMockupModeRadios.length) {
    elements.campaignMockupModeRadios.forEach((radio) => {
      radio.checked = radio.value === mode;
    });
  }
  const showShared = mode === 'campaign';
  if (elements.campaignMockupItemWrapper) {
    elements.campaignMockupItemWrapper.style.display = showShared ? '' : 'none';
  }
  if (elements.campaignMockupDescRow) {
    elements.campaignMockupDescRow.style.display = showShared ? '' : 'none';
  }
  if (elements.campaignMockupDescription) {
    elements.campaignMockupDescription.value = strategy.description || '';
  }
  if (elements.campaignMockupItemSelect) {
    const stickers = (state.campaign.items || []).filter(
      (item) => (item && String(item.productType || '').toLowerCase()) === 'sticker'
    );
    const options = ['<option value="">(project-level preview)</option>'];
    if (stickers.length) {
      stickers.forEach((item, idx) => {
        const label = cleanAiGeneratedName(item.name) || `Item ${idx + 1}`;
        options.push(`<option value="${escapeHtml(item.uid || '')}">${escapeHtml(label)}</option>`);
      });
    } else {
      options.push('<option value="">Add decals to choose a mockup</option>');
    }
    elements.campaignMockupItemSelect.innerHTML = options.join('');
    if (strategy.mockupItemUid && stickers.some((item) => item.uid === strategy.mockupItemUid)) {
      elements.campaignMockupItemSelect.value = strategy.mockupItemUid;
    } else {
      elements.campaignMockupItemSelect.value = '';
      if (strategy.mockupItemUid) {
        state.campaign.mockupStrategy.mockupItemUid = '';
      }
    }
    elements.campaignMockupItemSelect.disabled = !showShared;
  }
}

function readCampaignForm() {
  const get = (el) => (el ? el.value.trim() : '');
  const title = get(elements.campaignTitleInput);
  const subtitle = get(elements.campaignSubtitleInput);
  const themeColor = get(elements.campaignThemeInput) || '#1d4ed8';
  const heroImage = get(elements.campaignHeroInput);
  // Pull edited row values back into state
  const tbody = elements.campaignItemsBody;
  if (tbody) {
    Array.from(tbody.querySelectorAll('tr')).forEach((tr) => {
      const index = Number(tr.dataset.index || -1);
      if (index < 0 || !state.campaign.items[index]) return;
      const row = state.campaign.items[index];
      row.name = tr.querySelector('.campaign-name')?.value.trim() || row.name;
      row.productType = tr.querySelector('.campaign-type')?.value || row.productType;
      row.size = tr.querySelector('.campaign-size')?.value.trim() || row.size || undefined;
      const rawPrice = tr.querySelector('.campaign-price')?.value.trim();
      if (row.productType === 'sticker') {
        if (rawPrice) {
          const dollars = Number(rawPrice);
          if (Number.isFinite(dollars)) row.priceCents = Math.round(dollars * 100);
        }
      } else {
        row.priceCents = undefined;
      }
      const qty = Number(tr.querySelector('.campaign-qty')?.value || 1);
      row.quantity = Math.max(1, Number.isFinite(qty) ? qty : 1);
      const tmpl = tr.querySelector('.campaign-ad-template')?.value || '';
      row.adTemplate = tmpl;
    });
  }
  const radios = elements.campaignMockupModeRadios || [];
  const selectedRadio = radios.find((radio) => radio.checked);
  const strategy = ensureCampaignMockupStrategy();
  strategy.mode = selectedRadio && selectedRadio.value === 'campaign' ? 'campaign' : 'perItem';
  strategy.mockupItemUid = elements.campaignMockupItemSelect ? elements.campaignMockupItemSelect.value : strategy.mockupItemUid;
  strategy.description = elements.campaignMockupDescription ? elements.campaignMockupDescription.value.trim() : strategy.description;

  // Read new marketing fields
  const socialProof = get(elements.campaignSocialProof) || 'Trusted by 500+ customers';
  const endDate = get(elements.campaignEndDate) || '';
  const benefitsRaw = get(elements.campaignBenefits);
  const benefits = benefitsRaw
    ? benefitsRaw.split(/[\n,]+/).map(b => b.trim()).filter(Boolean)
    : [];

  return { title, subtitle, themeColor, heroImage, socialProof, endDate, benefits };
}

async function handleCampaignSave() {
  try {
    const meta = readCampaignForm();
    if (!meta.title) {
      alert('Enter a campaign title.');
      return;
    }
    // Get the bulk type from the select dropdown
    const bulkType = elements.campaignBulkTypeSelect?.value || '';

    const payload = {
      title: meta.title,
      subtitle: meta.subtitle,
      themeColor: meta.themeColor,
      hero: meta.heroImage ? { image: meta.heroImage } : null,
      bulkType: bulkType || state.campaign.bulkType || '',
    items: state.campaign.items.map((it) => ({
      name: it.name,
      productType: it.productType,
        categorySlug: it.categorySlug,
        designId: it.designId,
        image: it.image,
        size: it.size || undefined,
        priceCents: it.productType === 'sticker' ? it.priceCents : undefined,
        quantity: it.quantity || 1,
        adTemplate: it.adTemplate || '',
      marketingProfile: it._profile || null,
      apparel: it.apparel || null,
      mockupParams: it.mockupParams || null,
      uid: it.uid || undefined,
      autoDescription: it.autoDescription || '',
      shopifyProductId: it.shopifyProductId || undefined,
      metalPrintSizes: it.metalPrintSizes || null,
      sourceArtwork: it.sourceArtwork || null
    })),
    apparel: state.campaign.apparel || null,
    apparelChoices: state.campaign.apparelChoices || [null, null]
  };
  if (state.campaign.salesInitiative) {
    payload.salesInitiative = state.campaign.salesInitiative;
  }
  payload.mockupStrategy = { ...ensureCampaignMockupStrategy() };
  payload.productType = state.campaign.productType || '';
  payload.decalBackground = state.campaign.decalBackground || null;
  payload.socialProof = meta.socialProof;
  payload.endDate = meta.endDate;
  payload.benefits = meta.benefits;
    if (!state.config?.apiKey) {
      showToast('Set INTERNAL API key in Settings to enable saving.', 'warning', 5000);
    }
    elements.campaignSaveButton.disabled = true;
    let created = false;
    if (state.campaign?.slug) {
      await printStation.updateCampaign(state.campaign.slug, payload);
      showToast('Campaign updated.', 'success');
    } else {
      const response = await printStation.createCampaign(payload);
      const slug = response?.campaign?.slug;
      if (slug) {
        state.campaign.slug = slug;
        const base = ensureTrailingSlash(state.config?.serverBaseUrl || '');
        const url = `${base}web/campaign.html?c=${encodeURIComponent(slug)}`;
        if (elements.campaignShareLink) {
          elements.campaignShareLink.textContent = url;
        }
        created = true;
        showToast('Campaign created.', 'success');
      } else {
        showToast('Created, but slug missing.', 'warning');
      }
    }
    // Ensure lists and buttons reflect current state
    try { await refreshCampaignList(); } catch (_) {}
    try {
      if (elements.campaignCreateButton && elements.campaignSaveButton) {
        const hasSlug = Boolean(state.campaign?.slug);
        elements.campaignCreateButton.style.display = hasSlug ? 'none' : '';
        elements.campaignSaveButton.style.display = hasSlug ? '' : 'none';
      }
      if (elements.campaignDeleteButton) {
        elements.campaignDeleteButton.style.display = state.campaign?.slug ? '' : 'none';
      }
    } catch (_) {}
  } catch (error) {
    console.error('Campaign save failed:', error);
    showToast(error?.message || 'Unable to save campaign.', 'error', 6000);
  } finally {
    if (elements.campaignSaveButton) elements.campaignSaveButton.disabled = false;
  }
}

async function handleCampaignHeroChoose() {
  try {
    const files = await printStation.selectFiles({
      title: 'Choose hero image',
      properties: ['openFile'],
      filters: [
        { name: 'Images', extensions: ['png', 'jpg', 'jpeg', 'gif', 'webp'] },
        { name: 'All Files', extensions: ['*'] }
      ]
    });
    if (!files || !files.length) return;
    const filePath = files[0];
    const displayName = elements.campaignTitleInput?.value.trim() || 'Campaign Hero';
    const result = await printStation.uploadArtwork({
      previewPath: filePath,
      categoryMode: 'new',
      newCategoryName: 'Campaign Assets',
      displayName
    });
    const rel = result?.design?.preview || '';
    const proxy = rel && rel.startsWith('library/')
      ? `/api/library/${encodeURIComponent(rel.replace(/^library\//, '')).replace(/%2F/g, '/')}`
      : rel;
    if (elements.campaignHeroInput) elements.campaignHeroInput.value = proxy;
    showToast('Hero image uploaded.', 'success');
  } catch (error) {
    console.error('Hero image upload failed:', error);
    showToast(error?.message || 'Unable to upload hero image.', 'error');
  }
}

async function refreshCampaignList() {
  const body = elements.campaignListBody;
  if (!body) return;
  try {
    body.innerHTML = '<tr><td colspan="4" class="placeholder">Loading…</td></tr>';
    const resp = await printStation.listCampaigns();
    const list = Array.isArray(resp?.campaigns) ? resp.campaigns : [];
    if (!list.length) {
      body.innerHTML = '<tr><td colspan="4" class="placeholder">No campaigns found.</td></tr>';
      return;
    }
    body.innerHTML = list
      .map((c) => {
        const when = c.updatedAt ? new Date(c.updatedAt).toLocaleString() : '—';
        const title = escapeHtml(c.title || c.slug);
        const slug = escapeHtml(c.slug || '');
        return `
          <tr data-slug="${slug}">
            <td>${title}</td>
            <td><code>${slug}</code></td>
            <td>${when}</td>
            <td>
              <button type="button" class="secondary campaign-load">Load</button>
              <button type="button" class="secondary campaign-duplicate">Duplicate</button>
              <button type="button" class="secondary campaign-copy">Copy link</button>
              <button type="button" class="secondary campaign-rename">Rename</button>
              <button type="button" class="danger campaign-delete">Delete</button>
            </td>
          </tr>
        `;
      })
      .join('');

    body.querySelectorAll('.campaign-load').forEach((btn) => {
      btn.addEventListener('click', async () => {
        const tr = btn.closest('tr');
        const slug = tr?.dataset.slug || '';
        if (!slug) return;
        await handleCampaignLoad(slug);
      });
    });
    body.querySelectorAll('.campaign-duplicate').forEach((btn) => {
      btn.addEventListener('click', async () => {
        const tr = btn.closest('tr');
        const slug = tr?.dataset.slug || '';
        if (!slug) return;
        await handleCampaignDuplicate(slug);
        await refreshCampaignList();
      });
    });
    body.querySelectorAll('.campaign-copy').forEach((btn) => {
      btn.addEventListener('click', async () => {
        const tr = btn.closest('tr');
        const slug = tr?.dataset.slug || '';
        if (!slug) return;
        const base = ensureTrailingSlash(state.config?.serverBaseUrl || '');
        const url = `${base}web/campaign.html?c=${encodeURIComponent(slug)}`;
        try {
          if (navigator.clipboard?.writeText) await navigator.clipboard.writeText(url);
          else {
            const ta = document.createElement('textarea');
            ta.value = url; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove();
          }
          showToast('Share link copied.', 'success');
        } catch (error) {
          showToast('Unable to copy link.', 'error');
        }
      });
    });
    body.querySelectorAll('.campaign-rename').forEach((btn) => {
      btn.addEventListener('click', async () => {
        const tr = btn.closest('tr');
        const slug = tr?.dataset.slug || '';
        if (!slug) return;
        const newTitle = (prompt('New campaign title:') || '').trim();
        if (!newTitle) return;
        try {
          await printStation.updateCampaign(slug, { title: newTitle });
          showToast('Campaign renamed.', 'success');
          await refreshCampaignList();
        } catch (error) {
          showToast(error?.message || 'Unable to rename.', 'error');
        }
      });
    });
    body.querySelectorAll('.campaign-delete').forEach((btn) => {
      btn.addEventListener('click', async () => {
        const tr = btn.closest('tr');
        const slug = tr?.dataset.slug || '';
        if (!slug) return;
        if (!await nativeConfirm('Delete this campaign? This cannot be undone.', 'Delete Campaign')) return;
        try {
          await printStation.deleteCampaign(slug);
          showToast('Campaign deleted.', 'success');
          await refreshCampaignList();
        } catch (error) {
          showToast(error?.message || 'Unable to delete campaign.', 'error');
        }
      });
    });
  } catch (error) {
    console.error('Campaign list error:', error);
    body.innerHTML = `<tr><td colspan="4" class="placeholder error">${escapeHtml(
      error?.message || 'Unable to load campaigns.'
    )}</td></tr>`;
  }
}

async function refreshCampaignApparelFromInventory() {
  try {
    // Only refresh if apparel source is from inventory
    if (!state.campaign?.apparel || state.campaign.apparel.source !== 'inventory') {
      return;
    }

    const itemId = state.campaign.apparel.itemId;
    if (!itemId) return;

    // Ensure inventory is loaded
    if (!state.inventoryInitialized) {
      await loadInventory('apparel', { silent: true });
    }

    // Find the current inventory item
    const currentItem = state.inventoryItems.find(item => String(item.id) === String(itemId));
    if (!currentItem) {
      console.warn(`[Apparel Refresh] Inventory item ${itemId} not found in current inventory`);
      return;
    }

    // Update campaign apparel data with current inventory values
    const wasUpdated = !state.campaign.apparel.imageUrlBack && currentItem.imageUrlBack;

    state.campaign.apparel = {
      source: 'inventory',
      itemId: currentItem.id,
      name: currentItem.name || '',
      size: currentItem.size || '',
      colorName: currentItem.colorName || null,
      color: currentItem.color || null,
      imageUrl: currentItem.imageUrl || null,
      imageUrlBack: currentItem.imageUrlBack || null,
      unitCostCents: Number.isFinite(Number(currentItem.unitCostCents)) ? Number(currentItem.unitCostCents) : null
    };

    if (wasUpdated) {
      console.log('[Apparel Refresh] Updated campaign apparel with back image:', currentItem.imageUrlBack);
      try { renderCampaignApparelSummary(); } catch (_) {}
    }
  } catch (error) {
    console.error('[Apparel Refresh] Error refreshing apparel from inventory:', error);
  }
}

async function handleCampaignLoad(slug) {
  try {
    console.log(`[handleCampaignLoad] Loading campaign: ${slug}`);
    const resp = await printStation.getCampaign(slug);
    const c = resp?.campaign;
    if (!c) throw new Error('Campaign not found.');
    console.log(`[handleCampaignLoad] Campaign has ${c.items?.length || 0} items`);
    if (c.items && c.items.length > 0) {
      console.log(`[handleCampaignLoad] First item from server - mockupImage: ${c.items[0].mockupImage || 'NONE'}, shopifyProductId: ${c.items[0].shopifyProductId || 'NONE'}`);
    }
    // Populate form
    elements.campaignTitleInput.value = c.title || '';
    elements.campaignSubtitleInput.value = c.subtitle || c.tagline || '';
    elements.campaignThemeInput.value = c.themeColor || '#1d4ed8';
    elements.campaignHeroInput.value = c.hero?.image || '';
    state.campaign.slug = c.slug;
    state.campaign.shopifyPage = c.shopifyPage || null;
    state.campaign.apparel = c.apparel || null;
    state.campaign.apparelChoices = c.apparelChoices || (c.apparel ? [c.apparel, null] : [null, null]);
    state.campaign.mockupStrategy = { ...getDefaultMockupStrategy(), ...(c.mockupStrategy || {}) };
    state.campaign.productType = c.productType || '';
    state.campaign.decalBackground = c.decalBackground || null;
    state.campaign.bulkType = c.bulkType || '';
    state.campaign.mockupImage = c.mockupImage || null;

    // Set the bulk type dropdown to match the loaded campaign
    if (elements.campaignBulkTypeSelect && c.bulkType) {
      elements.campaignBulkTypeSelect.value = c.bulkType;
    }
    // Update landing page link UI
    if (elements.campaignShopifyPageLink) {
      const url = c.shopifyPage?.url || '';
      elements.campaignShopifyPageLink.textContent = url || 'Create a Shopify landing page to see it here.';
    }
    state.campaign.items = Array.isArray(c.items) ? c.items.map((it) => ({
      name: it.name || '',
      productType: it.productType || 'tshirt',
      categorySlug: it.categorySlug || null,
      designId: it.designId || null,
      image: it.image || null,
      size: it.size || it.sizeLabel || undefined,
      priceCents: Number.isFinite(Number(it.priceCents)) ? Number(it.priceCents) : undefined,
      quantity: Math.max(1, Number(it.quantity || 1)),
      adTemplate: it.adTemplate || '',
      _profile: it.marketingProfile || it.profile || null,
      uid: it.uid || it.campaignItemId || `ci-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      autoDescription: it.autoDescription || '',
      shopifyProductId: it.shopifyProductId || undefined,
      mockupImage: it.mockupImage || null,
      mockupParams: it.mockupParams || null,
      apparel: it.apparel || null,
      metalPrintSizes: it.metalPrintSizes || null,
      sourceArtwork: it.sourceArtwork || null
    })) : [];
    if (state.campaign.items.length > 0) {
      console.log(`[handleCampaignLoad] First item in state - mockupImage: ${state.campaign.items[0].mockupImage || 'NONE'}, shopifyProductId: ${state.campaign.items[0].shopifyProductId || 'NONE'}`);
    }
    state.campaign.selection = new Set();
    state.campaign.salesInitiative = c.salesInitiative
      ? { ...getDefaultSalesInitiative(), ...c.salesInitiative }
      : getDefaultSalesInitiative();
    state.campaign.socialProof = c.socialProof || 'Trusted by 500+ customers';
    state.campaign.endDate = c.endDate || '';
    state.campaign.benefits = Array.isArray(c.benefits) ? c.benefits : [];

    // Populate marketing UI fields
    if (elements.campaignSocialProof) elements.campaignSocialProof.value = state.campaign.socialProof;
    if (elements.campaignEndDate) elements.campaignEndDate.value = state.campaign.endDate;
    if (elements.campaignBenefits) {
      elements.campaignBenefits.value = state.campaign.benefits.join(', ');
    }

    renderCampaignItems();
    try { renderCampaignApparelSummary(); } catch (_) {}
    try { renderCampaignDecalBackground(); } catch (_) {}
    // Notify campaign view of loaded data (pipeline history, apparel slots, analytics)
    if (typeof window.onCampaignLoaded === 'function') window.onCampaignLoaded(state.campaign);
    // Refresh apparel data from inventory if applicable
    await refreshCampaignApparelFromInventory();
    renderSalesInitiativeSummary();
    syncSalesInitiativeInputs();
    // Share link
    const base = ensureTrailingSlash(state.config?.serverBaseUrl || '');
    const url = `${base}web/campaign.html?c=${encodeURIComponent(c.slug)}`;
    if (elements.campaignShareLink) {
      elements.campaignShareLink.textContent = url;
    }
    if (elements.campaignShopifyPageLink && c.shopifyPage?.url) {
      elements.campaignShopifyPageLink.textContent = c.shopifyPage.url;
    }
    // Update button visibility after loading
    if (elements.campaignCreateButton && elements.campaignSaveButton) {
      const hasSlug = Boolean(state.campaign?.slug);
      elements.campaignCreateButton.style.display = hasSlug ? 'none' : '';
      elements.campaignSaveButton.style.display = hasSlug ? '' : 'none';
    }
    if (elements.campaignDeleteButton) {
      elements.campaignDeleteButton.style.display = state.campaign?.slug ? '' : 'none';
    }
    showToast('Campaign loaded.', 'success');
  } catch (error) {
    console.error('Load campaign failed:', error);
    showToast(error?.message || 'Unable to load campaign.', 'error', 6000);
  }
}

async function handleCampaignDuplicate(slug) {
  try {
    const resp = await printStation.getCampaign(slug);
    const c = resp?.campaign;
    if (!c) throw new Error('Campaign not found.');
    const title = `${c.title || c.slug} (Copy)`;
    const payload = {
      title,
      subtitle: c.subtitle || c.tagline || '',
      themeColor: c.themeColor || '#1d4ed8',
      hero: c.hero?.image ? { image: c.hero.image } : null,
      items: Array.isArray(c.items) ? c.items.map((it) => ({
        name: it.name,
        productType: it.productType,
        categorySlug: it.categorySlug,
        designId: it.designId,
        image: it.image,
        size: it.size || it.sizeLabel || undefined,
        priceCents: Number.isFinite(Number(it.priceCents)) ? Number(it.priceCents) : undefined,
        quantity: it.quantity || 1,
        adTemplate: it.adTemplate || '',
        marketingProfile: it.marketingProfile || it.profile || null
      })) : []
    };
    if (c.mockupStrategy) {
      payload.mockupStrategy = c.mockupStrategy;
    };
    const created = await printStation.createCampaign(payload);
      const newSlug = created?.campaign?.slug;
    if (newSlug) {
      showToast('Campaign duplicated.', 'success');
      // Optionally load the new campaign
      await handleCampaignLoad(newSlug);
    } else {
      showToast('Duplicate saved but slug missing.', 'warning');
    }
  } catch (error) {
    console.error('Duplicate campaign failed:', error);
    showToast(error?.message || 'Unable to duplicate campaign.', 'error', 6000);
  }
}

function slugifyFilename(value, fallback = 'catalog-design') {
  const slug = String(value || '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .replace(/-{2,}/g, '-');
  return slug || fallback;
}

function extractFileExtension(pathValue, fallback = 'png') {
  if (!pathValue) return fallback;
  const match = /\.[a-z0-9]+(?=$|\?)/i.exec(pathValue);
  if (match && match[0]) {
    return match[0].slice(1).toLowerCase();
  }
  return fallback;
}

async function handleCatalogImageDownload({ id, name, image }) {
  const sourcePath = image || '';
  const resolvedUrl = resolveAssetUrl(sourcePath);
  if (!resolvedUrl) {
    showToast('Unable to resolve preview URL for this item.', 'error', 5000);
    return;
  }

  const extension = extractFileExtension(sourcePath, 'png');
  const filename = `${slugifyFilename(name || id || 'catalog-design')}.${extension}`;

  try {
    const result = await printStation.downloadFile({
      url: resolvedUrl,
      filename
    });
    if (result?.canceled) {
      showToast('Download canceled.', 'warning', 4000);
    } else {
      showToast('Catalog preview downloaded.', 'success');
    }
  } catch (error) {
    showToast(error.message || 'Unable to download preview.', 'error', 6000);
  }
}

function ensureNotificationPermission() {
  if (state.notificationPermissionRequested) return;
  if ('Notification' in window && Notification.permission === 'default') {
    Notification.requestPermission();
  }
  state.notificationPermissionRequested = true;
}

function notifyNewOrders(orders) {
  if (!orders.length) return;
  const count = orders.length;
  const titles = orders.slice(0, 3).map((order) => `#${order.orderNumber} • ${order.designName}`);
  const body =
    count > 3
      ? `${titles.join('\n')}\n+ ${count - 3} more`
      : titles.join('\n') || 'New print job ready.';

  showToast(`${count} new print job${count === 1 ? '' : 's'} added to the queue.`, 'success');
  ensureNotificationPermission();
  if ('Notification' in window && Notification.permission === 'granted') {
    new Notification('New print job ready', {
      body
    });
  }
}

function renderQueueTable() {
  const search = elements.queueSearchInput.value.trim().toLowerCase();
  const filtered = state.queue.filter((order) => {
    if (!search) return true;
    const haystack = [
      order.orderNumber,
      order.designName,
      order.designId,
      order.customer?.name,
      order.customer?.email,
      order.category
    ]
      .filter(Boolean)
      .join(' ')
      .toLowerCase();
    return haystack.includes(search);
  });

  state.filteredQueue = filtered;
  elements.queueTableBody.innerHTML = '';

  if (!filtered.length) {
    const row = document.createElement('tr');
    const cell = document.createElement('td');
    cell.colSpan = 6;
    cell.className = 'placeholder';
    cell.textContent = 'No orders match your filters.';
    row.appendChild(cell);
    elements.queueTableBody.appendChild(row);
    state.selectedOrderId = null;
    renderQueueDetail();
    return;
  }

  filtered.forEach((order) => {
    const row = document.createElement('tr');
    row.dataset.id = order.id;
    row.classList.toggle('selected', order.id === state.selectedOrderId);

    const customer = order.customer?.name || order.customer?.email || '—';
    const paymentBadge =
      order.paymentStatus === 'PAID' || order.paid
        ? '<span class="badge success">Paid</span>'
        : '<span class="badge warning">Unpaid</span>';
    const podBadge = order.pod ? '<span class="badge info">POD</span>' : '';

    row.innerHTML = `
      <td>${order.orderNumber ?? '—'}</td>
      <td>${order.designName || order.designId || 'Untitled design'} ${podBadge}</td>
      <td>${order.quantity ?? '—'}</td>
      <td>${customer}</td>
      <td>${formatDate(order.savedAt)}</td>
      <td>${paymentBadge}</td>
    `;

    row.addEventListener('click', () => {
      state.selectedOrderId = order.id;
      state.lastPreviewOpenedFor = null;
      renderQueueTable();
      renderQueueDetail(order);
    });

    elements.queueTableBody.appendChild(row);
  });

  const selected = filtered.find((order) => order.id === state.selectedOrderId);
  if (selected) {
    renderQueueDetail(selected);
  } else {
    state.selectedOrderId = filtered[0]?.id || null;
    renderQueueDetail(filtered[0]);
    renderQueueTable(); // re-render to highlight first if needed
  }
}

function filterQuotes() {
  const term = elements.quoteSearchInput.value.trim().toLowerCase();
  state.filteredQuotes = state.quotes.filter((quote) => {
    if (!term) return true;
    const haystack = [
      quote.quoteNumber,
      quote.business,
      quote.contactName,
      quote.packageOption,
      quote.status
    ]
      .filter(Boolean)
      .join(' ')
      .toLowerCase();
    return haystack.includes(term);
  });
  renderQuotesTable();
}

function renderQuotesTable() {
  if (!elements.quotesTableBody) return;
  elements.quotesTableBody.innerHTML = '';
  const list = state.filteredQuotes.length ? state.filteredQuotes : state.quotes;
  if (!list.length) {
    const row = document.createElement('tr');
    const cell = document.createElement('td');
    cell.colSpan = 6;
    cell.className = 'placeholder';
    cell.textContent = state.quotesLoading ? 'Loading race quotes…' : 'No race quotes found.';
    row.appendChild(cell);
    elements.quotesTableBody.appendChild(row);
    renderQuoteDetail(null);
    return;
  }

  list.forEach((quote) => {
    const row = document.createElement('tr');
    row.dataset.id = quote.id;
    row.classList.toggle('selected', quote.id === state.selectedQuoteId);
    row.innerHTML = `
      <td>${quote.quoteNumber ?? '—'}</td>
      <td>${quote.business || '—'}</td>
      <td>${getRacePackageLabel(quote.packageOption || '')}</td>
      <td>${quote.contactName || '—'}</td>
      <td>${formatQuoteStatus(quote.status)}</td>
      <td>${formatDate(quote.updatedAt || quote.createdAt)}</td>
    `;
    row.addEventListener('click', () => {
      state.selectedQuoteId = quote.id;
      renderQuotesTable();
      renderQuoteDetail(quote);
      if (!state.quoteDetails[quote.id]) {
        loadQuoteDetail(quote.id);
      }
    });
    elements.quotesTableBody.appendChild(row);
  });

  const selected = list.find((quote) => quote.id === state.selectedQuoteId);
  if (selected) {
    renderQuoteDetail(selected);
    if (!state.quoteDetails[selected.id]) {
      loadQuoteDetail(selected.id);
    }
  }
}

function renderQuoteDetail(quote) {
  if (!elements.quoteDetail) return;
  if (!quote) {
    elements.quoteDetail.innerHTML = '<p class="placeholder">Select a race quote to review details.</p>';
    return;
  }

  const detail = state.quoteDetails[quote.id];
  const current = detail?.quote || quote;
  const packageLabel = getRacePackageLabel(current.packageOption || '');
  const addonsLabel = (current.addons || []).map((addon) => formatAddonLabel(addon)).join(', ');
  const driverSummary = formatNameWithCountry(current.contactName || '', current.driverCountry);
  const coDriverSummary = formatNameWithCountry(current.coDriver || '', current.coDriverCountry);
  const quoteSummaryLines = [];
  if (driverSummary) {
    quoteSummaryLines.push(`<p class="muted">Driver: ${driverSummary}</p>`);
  }
  if (coDriverSummary) {
    quoteSummaryLines.push(`<p class="muted">Co-driver: ${coDriverSummary}</p>`);
  }
  if (current.carNumber) {
    quoteSummaryLines.push(`<p class="muted">Car #: ${current.carNumber}</p>`);
  }
  if (current.racingBody) {
    quoteSummaryLines.push(`<p class="muted">Series: ${current.racingBody}</p>`);
  }
  if (current.requestDate) {
    quoteSummaryLines.push(
      `<p class="muted">Requested: ${formatDate(current.requestDate)}</p>`
    );
  }

  const metaParts = [
    driverSummary ? `Driver: ${driverSummary}` : '',
    coDriverSummary ? `Co-driver: ${coDriverSummary}` : '',
    current.carNumber ? `Car #: ${current.carNumber}` : '',
    `Package: ${packageLabel}`,
    current.magnets ? 'Car number magnets: Yes (+$25)' : '',
    addonsLabel ? `Add-ons: ${addonsLabel}` : '',
    current.vehicle ? `Vehicle: ${current.vehicle}` : '',
    current.colors ? `Primary colors: ${current.colors}` : '',
    current.notes ? `Customer notes: ${current.notes}` : '',
    current.timelineText ? `Timeline: ${current.timelineText}` : '',
    current.deliveryText ? `Delivery: ${current.deliveryText}` : '',
    current.pricingNotes ? `Pricing notes: ${current.pricingNotes}` : '',
    current.quoteValidUntil ? `Valid until: ${current.quoteValidUntil}` : '',
    current.adminNotes ? `Shop notes: ${current.adminNotes}` : ''
  ]
    .filter(Boolean)
    .map((text) => `<p>${text}</p>`)
    .join('');
  const metaContent = metaParts || '<p>No additional details yet.</p>';
  const sponsorMarkup = renderSponsorSummary(current.sponsors);

  elements.quoteDetail.innerHTML = `
    <div class="quote-summary">
      <h3>${current.business || 'Race quote'}</h3>
      <p class="muted">Contact: ${current.contactName || '—'} · ${current.customer?.email || ''}</p>
      <p class="muted">Status: ${formatQuoteStatus(current.status)}</p>
      ${quoteSummaryLines.join('')}
    </div>

    <form id="quotePricingForm" class="quote-form">
      <fieldset>
        <legend>Pricing</legend>
        <label>
          <span>Base package</span>
          <input type="number" step="0.01" id="quoteBaseInput" />
        </label>
        <label>
          <span>Add-ons</span>
          <input type="number" step="0.01" id="quoteAddonsInput" />
        </label>
        <label>
          <span>Subtotal</span>
          <input type="number" step="0.01" id="quoteSubtotalInput" />
        </label>
        <label>
          <span>Sales tax</span>
          <input type="number" step="0.01" id="quoteTaxInput" />
        </label>
        <label>
          <span>Total</span>
          <input type="number" step="0.01" id="quoteTotalInput" />
        </label>
        <label>
          <span>Pricing notes</span>
          <textarea id="quotePricingNotesInput" rows="2"></textarea>
        </label>
      </fieldset>

      <fieldset>
        <legend>Timeline & Delivery</legend>
        <label>
          <span>Timeline</span>
          <input type="text" id="quoteTimelineInput" placeholder="e.g. Proof in 2 days, install next week" />
        </label>
        <label>
          <span>Delivery</span>
          <input type="text" id="quoteDeliveryInput" placeholder="e.g. Pick up at shop, shipping available" />
        </label>
        <label>
          <span>Valid until</span>
          <input type="text" id="quoteValidInput" placeholder="Optional date or timeframe" />
        </label>
        <label>
          <span>Shop notes (private)</span>
          <textarea id="quoteAdminNotesInput" rows="2"></textarea>
        </label>
      </fieldset>

      <label>
        <span>Status</span>
        <select id="quoteStatusSelect">
          <option value="submitted">Submitted</option>
          <option value="in_review">In review</option>
          <option value="quoted">Quoted</option>
          <option value="awaiting_payment">Awaiting payment</option>
          <option value="approved">Approved</option>
          <option value="paid">Paid</option>
          <option value="cancelled">Cancelled</option>
        </select>
      </label>

      <div class="quote-form-actions">
        <button type="submit" class="primary">Save updates</button>
        <button type="button" class="secondary" id="quoteGenerateAssetsButton">Generate cut JPEGs</button>
      </div>
    </form>

    <section class="quote-meta">
      <h4>Request summary</h4>
      ${metaContent}
      ${sponsorMarkup}
    </section>

    <section class="quote-files">
      <h4>Files</h4>
      <div id="quoteFilesContainer" class="quote-files-list">Loading files…</div>
    </section>

    <section class="quote-messages">
      <h4>Conversation</h4>
      <div id="quoteMessagesContainer" class="quote-messages-list">Loading messages…</div>
      <form id="quoteMessageForm" class="quote-message-form">
        <textarea id="quoteMessageInput" rows="3" placeholder="Send an update to the customer…"></textarea>
        <button type="submit" class="secondary">Send message</button>
      </form>
    </section>

    <section class="quote-sms">
      <h4>SMS Conversation</h4>
      <div class="inventory-table-wrapper">
        <table class="inventory-table">
          <thead>
            <tr><th>When</th><th>From</th><th>To</th><th>Message</th></tr>
          </thead>
          <tbody id="quoteSmsTableBody"><tr><td colspan="4" class="placeholder">${(current.customer?.phone ? 'Loading…' : 'No phone on file')}</td></tr></tbody>
        </table>
      </div>
      <div class="inventory-form-grid" style="margin-top:8px;">
        <label><span>Reply to</span><input id="quoteSmsTo" type="tel" placeholder="+15551234567" /></label>
        <label class="full"><span>Message</span><textarea id="quoteSmsText" rows="2" placeholder="Type a reply…"></textarea></label>
      </div>
      <div class="inventory-form-actions" style="display:flex;gap:8px;justify-content:flex-end;">
        <button id="quoteSmsSend" type="button" class="secondary">Send SMS</button>
      </div>
      <div id="quoteSmsStatus" class="status-bar muted">Ready.</div>
    </section>
  `;

  const fields = {
    base: document.getElementById('quoteBaseInput'),
    addons: document.getElementById('quoteAddonsInput'),
    subtotal: document.getElementById('quoteSubtotalInput'),
    tax: document.getElementById('quoteTaxInput'),
    total: document.getElementById('quoteTotalInput'),
    pricingNotes: document.getElementById('quotePricingNotesInput'),
    timeline: document.getElementById('quoteTimelineInput'),
    delivery: document.getElementById('quoteDeliveryInput'),
    valid: document.getElementById('quoteValidInput'),
    adminNotes: document.getElementById('quoteAdminNotesInput'),
    status: document.getElementById('quoteStatusSelect')
  };

  const toDollars = (cents) => (Number.isFinite(cents) ? (cents / 100).toFixed(2) : '');

  fields.base.value = toDollars(current.baseCents);
  fields.addons.value = toDollars(current.addonsCents);
  fields.subtotal.value = toDollars(current.subtotalCents);
  fields.tax.value = toDollars(current.taxCents);
  fields.total.value = toDollars(current.totalCents);
  fields.pricingNotes.value = current.pricingNotes || '';
  fields.timeline.value = current.timelineText || '';
  fields.delivery.value = current.deliveryText || '';
  fields.valid.value = current.quoteValidUntil || '';
  fields.adminNotes.value = current.adminNotes || '';
  fields.status.value = (current.status || 'submitted').toLowerCase();

  const pricingForm = document.getElementById('quotePricingForm');
  pricingForm.addEventListener('submit', (event) => {
    event.preventDefault();
    handleQuoteUpdate(current.id, fields, pricingForm.querySelector('button[type="submit"]'));
  });

  const generateButton = document.getElementById('quoteGenerateAssetsButton');
  if (generateButton) {
    generateButton.addEventListener('click', () => {
      handleQuoteGenerateAssets(current.id, generateButton);
    });
  }

  const messageForm = document.getElementById('quoteMessageForm');
  const messageInput = document.getElementById('quoteMessageInput');
  const messagesContainer = document.getElementById('quoteMessagesContainer');
  const filesContainer = document.getElementById('quoteFilesContainer');
  messageForm.addEventListener('submit', (event) => {
    event.preventDefault();
    handleQuoteMessageSend(current.id, messageInput, messagesContainer, messageForm.querySelector('button'));
  });

  if (detail) {
    renderQuoteMessages(messagesContainer, detail.messages);
    renderQuoteAttachments(filesContainer, detail.files);
  } else {
    messagesContainer.textContent = 'Loading messages…';
    filesContainer.textContent = 'Loading files…';
  }

  // SMS thread for quote
  try {
    const smsToInput = document.getElementById('quoteSmsTo');
    const smsTextInput = document.getElementById('quoteSmsText');
    const smsSendBtn = document.getElementById('quoteSmsSend');
    const smsTableBody = document.getElementById('quoteSmsTableBody');
    const smsStatus = document.getElementById('quoteSmsStatus');
    const phone = (current.customer && current.customer.phone) ? String(current.customer.phone).trim() : '';
    if (smsToInput) smsToInput.value = phone || '';
    async function loadQuoteSms() {
      if (!smsTableBody) return;
      if (!phone) { smsTableBody.innerHTML = '<tr><td colspan="4" class="placeholder">No phone on file.</td></tr>'; return; }
      smsTableBody.innerHTML = '<tr><td colspan="4" class="placeholder">Loading…</td></tr>';
      try {
        const data = await printStation.listInboundMessages({ phone, limit: 200 });
        const items = Array.isArray(data?.items) ? data.items : [];
        const rows = items.map((m) => {
          const when = m.createdAt ? new Date(m.createdAt).toLocaleString() : '';
          const body = String(m.body || '').replace(/</g, '&lt;');
          return `<tr><td>${when}</td><td>${m.from || ''}</td><td>${m.to || ''}</td><td style="max-width:520px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;" title="${body}">${body}</td></tr>`;
        }).join('');
        smsTableBody.innerHTML = rows || '<tr><td colspan="4" class="placeholder">No messages.</td></tr>';
      } catch (e) {
        smsTableBody.innerHTML = '<tr><td colspan="4" class="placeholder">Unable to load messages.</td></tr>';
      }
    }
    if (phone) loadQuoteSms();
    if (smsSendBtn) {
      smsSendBtn.addEventListener('click', async () => {
        if (!smsStatus) return;
        const to = (smsToInput?.value || '').trim();
        const text = (smsTextInput?.value || '').trim();
        if (!to || !text) { smsStatus.textContent = 'Enter phone and message.'; smsStatus.className = 'status-bar warning'; return; }
        smsStatus.textContent = 'Sending…'; smsStatus.className = 'status-bar muted';
        try {
          await printStation.sendSms({ to, message: text });
          smsStatus.textContent = 'Sent.'; smsStatus.className = 'status-bar success';
          if (smsTextInput) smsTextInput.value = '';
          await loadQuoteSms();
        } catch (err) {
          smsStatus.textContent = err?.message || 'Send failed'; smsStatus.className = 'status-bar error';
        }
      });
    }
  } catch (_) {}
}

async function handleQuoteUpdate(quoteId, fields, submitButton) {
  if (!quoteId) return;
  const payload = {
    status: fields.status.value,
    pricingNotes: fields.pricingNotes.value.trim(),
    timelineText: fields.timeline.value.trim(),
    deliveryText: fields.delivery.value.trim(),
    quoteValidUntil: fields.valid.value.trim(),
    adminNotes: fields.adminNotes.value.trim()
  };

  const parseMoney = (input) => {
    const value = parseFloat(input.value);
    if (Number.isFinite(value)) {
      return Math.round(value * 100);
    }
    return null;
  };

  const baseCents = parseMoney(fields.base);
  const addonsCents = parseMoney(fields.addons);
  const subtotalCents = parseMoney(fields.subtotal);
  const taxCents = parseMoney(fields.tax);
  const totalCents = parseMoney(fields.total);

  if (baseCents !== null) payload.baseCents = baseCents;
  if (addonsCents !== null) payload.addonsCents = addonsCents;
  if (subtotalCents !== null) payload.subtotalCents = subtotalCents;
  if (taxCents !== null) payload.taxCents = taxCents;
  if (totalCents !== null) payload.totalCents = totalCents;

  submitButton.disabled = true;
  try {
    const response = await printStation.updateRaceQuote(quoteId, payload);
    if (response?.quote) {
      updateQuoteInState(response.quote);
      state.quoteDetails[quoteId] = null;
      renderQuotesTable();
      showToast('Quote updated.', 'success');
    }
  } catch (error) {
    console.error('handleQuoteUpdate error:', error);
    showToast(error.message || 'Unable to update quote.', 'error', 5000);
  } finally {
    submitButton.disabled = false;
  }
}

async function handleQuoteGenerateAssets(quoteId, button) {
  if (!quoteId) return;
  if (button) {
    button.disabled = true;
  }
  showToast('Generating cut JPEGs…', 'info');
  try {
    const response = await printStation.generateQuoteAssets(quoteId);
    if (response?.success) {
      const count = Array.isArray(response.files) ? response.files.length : 0;
      const suffix = count === 1 ? '' : 's';
      const detail = response.outputDir ? ` → ${response.outputDir}` : '';
      showToast(`Generated ${count} JPEG${suffix}${detail}`, 'success', 6000);
    } else if (response?.cancelled) {
      showToast('Generation cancelled.', 'info');
    } else {
      throw new Error(response?.error || 'Unable to generate JPEGs.');
    }
  } catch (error) {
    console.error('handleQuoteGenerateAssets error:', error);
    showToast(error.message || 'Unable to generate JPEGs.', 'error', 6000);
  } finally {
    if (button) {
      button.disabled = false;
    }
  }
}

function renderQuoteMessages(container, messages = []) {
  if (!container) return;
  container.innerHTML = '';
  if (!messages.length) {
    const empty = document.createElement('p');
    empty.className = 'hint';
    empty.textContent = 'No messages yet.';
    container.appendChild(empty);
    return;
  }
  messages.forEach((message) => {
    const bubble = document.createElement('div');
    bubble.className = `quote-message quote-message--${message.sender || 'customer'}`;
    const meta = document.createElement('span');
    meta.className = 'quote-message__meta';
    const when = message.createdAt ? new Date(message.createdAt).toLocaleString() : '';
    meta.textContent = `${message.sender === 'shop' ? 'Shop' : 'Customer'} · ${when}`;
    const body = document.createElement('p');
    body.className = 'quote-message__body';
    body.textContent = message.message;
    bubble.appendChild(meta);
    bubble.appendChild(body);
    container.appendChild(bubble);
  });
}

function updateCampaignBulkStatus() {
  const status = elements.campaignBulkStatus;
  if (!status) return;
  const count = state.campaign.selection.size;
  if (!count) {
    status.textContent = 'Select items to enable bulk edits.';
    return;
  }
  status.textContent = `Selected ${count} item${count === 1 ? '' : 's'}.`;
}

function handleCampaignSelectItem(uid, checked) {
  if (!uid) return;
  const selection = new Set(state.campaign.selection);
  if (checked) selection.add(uid);
  else selection.delete(uid);
  state.campaign.selection = selection;
  updateCampaignBulkStatus();
}

function applyCampaignSelectionForAll(apply) {
  const selection = apply
    ? new Set((state.campaign.items || []).map((item) => item.uid).filter(Boolean))
    : new Set();
  state.campaign.selection = selection;
  updateCampaignBulkStatus();
}

function applyBulkProductType(type) {
  if (!type) return;
  const selection = state.campaign.selection;
  const items = state.campaign.items || [];
  const updated = [];
  items.forEach((item) => {
    if (selection.has(item.uid)) {
      item.productType = type;
      updated.push(item);
    }
  });
  if (!updated.length) {
    showToast('Select items before applying a bulk type.', 'warning');
    return;
  }
  showToast(`Applied ${type} to ${updated.length} item${updated.length === 1 ? '' : 's'}.`, 'success');
  renderCampaignItems();
}

function resetCampaignSelection() {
  state.campaign.selection.clear();
  updateCampaignBulkStatus();
}

function ensureSalesInitiativeState() {
  if (!state.campaign.salesInitiative) {
    state.campaign.salesInitiative = getDefaultSalesInitiative();
  }
}

function renderSalesInitiativeSummary() {
  ensureSalesInitiativeState();
  const summary = elements.campaignSalesSummary;
  if (!summary) return;
  const promo = state.campaign.salesInitiative;

  let summaryText = 'No promotion configured.';
  let summaryClass = 'muted';

  switch (promo?.type) {
    case 'percentOff':
      summaryText = `${promo.percentOff}% off`;
      if (promo.percentMinQty > 0) summaryText += ` (min ${promo.percentMinQty} items)`;
      summaryClass = 'success';
      break;
    case 'fixedOff':
      summaryText = `$${promo.fixedAmount} off`;
      if (promo.fixedMinOrder > 0) summaryText += ` orders over $${promo.fixedMinOrder}`;
      summaryClass = 'success';
      break;
    case 'buyXGetY': {
      const buyPart = promo.buySize ? `${promo.buyQuantity} ${promo.buySize}` : String(promo.buyQuantity);
      const freePart = promo.freeSize ? `${promo.freeQuantity} ${promo.freeSize}` : String(promo.freeQuantity);
      summaryText = `Buy ${buyPart}, get ${freePart} free`;
      summaryClass = 'success';
      break;
    }
    case 'bundle':
      summaryText = `Any ${promo.bundleQty} for $${promo.bundlePrice}`;
      summaryClass = 'success';
      break;
    case 'freeShipping':
      summaryText = `Free shipping on orders over $${promo.freeShipThreshold}`;
      summaryClass = 'success';
      break;
    case 'tiered':
      summaryText = `${promo.tier1Percent}%/${promo.tier2Percent}%/${promo.tier3Percent}% tiered discount`;
      summaryClass = 'success';
      break;
  }

  summary.className = `status-bar ${summaryClass}`;
  summary.textContent = summaryText;

  if (promo?.description && promo.type !== 'none') {
    summary.innerHTML = `${summaryText}<div class="hint" style="margin-top:4px;">${escapeHtml(promo.description)}</div>`;
  }

  // Show/hide promo results section
  if (elements.campaignPromoResults) {
    elements.campaignPromoResults.style.display = (promo?.shopifyDiscountId || promo?.type !== 'none') ? '' : 'none';
  }
}

function showPromoFieldsForType(type) {
  // Hide all promo field groups
  const allFields = [
    elements.promoPercentFields,
    elements.promoFixedFields,
    elements.promoBuyXGetYFields,
    elements.promoBundleFields,
    elements.promoShippingFields,
    elements.promoTieredFields
  ];
  allFields.forEach(el => { if (el) el.style.display = 'none'; });

  // Show the relevant fields
  switch (type) {
    case 'percentOff':
      if (elements.promoPercentFields) elements.promoPercentFields.style.display = '';
      break;
    case 'fixedOff':
      if (elements.promoFixedFields) elements.promoFixedFields.style.display = '';
      break;
    case 'buyXGetY':
      if (elements.promoBuyXGetYFields) elements.promoBuyXGetYFields.style.display = '';
      break;
    case 'bundle':
      if (elements.promoBundleFields) elements.promoBundleFields.style.display = '';
      break;
    case 'freeShipping':
      if (elements.promoShippingFields) elements.promoShippingFields.style.display = '';
      break;
    case 'tiered':
      if (elements.promoTieredFields) elements.promoTieredFields.style.display = '';
      break;
  }

  // Auto-generate description if empty
  autoGeneratePromoDescription(type);
}

function autoGeneratePromoDescription(type) {
  ensureSalesInitiativeState();
  const promo = state.campaign.salesInitiative;

  // Only auto-generate if description is empty or matches a previous auto-generated one
  const currentDesc = promo.description || '';
  const autoDescPatterns = [
    /^Save \d+% on/i,
    /^\$\d+ off/i,
    /^Buy \d+, get \d+ free/i,
    /^Bundle deal:/i,
    /^Free shipping on/i,
    /^Save more when you buy more/i
  ];
  const isAutoGenerated = !currentDesc || autoDescPatterns.some(p => p.test(currentDesc));

  if (!isAutoGenerated) return;

  let newDesc = '';
  switch (type) {
    case 'percentOff':
      newDesc = `Save ${promo.percentOff}% on your order`;
      if (promo.percentMinQty > 0) newDesc += ` when you buy ${promo.percentMinQty}+ items`;
      break;
    case 'fixedOff':
      newDesc = `$${promo.fixedAmount} off`;
      if (promo.fixedMinOrder > 0) newDesc += ` orders over $${promo.fixedMinOrder}`;
      break;
    case 'buyXGetY': {
      const buyPart = promo.buySize ? `${promo.buyQuantity} ${promo.buySize}s` : String(promo.buyQuantity);
      const freePart = promo.freeSize ? `${promo.freeQuantity} ${promo.freeSize}s` : String(promo.freeQuantity);
      newDesc = `Buy ${buyPart}, get ${freePart} free!`;
      break;
    }
    case 'bundle':
      newDesc = `Bundle deal: Any ${promo.bundleQty} for just $${promo.bundlePrice}`;
      break;
    case 'freeShipping':
      newDesc = `Free shipping on orders over $${promo.freeShipThreshold}`;
      break;
    case 'tiered':
      newDesc = 'Save more when you buy more!';
      break;
    default:
      newDesc = '';
  }

  if (newDesc && elements.campaignSalesDescription) {
    elements.campaignSalesDescription.value = newDesc;
    promo.description = newDesc;
  }
}

function syncSalesInitiativeInputs() {
  ensureSalesInitiativeState();
  const promo = state.campaign.salesInitiative;

  // Type selector
  if (elements.campaignSalesType) elements.campaignSalesType.value = promo.type || 'none';

  // Buy X Get Y fields
  if (elements.campaignSalesBuy) elements.campaignSalesBuy.value = String(promo.buyQuantity || 2);
  if (elements.campaignBuySize) elements.campaignBuySize.value = promo.buySize || '';
  if (elements.campaignSalesFree) elements.campaignSalesFree.value = String(promo.freeQuantity || 2);
  if (elements.campaignFreeSize) elements.campaignFreeSize.value = promo.freeSize || '';

  // Percentage discount fields
  if (elements.campaignPromoPercent) elements.campaignPromoPercent.value = String(promo.percentOff || 15);
  if (elements.campaignPromoMinQty) elements.campaignPromoMinQty.value = String(promo.percentMinQty || 0);

  // Fixed amount off fields
  if (elements.campaignPromoFixedAmount) elements.campaignPromoFixedAmount.value = String(promo.fixedAmount || 5);
  if (elements.campaignPromoMinOrder) elements.campaignPromoMinOrder.value = String(promo.fixedMinOrder || 0);

  // Bundle pricing fields
  if (elements.campaignBundleQty) elements.campaignBundleQty.value = String(promo.bundleQty || 3);
  if (elements.campaignBundlePrice) elements.campaignBundlePrice.value = String(promo.bundlePrice || 25);

  // Free shipping fields
  if (elements.campaignFreeShipThreshold) elements.campaignFreeShipThreshold.value = String(promo.freeShipThreshold || 50);

  // Tiered discount fields
  if (elements.campaignTier1Percent) elements.campaignTier1Percent.value = String(promo.tier1Percent || 10);
  if (elements.campaignTier2Percent) elements.campaignTier2Percent.value = String(promo.tier2Percent || 20);
  if (elements.campaignTier3Percent) elements.campaignTier3Percent.value = String(promo.tier3Percent || 30);

  // Common fields
  if (elements.campaignSalesDescription) elements.campaignSalesDescription.value = promo.description || '';
  if (elements.campaignPromoCode) elements.campaignPromoCode.value = promo.promoCode || '';
  if (elements.campaignPromoStartDate) elements.campaignPromoStartDate.value = promo.startDate || '';
  if (elements.campaignPromoEndDate) elements.campaignPromoEndDate.value = promo.endDate || '';
  if (elements.campaignPromoApplyToShopify) elements.campaignPromoApplyToShopify.checked = promo.applyToShopify !== false;

  // Show the correct fields for the current type
  showPromoFieldsForType(promo.type || 'none');
}

function updateSalesInitiativeField(key, value) {
  ensureSalesInitiativeState();
  state.campaign.salesInitiative = {
    ...state.campaign.salesInitiative,
    [key]: value
  };
  renderSalesInitiativeSummary();
}

async function refreshPromoStats() {
  const promo = state.campaign?.salesInitiative;
  if (!promo || promo.type === 'none') {
    showToast('No promotion configured.', 'warning');
    return;
  }

  // Update UI to show loading
  if (elements.promoStatOrders) elements.promoStatOrders.textContent = '...';
  if (elements.promoStatRevenue) elements.promoStatRevenue.textContent = '...';
  if (elements.promoStatSavings) elements.promoStatSavings.textContent = '...';

  try {
    // If we have a Shopify discount ID, fetch stats for it
    if (promo.shopifyDiscountId) {
      const stats = await printStation.getPromoStats(promo.shopifyDiscountId);
      if (stats) {
        if (elements.promoStatOrders) elements.promoStatOrders.textContent = stats.orders || '0';
        if (elements.promoStatRevenue) elements.promoStatRevenue.textContent = `$${(stats.revenue / 100).toFixed(2)}`;
        if (elements.promoStatSavings) elements.promoStatSavings.textContent = `$${(stats.discountsGiven / 100).toFixed(2)}`;
        showToast('Promo stats refreshed.', 'success');
        return;
      }
    }

    // Fallback: show placeholder stats
    if (elements.promoStatOrders) elements.promoStatOrders.textContent = '0';
    if (elements.promoStatRevenue) elements.promoStatRevenue.textContent = '$0.00';
    if (elements.promoStatSavings) elements.promoStatSavings.textContent = '$0.00';
    showToast('No stats available yet. Export campaign to Shopify first.', 'info');
  } catch (err) {
    console.error('refreshPromoStats error:', err);
    if (elements.promoStatOrders) elements.promoStatOrders.textContent = '-';
    if (elements.promoStatRevenue) elements.promoStatRevenue.textContent = '-';
    if (elements.promoStatSavings) elements.promoStatSavings.textContent = '-';
    showToast(err?.message || 'Unable to fetch promo stats.', 'error');
  }
}

function renderQuoteAttachments(container, files = []) {
  if (!container) return;
  container.innerHTML = '';
  if (!files.length) {
    const empty = document.createElement('p');
    empty.className = 'hint';
    empty.textContent = 'No files uploaded yet.';
    container.appendChild(empty);
    return;
  }
  const list = document.createElement('ul');
  list.className = 'quote-file-list';
  files.forEach((file) => {
    const item = document.createElement('li');
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'secondary';
    button.textContent = file.originalName || 'Download';
    button.disabled = !file.url;
    button.addEventListener('click', () => {
      if (file.url) {
        const target = file.url.startsWith('http') ? file.url : buildServerUrl(file.url);
        if (target) {
          printStation.openExternal(target);
        }
      }
    });
    const meta = document.createElement('span');
    meta.className = 'quote-file-meta';
    const sizeKb = file.size ? `${(file.size / 1024).toFixed(1)} KB` : '';
    const uploaded = file.createdAt ? new Date(file.createdAt).toLocaleString() : '';
    meta.textContent = [sizeKb, uploaded].filter(Boolean).join(' · ');
    item.appendChild(button);
    if (meta.textContent) {
      item.appendChild(meta);
    }
    list.appendChild(item);
  });
  container.appendChild(list);
}

async function handleQuoteMessageSend(quoteId, input, container, button) {
  const message = input.value.trim();
  if (!message) {
    showToast('Enter a message before sending.', 'error');
    return;
  }
  button.disabled = true;
  try {
    const response = await printStation.postRaceQuoteMessage(quoteId, message);
    if (response?.message) {
      const cache = state.quoteDetails[quoteId] || { quote: null, messages: [], files: [] };
      cache.messages = [...(cache.messages || []), response.message];
      state.quoteDetails[quoteId] = cache;
      input.value = '';
      renderQuoteMessages(container, cache.messages);
      showToast('Message sent.', 'success');
    }
  } catch (error) {
    console.error('handleQuoteMessageSend error:', error);
    showToast(error.message || 'Unable to send message.', 'error');
  } finally {
    button.disabled = false;
  }
}

async function loadQuoteDetail(id) {
  try {
    const detail = await printStation.fetchRaceQuoteDetail(id);
    if (detail?.quote) {
      updateQuoteInState(detail.quote);
      state.quoteDetails[id] = {
        quote: detail.quote,
        messages: Array.isArray(detail.messages) ? detail.messages : [],
        files: Array.isArray(detail.files) ? detail.files : []
      };
      if (state.selectedQuoteId === id) {
        renderQuoteDetail(detail.quote);
      }
    }
  } catch (error) {
    console.error('loadQuoteDetail error:', error);
    showToast(error.message || 'Unable to load quote detail.', 'error');
  }
}

async function refreshQuotes({ silent = false } = {}) {
  if (state.quotesLoading) return;
  if (!silent) {
    showToast('Refreshing race quotes…', 'info');
  }
  state.quotesLoading = true;
  try {
    const payload = await printStation.fetchRaceQuotes();
    state.quotes = Array.isArray(payload?.quotes) ? payload.quotes : [];
    state.quotes.forEach((quote) => {
      if (state.quoteDetails[quote.id]) {
        state.quoteDetails[quote.id].quote = quote;
      }
    });
    filterQuotes();
  } catch (error) {
    console.error('refreshQuotes error:', error);
    showToast(error.message || 'Unable to load race quotes.', 'error');
  } finally {
    state.quotesLoading = false;
  }
}

function updateQuoteInState(updated) {
  if (!updated) return;
  const index = state.quotes.findIndex((quote) => quote.id === updated.id);
  if (index >= 0) {
    state.quotes[index] = updated;
  } else {
    state.quotes.unshift(updated);
  }
  if (state.quoteDetails[updated.id]) {
    state.quoteDetails[updated.id].quote = updated;
  }
  filterQuotes();
}

function formatQuoteStatus(status) {
  switch ((status || '').toLowerCase()) {
    case 'in_review':
      return 'In review';
    case 'quoted':
      return 'Quoted';
    case 'awaiting_payment':
      return 'Awaiting payment';
    case 'approved':
      return 'Approved';
    case 'paid':
      return 'Paid';
    case 'cancelled':
      return 'Cancelled';
    case 'submitted':
    default:
      return 'Submitted';
  }
}

function getRacePackageLabel(value) {
  switch ((value || '').toLowerCase()) {
    case 'basic':
      return 'Basic Number Kit';
    case 'sponsor':
      return 'Sponsor Kit';
    case 'pro':
      return 'Pro Package';
    case 'elite':
      return 'Elite Custom Kit';
    default:
      return value || 'Package';
  }
}

function getSponsorSizeLabel(value) {
  if (!value) return '';
  const key = String(value).toLowerCase();
  return SPONSOR_SIZE_LABELS[key] || value;
}

function formatAddonLabel(value) {
  if (!value) return '';
  return value
    .split(/[-_]/g)
    .map((segment) => segment.charAt(0).toUpperCase() + segment.slice(1))
    .join(' ');
}

function formatCountryLabel(code) {
  if (!code) return '';
  const normalized = String(code).trim().toUpperCase();
  return COUNTRY_NAMES[normalized] || normalized;
}

function formatNameWithCountry(name, country) {
  if (!name) return '';
  const label = formatCountryLabel(country);
  return label ? `${name} (${label})` : name;
}

// ============================================================================
// DRIVER / CO-DRIVER NAME GENERATOR
// ============================================================================

const DN_SIZE_MAP = {
  'ARA': '2.5"', 'SCCA': '2"', 'NASA_E30': '3"',
  'NASA_S3': '3"', 'RallyCross': '2.5"', 'AutoCross': '2"'
};

function openDriverNamesModal() {
  const modal = document.getElementById('driverNamesModal');
  if (modal) {
    modal.style.display = 'flex';
    document.getElementById('dnResultArea').style.display = 'none';
    updateDnSizePreview();
  }
}

function closeDriverNamesModal() {
  const modal = document.getElementById('driverNamesModal');
  if (modal) modal.style.display = 'none';
}

function updateDnSizePreview() {
  const body = document.getElementById('dnRacingBody')?.value || 'ARA';
  const el = document.getElementById('dnSizePreview');
  if (el) el.textContent = `${body}: ${DN_SIZE_MAP[body] || '2.5"'} height, bold sans-serif, with national flag`;
}

async function generateDriverNames(sendToEditor) {
  const driverName = document.getElementById('dnDriverName')?.value?.trim();
  const coDriverName = document.getElementById('dnCoDriverName')?.value?.trim();
  const country = document.getElementById('dnCountry')?.value || 'US';
  const racingBody = document.getElementById('dnRacingBody')?.value || 'ARA';

  if (!driverName) {
    showToast('Driver name is required', 'error');
    return;
  }

  const genBtn = document.getElementById('dnGenerateBtn');
  const editorBtn = document.getElementById('dnEditorBtn');
  if (genBtn) genBtn.disabled = true;
  if (editorBtn) editorBtn.disabled = true;

  try {
    const result = await printStation.vinylCutter.generateDriverNames({
      driverName, coDriverName, country, racingBody
    });

    if (!result || !result.success) {
      throw new Error(result?.error || 'Generation failed');
    }

    // Show result area with preview
    const resultArea = document.getElementById('dnResultArea');
    resultArea.style.display = 'block';

    // SVG preview — render inline
    const previewEl = document.getElementById('dnPreviewSvg');
    if (previewEl && result.svgContent) {
      previewEl.innerHTML = result.svgContent;
      // Scale SVG to fit preview
      const svg = previewEl.querySelector('svg');
      if (svg) {
        svg.style.maxWidth = '100%';
        svg.style.maxHeight = '120px';
        svg.style.width = 'auto';
        svg.style.height = 'auto';
      }
    }

    // Download link
    const downloadLink = document.getElementById('dnDownloadLink');
    if (downloadLink && result.downloadUrl) {
      const config = await printStation.getConfig();
      const base = config?.serverBaseUrl || '';
      downloadLink.href = base + result.downloadUrl;
      downloadLink.download = `driver-names-${driverName}.svg`;
    }

    if (sendToEditor) {
      // Switch to vinyl cutter view and add the SVG
      window.switchView('vinylCutterView');
      closeDriverNamesModal();

      // Add to vinyl cutter canvas if available
      if (typeof addDriverNameToVinylCanvas === 'function') {
        addDriverNameToVinylCanvas(result);
      }
    }

    showToast(`Driver names generated! (${DN_SIZE_MAP[racingBody] || '2.5"'} height)`, 'success');

  } catch (err) {
    showToast('Failed: ' + err.message, 'error');
    console.error('[Driver Names]', err);
  } finally {
    if (genBtn) genBtn.disabled = false;
    if (editorBtn) editorBtn.disabled = false;
  }
}

function addDriverNameToVinylCanvas(result) {
  if (!result.svgContent) return;
  // If vinyl cutter editor is loaded and has fabric.js canvas
  if (typeof initVinylCutterEditor === 'function' && typeof fabric !== 'undefined') {
    if (!window.vinylCutterState?.canvas) {
      initVinylCutterEditor();
    }
    const canvas = window.vinylCutterState?.canvas;
    if (!canvas) return;

    fabric.loadSVGFromString(result.svgContent, (objects, options) => {
      if (!objects || objects.length === 0) return;
      const group = fabric.util.groupSVGElements(objects, options);
      group.set({
        left: 50,
        top: 50,
        selectable: true,
        hasControls: true,
        hasBorders: true,
        cornerStyle: 'circle',
        cornerColor: '#8b5cf6',
        borderColor: '#8b5cf6'
      });
      group.vinylData = {
        id: `driver-name-${Date.now()}`,
        title: `Driver Names`,
        colors: [{ hex: '#000000', name: 'Black', contourPath: null, count: 1, percentage: 100 }]
      };
      canvas.add(group);
      canvas.setActiveObject(group);
      canvas.renderAll();
      if (window.vinylCutterState?.items) {
        window.vinylCutterState.items.push(group);
      }
    });
  }
}

// Wire up driver names UI
(function wireDriverNamesUI() {
  const wire = () => {
    const btn = document.getElementById('createDriverNamesBtn');
    if (btn) btn.addEventListener('click', openDriverNamesModal);

    const closeBtn = document.getElementById('dnCloseBtn');
    if (closeBtn) closeBtn.addEventListener('click', closeDriverNamesModal);

    const genBtn = document.getElementById('dnGenerateBtn');
    if (genBtn) genBtn.addEventListener('click', () => generateDriverNames(false));

    const editorBtn = document.getElementById('dnEditorBtn');
    if (editorBtn) editorBtn.addEventListener('click', () => generateDriverNames(true));

    const racingSelect = document.getElementById('dnRacingBody');
    if (racingSelect) racingSelect.addEventListener('change', updateDnSizePreview);

    // Close modal on overlay click
    const modal = document.getElementById('driverNamesModal');
    if (modal) {
      modal.addEventListener('click', (e) => {
        if (e.target === modal) closeDriverNamesModal();
      });
    }
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', wire);
  } else {
    wire();
  }
})();

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function renderTextLayers(list = []) {
  if (!Array.isArray(list) || !list.length) {
    return '<p class="hint">No custom text layers.</p>';
  }
  return `
    <div class="text-layer-list">
      ${list
        .map(
          (layer, idx) => `
            <div class="text-layer-item">
              <strong>Line ${idx + 1}:</strong> ${layer.content || ''}
              <div class="hint">
                Font: ${layer.font || '—'} • Size: ${layer.fontSize || '—'} • Color: ${
            layer.color || '—'
          }
              </div>
            </div>
          `
        )
        .join('')}
    </div>
  `;
}

function renderSponsorSummary(list = []) {
  if (!Array.isArray(list) || !list.length) {
    return '';
  }
  const sponsors = list.filter((entry) => entry && entry.name);
  if (!sponsors.length) {
    return '';
  }

  const items = sponsors
    .map((sponsor) => {
      const details = [];
      const sizeLabel = getSponsorSizeLabel(sponsor.size);
      if (sizeLabel) {
        details.push(sizeLabel);
      }
      if (sponsor.color) {
        details.push(`Color: ${sponsor.color}`);
      }
      if (sponsor.apparel) {
        details.push('Include on apparel');
      }
      const detailText = details.length
        ? `<span class="quote-sponsor-meta">${details.join(' • ')}</span>`
        : '';
      return `
        <li>
          <span class="quote-sponsor-name">${sponsor.name}</span>
          ${detailText}
        </li>
      `;
    })
    .join('');

  if (!items) {
    return '';
  }

  return `
    <div class="quote-sponsors">
      <h4>Sponsor decals</h4>
      <ul class="quote-sponsor-list">
        ${items}
      </ul>
    </div>
  `;
}

function renderApparelItems(list = []) {
  if (!Array.isArray(list) || !list.length) {
    return '';
  }
  const subtotalCents = list.reduce((sum, item) => {
    if (Number.isFinite(item.lineTotalCents)) return sum + item.lineTotalCents;
    if (Number.isFinite(item.unitPriceCents)) {
      return sum + item.unitPriceCents * Math.max(1, Number(item.quantity) || 1);
    }
    return sum;
  }, 0);
  const items = list
    .map((item) => {
      const quantityLabel = escapeHtml(String(item.quantity || 1));
      const quantityValue = Math.max(1, Number(item.quantity) || 1);
      const title = escapeHtml(item.title || item.handle || 'Apparel item');
      const parts = [];
      if (item.color) parts.push(item.color);
      if (item.size) parts.push(item.size);
      parts.push(`SKU ${item.sku}`);
      const meta = escapeHtml(parts.join(' • '));
      const productLink = item.productUrl
        ? `<button type="button" class="link-button" data-action="open-apparel" data-url="${encodeURIComponent(
            item.productUrl
          )}">Product page</button>`
        : '';
      const imageLink = item.imageUrl
        ? `<button type="button" class="link-button" data-action="open-apparel-image" data-url="${encodeURIComponent(
            item.imageUrl
          )}">Open image</button>`
        : '';
      const lineTotalCents = Number.isFinite(item.lineTotalCents) ? item.lineTotalCents : 0;
      const unitPriceCents = Number.isFinite(item.unitPriceCents)
        ? item.unitPriceCents
        : lineTotalCents && quantityValue > 0
        ? Math.round(lineTotalCents / quantityValue)
        : 0;
      const price = lineTotalCents
        ? `<div class="queue-apparel-price">${escapeHtml(
            `${formatMoney(unitPriceCents)} each · ${formatMoney(lineTotalCents)}`
          )}</div>`
        : '';
      let warningText = '';
      if (!item.imageUrl && item.imageStatus?.status) {
        warningText =
          item.imageStatus.status === 403
            ? 'Preview blocked by vendor (HTTP 403).'
            : `Preview unavailable (HTTP ${item.imageStatus.status}).`;
      }
      const warning = warningText
        ? `<div class="queue-apparel-warning">${escapeHtml(warningText)}</div>`
        : '';
      return `
        <li>
          <div class="queue-apparel-name">${quantityLabel} × ${title}</div>
          <div class="queue-apparel-meta">${meta}</div>
          ${productLink}
          ${imageLink}
          ${price}
          ${warning}
        </li>
      `;
    })
    .join('');
  const subtotalLine = subtotalCents
    ? `<div class="queue-apparel-total">Apparel subtotal: ${escapeHtml(formatMoney(subtotalCents))}</div>`
    : '';
  return `
    <div class="queue-apparel">
      <h4>Apparel add-ons</h4>
      <ul>${items}</ul>
      ${subtotalLine}
    </div>
  `;
}

function prepareApparelEditor(order) {
  if (!order) {
    state.apparelEditor.orderId = null;
    state.apparelEditor.selectedIndex = 0;
    state.apparelEditor.statusMessage = '';
    state.apparelEditor.statusVariant = 'muted';
    return;
  }
  if (state.apparelEditor.orderId !== order.id) {
    state.apparelEditor.orderId = order.id;
    state.apparelEditor.selectedIndex = 0;
    state.apparelEditor.statusMessage = '';
    state.apparelEditor.statusVariant = 'muted';
  }
  const items = Array.isArray(order.apparelItems) ? order.apparelItems : [];
  if (!items.length) {
    state.apparelEditor.selectedIndex = 0;
    return;
  }
  if (
    state.apparelEditor.selectedIndex == null ||
    Number.isNaN(state.apparelEditor.selectedIndex)
  ) {
    state.apparelEditor.selectedIndex = 0;
  }
  if (state.apparelEditor.selectedIndex >= items.length) {
    state.apparelEditor.selectedIndex = Math.max(0, items.length - 1);
  }
  if (state.apparelEditor.selectedIndex < 0) {
    state.apparelEditor.selectedIndex = 0;
  }
}

function renderApparelEditor(order) {
  const items = Array.isArray(order?.apparelItems) ? order.apparelItems : [];
  if (!items.length) return '';

  const clampedIndex = Math.min(
    Math.max(Number(state.apparelEditor.selectedIndex) || 0, 0),
    items.length - 1
  );
  const selectedItem = items[clampedIndex] || items[0] || {};
  const unitPriceValue =
    Number.isFinite(selectedItem.unitPriceCents) && selectedItem.unitPriceCents != null
      ? centsToDisplay(selectedItem.unitPriceCents)
      : '';
  const quantityValue = Number.isFinite(selectedItem.quantity)
    ? String(Math.max(1, Math.round(selectedItem.quantity)))
    : '1';
  const options = items
    .map((item, idx) => {
      const name = item.title || item.handle || 'Apparel item';
      const skuLabel = item.sku ? ` · #${item.sku}` : '';
      return `<option value="${idx}"${idx === clampedIndex ? ' selected' : ''}>${escapeHtml(
        `${name}${skuLabel}`
      )}</option>`;
    })
    .join('');
  const statusMessage =
    state.apparelEditor.statusMessage || 'Select an apparel item to edit.';
  const statusVariant = state.apparelEditor.statusVariant || 'muted';

  return `
    <div class="queue-apparel-editor" data-order="${escapeHtml(order.id || '')}">
      <h4>Edit apparel items</h4>
      <p class="hint">Adjust quantity, pricing, or vendor links for the apparel pulled into this order.</p>
      <div class="queue-apparel-editor__grid">
        <label class="full">
          <span>Apparel item</span>
          <select id="apparelEditorSelect">
            ${options}
          </select>
        </label>
        <label class="full">
          <span>Product name</span>
          <input
            id="apparelEditorTitle"
            type="text"
            value="${escapeHtml(selectedItem.title || selectedItem.handle || '')}"
            placeholder="Display name"
          />
        </label>
        <label>
          <span>SKU</span>
          <input
            id="apparelEditorSku"
            type="text"
            value="${escapeHtml(selectedItem.sku || '')}"
            placeholder="Vendor SKU"
          />
        </label>
        <label>
          <span>Quantity</span>
          <input
            id="apparelEditorQuantity"
            type="number"
            min="1"
            step="1"
            value="${escapeHtml(quantityValue)}"
          />
        </label>
        <label>
          <span>Size</span>
          <input
            id="apparelEditorSize"
            type="text"
            value="${escapeHtml(selectedItem.size || '')}"
            placeholder="e.g. XL"
          />
        </label>
        <label>
          <span>Color</span>
          <input
            id="apparelEditorColor"
            type="text"
            value="${escapeHtml(selectedItem.color || '')}"
            placeholder="e.g. Black"
          />
        </label>
        <label>
          <span>Product type</span>
          <input
            id="apparelEditorProductType"
            type="text"
            value="${escapeHtml(selectedItem.productType || '')}"
            placeholder="Tshirt, Hoodie…"
          />
        </label>
        <label>
          <span>Style</span>
          <input
            id="apparelEditorStyle"
            type="text"
            value="${escapeHtml(selectedItem.style || '')}"
            placeholder="Style or fit"
          />
        </label>
        <label>
          <span>Vendor / Brand</span>
          <input
            id="apparelEditorVendor"
            type="text"
            value="${escapeHtml(selectedItem.vendor || '')}"
            placeholder="Vendor name"
          />
        </label>
        <label>
          <span>Unit price (USD)</span>
          <input
            id="apparelEditorUnitPrice"
            type="text"
            inputmode="decimal"
            value="${escapeHtml(unitPriceValue)}"
            placeholder="e.g. 18.50"
          />
        </label>
        <label class="full">
          <span>Product URL</span>
          <input
            id="apparelEditorProductUrl"
            type="text"
            value="${escapeHtml(selectedItem.productUrl || '')}"
            placeholder="https://vendor.example/item"
          />
        </label>
        <label class="full">
          <span>Preview image URL</span>
          <input
            id="apparelEditorImageUrl"
            type="text"
            value="${escapeHtml(selectedItem.imageUrl || '')}"
            placeholder="/productimages/apparel/preview.png"
          />
        </label>
        <label class="full">
          <span>Color chart URL</span>
          <input
            id="apparelEditorColorPageUrl"
            type="text"
            value="${escapeHtml(selectedItem.colorPageUrl || '')}"
            placeholder="Optional vendor color page"
          />
        </label>
      </div>
      <div class="queue-apparel-editor__actions">
        <button type="button" class="primary" id="apparelEditorSave">Save changes</button>
        <button type="button" class="danger" id="apparelEditorRemove">Remove item</button>
      </div>
      <div id="apparelEditorStatus" class="status-bar ${statusVariant}">
        ${escapeHtml(statusMessage)}
      </div>
    </div>
  `;
}

function initApparelEditor(order) {
  const editor = elements.queueDetail.querySelector('.queue-apparel-editor');
  if (!editor) return;
  const items = Array.isArray(order?.apparelItems) ? order.apparelItems : [];
  if (!items.length) return;

  const select = editor.querySelector('#apparelEditorSelect');
  const inputs = {
    title: editor.querySelector('#apparelEditorTitle'),
    sku: editor.querySelector('#apparelEditorSku'),
    quantity: editor.querySelector('#apparelEditorQuantity'),
    size: editor.querySelector('#apparelEditorSize'),
    color: editor.querySelector('#apparelEditorColor'),
    productType: editor.querySelector('#apparelEditorProductType'),
    style: editor.querySelector('#apparelEditorStyle'),
    vendor: editor.querySelector('#apparelEditorVendor'),
    unitPrice: editor.querySelector('#apparelEditorUnitPrice'),
    productUrl: editor.querySelector('#apparelEditorProductUrl'),
    imageUrl: editor.querySelector('#apparelEditorImageUrl'),
    colorPageUrl: editor.querySelector('#apparelEditorColorPageUrl')
  };
  const saveButton = editor.querySelector('#apparelEditorSave');
  const removeButton = editor.querySelector('#apparelEditorRemove');
  const statusBar = editor.querySelector('#apparelEditorStatus');

  function setStatus(message, variant = 'muted', persist = true) {
    if (statusBar) {
      statusBar.textContent = message;
      statusBar.className = `status-bar ${variant}`;
    }
    if (persist) {
      state.apparelEditor.statusMessage = message;
      state.apparelEditor.statusVariant = variant;
    }
  }

  function applyStoredStatus() {
    const message =
      state.apparelEditor.statusMessage || 'Select an apparel item to edit.';
    const variant = state.apparelEditor.statusVariant || 'muted';
    setStatus(message, variant, false);
  }

  function getSelectedIndex() {
    const raw = Number(select?.value ?? state.apparelEditor.selectedIndex ?? 0);
    if (!Number.isFinite(raw)) return 0;
    return Math.min(Math.max(0, Math.round(raw)), Math.max(items.length - 1, 0));
  }

  function populate(index) {
    const item = items[index];
    if (!item) return;
    if (inputs.title) inputs.title.value = item.title || item.handle || '';
    if (inputs.sku) inputs.sku.value = item.sku || '';
    if (inputs.quantity) {
      inputs.quantity.value = Number.isFinite(item.quantity)
        ? String(Math.max(1, Math.round(item.quantity)))
        : '1';
    }
    if (inputs.size) inputs.size.value = item.size || '';
    if (inputs.color) inputs.color.value = item.color || '';
    if (inputs.productType) inputs.productType.value = item.productType || '';
    if (inputs.style) inputs.style.value = item.style || '';
    if (inputs.vendor) inputs.vendor.value = item.vendor || '';
    if (inputs.unitPrice) {
      inputs.unitPrice.value =
        item.unitPriceCents != null && Number.isFinite(item.unitPriceCents)
          ? centsToDisplay(item.unitPriceCents)
          : '';
    }
    if (inputs.productUrl) inputs.productUrl.value = item.productUrl || '';
    if (inputs.imageUrl) inputs.imageUrl.value = item.imageUrl || '';
    if (inputs.colorPageUrl) inputs.colorPageUrl.value = item.colorPageUrl || '';
  }

  function setBusy(busy) {
    editor.classList.toggle('busy', busy);
    if (select) select.disabled = busy;
    if (saveButton) saveButton.disabled = busy;
    if (removeButton) removeButton.disabled = busy;
  }

  if (select) {
    select.addEventListener('change', () => {
      const index = getSelectedIndex();
      state.apparelEditor.selectedIndex = index;
      populate(index);
      setStatus('Editing apparel item.', 'muted');
    });
  }

  async function submitChanges(remove = false) {
    const index = getSelectedIndex();
    const originalItem = items[index];
    if (!originalItem) {
      setStatus('Select an apparel item first.', 'error');
      return;
    }

    const clonedItems = items.map((entry) => ({ ...entry }));
    let nextItems = clonedItems;
    let nextIndex = index;
    let successMessage = 'Apparel item updated.';

    if (remove) {
      const confirmMessage =
        items.length === 1
          ? 'Remove the only apparel item from this order?'
          : 'Remove this apparel item from the order?';
      const confirmed = await nativeConfirm(confirmMessage, 'Remove Item');
      if (!confirmed) return;
      nextItems = clonedItems.filter((_, idx) => idx !== index);
      nextIndex = Math.max(0, Math.min(index, Math.max(nextItems.length - 1, 0)));
      successMessage =
        nextItems.length > 0
          ? 'Apparel item removed.'
          : 'All apparel items removed from this order.';
    } else {
      const sku = inputs.sku?.value.trim();
      if (!sku) {
        setStatus('Enter the SKU for this apparel item.', 'error');
        inputs.sku?.focus();
        return;
      }

      const quantityRaw = Number.parseInt(inputs.quantity?.value, 10);
      if (!Number.isFinite(quantityRaw) || quantityRaw <= 0) {
        setStatus('Quantity must be at least 1.', 'error');
        inputs.quantity?.focus();
        return;
      }
      const quantity = Math.min(500, Math.max(1, Math.round(quantityRaw)));

      const unitPriceCentsRaw = parseCurrencyInput(inputs.unitPrice?.value);
      if (Number.isNaN(unitPriceCentsRaw)) {
        setStatus('Enter a valid unit price (e.g. 18.50).', 'error');
        inputs.unitPrice?.focus();
        return;
      }
      if (unitPriceCentsRaw != null && unitPriceCentsRaw < 0) {
        setStatus('Unit price cannot be negative.', 'error');
        inputs.unitPrice?.focus();
        return;
      }
      const unitPriceCents = unitPriceCentsRaw != null ? unitPriceCentsRaw : null;

      const target = clonedItems[index];
      target.sku = sku;
      target.title = inputs.title?.value.trim() || null;
      target.quantity = quantity;
      target.size = inputs.size?.value.trim() || null;
      target.color = inputs.color?.value.trim() || null;
      target.productType = inputs.productType?.value.trim() || null;
      target.style = inputs.style?.value.trim() || null;
      target.vendor = inputs.vendor?.value.trim() || null;
      target.unitPriceCents = unitPriceCents;
      target.lineTotalCents = unitPriceCents != null ? unitPriceCents * quantity : null;

      const productUrl = inputs.productUrl?.value.trim() || '';
      target.productUrl = productUrl || null;

      const imageUrl = inputs.imageUrl?.value.trim() || '';
      const imageChanged = imageUrl !== (originalItem.imageUrl || '');
      target.imageUrl = imageUrl || null;
      if (imageChanged) {
        target.imageStatus = null;
      }

      const colorPageUrl = inputs.colorPageUrl?.value.trim() || '';
      target.colorPageUrl = colorPageUrl || null;

      nextItems = clonedItems;
      nextIndex = index;
      successMessage = 'Apparel item updated.';
    }

    setBusy(true);
    setStatus(remove ? 'Removing apparel item…' : 'Saving apparel item…', 'muted');

    try {
      state.apparelEditor.selectedIndex = nextIndex;
      state.selectedOrderId = order.id;
      await printStation.updateOrder({
        orderId: order.id,
        updates: { apparelItems: nextItems }
      });
      state.apparelEditor.statusMessage = successMessage;
      state.apparelEditor.statusVariant = 'success';
      showToast(successMessage, 'success');
      try {
        await refreshQueue({ silent: true });
      } catch (refreshError) {
        console.error('Unable to refresh queue after apparel update:', refreshError);
        const message =
          'Apparel item updated, but the queue failed to refresh. Click “Refresh” to reload orders.';
        state.apparelEditor.statusMessage = message;
        state.apparelEditor.statusVariant = 'error';
        setStatus(message, 'error');
        showToast(message, 'error', 6000);
        setBusy(false);
        return;
      }
    } catch (error) {
      console.error('Unable to update apparel item:', error);
      const message = error?.message || 'Unable to update apparel item.';
      state.apparelEditor.statusMessage = message;
      state.apparelEditor.statusVariant = 'error';
      setStatus(message, 'error', false);
      showToast(message, 'error', 6000);
      setBusy(false);
    }
  }

  if (saveButton) {
    saveButton.addEventListener('click', () => {
      void submitChanges(false);
    });
  }

  if (removeButton) {
    removeButton.addEventListener('click', () => {
      void submitChanges(true);
    });
  }

  populate(getSelectedIndex());
  applyStoredStatus();
}

function setApparelStore(store = {}) {
  state.apparelStore.items = Array.isArray(store?.items) ? store.items : [];
  state.apparelStore.categories = Array.isArray(store?.categories) ? store.categories : [];
  state.apparelStore.updatedAt = store?.updatedAt || null;
  state.apparelStore.loaded = true;
  state.apparelStore.error = null;
}

function ensureApparelStoreLoaded({ force = false } = {}) {
  if (force) {
    state.apparelStore.loaded = false;
  }
  if (state.apparelStore.loading && !force) {
    return state.apparelStore.promise;
  }
  if (state.apparelStore.loaded && !force) {
    return Promise.resolve(state.apparelStore);
  }
  state.apparelStore.loading = true;
  state.apparelStore.error = null;
  state.apparelStore.promise = printStation
    .fetchApparelStore()
    .then((response) => {
      setApparelStore(response || {});
      return state.apparelStore;
    })
    .catch((error) => {
      console.error('Unable to load apparel store:', error);
      state.apparelStore.error = error?.message || 'Unable to load apparel store.';
      state.apparelStore.items = [];
      state.apparelStore.categories = [];
      state.apparelStore.updatedAt = null;
      state.apparelStore.loaded = true;
      throw error;
    })
    .finally(() => {
      state.apparelStore.loading = false;
      state.apparelStore.promise = null;
    });
  return state.apparelStore.promise;
}

function findApparelStoreItemForDesign(design) {
  if (!design) return null;
  const items = state.apparelStore.items || [];
  if (!items.length) return null;
  const candidates = new Set();
  if (design.id) candidates.add(design.id);
  if (design.apparel?.id) candidates.add(design.apparel.id);
  if (design.image) candidates.add(design.image);
  if (design.apparel?.preview) candidates.add(design.apparel.preview);
  if (design.apparel?.previewPath) candidates.add(design.apparel.previewPath);
  const candidateValues = Array.from(candidates).filter(Boolean);
  let match = items.find((item) => candidateValues.includes(item.id));
  if (match) return match;
  match = items.find(
    (item) =>
      candidateValues.includes(item.preview) ||
      candidateValues.includes(item.previewPath)
  );
  if (match) return match;
  const targetName = (design.name || '').toLowerCase();
  if (!targetName) return null;
  match = items.find((item) => (item.name || '').toLowerCase() === targetName);
  return match || null;
}

function setCatalogApparelStatus(message, variant = 'muted', persist = true) {
  if (elements.catalogApparelStatus) {
    elements.catalogApparelStatus.textContent = message;
    elements.catalogApparelStatus.className = `status-bar ${variant}`;
  }
  if (persist) {
    state.catalogApparelEditor.statusMessage = message;
    state.catalogApparelEditor.statusVariant = variant;
  }
}

function setCatalogApparelModalBusy(busy) {
  state.catalogApparelEditor.busy = busy;
  if (elements.catalogApparelModal) {
    elements.catalogApparelModal.classList.toggle('busy', busy);
  }
  if (elements.catalogApparelSave) {
    elements.catalogApparelSave.disabled = busy;
  }
  if (elements.catalogApparelForm) {
    elements.catalogApparelForm.querySelectorAll('input').forEach((input) => {
      input.disabled = busy;
    });
  }
}

function openCatalogApparelModal(design, item) {
  if (!elements.catalogApparelModal || !elements.catalogApparelForm) return;
  state.catalogApparelEditor.open = true;
  state.catalogApparelEditor.designId = design?.id || null;
  state.catalogApparelEditor.itemId = item?.id || design?.id || null;
  state.catalogApparelEditor.statusMessage = '';
  state.catalogApparelEditor.statusVariant = 'muted';
  setCatalogApparelModalBusy(false);
  elements.catalogApparelForm.reset();
  if (elements.catalogApparelName) {
    elements.catalogApparelName.value = item?.name || design?.name || '';
  }
  if (elements.catalogApparelType) {
    elements.catalogApparelType.value =
      item?.productType || design?.apparel?.productType || '';
  }
  if (elements.catalogApparelCategory) {
    elements.catalogApparelCategory.value =
      item?.categoryName || design?.categoryName || '';
  }
  setCatalogApparelStatus('Update apparel details and press save.', 'muted');
  elements.catalogApparelModal.classList.remove('hidden');
  elements.catalogApparelName?.focus({ preventScroll: true });
}

function closeCatalogApparelModal() {
  if (!elements.catalogApparelModal || !elements.catalogApparelForm) return;
  setCatalogApparelModalBusy(false);
  elements.catalogApparelModal.classList.add('hidden');
  elements.catalogApparelForm.reset();
  state.catalogApparelEditor.open = false;
  state.catalogApparelEditor.designId = null;
  state.catalogApparelEditor.itemId = null;
  state.catalogApparelEditor.statusMessage = '';
  state.catalogApparelEditor.statusVariant = 'muted';
}

async function handleCatalogApparelEdit(designId) {
  if (!designId) {
    showToast('Design not found.', 'error', 6000);
    return;
  }
  const design = state.catalogDesignMap?.get(designId);
  if (!design) {
    showToast('Design not found in catalog.', 'error', 6000);
    return;
  }
  try {
    await ensureApparelStoreLoaded();
  } catch (error) {
    const message = error?.message || 'Unable to load apparel store.';
    setCatalogApparelStatus(message, 'error');
    showToast(message, 'error', 6000);
    return;
  }
  const item = findApparelStoreItemForDesign(design);
  if (!item) {
    const message = 'This catalog design is not registered as apparel yet.';
    setCatalogApparelStatus(message, 'error');
    showToast(message, 'error', 6000);
    return;
  }
  openCatalogApparelModal(design, item);
}

async function handleCatalogApparelSubmit(event) {
  event.preventDefault();
  const itemId = state.catalogApparelEditor.itemId;
  if (!itemId) {
    setCatalogApparelStatus('Apparel item not loaded.', 'error');
    return;
  }
  const name = elements.catalogApparelName?.value.trim() || '';
  if (!name) {
    setCatalogApparelStatus('Enter a display name for this apparel item.', 'error');
    elements.catalogApparelName?.focus({ preventScroll: true });
    return;
  }
  const productTypeInput = elements.catalogApparelType?.value.trim() || '';
  const productType = productTypeInput || 'tshirt';
  const categoryName = elements.catalogApparelCategory?.value.trim() || '';
  if (!categoryName) {
    setCatalogApparelStatus('Enter an apparel category.', 'error');
    elements.catalogApparelCategory?.focus({ preventScroll: true });
    return;
  }
  setCatalogApparelModalBusy(true);
  setCatalogApparelStatus('Saving apparel item…', 'muted');
  try {
    await printStation.updateApparelStoreItem({
      id: itemId,
      updates: {
        name,
        productType,
        categoryName
      }
    });
    setCatalogApparelStatus('Apparel item updated.', 'success');
    showToast('Apparel item updated.', 'success');
    await ensureApparelStoreLoaded({ force: true }).catch(() => {});
    await loadCatalog({ silent: true, forceRefresh: true });
    closeCatalogApparelModal();
  } catch (error) {
    const message = error?.message || 'Unable to update apparel item.';
    setCatalogApparelStatus(message, 'error');
    showToast(message, 'error', 6000);
    setCatalogApparelModalBusy(false);
  }
}

function handleCatalogApparelCancel() {
  if (state.catalogApparelEditor.busy) return;
  closeCatalogApparelModal();
}

function handleCatalogApparelModalClick(event) {
  if (!state.catalogApparelEditor.open) return;
  const target = event.target;
  if (
    target === elements.catalogApparelModal ||
    target?.dataset?.action === 'close-catalog-apparel'
  ) {
    handleCatalogApparelCancel();
  }
}

function handleGlobalKeydown(event) {
  if (event.key === 'Escape') {
    // Close mockup modal if open
    const mockupModal = document.getElementById('customArtMockupModal');
    if (mockupModal && mockupModal.style.display !== 'none') {
      event.preventDefault();
      closeMockupModal();
      return;
    }
    // Close catalog apparel modal if open
    if (state.catalogApparelEditor.open && !state.catalogApparelEditor.busy) {
      event.preventDefault();
      closeCatalogApparelModal();
    }
    // Force close all blocking modals
    forceCloseAllBlockingModals();
  }

  // Debug shortcut: Ctrl+Shift+D to identify blocking elements
  if (event.ctrlKey && event.shiftKey && event.key === 'D') {
    event.preventDefault();
    debugBlockingElements();
  }
}

// Debug function to identify elements blocking interaction
function debugBlockingElements() {
  const blocking = [];

  // Check ALL elements for computed position: fixed (not just inline styles)
  document.querySelectorAll('*').forEach(el => {
    const style = window.getComputedStyle(el);
    if (style.position === 'fixed' || style.position === 'absolute') {
      const display = style.display;
      const visibility = style.visibility;
      const pointerEvents = style.pointerEvents;
      const zIndex = style.zIndex;
      const rect = el.getBoundingClientRect();

      // If it's visible, could receive pointer events, and covers a significant area
      if (display !== 'none' && visibility !== 'hidden' && pointerEvents !== 'none') {
        if (rect.width > 100 && rect.height > 100) {
          blocking.push({
            element: el,
            id: el.id,
            className: el.className,
            tagName: el.tagName,
            display,
            visibility,
            pointerEvents,
            zIndex,
            position: style.position,
            rect: { top: rect.top, left: rect.left, width: rect.width, height: rect.height }
          });
        }
      }
    }
  });

  // Sort by z-index (highest first)
  blocking.sort((a, b) => (parseInt(b.zIndex) || 0) - (parseInt(a.zIndex) || 0));

  console.log('[Debug] Potentially blocking fixed/absolute elements:', blocking);
  console.table(blocking.map(b => ({ id: b.id, class: b.className, tag: b.tagName, zIndex: b.zIndex, position: b.position, width: b.rect.width, height: b.rect.height })));

  if (blocking.length > 0) {
    showToast(`Found ${blocking.length} potentially blocking element(s). Check console (F12).`, 'warning');
    // Highlight the top blocking element
    const top = blocking[0];
    if (top.element) {
      top.element.style.outline = '3px solid red';
      setTimeout(() => { top.element.style.outline = ''; }, 3000);
    }
  } else {
    showToast('No blocking elements found.', 'info');
  }
}

// Click debugger - logs what element receives the click
let clickDebugEnabled = false;
function enableClickDebug() {
  if (clickDebugEnabled) return;
  clickDebugEnabled = true;

  document.addEventListener('click', (e) => {
    console.log('[Click Debug] Click at:', e.clientX, e.clientY);
    console.log('[Click Debug] Target:', e.target);
    console.log('[Click Debug] Target ID:', e.target.id);
    console.log('[Click Debug] Target class:', e.target.className);
    console.log('[Click Debug] Target tag:', e.target.tagName);

    // Check what element is at this point
    const elementAtPoint = document.elementFromPoint(e.clientX, e.clientY);
    if (elementAtPoint !== e.target) {
      console.log('[Click Debug] Element at point differs!', elementAtPoint);
    }
  }, true); // capture phase

  // Also log mousedown to catch early interception
  document.addEventListener('mousedown', (e) => {
    const elementAtPoint = document.elementFromPoint(e.clientX, e.clientY);
    console.log('[MouseDown Debug] Element at', e.clientX, e.clientY, ':', elementAtPoint?.tagName, elementAtPoint?.id, elementAtPoint?.className);
  }, true);

  console.log('[Click Debug] Click debugging enabled. Click anywhere to see what receives the click.');
  showToast('Click debugging enabled. Check console.', 'info');
}

// Ctrl+Shift+C to enable click debugging
document.addEventListener('keydown', (e) => {
  if (e.ctrlKey && e.shiftKey && e.key === 'C') {
    e.preventDefault();
    enableClickDebug();
  }
});

// Global mousedown/click handlers to ensure input elements can receive focus
// This is a fallback to handle cases where focus state gets stuck after native dialogs in Electron
document.addEventListener('mousedown', (e) => {
  const target = e.target;
  if (!target) return;

  // If clicking on an input, textarea, or select, force focus immediately on mousedown
  if (target.matches('input, textarea, select, [contenteditable="true"]')) {
    try {
      target.focus();
    } catch (_) {}
  }
}, true); // capture phase

document.addEventListener('click', (e) => {
  const target = e.target;
  if (!target) return;

  // Double-check focus on click as well
  if (target.matches('input, textarea, select, [contenteditable="true"]')) {
    if (document.activeElement !== target) {
      try {
        target.focus();
      } catch (_) {}
    }
  }
}, true); // capture phase

// Force close all modals that might be blocking
// PROTECTED_MODALS are NEVER force-closed - they have their own lifecycle
function forceCloseAllBlockingModals() {
  const modalIds = [
    'customPromptModal',
    'roomPickerModal',
    'campaignMockupSettingsModal',
    'inventoryApparelModal',
    'ssawVisualModal',
    'ssawCurateModal',
    'guidedExportModal',
    'catalogApparelModal',
    'metadataProgressModal',
    'localMockupModal',
    'artworkBulkUploadModal'
    // NOTE: customArtMockupModal and tiledProductModal are explicitly excluded
  ];

  modalIds.forEach(id => {
    // Skip modals that are intentionally open
    if (intentionallyOpenModals.has(id)) {
      console.log('[forceCloseAllBlockingModals] Skipping intentionally open modal:', id);
      return;
    }
    const modal = document.getElementById(id);
    if (modal) {
      modal.style.display = 'none';
      modal.style.pointerEvents = 'none';
      modal.style.visibility = 'hidden';
      modal.setAttribute('hidden', '');
    }
  });

  // Also close any ssaw-modal or modal class elements
  document.querySelectorAll('.ssaw-modal, .modal, .modal-overlay').forEach(modal => {
    // CRITICAL: Never close protected modals
    if (modal.id && (modal.id === 'customArtMockupModal' || modal.id === 'tiledProductModal' || modal.id === 'stickerSheetsBrowserModal')) {
      return;
    }
    // Skip modals that are intentionally open
    if (modal.id && intentionallyOpenModals.has(modal.id)) {
      console.log('[forceCloseAllBlockingModals] Skipping intentionally open modal by class:', modal.id);
      return;
    }
    modal.style.display = 'none';
    modal.style.pointerEvents = 'none';
    modal.setAttribute('hidden', '');
  });
}

// Periodic cleanup of blocking modals - DISABLED to debug lockups
// These modals should NEVER be auto-cleaned - they have their own lifecycle management
const PROTECTED_MODALS = ['customArtMockupModal', 'tiledProductModal', 'stickerSheetsBrowserModal'];

// Modal cleanup disabled - was causing performance issues
// If modals get stuck, use Ctrl+Shift+B to force close them

function renderInventoryUsage(list = []) {
  if (!Array.isArray(list) || !list.length) {
    return '';
  }
  const items = list
    .map((entry) => {
      const name = escapeHtml(entry.name || entry.itemName || entry.itemId || 'Inventory item');
      const quantity = Number(entry.quantity || 0);
      const unit = escapeHtml(entry.unit || 'unit');
      const material = entry.material ? escapeHtml(formatInventoryMaterial(entry.material)) : '';
      const color = entry.color ? escapeHtml(entry.color) : '';
      const metaParts = [];
      if (material) metaParts.push(material);
      if (color) metaParts.push(color);
      if (entry.reason) metaParts.push(escapeHtml(entry.reason));
      const meta = metaParts.length
        ? `<div class="queue-inventory-meta">${metaParts.join(' • ')}</div>`
        : '';
      const swatch = entry.color
        ? `<span class="inventory-swatch" style="background-color: ${entry.color};"></span>`
        : '';
      return `<li><span class="queue-inventory-qty">${quantity} ${unit}</span>${swatch}<span class="queue-inventory-name">${name}</span>${meta}</li>`;
    })
    .join('');
  return `
    <div class="queue-inventory-usage">
      <h4>Inventory usage</h4>
      <ul>${items}</ul>
    </div>
  `;
}

function formatInventoryMaterial(value) {
  const material = String(value || '').toLowerCase();
  if (!material) return 'Inventory';
  if (material === 'regular-vinyl') return 'Regular vinyl';
  if (material === 'heat-transfer') return 'Heat transfer vinyl';
  if (material === 'apparel-ssaw') return 'S&S apparel';
  if (material === 'apparel') return 'Apparel';
  return material.replace(/[-_]/g, ' ').replace(/\b\w/g, (match) => match.toUpperCase());
}

function formatInventoryQuantity(item) {
  const quantity = Number(item?.quantity || 0);
  const unit = item?.unit || 'unit';
  return `${quantity} ${unit}`;
}

function slugify(value, fallback = 'item') {
  const slug = String(value || '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .replace(/-{2,}/g, '-');
  if (slug === 't-shirt') return 'tshirt';
  return slug || fallback;
}

function formatApparelTypeLabel(value) {
  const slug = String(value || '').trim().toLowerCase();
  if (!slug) return 'Apparel';
  if (slug === 'tshirt' || slug === 't-shirt' || slug === 'tee') return 'T-shirt';
  if (slug === 'hoodie') return 'Hoodie';
  if (slug === 'beanie') return 'Beanie';
  if (slug === 'hat' || slug === 'cap') return 'Hat';
  const parts = slug.split(/[-_]/).filter(Boolean);
  return parts
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');
}

function normalizeApparelTypeEntry(entry) {
  if (!entry) return null;
  const rawValue = entry.value || entry;
  const rawLabel = entry.label || entry;
  const slug = slugify(rawValue || rawLabel);
  if (!slug || slug === 'other') return null;
  const label = entry.label ? String(entry.label).trim() : formatApparelTypeLabel(slug);
  return { value: slug, label: label || formatApparelTypeLabel(slug) };
}

function loadStoredApparelTypes() {
  try {
    const raw = localStorage.getItem(APPAREL_TYPES_STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.map(normalizeApparelTypeEntry).filter(Boolean);
  } catch (error) {
    console.warn('Unable to load stored apparel types:', error);
    return [];
  }
}

function saveApparelTypes(types) {
  try {
    localStorage.setItem(APPAREL_TYPES_STORAGE_KEY, JSON.stringify(types));
  } catch (error) {
    console.warn('Unable to persist apparel types:', error);
  }
}

function setApparelTypes(types = []) {
  const unique = new Map();
  types.forEach((entry) => {
    if (entry && entry.value) {
      unique.set(entry.value, { value: entry.value, label: entry.label });
    }
  });
  state.apparelTypes = Array.from(unique.values()).sort((a, b) =>
    a.label.localeCompare(b.label)
  );
  renderApparelTypeOptions();
}

function renderApparelTypeOptions(selectedValue) {
  if (!elements.inventoryApparelTypeSelect) return;
  const select = elements.inventoryApparelTypeSelect;
  const previous = selectedValue || select.value || 'tshirt';
  select.innerHTML = '';
  state.apparelTypes.forEach((entry) => {
    const option = document.createElement('option');
    option.value = entry.value;
    option.textContent = entry.label;
    select.appendChild(option);
  });
  const otherOption = document.createElement('option');
  otherOption.value = 'other';
  otherOption.textContent = 'Other…';
  select.appendChild(otherOption);
  if (state.apparelTypes.some((entry) => entry.value === previous)) {
    select.value = previous;
  } else if (state.apparelTypes.length) {
    select.value = state.apparelTypes[0].value;
  } else {
    select.value = 'tshirt';
  }
  handleInventoryApparelTypeChange();
}

function showInventoryApparelOtherRow(show) {
  if (!elements.inventoryApparelTypeOtherRow) return;
  elements.inventoryApparelTypeOtherRow.classList.toggle('hidden', !show);
  if (!show && elements.inventoryApparelTypeOtherInput) {
    elements.inventoryApparelTypeOtherInput.value = '';
  }
  if (show && elements.inventoryApparelTypeOtherInput) {
    elements.inventoryApparelTypeOtherInput.focus();
  }
}

function handleInventoryApparelTypeChange() {
  if (!elements.inventoryApparelTypeSelect) return;
  const value = elements.inventoryApparelTypeSelect.value;
  showInventoryApparelOtherRow(value === 'other');
  populateInventoryApparelSizes();
}

function populateInventoryApparelSizes() {
  if (!elements.inventoryApparelSizeChecks) return;
  const container = elements.inventoryApparelSizeChecks;
  container.innerHTML = '';
  const type = elements.inventoryApparelTypeSelect?.value || 'tshirt';
  const preferred = (type === 'hat' || type === 'beanie') ? ['One size fits all'] : ['M'];
  APPAREL_SIZE_OPTIONS.forEach((size) => {
    const id = `apparel-size-${size.replace(/\s+/g,'-').toLowerCase()}`;
    const label = document.createElement('label');
    label.className = 'inline';
    const cb = document.createElement('input');
    cb.type = 'checkbox';
    cb.value = size;
    cb.id = id;
    if (preferred.includes(size)) cb.checked = true;
    label.appendChild(cb);
    const span = document.createElement('span');
    span.textContent = ` ${size}`;
    label.appendChild(span);
    container.appendChild(label);
  });
}

function addApparelType(label) {
  const normalizedLabel = formatApparelTypeLabel(label);
  const value = slugify(normalizedLabel);
  if (!value || value === 'other') return value;
  if (!state.apparelTypes.some((entry) => entry.value === value)) {
    const next = [...state.apparelTypes, { value, label: normalizedLabel }].sort((a, b) =>
      a.label.localeCompare(b.label)
    );
    setApparelTypes(next);
    saveApparelTypes(next);
    showToast(`Added apparel type: ${normalizedLabel}`, 'success');
  }
  return value;
}

function ensureApparelTypesInitialized() {
  const stored = loadStoredApparelTypes();
  const merged = [...DEFAULT_APPAREL_TYPES, ...stored];
  setApparelTypes(merged);
  saveApparelTypes(state.apparelTypes);
  populateInventoryApparelSizes();
}

function normalizeApparelCategoryEntry(entry) {
  if (!entry) return null;
  const rawName = String(entry.name || entry.label || entry.slug || '').trim();
  const slug = String(entry.slug || slugify(rawName)).trim().toLowerCase();
  if (!slug) return null;
  const name = rawName || slugify(slug, 'Apparel').replace(/-/g, ' ');
  return {
    slug,
    name
  };
}

function setApparelCategories(categories = []) {
  const normalized = categories
    .map(normalizeApparelCategoryEntry)
    .filter(Boolean);
  const unique = new Map(normalized.map((entry) => [entry.slug, entry]));
  state.apparelCategories = Array.from(unique.values()).sort((a, b) =>
    a.name.localeCompare(b.name)
  );
  state.apparelCategoriesLoaded = true;
  state.apparelCategoriesError = null;
  renderUploadApparelCategoryOptions();
}

function showUploadApparelCategoryOtherRow(show) {
  if (!elements.uploadApparelCategoryOtherRow) return;
  elements.uploadApparelCategoryOtherRow.classList.toggle('hidden', !show);
  if (!show && elements.uploadApparelCategoryOtherInput) {
    elements.uploadApparelCategoryOtherInput.value = '';
  }
  if (show && elements.uploadApparelCategoryOtherInput) {
    elements.uploadApparelCategoryOtherInput.focus();
  }
  if (show) {
    state.upload.apparelCategory = '';
  }
}

function renderUploadApparelCategoryOptions(selectedSlug) {
  const select = elements.uploadApparelCategorySelect;
  if (!select) return;
  const hint = elements.uploadApparelCategoryRow?.querySelector('.hint');
  const previous = selectedSlug || select.value || '';
  select.innerHTML = '';

  if (!state.apparelCategoriesLoaded) {
    const option = document.createElement('option');
    option.value = '';
    option.textContent = state.apparelCategoriesLoading
      ? 'Loading categories…'
      : state.apparelCategoriesError || 'Select apparel category';
    option.disabled = true;
    option.selected = true;
    select.appendChild(option);
    select.disabled = true;
    showUploadApparelCategoryOtherRow(false);
    if (hint) {
      hint.textContent = state.apparelCategoriesError
        ? `${state.apparelCategoriesError}. You can still create a new category below.`
        : 'Pick the storefront category this design belongs in.';
    }
    return;
  }

  if (hint) {
    hint.textContent = state.apparelCategoriesError
      ? `${state.apparelCategoriesError}. You can still create a new category below.`
      : 'Pick the storefront category this design belongs in.';
  }

  const placeholder = document.createElement('option');
  placeholder.value = '';
  placeholder.textContent = state.apparelCategories.length
    ? 'Select apparel category'
    : 'Create a new category';
  placeholder.disabled = false;
  placeholder.selected = true;
  select.appendChild(placeholder);

  state.apparelCategories.forEach((category) => {
    const option = document.createElement('option');
    option.value = category.slug;
    option.textContent = category.name;
    select.appendChild(option);
  });

  const otherOption = document.createElement('option');
  otherOption.value = 'other';
  otherOption.textContent = 'Other…';
  select.appendChild(otherOption);

  select.disabled = false;
  if (!state.apparelCategories.length) {
    select.value = 'other';
    handleUploadApparelCategoryChange();
    return;
  }
  if (state.apparelCategories.some((category) => category.slug === previous)) {
    select.value = previous;
  } else if (previous === 'other') {
    select.value = 'other';
  } else {
    select.value = '';
  }
  handleUploadApparelCategoryChange();
}

function handleUploadApparelCategoryChange() {
  const select = elements.uploadApparelCategorySelect;
  if (!select) return;
  showUploadApparelCategoryOtherRow(select.value === 'other');
  if (select.value && select.value !== 'other') {
    const entry = state.apparelCategories.find((item) => item.slug === select.value);
    state.upload.apparelCategory = entry?.name || '';
  } else if (select.value !== 'other') {
    state.upload.apparelCategory = '';
  }
}

async function loadApparelCategories({ force = false } = {}) {
  if (state.apparelCategoriesLoading && !force) {
    return state.apparelCategoriesPromise;
  }
  if (state.apparelCategoriesLoaded && !force) {
    return Promise.resolve(state.apparelCategories);
  }
  state.apparelCategoriesLoading = true;
  state.apparelCategoriesError = null;
  state.apparelCategoriesPromise = printStation
    .fetchApparelCategories()
    .then((response) => {
      const categories = Array.isArray(response?.categories) ? response.categories : [];
      setApparelCategories(categories);
      return state.apparelCategories;
    })
    .catch((error) => {
      console.error('Unable to load apparel categories:', error);
      state.apparelCategoriesError = error?.message || 'Unable to load apparel categories.';
      state.apparelCategoriesLoaded = true;
      state.apparelCategories = [];
      renderUploadApparelCategoryOptions();
      return [];
    })
    .finally(() => {
      state.apparelCategoriesLoading = false;
      state.apparelCategoriesPromise = null;
    });
  return state.apparelCategoriesPromise;
}

function ensureApparelCategoriesLoaded(options = {}) {
  return loadApparelCategories(options);
}

function getInventoryItem(itemId) {
  return state.inventoryItems.find((item) => item.id === itemId) || null;
}

function centsToDisplay(cents) {
  if (!Number.isFinite(cents)) return '';
  return (cents / 100).toFixed(2);
}

function parseCurrencyInput(value) {
  if (value == null) return null;
  const trimmed = String(value).trim();
  if (!trimmed) return null;
  const normalized = trimmed.replace(/[^0-9.,-]/g, '').replace(/,/g, '.');
  if (!normalized) return null;
  const parsed = Number(normalized);
  if (!Number.isFinite(parsed)) {
    return NaN;
  }
  return Math.round(parsed * 100);
}

function fillVariantGroupEditForm(item) {
  if (!item?.variantGroupId) return;

  // Get all items in this variant group
  const variantGroupItems = state.inventoryItems.filter(
    (i) => i.variantGroupId === item.variantGroupId
  );

  if (!variantGroupItems.length) return;

  // Extract unique variants (by color) and store item IDs
  const variantMap = new Map();
  console.log('[Variant Edit] Grouping', variantGroupItems.length, 'items');
  variantGroupItems.forEach((vItem) => {
    const colorKey = vItem.colorName || vItem.color || 'default';
    console.log(`  Item ${vItem.id}: colorKey="${colorKey}" (from colorName="${vItem.colorName}", color="${vItem.color}"), size="${vItem.size}"`);
    if (!variantMap.has(colorKey)) {
      variantMap.set(colorKey, {
        colorName: vItem.colorName || '',
        colorHex: vItem.color || '',
        imageFront: vItem.imageUrl || '',
        imageBack: vItem.imageUrlBack || '',
        sizes: [],
        itemIds: []
      });
    }
    const variant = variantMap.get(colorKey);
    if (vItem.size) {
      variant.sizes.push(vItem.size);
    }
    variant.itemIds.push(vItem.id);
  });

  console.log('[Variant Edit] Grouped into', variantMap.size, 'variants');
  variantMap.forEach((variant, colorKey) => {
    console.log(`  Variant "${colorKey}": ${variant.itemIds.length} items [${variant.itemIds.join(', ')}], sizes: ${variant.sizes.join(', ')}`);
  });

  // Build array of variants with their original color keys
  const variants = [];
  variantMap.forEach((variant, colorKey) => {
    variants.push({ ...variant, originalColorKey: colorKey });
  });

  // Fill shared fields (use first item as reference)
  const firstItem = variantGroupItems[0];
  if (elements.inventoryEditVariantCost) {
    elements.inventoryEditVariantCost.value = centsToDisplay(firstItem.unitCostCents);
  }
  if (elements.inventoryEditVariantFabric) {
    elements.inventoryEditVariantFabric.value = firstItem.fabric || '';
  }
  if (elements.inventoryEditVariantDescription) {
    elements.inventoryEditVariantDescription.value = firstItem.description || '';
  }
  if (elements.inventoryEditVariantRefUrl) {
    elements.inventoryEditVariantRefUrl.value = firstItem.referenceUrl || '';
  }

  // Render variants list
  if (elements.inventoryEditVariantsList) {
    elements.inventoryEditVariantsList.innerHTML = variants
      .map((variant, idx) => {
        const frontThumbUrl = variant.imageFront ? resolveAssetUrl(variant.imageFront, { width: 200 }) : '';
        const backThumbUrl = variant.imageBack ? resolveAssetUrl(variant.imageBack, { width: 200 }) : '';

        return `
          <div class="variant-edit-row" data-variant-index="${idx}" data-original-color-key="${escapeHtml(variant.originalColorKey)}" data-item-ids="${variant.itemIds.join(',')}" style="border:1px solid var(--border);border-radius:8px;padding:16px;margin-top:12px;width:fit-content;">
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
              <label>
                <span>Color Name</span>
                <input type="text" class="variant-edit-color-name" value="${escapeHtml(variant.colorName)}" required />
              </label>
              <label>
                <span>Color Hex (optional)</span>
                <input type="text" class="variant-edit-color-hex" value="${escapeHtml(variant.colorHex)}" placeholder="#000000" />
              </label>
              <label>
                <span>Front Image</span>
                <div style="display:flex;gap:8px;">
                  <input type="text" class="variant-edit-image-front" value="${escapeHtml(variant.imageFront)}" placeholder="/api/library/.../front.jpg" />
                  <button type="button" class="variant-edit-choose-front secondary">Choose…</button>
                </div>
                ${frontThumbUrl ? `<img src="${frontThumbUrl}" style="max-width:100%;max-height:60px;margin-top:8px;border-radius:4px;object-fit:contain;" />` : ''}
              </label>
              <label>
                <span>Back Image</span>
                <div style="display:flex;gap:8px;">
                  <input type="text" class="variant-edit-image-back" value="${escapeHtml(variant.imageBack)}" placeholder="/api/library/.../back.jpg" />
                  <button type="button" class="variant-edit-choose-back secondary">Choose…</button>
                </div>
                ${backThumbUrl ? `<img src="${backThumbUrl}" style="max-width:100%;max-height:60px;margin-top:8px;border-radius:4px;object-fit:contain;" />` : ''}
              </label>
              <div style="grid-column:1/-1;">
                <span style="font-size:0.875rem;color:var(--text-muted);">Sizes: ${variant.sizes.join(', ')}</span>
              </div>
              <div style="grid-column:1/-1;margin-top:8px;">
                <button type="button" class="variant-delete-btn secondary" style="color:var(--danger);">Delete this variant</button>
              </div>
            </div>
          </div>
        `;
      })
      .join('');

    // Add event listeners for image choosers
    const chooseFrontButtons = elements.inventoryEditVariantsList.querySelectorAll('.variant-edit-choose-front');
    const chooseBackButtons = elements.inventoryEditVariantsList.querySelectorAll('.variant-edit-choose-back');

    chooseFrontButtons.forEach((btn, idx) => {
      btn.addEventListener('click', async () => {
        const result = await printStation.chooseImage();
        if (result && result.relativePath) {
          const row = btn.closest('.variant-edit-row');
          const input = row.querySelector('.variant-edit-image-front');
          if (input) {
            input.value = result.relativePath;
            // Update thumbnail
            const existingThumb = row.querySelector('label:nth-child(3) img');
            if (existingThumb) {
              existingThumb.src = resolveAssetUrl(result.relativePath, { width: 200 });
            } else {
              const thumbImg = document.createElement('img');
              thumbImg.src = resolveAssetUrl(result.relativePath, { width: 200 });
              thumbImg.style.cssText = 'max-height:60px;margin-top:8px;border-radius:4px;';
              input.parentElement.parentElement.appendChild(thumbImg);
            }
          }
        }
      });
    });

    chooseBackButtons.forEach((btn, idx) => {
      btn.addEventListener('click', async () => {
        const result = await printStation.chooseImage();
        if (result && result.relativePath) {
          const row = btn.closest('.variant-edit-row');
          const input = row.querySelector('.variant-edit-image-back');
          if (input) {
            input.value = result.relativePath;
            // Update thumbnail
            const existingThumb = row.querySelector('label:nth-child(4) img');
            if (existingThumb) {
              existingThumb.src = resolveAssetUrl(result.relativePath, { width: 200 });
            } else {
              const thumbImg = document.createElement('img');
              thumbImg.src = resolveAssetUrl(result.relativePath, { width: 200 });
              thumbImg.style.cssText = 'max-height:60px;margin-top:8px;border-radius:4px;';
              input.parentElement.parentElement.appendChild(thumbImg);
            }
          }
        }
      });
    });

    // Add event listeners for delete buttons
    const deleteButtons = elements.inventoryEditVariantsList.querySelectorAll('.variant-delete-btn');
    deleteButtons.forEach((btn) => {
      btn.addEventListener('click', async () => {
        const row = btn.closest('.variant-edit-row');
        const itemIdsStr = row.getAttribute('data-item-ids');
        const colorName = row.querySelector('.variant-edit-color-name')?.value || 'this variant';

        if (!itemIdsStr) {
          showToast('Unable to find variant items to delete.', 'error');
          return;
        }

        // Confirm deletion
        const itemIds = itemIdsStr.split(',').filter(Boolean);
        const confirmed = await nativeConfirm(`Delete "${colorName}" variant? This will delete ${itemIds.length} inventory item(s) (all sizes of this color). This action cannot be undone.`, 'Delete Variant');

        if (!confirmed) return;

        try {
          btn.disabled = true;
          btn.textContent = 'Deleting...';

          // Delete all items for this variant
          for (const itemId of itemIds) {
            await printStation.deleteInventoryItem({ itemId });
          }

          showToast(`Deleted ${itemIds.length} item(s) for "${colorName}" variant.`, 'success');

          // Reload inventory
          await loadInventory(state.inventoryMaterial, { silent: true });

          // Refresh the edit form to show updated variants
          const currentItemId = elements.inventoryEditItemSelect?.value;
          if (currentItemId) {
            fillInventoryEditForm(currentItemId);
          }
        } catch (error) {
          console.error('Error deleting variant:', error);
          showToast(error.message || 'Unable to delete variant.', 'error');
          btn.disabled = false;
          btn.textContent = 'Delete this variant';
        }
      });
    });
  }

  // Enable submit button
  const submitButton = elements.inventoryEditForm?.querySelector('button[type="submit"]');
  if (submitButton) {
    submitButton.disabled = false;
  }
}

function addNewVariantToEdit() {
  if (!elements.inventoryEditVariantsList) return;

  // Get the current variant count for the index
  const existingRows = elements.inventoryEditVariantsList.querySelectorAll('.variant-edit-row');
  const newIndex = existingRows.length;

  // Create new variant row HTML
  const newVariantHTML = `
    <div class="variant-edit-row" data-variant-index="${newIndex}" data-is-new="true" style="border:1px solid var(--border);border-radius:8px;padding:16px;margin-top:12px;width:fit-content;">
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
        <label>
          <span>Color Name</span>
          <input type="text" class="variant-edit-color-name" value="" placeholder="e.g., Black" required />
        </label>
        <label>
          <span>Color Hex (optional)</span>
          <input type="text" class="variant-edit-color-hex" value="" placeholder="#000000" />
        </label>
        <label>
          <span>Front Image</span>
          <div style="display:flex;gap:8px;">
            <input type="text" class="variant-edit-image-front" value="" placeholder="/api/library/.../front.jpg" />
            <button type="button" class="variant-edit-choose-front secondary">Choose…</button>
          </div>
        </label>
        <label>
          <span>Back Image</span>
          <div style="display:flex;gap:8px;">
            <input type="text" class="variant-edit-image-back" value="" placeholder="/api/library/.../back.jpg" />
            <button type="button" class="variant-edit-choose-back secondary">Choose…</button>
          </div>
        </label>
        <div style="grid-column:1/-1;">
          <button type="button" class="variant-remove-new secondary" style="color:var(--danger);">Remove this variant</button>
        </div>
      </div>
    </div>
  `;

  // Append to the list
  elements.inventoryEditVariantsList.insertAdjacentHTML('beforeend', newVariantHTML);

  // Get the newly added row
  const newRow = elements.inventoryEditVariantsList.querySelector(`[data-variant-index="${newIndex}"]`);

  // Add event listeners for image choosers
  const chooseFrontBtn = newRow.querySelector('.variant-edit-choose-front');
  const chooseBackBtn = newRow.querySelector('.variant-edit-choose-back');
  const removeBtn = newRow.querySelector('.variant-remove-new');

  if (chooseFrontBtn) {
    chooseFrontBtn.addEventListener('click', async () => {
      const result = await printStation.chooseImage();
      if (result && result.relativePath) {
        const input = newRow.querySelector('.variant-edit-image-front');
        if (input) input.value = result.relativePath;
      }
    });
  }

  if (chooseBackBtn) {
    chooseBackBtn.addEventListener('click', async () => {
      const result = await printStation.chooseImage();
      if (result && result.relativePath) {
        const input = newRow.querySelector('.variant-edit-image-back');
        if (input) input.value = result.relativePath;
      }
    });
  }

  if (removeBtn) {
    removeBtn.addEventListener('click', () => {
      newRow.remove();
    });
  }
}

function fillInventoryEditForm(itemId) {
  console.log('===== fillInventoryEditForm called with itemId:', itemId);
  if (!elements.inventoryEditForm) return;
  const item = itemId ? getInventoryItem(itemId) : null;
  console.log('Item data:', item);

  // Check if this item is part of a variant group
  const isVariantGroup = item?.variantGroupId;
  console.log('Is variant group?', isVariantGroup, 'variantGroupId:', item?.variantGroupId);

  // Toggle between single and variant modes
  if (elements.inventoryEditSingleMode) {
    elements.inventoryEditSingleMode.style.display = isVariantGroup ? 'none' : '';
  }
  if (elements.inventoryEditVariantMode) {
    elements.inventoryEditVariantMode.style.display = isVariantGroup ? '' : 'none';
  }

  if (isVariantGroup) {
    // Variant group mode
    fillVariantGroupEditForm(item);
  } else {
    // Single item mode (original behavior)
    const disabled = !item;
    const inputs = [
      elements.inventoryEditName,
      elements.inventoryEditSize,
      elements.inventoryEditMaterial,
      elements.inventoryEditColor,
      elements.inventoryEditColorName,
      elements.inventoryEditUnit,
      elements.inventoryEditCost,
      elements.inventoryEditUrl,
      elements.inventoryEditFabric,
      elements.inventoryEditDescription,
      elements.inventoryEditImageUrl,
      elements.inventoryEditImageUrlBack,
      elements.inventoryEditNotes
    ].filter(Boolean);
    const submitButton = elements.inventoryEditForm?.querySelector('button[type="submit"]');
    inputs.forEach((input) => {
      input.disabled = disabled;
    });
    if (submitButton) {
      submitButton.disabled = disabled;
    }
    if (!item) {
      if (elements.inventoryEditName) elements.inventoryEditName.value = '';
      if (elements.inventoryEditSize) elements.inventoryEditSize.value = '';
      if (elements.inventoryEditMaterial) elements.inventoryEditMaterial.value = '';
      if (elements.inventoryEditColor) elements.inventoryEditColor.value = '';
      if (elements.inventoryEditColorName) elements.inventoryEditColorName.value = '';
      if (elements.inventoryEditUnit) elements.inventoryEditUnit.value = '';
      if (elements.inventoryEditCost) elements.inventoryEditCost.value = '';
      if (elements.inventoryEditUrl) elements.inventoryEditUrl.value = '';
      if (elements.inventoryEditFabric) elements.inventoryEditFabric.value = '';
      if (elements.inventoryEditDescription) elements.inventoryEditDescription.value = '';
      if (elements.inventoryEditImageUrl) elements.inventoryEditImageUrl.value = '';
      if (elements.inventoryEditImageUrlBack) elements.inventoryEditImageUrlBack.value = '';
      if (elements.inventoryEditNotes) elements.inventoryEditNotes.value = '';
      return;
    }

    if (elements.inventoryEditName) elements.inventoryEditName.value = item.name || '';
    if (elements.inventoryEditSize) elements.inventoryEditSize.value = item.size || '';
    if (elements.inventoryEditMaterial) {
      elements.inventoryEditMaterial.value = item.material || '';
    }
    if (elements.inventoryEditColor) elements.inventoryEditColor.value = item.color || '';
    if (elements.inventoryEditColorName) elements.inventoryEditColorName.value = item.colorName || '';
    if (elements.inventoryEditUnit) elements.inventoryEditUnit.value = item.unit || '';
    if (elements.inventoryEditCost)
      elements.inventoryEditCost.value = centsToDisplay(item.unitCostCents);
    if (elements.inventoryEditUrl) elements.inventoryEditUrl.value = item.itemUrl || '';
    if (elements.inventoryEditFabric) elements.inventoryEditFabric.value = item.fabric || '';
    if (elements.inventoryEditDescription) elements.inventoryEditDescription.value = item.description || '';
    if (elements.inventoryEditImageUrl) elements.inventoryEditImageUrl.value = item.imageUrl || '';
    if (elements.inventoryEditImageUrlBack) elements.inventoryEditImageUrlBack.value = item.imageUrlBack || '';
    if (elements.inventoryEditNotes) elements.inventoryEditNotes.value = item.notes || '';
  }
}

function setInventoryStatus(message, variant = 'muted') {
  if (!elements.inventoryStatus) return;
  elements.inventoryStatus.textContent = message;
  elements.inventoryStatus.className = `inventory-status ${variant}`;
}

// --- S&S Visual Browser (categories -> brands -> styles -> variants) ---
// Modal stack management
function openModal(modal) {
  if (!modal) return;

  // Add stacking class based on current stack depth
  if (state.modalStack.length > 0) {
    if (state.modalStack.length === 1) {
      modal.classList.add('modal-stacked');
    } else if (state.modalStack.length >= 2) {
      modal.classList.add('modal-stacked-2');
    }
  }

  // Add to stack and show modal
  state.modalStack.push(modal);
  modal.removeAttribute('hidden');
  // Clear any inline styles set by auto-cleanup that would hide the modal
  modal.style.display = '';
  modal.style.pointerEvents = '';
  modal.style.visibility = '';
}

function closeModal(modal) {
  if (!modal) return;

  // Remove from stack
  const index = state.modalStack.indexOf(modal);
  if (index > -1) {
    state.modalStack.splice(index, 1);
  }

  // Remove stacking classes and hide
  modal.classList.remove('modal-stacked', 'modal-stacked-2');
  modal.setAttribute('hidden', '');
}

function openSsawVisual() {
  if (!elements.ssawVisualModal) return;
  openModal(elements.ssawVisualModal);
  renderSsawCategories();
  // Initialize preferred label from warehouse input
  if (elements.ssawInStockLabel) {
    elements.ssawInStockLabel.textContent = 'Showing in-stock at IL/GA/PA';
  }
  // Hide or force the in-stock checkbox if present
  if (elements.ssawInStockOnly) {
    try { elements.ssawInStockOnly.checked = true; elements.ssawInStockOnly.closest('label').style.display = 'none'; } catch (_) {}
  }
}

function closeSsawVisual() {
  if (!elements.ssawVisualModal) return;
  closeModal(elements.ssawVisualModal);
  resetSsawSelected();
}

function setSsawStatus(msg) {
  if (elements.ssawStatus) elements.ssawStatus.textContent = msg || '';
}

function setSsawCrumbs(parts) {
  const nav = elements.ssawCrumbs;
  if (!nav) return;
  nav.innerHTML = '';
  parts.forEach((p, idx) => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.textContent = p.label;
    if (p.onClick) btn.addEventListener('click', p.onClick);
    if (idx === parts.length - 1) btn.classList.add('current');
    nav.appendChild(btn);
    if (idx !== parts.length - 1) {
      const sep = document.createElement('span');
      sep.textContent = '›';
      sep.style.opacity = '0.75';
      sep.style.margin = '0 6px';
      nav.appendChild(sep);
    }
  });
}

function buildSsawCard({ title, meta, imageUrl, onClick }) {
  const card = document.createElement('button');
  card.type = 'button';
  card.className = 'ssaw-card';
  card.addEventListener('click', onClick);
  const media = document.createElement('div');
  media.className = 'ssaw-card__media';
  if (imageUrl) {
    const img = document.createElement('img');
    img.src = imageUrl;
    img.alt = title || 'Preview';
    img.loading = 'lazy';
    media.appendChild(img);
  }
  const body = document.createElement('div');
  body.className = 'ssaw-card__body';
  const h = document.createElement('div');
  h.className = 'ssaw-card__title';
  h.textContent = title || 'Untitled';
  body.appendChild(h);
  if (meta) {
    const p = document.createElement('div');
    p.className = 'ssaw-card__meta';
    p.textContent = meta;
    body.appendChild(p);
  }
  card.appendChild(media);
  card.appendChild(body);
  return card;
}

let SSAW_CATEGORIES = [
  { id: 'tshirt', label: 'T-Shirts', query: 't-shirt' },
  { id: 'longsleeve', label: 'Long-Sleeve', query: 'long sleeve' },
  { id: 'polo', label: 'Polos', query: 'polo' },
  { id: 'hoodie', label: 'Hoodies & Sweatshirts', query: 'hood' },
  { id: 'outerwear', label: 'Jackets & Outerwear', query: 'jacket' },
  { id: 'hat', label: 'Hats & Caps', query: 'cap' },
  { id: 'beanie', label: 'Beanies', query: 'beanie' },
  { id: 'accessory', label: 'Accessories', query: 'accessor' }
];

const ssawCache = {
  categories: new Map(),
  brandStyles: new Map(),
  availability: new Map()
};
const ssawViewState = { category: null, brand: null };
let ssawSelectedVariants = new Map();
let ssawSelectedStyles = new Map();

function resetSsawSelected() {
  ssawSelectedVariants = new Map();
  ssawSelectedStyles = new Map();
  const bar = document.getElementById('ssawSelectedBar');
  if (bar) bar.remove();
  try { elements.ssawGrid?.querySelectorAll('.ssaw-variant-card.selected, .ssaw-style-card.selected').forEach((el) => el.classList.remove('selected')); } catch (_) {}
}

function ensureSsawSelectedBar() {
  const grid = elements.ssawGrid;
  if (!grid || grid.parentElement == null) return;
  let bar = document.getElementById('ssawSelectedBar');
  if (!bar) {
    bar = document.createElement('div');
    bar.id = 'ssawSelectedBar';
    bar.style.cssText = 'position:sticky;top:6px;z-index:5;background:rgba(148,163,184,0.15);border:1px solid var(--border);border-radius:6px;padding:6px 8px;margin:6px 0;display:flex;gap:8px;align-items:center;justify-content:space-between;';
    const left = document.createElement('div');
    left.id = 'ssawSelectedCount'; left.textContent = 'Selected 0';
    const right = document.createElement('div'); right.style.display = 'flex'; right.style.gap = '8px';
    const addBtn = document.createElement('button'); addBtn.type = 'button'; addBtn.className = 'primary'; addBtn.textContent = 'Add selected to inventory';
    addBtn.addEventListener('click', () => {
      if (ssawSelectedStyles && ssawSelectedStyles.size) return addSelectedStylesToInventory();
      return addSelectedVariantsToInventory();
    });
    const clearBtn = document.createElement('button'); clearBtn.type = 'button'; clearBtn.className = 'secondary'; clearBtn.textContent = 'Clear';
    clearBtn.addEventListener('click', () => { ssawSelectedVariants.clear(); updateSsawSelectedBar(); elements.ssawGrid?.querySelectorAll('.ssaw-variant-card.selected').forEach((el)=>el.classList.remove('selected')); });
    right.append(addBtn, clearBtn); bar.append(left, right);
    grid.parentElement.insertBefore(bar, grid);
  }
  updateSsawSelectedBar();
}

function updateSsawSelectedBar() {
  const el = document.getElementById('ssawSelectedCount');
  if (el) el.textContent = `Selected ${ssawSelectedStyles.size || ssawSelectedVariants.size}`;
}

async function addSelectedVariantsToInventory() {
  if (!ssawSelectedVariants.size) { showToast('No variants selected.', 'info'); return; }
  const qtyPer = Math.max(0, Math.round(Number(elements.ssawOnHandQty?.value || '0')));
  let ok = 0, fail = 0;
  for (const v of ssawSelectedVariants.values()) {
    try {
      await printStation.createInventoryItem({
        name: v.sku,
        material: 'apparel-ssaw',
        size: v.size || undefined,
        unit: 'pcs',
        quantity: qtyPer,
        unitCostCents: Number(v.priceCents || 0) || undefined,
        colorName: v.color || undefined,
        imageUrl: v.imageUrl || undefined,
        description: `Variant for ${v.sku}`,
        notes: `S&S SKU ${v.sku}${v.color ? ' • ' + v.color : ''}`
      });
      ok++;
    } catch (_) { fail++; }
  }
  showToast(`Added ${ok} variant${ok===1?'':'s'}${fail?`, ${fail} failed`:''}.`, fail ? 'warning' : 'success');
}

async function addSelectedStylesToInventory() {
  if (!ssawSelectedStyles.size) { showToast('No styles selected.', 'info'); return; }
  const qtyPer = Math.max(0, Math.round(Number(elements.ssawOnHandQty?.value || '0')));
  let ok = 0, fail = 0;
  for (const s of ssawSelectedStyles.values()) {
    try {
      let unitCostCents = null;
      try {
        const data = await printStation.fetchSsawProducts(s.styleID);
        const variants = Array.isArray(data?.variants) ? data.variants : [];
        const prices = variants
          .map((v) => (Number.isFinite(Number(v.piecePriceCents)) ? Number(v.piecePriceCents) : (Number.isFinite(Number(v.piecePrice)) ? Math.round(Number(v.piecePrice) * 100) : null)))
          .filter((n) => Number.isFinite(n));
        if (prices.length) unitCostCents = Math.min(...prices);
      } catch (_) {}
      const name = `${s.brandName || ''} ${s.styleName || ''}`.trim() || s.title || `Style ${s.styleID}`;
      await printStation.createInventoryItem({
        name,
        material: 'apparel-ssaw',
        unit: 'pcs',
        quantity: qtyPer,
        unitCostCents: unitCostCents || undefined,
        imageUrl: s.imageUrl || undefined,
        description: s.title || undefined,
        notes: `S&S Style ${s.styleID}${s.brandName ? ' • ' + s.brandName : ''}`
      });
      ok++;
    } catch (_) { fail++; }
  }
  showToast(`Added ${ok} style${ok===1?'':'s'}${fail?`, ${fail} failed`:''}.`, fail ? 'warning' : 'success');
}

async function renderSsawCategories() {
  const grid = elements.ssawGrid;
  if (!grid) return;
  setSsawCrumbs([{ label: 'Categories' }]);
  setSsawStatus('');
  grid.innerHTML = '';
  // Apply visibility filter if configured via config fetch earlier (loadSsawVisibility stores to elements)
  let allowed = [];
  try {
    const cfg = await printStation.fetchSsawConfig();
    allowed = Array.isArray(cfg?.visibleCategories) ? cfg.visibleCategories : [];
  } catch (_) {}
  const cats = allowed.length ? SSAW_CATEGORIES.filter((c) => allowed.includes(c.id)) : SSAW_CATEGORIES;
  cats.forEach(async (cat) => {
    let previewUrl = ssawCache.categories.get(cat.id)?.previewUrl;
    if (!previewUrl) {
      try {
        const data = await printStation.fetchSsawStyles({ q: cat.query });
        const styles = Array.isArray(data?.styles) ? data.styles : [];
        const first = styles.find((s) => s.imageUrl);
        previewUrl = first?.imageUrl || '';
        ssawCache.categories.set(cat.id, { styles, previewUrl });
      } catch {
        previewUrl = '';
      }
    }
    const card = buildSsawCard({ title: cat.label, imageUrl: previewUrl, onClick: () => renderSsawBrands(cat) });
    grid.appendChild(card);
  });
}

function groupByBrand(styles) {
  const map = new Map();
  styles.forEach((s) => {
    const brand = (s.brandName || 'Other').trim();
    if (!map.has(brand)) map.set(brand, []);
    map.get(brand).push(s);
  });
  return Array.from(map.entries()).sort((a, b) => b[1].length - a[1].length || a[0].localeCompare(b[0]));
}

async function renderSsawBrands(cat) {
  const grid = elements.ssawGrid;
  if (!grid) return;
  ssawViewState.category = cat;
  setSsawCrumbs([{ label: 'Categories', onClick: () => renderSsawCategories() }, { label: cat.label }]);
  setSsawStatus(`Loading ${cat.label} brands…`);
  grid.innerHTML = '';
  let entry = ssawCache.categories.get(cat.id);
  if (!entry || !Array.isArray(entry.styles) || !entry.styles.length) {
    try {
      const data = await printStation.fetchSsawStyles({ q: cat.query });
      entry = { styles: Array.isArray(data?.styles) ? data.styles : [], previewUrl: '' };
      ssawCache.categories.set(cat.id, entry);
    } catch (err) {
      setSsawStatus('Unable to load brand list.');
      return;
    }
  }
  setSsawStatus('');
  const brands = groupByBrand(entry.styles).slice(0, 18);
  brands.forEach(([brand, styles]) => {
    const preview = styles.find((s) => s.imageUrl)?.imageUrl || '';
    const card = buildSsawCard({ title: brand, imageUrl: preview, meta: `${styles.length} style(s)`, onClick: () => renderSsawStyles(cat, brand) });
    grid.appendChild(card);
  });
}

async function styleHasPreferredInventory(styleId, preferred) {
  const key = String(styleId);
  if (!key) return true;
  // preferred can be a single code or an array of codes
  const prefs = Array.isArray(preferred) ? preferred.map((p) => String(p || '').toUpperCase()) : [String(preferred || '').toUpperCase()].filter(Boolean);
  if (!prefs.length) return true;
  const cacheKey = key + '|' + prefs.join(',');
  if (ssawCache.availability.has(cacheKey)) return ssawCache.availability.get(cacheKey);
  try {
    const data = await printStation.fetchSsawProducts(styleId);
    const variants = Array.isArray(data?.variants) ? data.variants : [];
    const ok = variants.some((v) => Array.isArray(v.warehouses) && v.warehouses.some((w) => prefs.includes(String(w.abbr || '').toUpperCase()) && Number(w.qty) > 0));
    ssawCache.availability.set(cacheKey, ok);
    return ok;
  } catch {
    ssawCache.availability.set(cacheKey, false);
    return false;
  }
}

async function renderSsawStyles(cat, brand) {
  const grid = elements.ssawGrid;
  if (!grid) return;
  ssawViewState.category = cat;
  ssawViewState.brand = brand;
  setSsawCrumbs([
    { label: 'Categories', onClick: () => renderSsawCategories() },
    { label: cat.label, onClick: () => renderSsawBrands(cat) },
    { label: brand }
  ]);
  // Default preferred warehouses: IL, GA, PA
  const prefList = ['IL','GA','PA'];
  const onlyInStock = true;
  const sizeFilter = (elements.ssawFilterSize?.value || '').trim().toUpperCase();
  const colorFilter = (elements.ssawFilterColor?.value || '').trim().toUpperCase();
  const maxPrice = Number(elements.ssawFilterMaxPrice?.value || '');
  setSsawStatus(`Loading ${brand} styles…`);
  grid.innerHTML = '';
  try {
    const data = await printStation.fetchSsawStyles({ q: cat.query, brand });
    let styles = Array.isArray(data?.styles) ? data.styles : [];
    // Enforce brand filter client-side in case the vendor API ignores brand param
    if (brand) {
      const b = String(brand).toLowerCase();
      styles = styles.filter((s) => String(s.brandName || '').toLowerCase() === b);
    }
    styles = styles.slice(0, 48);
    if (onlyInStock) {
      const checks = await Promise.all(styles.map(async (s) => ({ s, ok: await styleHasPreferredInventory(s.styleID, prefList) })));
      styles = checks.filter((c) => c.ok).map((c) => c.s);
    }
    if (sizeFilter || colorFilter || Number.isFinite(maxPrice)) {
      const enriched = await Promise.all(
        styles.map(async (s) => {
          try {
            const prod = await printStation.fetchSsawProducts(s.styleID);
            const variants = Array.isArray(prod?.variants) ? prod.variants : [];
            const match = variants.some((v) => {
              const vSize = String(v.size || '').toUpperCase();
              const vColor = String(v.color || '').toUpperCase();
              const priceCents = Number.isFinite(Number(v.piecePriceCents))
                ? Number(v.piecePriceCents)
                : Number.isFinite(Number(v.piecePrice))
                ? Math.round(Number(v.piecePrice) * 100)
                : null;
              if (sizeFilter && !vSize.includes(sizeFilter)) return false;
              if (colorFilter && !vColor.includes(colorFilter)) return false;
              if (Number.isFinite(maxPrice) && maxPrice > 0) {
                if (!Number.isFinite(priceCents)) return false;
                if (priceCents > Math.round(maxPrice * 100)) return false;
              }
              return true;
            });
            return match ? s : null;
          } catch (_) {
            return null;
          }
        })
      );
      styles = enriched.filter(Boolean);
    }
    const inCampaign = (typeof state.campaignApparelSelectIndex === 'number' && state.campaignApparelSelectIndex >= 0);
    if (inCampaign) {
      setSsawStatus(styles.length ? 'Choose a style to pick a color.' : (onlyInStock ? `No styles in-stock at IL/GA/PA` : 'No styles found'));
      // In campaign mode, click a style to go pick a color (variants)
      styles.forEach((s) => {
        const title = `${s.styleName || ''} ${s.title || ''}`.trim() || s.brandName || 'Style';
        const card = buildSsawCard({ title, imageUrl: s.imageUrl, meta: s.brandName || '', onClick: () => renderSsawVariants(s) });
        grid.appendChild(card);
      });
    } else {
      // Non-campaign flow: go one level deeper to variants before allowing add-to-inventory
      setSsawStatus(styles.length ? 'Choose a style to view color/size variants.' : (onlyInStock ? `No styles in-stock at IL/GA/PA` : 'No styles found'));
      styles.forEach((s) => {
        const title = `${s.styleName || ''} ${s.title || ''}`.trim() || s.brandName || 'Style';
        const card = buildSsawCard({ title, imageUrl: s.imageUrl, meta: s.brandName || '', onClick: () => renderSsawVariants(s) });
        grid.appendChild(card);
      });
    }
  } catch (err) {
    setSsawStatus('Unable to load style list.');
  }
}

async function renderSsawVariants(style) {
  const grid = elements.ssawGrid;
  if (!grid) return;
  ensureSsawSelectedBar();
  setSsawCrumbs([
    { label: 'Categories', onClick: () => renderSsawCategories() },
    { label: ssawViewState.category?.label || (style.brandName || 'Brand'), onClick: () => renderSsawStyles(ssawViewState.category || { label: 'Back', query: '' }, ssawViewState.brand || style.brandName || '') },
    { label: `${style.styleName || ''} ${style.title || ''}`.trim() }
  ]);
  setSsawStatus('Loading variants…');
  grid.innerHTML = '';
  try {
    const data = await printStation.fetchSsawProducts(style.styleID);
    let variants = Array.isArray(data?.variants) ? data.variants : [];
    // Filter to in-stock for preferred warehouses IL, GA, PA
    const prefList = ['IL','GA','PA'];
    variants = variants.filter((v) => Array.isArray(v.warehouses) && v.warehouses.some((w) => prefList.includes(String(w.abbr || '').toUpperCase()) && Number(w.qty) > 0));
    setSsawStatus(variants.length ? '' : 'No in-stock variants for IL/GA/PA.');
    variants.slice(0, 120).forEach((v) => {
      const card = document.createElement('div');
      card.className = 'ssaw-variant-card';
      const media = document.createElement('div');
      media.className = 'ssaw-variant-card__media';
      if (v.imageUrl) {
        const img = document.createElement('img');
        img.src = v.imageUrl;
        img.alt = `${v.color || ''} ${v.size || ''}`;
        img.loading = 'lazy';
        media.appendChild(img);
      }
      const body = document.createElement('div');
      body.className = 'ssaw-variant-card__body';
      const title = document.createElement('div');
      title.textContent = `${v.color || ''} • ${v.size || ''}`;
      const qty = document.createElement('div');
      const prefList2 = ['IL','GA','PA'];
      let qtyText = 'In stock in IL/GA/PA';
      if (Array.isArray(v.warehouses)) {
        const parts = v.warehouses
          .filter((w) => prefList2.includes(String(w.abbr || '').toUpperCase()))
          .map((w) => `${String(w.abbr).toUpperCase()}:${Number(w.qty || 0)}`);
        if (parts.length) qtyText = parts.join(' • ');
      }
      qty.className = 'ssaw-card__meta';
      qty.textContent = qtyText;
      body.append(title, qty);
      const actions = document.createElement('div');
      actions.className = 'ssaw-variant-card__actions';
      const selectToggle = document.createElement('input');
      selectToggle.type = 'checkbox';
      selectToggle.addEventListener('change', () => {
        if (selectToggle.checked) {
          const cents = Number.isFinite(Number(v.piecePriceCents)) ? Number(v.piecePriceCents) : (Number.isFinite(Number(v.piecePrice)) ? Math.round(Number(v.piecePrice)*100) : 0);
          ssawSelectedVariants.set(v.sku, { sku: v.sku, size: v.size || '', color: v.color || '', priceCents: cents, imageUrl: v.imageUrl || '' });
          card.classList.add('selected');
        } else {
          ssawSelectedVariants.delete(v.sku);
          card.classList.remove('selected');
        }
        updateSsawSelectedBar();
      });
      const selectBtn = document.createElement('button');
      selectBtn.type = 'button';
      selectBtn.className = 'secondary';
      selectBtn.textContent = (typeof state.campaignApparelSelectIndex === 'number' && state.campaignApparelSelectIndex >= 0) ? 'Use for campaign' : 'Select variant';
      selectBtn.addEventListener('click', async () => {
        const inCampaignMode = typeof state.campaignApparelSelectIndex === 'number' && state.campaignApparelSelectIndex >= 0 && state.campaign;
        const inSlotMode = typeof state.campaignApparelSlotIndex === 'number' && state.campaign;
        if (inCampaignMode || inSlotMode) {
          const cents = Number.isFinite(Number(v.piecePriceCents)) ? Number(v.piecePriceCents) : (Number.isFinite(Number(v.piecePrice)) ? Math.round(Number(v.piecePrice) * 100) : 0);
          const _ssawApparel = {
            source: 'ssaw',
            styleID: style.styleID,
            brandName: style.brandName || '',
            styleName: style.styleName || '',
            title: style.title || '',
            colorName: v.color || '',
            imageUrl: v.imageUrl || '',
            piecePriceCents: cents || undefined
          };
          // Route to 2-slot apparel chooser if active
          if (typeof window.handleApparelSelected === 'function' && inSlotMode) {
            window.handleApparelSelected(_ssawApparel);
          } else {
            state.campaign.apparel = _ssawApparel;
          }
          // Clear any per-item apparel overrides for consistency
          try { (state.campaign.items || []).forEach(it => { if (it.apparel) delete it.apparel; }); } catch (_) {}
          state.campaignApparelSelectIndex = null;
          renderCampaignItems();
          try { renderCampaignApparelSummary(); } catch (_) {}
          // If guided wizard is open, update the base image immediately
          try {
            if (elements.guidedExportModal && !elements.guidedExportModal.hasAttribute('hidden')) {
              const url = v.imageUrl ? resolveAssetUrl(v.imageUrl, { width: 1200, quality: 80 }) : '';
              state.guided.baseUrl = url;
              if (elements.guidedBaseImg) elements.guidedBaseImg.src = withCacheBust(url || '');
              setGuidedBaseStatusFromCampaign(url);
              scheduleServerPreview();
            }
          } catch (_) {}
          closeSsawVisual();
          showToast('Apparel attached to campaign.', 'success');
          return;
        }
        // Fill S&S form selects
        if (elements.ssawStyleSelect) {
          // Ensure style select has this style
          let has = Array.from(elements.ssawStyleSelect.options).some((o) => o.value === String(style.styleID));
          if (!has) {
            const opt = document.createElement('option');
            opt.value = style.styleID;
            opt.textContent = `${style.brandName || ''} ${style.styleName || ''} ${style.title || ''}`.trim();
            elements.ssawStyleSelect.appendChild(opt);
          }
          elements.ssawStyleSelect.value = String(style.styleID);
          await handleSsawStyleChange();
        }
        if (elements.ssawVariantSelect) {
          // select by SKU
          const sku = v.sku;
          const opt = Array.from(elements.ssawVariantSelect.options).find((o) => o.value === sku);
          if (opt) {
            elements.ssawVariantSelect.value = sku;
            handleSsawVariantChange();
          }
        }
        closeSsawVisual();
        showToast('Variant selected.', 'success');
      });
      actions.append(selectToggle, selectBtn);
      card.append(media, body, actions);
      grid.appendChild(card);
    });
  } catch (err) {
    setSsawStatus('Unable to load variants.');
  }
}

async function handleSsawSearchClick() {
  const q = elements.ssawSearchInput?.value.trim();
  const brand = elements.ssawBrandInput?.value.trim();
  if (!q) {
    showToast('Enter a search term.', 'warning');
    return;
  }
  try {
    setInventoryStatus('Searching S&S…', 'muted');
    const data = await printStation.fetchSsawStyles({ q, brand });
    let styles = Array.isArray(data?.styles) ? data.styles : [];
    try {
      const cfg = await printStation.fetchSsawConfig();
      const allowedCats = Array.isArray(cfg?.visibleCategories) ? cfg.visibleCategories : [];
      const allowedBrands = Array.isArray(cfg?.visibleBrands) ? cfg.visibleBrands : [];
      if (allowedCats.length || allowedBrands.length) {
        styles = styles.filter((s) => {
          const catOk = allowedCats.length ? allowedCats.includes((s.productType || '').toLowerCase()) : true;
          const brandOk = allowedBrands.length ? allowedBrands.includes(s.brandName || '') : true;
          return catOk && brandOk;
        });
      }
    } catch (_) {}
    if (!styles.length) {
      showToast('No S&S styles found.', 'warning');
    }
    if (elements.ssawStyleSelect) {
      elements.ssawStyleSelect.innerHTML = '';
      const placeholder = document.createElement('option');
      placeholder.value = '';
      placeholder.textContent = styles.length ? 'Select a style…' : 'No results';
      elements.ssawStyleSelect.appendChild(placeholder);
      styles.forEach((s) => {
        const opt = document.createElement('option');
        opt.value = s.styleID;
        opt.textContent = `${s.brandName || ''} ${s.styleName || ''} ${s.title || ''}`.trim();
        elements.ssawStyleSelect.appendChild(opt);
      });
    }
  } catch (error) {
    console.error('SSAW search failed:', error);
    showToast('S&S search failed.', 'error');
  } finally {
    setInventoryStatus('Ready', 'muted');
  }
}

async function handleSsawStyleChange() {
  const styleId = elements.ssawStyleSelect?.value || '';
  if (!styleId) return;
  try {
    elements.ssawVariantSelect.innerHTML = '<option value="">Loading…</option>';
    const data = await printStation.fetchSsawProducts(styleId);
    const variants = Array.isArray(data?.variants) ? data.variants : [];
    elements.ssawVariantSelect.innerHTML = '';
    const placeholder = document.createElement('option');
    placeholder.value = '';
    placeholder.textContent = variants.length ? 'Select a variant…' : 'No variants';
    elements.ssawVariantSelect.appendChild(placeholder);
    const pref = (elements.ssawWarehouseInput?.value || '').toUpperCase().trim();
    const filtered = pref
      ? variants.filter((v) => {
          const wh = Array.isArray(v.warehouses) ? v.warehouses : [];
          const found = wh.find((w) => String(w.abbr || '').toUpperCase() === pref);
          return found && Number(found.qty) > 0;
        })
      : variants;
    filtered.forEach((v) => {
      const opt = document.createElement('option');
      opt.value = v.sku;
      const wh = Array.isArray(v.warehouses) ? v.warehouses : [];
      let qtyText = `${Number(v.qty || 0)} in stock`;
      if (pref) {
        const found = wh.find((w) => String(w.abbr || '').toUpperCase() === pref);
        qtyText = found ? `${Number(found.qty || 0)} in ${pref}` : `0 in ${pref}`;
      }
      opt.textContent = `${v.color || ''} / ${v.size || ''} · ${qtyText}`;
      opt.dataset.size = v.size || '';
      opt.dataset.color = v.color || '';
      opt.dataset.qty = String(Number(v.qty || 0));
      const cents = Number.isFinite(Number(v.piecePriceCents))
        ? Number(v.piecePriceCents)
        : Number.isFinite(Number(v.piecePrice))
        ? Math.round(Number(v.piecePrice) * 100)
        : 0;
      opt.dataset.priceCents = String(cents);
      elements.ssawVariantSelect.appendChild(opt);
    });
    elements.ssawVendorStock.textContent = 'Vendor stock: —';
  } catch (error) {
    console.error('Load S&S variants failed:', error);
    showToast('Failed to load S&S variants.', 'error');
  }
}

function handleSsawVariantChange() {
  const opt = elements.ssawVariantSelect?.selectedOptions?.[0];
  if (!opt) return;
  const qty = Number(opt.dataset.qty || '0');
  elements.ssawVendorStock.textContent = `Vendor stock: ${qty}`;
}

async function handleSsawSaveClick() {
  const styleId = elements.ssawStyleSelect?.value || '';
  const opt = elements.ssawVariantSelect?.selectedOptions?.[0];
  if (!styleId || !opt || !opt.value) {
    showToast('Choose a style and variant.', 'error');
    return;
  }
  const sku = opt.value;
  const size = opt.dataset.size || '';
  const onHandQty = Math.max(0, Math.round(Number(elements.ssawOnHandQty?.value || '0')));
  const createOrder = elements.ssawCreateOrderCheckbox?.checked || false;
  const orderQty = Math.max(0, Math.round(Number(elements.ssawOrderQty?.value || '0')));
  const prefWh = (elements.ssawWarehouseInput?.value || '').toUpperCase().trim().replace(/[^A-Z]/g, '').slice(0, 4);
  const shipMethod = (elements.ssawShippingMethodInput?.value || '').trim();

  try {
    if (onHandQty > 0) {
      // Create or update on-hand inventory for this SKU
      await printStation.createInventoryItem({
        name: sku,
        material: 'apparel-ssaw',
        size: size || undefined,
        unit: 'pcs',
        quantity: onHandQty,
        unitCostCents: Number(opt.dataset.priceCents || '0') || undefined,
        notes: `S&S SKU ${sku}`
      });
    }

    if (createOrder && orderQty > 0) {
      // Save as pending approval (no vendor call yet)
      const payload = {
        poNumber: `INV-${Date.now()}`,
        lines: [{ sku, qty: orderQty }],
        warehouses: prefWh ? [prefWh] : undefined,
        allowSplit: false,
        shippingMethod: shipMethod || undefined,
        notes: 'Saved from Print Station (pending approval).'
      };
      await printStation.createLocalVendorOrderDraft(payload);
      showToast('Vendor order saved for approval.', 'success');
      refreshLocalVendorOrders();
    }

    showToast('Saved.', 'success');
    // Refresh list under S&S filter so user sees the item
    if (elements.inventoryMaterialSelect) {
      elements.inventoryMaterialSelect.value = 'apparel-ssaw';
      await loadInventory('apparel-ssaw', { silent: true });
    }
  } catch (error) {
    console.error('S&S add failed:', error);
    showToast(error?.message || 'Unable to save S&S item.', 'error');
  }
}

function formatSsawOrderRow(order) {
  const id = String(order?.OrderID || order?.orderID || order?.id || '—');
  const po = String(order?.CustomerPO || order?.customerPO || '—');
  const status = String(order?.OrderStatus || order?.status || '—');
  const date = String(order?.OrderDate || order?.date || order?.Created || order?.createdAt || '');
  return { id, po, status, date };
}

function toArray(value) {
  if (!value) return [];
  return Array.isArray(value) ? value : [value];
}

function extractSsawWarehouses(order) {
  const set = new Set();
  toArray(order?.Warehouses).forEach((w) => {
    const code = String(w || '').trim();
    if (code) set.add(code);
  });
  const lines = toArray(order?.Lines || order?.lines || order?.Items || order?.items);
  lines.forEach((ln) => {
    const wh = ln?.WarehouseAbbr || ln?.Warehouse || ln?.warehouse || '';
    if (wh) set.add(String(wh).trim());
  });
  return Array.from(set);
}

function extractSsawShippingMethod(order) {
  return String(
    order?.ShippingMethod || order?.shippingMethod || order?.Shipping?.Method || order?.shipping?.method || ''
  ).trim();
}

function extractSsawLines(order) {
  const raw = toArray(order?.Lines || order?.lines || order?.Items || order?.items);
  return raw
    .map((ln) => {
      const sku = ln?.Identifier || ln?.SKU || ln?.Sku || ln?.sku || '';
      const qty = ln?.Qty ?? ln?.Quantity ?? ln?.quantity ?? ln?.qty ?? 0;
      const wh = ln?.WarehouseAbbr || ln?.Warehouse || ln?.warehouse || '';
      const numQty = Number(qty);
      return sku ? { sku: String(sku), qty: Number.isFinite(numQty) ? numQty : 0, warehouse: wh || '' } : null;
    })
    .filter(Boolean);
}

function renderSsawOrderDetail(order) {
  if (!elements.ssawOrdersSummary || !elements.ssawOrdersLines || !elements.ssawOrdersActions) return;
  if (!order) {
    elements.ssawOrdersSummary.textContent = 'Select an order to view details.';
    elements.ssawOrdersLines.innerHTML = '';
    elements.ssawOrdersActions.innerHTML = '';
    return;
  }
  const meta = formatSsawOrderRow(order);
  const warehouses = extractSsawWarehouses(order);
  const shipMethod = extractSsawShippingMethod(order) || '—';
  const lines = extractSsawLines(order);
  elements.ssawOrdersSummary.innerHTML = `
    <div style="display:flex;flex-wrap:wrap;gap:10px;align-items:center;">
      <strong>Order</strong> <span>${escapeHtml(meta.id)}</span>
      <strong>PO</strong> <span>${escapeHtml(meta.po)}</span>
      <strong>Status</strong> <span>${escapeHtml(meta.status)}</span>
      <strong>Date</strong> <span>${escapeHtml(meta.date)}</span>
      <strong>Ship</strong> <span>${escapeHtml(shipMethod)}</span>
      <strong>Warehouses</strong> <span>${escapeHtml(warehouses.join(', ') || '—')}</span>
    </div>
  `;
  const rows = lines
    .map(
      (ln, idx) => `
      <tr data-index="${idx}">
        <td>${escapeHtml(ln.sku)}</td>
        <td>${escapeHtml(String(ln.qty))}</td>
        <td>${escapeHtml(ln.warehouse || '')}</td>
        <td><button type="button" class="secondary" data-action="use-qty" data-index="${idx}">Use qty</button></td>
      </tr>
    `
    )
    .join('');
  elements.ssawOrdersLines.innerHTML = `
    <table class="inventory-table">
      <thead><tr><th>SKU</th><th>Qty</th><th>WH</th><th></th></tr></thead>
      <tbody>${rows || '<tr><td colspan="4" class="placeholder">No lines.</td></tr>'}</tbody>
    </table>
  `;
  // Wire "Use qty" buttons
  Array.from(elements.ssawOrdersLines.querySelectorAll('button[data-action="use-qty"]')).forEach((btn) => {
    btn.addEventListener('click', () => {
      const idx = Number(btn.dataset.index || -1);
      if (idx >= 0 && lines[idx]) {
        if (elements.ssawOrderQty) elements.ssawOrderQty.value = String(lines[idx].qty || 0);
      }
    });
  });
  // Actions: Apply to form
  elements.ssawOrdersActions.innerHTML = '';
  const applyBtn = document.createElement('button');
  applyBtn.type = 'button';
  applyBtn.className = 'primary';
  applyBtn.textContent = 'Apply to S&S form';
  applyBtn.addEventListener('click', () => applyOrderToSsawForm(order));
  elements.ssawOrdersActions.appendChild(applyBtn);
}

function applyOrderToSsawForm(order) {
  const warehouses = extractSsawWarehouses(order);
  const shipMethod = extractSsawShippingMethod(order);
  const lines = extractSsawLines(order);
  if (elements.ssawWarehouseInput && warehouses.length) {
    elements.ssawWarehouseInput.value = warehouses[0];
  }
  if (elements.ssawShippingMethodInput && shipMethod) {
    elements.ssawShippingMethodInput.value = shipMethod;
  }
  if (elements.ssawCreateOrderCheckbox) {
    elements.ssawCreateOrderCheckbox.checked = true;
  }
  if (elements.ssawOrderQty && lines.length) {
    elements.ssawOrderQty.value = String(lines[0].qty || 0);
  }
  // Scroll to the S&S form for convenience
  try {
    elements.ssawForm?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  } catch (_) {}
  showToast('Applied order shipping/warehouse/qty to S&S form.', 'success');
}

async function refreshLocalVendorOrders() {
  if (!elements.localVendorOrdersTableBody) return;
  const vendor = elements.localVendorFilterVendor?.value.trim();
  const po = elements.localVendorFilterPO?.value.trim();
  const status = elements.localVendorFilterStatus?.value.trim();
  try {
    const data = await window.printStation.fetchLocalVendorOrders({ vendor, po, status, limit: 200 });
    const items = Array.isArray(data?.items) ? data.items : [];
    if (!items.length) {
      elements.localVendorOrdersTableBody.innerHTML = '<tr><td colspan="7" class="placeholder">No local vendor orders.</td></tr>';
      return;
    }
    const rows = items
      .map((it) => {
        const id = escapeHtml(it.id);
        const ven = escapeHtml(it.vendor || '');
        const orderId = escapeHtml(it.vendorOrderId || '');
        const poVal = escapeHtml(it.customerPO || '');
        const statusText = escapeHtml(it.status || '');
        const updated = escapeHtml(it.updatedAt || '');
        const tracking = escapeHtml(it.tracking || '');
        const actionButtons =
          (it.status === 'pending_approval')
            ? `<button type="button" class="secondary local-approve">Approve & Send</button>
               <button type="button" class="danger local-reject">Reject</button>`
            : '';
        return `
          <tr data-id="${id}">
            <td>${ven}</td>
            <td>${orderId}</td>
            <td>${poVal}</td>
            <td>
              <input type="text" class="local-status" value="${statusText}" style="width:120px;" />
            </td>
            <td>${updated}</td>
            <td>
              <input type="text" class="local-tracking" value="${tracking}" style="width:160px;" />
            </td>
            <td>
              <button type="button" class="secondary local-save">Save</button>
              ${actionButtons}
            </td>
          </tr>
        `;
      })
      .join('');
    elements.localVendorOrdersTableBody.innerHTML = rows;
    // Wire save buttons
    Array.from(elements.localVendorOrdersTableBody.querySelectorAll('button.local-save')).forEach((btn) => {
      btn.addEventListener('click', async () => {
        const tr = btn.closest('tr[data-id]');
        const id = tr?.dataset.id;
        if (!id) return;
        const statusInput = tr.querySelector('input.local-status');
        const trackingInput = tr.querySelector('input.local-tracking');
        const updates = {
          status: statusInput?.value || '',
          tracking: trackingInput?.value || ''
        };
        try {
          await window.printStation.updateLocalVendorOrder(id, updates);
          showToast('Vendor order updated.', 'success');
          refreshLocalVendorOrders();
        } catch (error) {
          console.error('Update local vendor order failed:', error);
          showToast(error?.message || 'Update failed.', 'error');
        }
      });
    });
    // Approve & Send
    Array.from(elements.localVendorOrdersTableBody.querySelectorAll('button.local-approve')).forEach((btn) => {
      btn.addEventListener('click', async () => {
        const tr = btn.closest('tr[data-id]');
        const id = tr?.dataset.id;
        if (!id) return;
        try {
          await window.printStation.approveLocalVendorOrder(id);
          showToast('Vendor order sent to vendor.', 'success');
        } catch (error) {
          console.error('Approve & send failed:', error);
          showToast(error?.message || 'Send failed.', 'error');
        } finally {
          refreshLocalVendorOrders();
        }
      });
    });
    // Reject
    Array.from(elements.localVendorOrdersTableBody.querySelectorAll('button.local-reject')).forEach((btn) => {
      btn.addEventListener('click', async () => {
        const tr = btn.closest('tr[data-id]');
        const id = tr?.dataset.id;
        if (!id) return;
        try {
          await window.printStation.rejectLocalVendorOrder(id);
          showToast('Vendor order rejected.', 'success');
        } catch (error) {
          console.error('Reject failed:', error);
          showToast(error?.message || 'Reject failed.', 'error');
        } finally {
          refreshLocalVendorOrders();
        }
      });
    });
  } catch (error) {
    console.error('Fetch local vendor orders failed:', error);
    elements.localVendorOrdersTableBody.innerHTML = '<tr><td colspan="7" class="placeholder error">Unable to load local vendor orders.</td></tr>';
  }
}

async function refreshTopSellers() {
  if (!elements.topTableBody) return;
  const params = {
    vendor: 'S&S Activewear',
    from: elements.topFromInput?.value || '',
    to: elements.topToInput?.value || '',
    limit: Math.max(1, Math.min(Number(elements.topLimitInput?.value || 10), 200))
  };
  try {
    const data = await window.printStation.fetchLocalTopVendorItems(params);
    const items = Array.isArray(data?.items) ? data.items : [];
    if (!items.length) {
      elements.topTableBody.innerHTML = '<tr><td colspan="3" class="placeholder">No data for this period.</td></tr>';
      return;
    }
    const rows = items
      .map((it) => {
        const sku = escapeHtml(it.sku || '');
        const qty = escapeHtml(String(it.quantity || 0));
        return `
          <tr data-sku="${sku}">
            <td>${sku}</td>
            <td>${qty}</td>
            <td><button type="button" class="secondary top-search">Search</button></td>
          </tr>
        `;
      })
      .join('');
    elements.topTableBody.innerHTML = rows;
    Array.from(elements.topTableBody.querySelectorAll('button.top-search')).forEach((btn) => {
      btn.addEventListener('click', () => {
        const tr = btn.closest('tr[data-sku]');
        const sku = tr?.dataset.sku || '';
        if (!sku) return;
        // Pre-fill S&S search input and search
        if (elements.ssawSearchInput) {
          elements.ssawSearchInput.value = sku;
        }
        if (elements.ssawSearchButton) {
          elements.ssawSearchButton.click();
        }
        showToast(`Searching S&S for SKU ${sku}…`, 'info');
      });
    });
  } catch (error) {
    console.error('Top sellers fetch failed:', error);
    elements.topTableBody.innerHTML = '<tr><td colspan="3" class="placeholder error">Unable to load top sellers.</td></tr>';
  }
}

async function loadSsawVisibility() {
  if (!elements.ssawCats || !elements.ssawBrandsInput) return;
  try {
    const res = await window.printStation.fetchSsawConfig();
    const cats = Array.isArray(res?.visibleCategories) ? res.visibleCategories : [];
    const brands = Array.isArray(res?.visibleBrands) ? res.visibleBrands : [];
    const styleIncludes = Array.isArray(res?.visibleStyleIncludes) ? res.visibleStyleIncludes : [];
    const styleIds = Array.isArray(res?.visibleStyleIds) ? res.visibleStyleIds : [];
    const set = new Set(cats);
    elements.ssawCats.forEach((cb) => {
      cb.checked = set.has(cb.value);
    });
    elements.ssawBrandsInput.value = brands.join(', ');
    if (elements.ssawStyleIncludesInput) elements.ssawStyleIncludesInput.value = styleIncludes.join(', ');
    if (elements.ssawStyleIdsInput) elements.ssawStyleIdsInput.value = styleIds.join(', ');
    if (elements.ssawVisibilityStatus) elements.ssawVisibilityStatus.textContent = 'Loaded.';
  } catch (error) {
    if (elements.ssawVisibilityStatus) elements.ssawVisibilityStatus.textContent = 'Unable to load.';
  }
}

async function saveSsawVisibility() {
  if (!elements.ssawCats || !elements.ssawBrandsInput) return;
  const visibleCategories = elements.ssawCats.filter((cb) => cb.checked).map((cb) => cb.value);
  const visibleBrands = elements.ssawBrandsInput.value
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
  const visibleStyleIncludes = (elements.ssawStyleIncludesInput?.value || '')
    .split(',')
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
  const visibleStyleIds = (elements.ssawStyleIdsInput?.value || '')
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
  try {
    if (elements.ssawVisibilityStatus) elements.ssawVisibilityStatus.textContent = 'Saving…';
    await window.printStation.updateSsawConfig({ visibleCategories, visibleBrands, visibleStyleIncludes, visibleStyleIds });
    if (elements.ssawVisibilityStatus) elements.ssawVisibilityStatus.textContent = 'Saved.';
  } catch (error) {
    if (elements.ssawVisibilityStatus) elements.ssawVisibilityStatus.textContent = 'Save failed.';
  }
}

// --- S&S Style Curator ---
let curatorSelected = new Set();

function initCuratorState() {
  curatorSelected = new Set();
  printStation.fetchSsawConfig()
    .then((cfg) => {
      const ids = Array.isArray(cfg?.visibleStyleIds) ? cfg.visibleStyleIds : [];
      ids.forEach((id) => curatorSelected.add(String(id)));
      renderCuratedSelected();
    })
    .catch(() => {});
}

function openSsawCurator() {
  if (!elements.ssawCurateModal) return;
  openModal(elements.ssawCurateModal);
  elements.curateStatus.textContent = '';
  elements.curateGrid.innerHTML = '';
  renderCuratedSelected();
}

function closeSsawCurator() {
  if (!elements.ssawCurateModal) return;
  closeModal(elements.ssawCurateModal);
}

function renderCuratedSelected() {
  if (!elements.curateSelectedList) return;
  elements.curateSelectedList.innerHTML = '';
  if (!curatorSelected.size) {
    const span = document.createElement('span');
    span.className = 'placeholder';
    span.textContent = 'No styles selected yet.';
    elements.curateSelectedList.appendChild(span);
    return;
  }
  curatorSelected.forEach((id) => {
    const chip = document.createElement('button');
    chip.type = 'button';
    chip.className = 'secondary';
    chip.textContent = id;
    chip.style.fontSize = '12px';
    chip.style.padding = '4px 8px';
    chip.addEventListener('click', () => {
      curatorSelected.delete(id);
      renderCuratedSelected();
      // Also uncheck card if present
      const card = elements.curateGrid?.querySelector(`.curate-card[data-style-id="${CSS.escape(id)}"]`);
      if (card) card.classList.remove('selected');
    });
    elements.curateSelectedList.appendChild(chip);
  });
}

async function curateSearch() {
  if (!elements.curateGrid) return;
  const q = (elements.curateQueryInput?.value || '').trim();
  const brand = (elements.curateBrandInput?.value || '').trim();
  if (!q && !brand) {
    elements.curateStatus.textContent = 'Enter a search term or brand.';
    return;
  }
  elements.curateStatus.textContent = 'Searching…';
  elements.curateGrid.innerHTML = '';
  try {
    // Resolve preferred warehouse from config
    let preferred = '';
    try {
      const cfg = await printStation.fetchSsawConfig();
      preferred = (cfg?.preferredWarehouse || '').toUpperCase();
    } catch (_) {}
    const data = await printStation.fetchSsawStyles({ q, brand });
    const styles = Array.isArray(data?.styles) ? data.styles : [];
    if (!styles.length) {
      elements.curateStatus.textContent = 'No results.';
      return;
    }
    elements.curateStatus.textContent = '';
    for (const s of styles) {
      // Filter by preferred warehouse and ensure a price exists
      let minCents = null;
      let passes = false;
      try {
        const prod = await printStation.fetchSsawProducts(s.styleID);
        const variants = Array.isArray(prod?.variants) ? prod.variants : [];
        for (const v of variants) {
          const priceCents = Number.isFinite(Number(v.piecePriceCents))
            ? Number(v.piecePriceCents)
            : Number.isFinite(Number(v.piecePrice))
            ? Math.round(Number(v.piecePrice) * 100)
            : null;
          if (!Number.isFinite(priceCents) || priceCents <= 0) continue;
          // If preferred warehouse configured, require presence with qty > 0
          if (preferred) {
            const warehouses = Array.isArray(v.warehouses) ? v.warehouses : [];
            const inPref = warehouses.some((w) => String(w.abbr || '').toUpperCase() === preferred && Number(w.qty || 0) > 0);
            if (!inPref) continue;
          }
          passes = true;
          if (minCents == null || priceCents < minCents) minCents = priceCents;
        }
      } catch (_) {
        // treat as non‑pass if we cannot load variants
      }
      if (!passes) continue; // skip styles without price in preferred warehouse

      const card = document.createElement('div');
      card.className = 'ssaw-card curate-card';
      card.dataset.styleId = String(s.styleID || '');
      if (curatorSelected.has(String(s.styleID))) card.classList.add('selected');

      const media = document.createElement('div');
      media.className = 'ssaw-card__media';
      const img = document.createElement('img');
      img.src = s.imageUrl || '';
      img.alt = `${s.brandName || ''} ${s.styleName || ''}`.trim();
      img.loading = 'lazy';
      media.appendChild(img);

      const body = document.createElement('div');
      body.className = 'ssaw-card__body';
      const title = document.createElement('div');
      title.className = 'ssaw-card__title';
      title.textContent = `${s.brandName || ''} ${s.styleName || ''}`.trim() || 'Style';
      body.appendChild(title);
      const price = document.createElement('div');
      price.className = 'ssaw-card__meta';
      price.textContent = Number.isFinite(minCents) ? formatMoney(minCents) : '—';
      body.appendChild(price);
      const toggle = document.createElement('button');
      toggle.type = 'button';
      toggle.className = 'secondary';
      toggle.textContent = curatorSelected.has(String(s.styleID)) ? 'Remove' : 'Include';
      toggle.addEventListener('click', () => {
        const id = String(s.styleID);
        if (curatorSelected.has(id)) {
          curatorSelected.delete(id);
          card.classList.remove('selected');
          toggle.textContent = 'Include';
        } else {
          curatorSelected.add(id);
          card.classList.add('selected');
          toggle.textContent = 'Remove';
        }
        renderCuratedSelected();
      });
      body.appendChild(toggle);

      card.appendChild(media);
      card.appendChild(body);
      elements.curateGrid.appendChild(card);
    }
  } catch (error) {
    elements.curateStatus.textContent = 'Search failed.';
  }
}

async function saveCuratedStyles() {
  try {
    await printStation.updateSsawConfig({ visibleStyleIds: Array.from(curatorSelected) });
    showToast('Curated styles saved.', 'success');
    // Optionally update selected chips in visibility form
    closeSsawCurator();
  } catch (error) {
    showToast('Unable to save curated styles.', 'error');
  }
}

async function handleSsawOrdersSearch() {
  if (!elements.ssawOrdersTableBody || !elements.ssawOrdersStatus) return;
  const id = elements.ssawOrdersIdInput?.value.trim();
  const po = elements.ssawOrdersPoInput?.value.trim();
  const from = elements.ssawOrdersFromInput?.value;
  const to = elements.ssawOrdersToInput?.value;
  const status = elements.ssawOrdersStatusInput?.value.trim();
  try {
    elements.ssawOrdersStatus.textContent = 'Searching…';
    const data = await window.printStation.fetchSsawOrders({ id, po, from, to, status });
    const orders = Array.isArray(data?.orders) ? data.orders : (data?.order ? [data.order] : []);
    if (!orders.length) {
      elements.ssawOrdersTableBody.innerHTML = '<tr><td colspan="4" class="placeholder">No matching orders.</td></tr>';
      renderSsawOrderDetail(null);
      elements.ssawOrdersStatus.textContent = 'No results.';
      return;
    }
    const rowsHtml = orders
      .map((o, idx) => {
        const r = formatSsawOrderRow(o);
        return `<tr data-index="${idx}"><td>${escapeHtml(r.id)}</td><td>${escapeHtml(r.po)}</td><td>${escapeHtml(r.status)}</td><td>${escapeHtml(r.date)}</td></tr>`;
      })
      .join('');
    elements.ssawOrdersTableBody.innerHTML = rowsHtml;
    elements.ssawOrdersStatus.textContent = `${orders.length} result${orders.length === 1 ? '' : 's'}.`;
    renderSsawOrderDetail(null);
    // Row click shows details
    Array.from(elements.ssawOrdersTableBody.querySelectorAll('tr[data-index]')).forEach((tr) => {
      tr.addEventListener('click', () => {
        const idx = Number(tr.dataset.index || -1);
        if (idx >= 0 && orders[idx]) {
          renderSsawOrderDetail(orders[idx]);
        }
      });
    });
  } catch (error) {
    console.error('SSAW orders search failed:', error);
    elements.ssawOrdersStatus.textContent = error?.message || 'Search failed';
    elements.ssawOrdersTableBody.innerHTML = '<tr><td colspan="4" class="placeholder error">Search failed.</td></tr>';
  }
}

function populateInventorySelects() {
  const adjustSelect = elements.inventoryAdjustItemSelect;
  const editSelect = elements.inventoryEditItemSelect;
  if (adjustSelect) {
    adjustSelect.innerHTML = '';
    if (!state.inventoryItems.length) {
      const option = document.createElement('option');
      option.value = '';
      option.textContent = 'No inventory items';
      adjustSelect.appendChild(option);
      adjustSelect.disabled = true;
    } else {
      adjustSelect.disabled = false;
      const placeholder = document.createElement('option');
      placeholder.value = '';
      placeholder.textContent = 'Select an item';
      adjustSelect.appendChild(placeholder);
      state.inventoryItems.forEach((item) => {
        const option = document.createElement('option');
        option.value = item.id;
        option.textContent = `${item.name} · ${formatInventoryQuantity(item)}`;
        adjustSelect.appendChild(option);
      });
    }
  }

  if (editSelect) {
    const previous = editSelect.value;
    editSelect.innerHTML = '';
    if (!state.inventoryItems.length) {
      const option = document.createElement('option');
      option.value = '';
      option.textContent = 'No inventory items';
      editSelect.appendChild(option);
      editSelect.disabled = true;
      fillInventoryEditForm(null);
    } else {
      editSelect.disabled = false;
      const placeholder = document.createElement('option');
      placeholder.value = '';
      placeholder.textContent = 'Select an item';
      editSelect.appendChild(placeholder);
      state.inventoryItems.forEach((item) => {
        const option = document.createElement('option');
        option.value = item.id;
        option.textContent = `${item.name} · ${formatInventoryQuantity(item)}`;
        editSelect.appendChild(option);
      });
      const nextValue = previous && getInventoryItem(previous) ? previous : state.inventoryItems[0].id;
      editSelect.value = nextValue || '';
      fillInventoryEditForm(editSelect.value || null);
    }
  }
}

function renderInventoryList() {
  if (!elements.inventoryList) return;
  if (state.inventoryLoading) {
    elements.inventoryList.innerHTML = '<p class="placeholder">Loading inventory…</p>';
    return;
  }
  if (state.inventoryError) {
    elements.inventoryList.innerHTML = `<p class="placeholder error">${escapeHtml(
      state.inventoryError
    )}</p>`;
    return;
  }
  if (!state.inventoryItems.length) {
    elements.inventoryList.innerHTML =
      '<p class="placeholder">No inventory items yet. Add stock to get started.</p>';
    return;
  }

  const rows = state.inventoryItems
    .map((item) => {
      const name = escapeHtml(item.name || 'Inventory item');
      const material = escapeHtml(formatInventoryMaterial(item.material));
      const quantity = formatInventoryQuantity(item);
      const imageCell = item.imageUrl
        ? `<img src="${escapeHtml(resolveAssetUrl(item.imageUrl, { width: 80, quality: 70 }))}" alt="img" style="max-height:42px;border-radius:6px;border:1px solid var(--border);" />`
        : '—';
      let colorDisplay = item.color || '';
      let colorIsHex =
        !!colorDisplay && /^#([0-9A-F]{3}|[0-9A-F]{6})$/i.test(colorDisplay);
      if ((!colorDisplay || colorDisplay === '#') && item.material === 'apparel') {
        const match = /Color:\s*([^|]+)/i.exec(item.notes || '');
        if (match) {
          colorDisplay = match[1].trim();
          colorIsHex = /^#([0-9A-F]{3}|[0-9A-F]{6})$/i.test(colorDisplay);
        }
      }
      const colorCell = colorDisplay
        ? colorIsHex
          ? `<span class="inventory-swatch" style="background-color: ${colorDisplay};"></span>${escapeHtml(
              colorDisplay
            )}`
          : escapeHtml(colorDisplay)
        : '—';
      const cost = Number.isFinite(item.unitCostCents)
        ? formatMoney(item.unitCostCents)
        : '—';
      const used =
        Number.isFinite(item.totalRemoved) && item.totalRemoved
          ? `${Math.abs(Math.round(item.totalRemoved))} ${item.unit || 'unit'}`
          : '—';
      const notes = item.notes ? escapeHtml(item.notes) : '—';
      return `
        <tr data-inventory-id="${item.id}" style="cursor: pointer;">
          <td>${imageCell}</td>
          <td>${name}</td>
          <td>${material}</td>
          <td>${colorCell}</td>
          <td>${escapeHtml(quantity)}</td>
          <td>${escapeHtml(cost)}</td>
          <td>${escapeHtml(used)}</td>
          <td>${notes}</td>
        </tr>
      `;
    })
    .join('');

  elements.inventoryList.innerHTML = `
    <table class="inventory-table">
      <thead>
        <tr>
          <th>Image</th>
          <th>Name</th>
          <th>Material</th>
          <th>Color</th>
          <th>On hand</th>
          <th>Cost/unit</th>
          <th>Used</th>
          <th>Notes</th>
        </tr>
      </thead>
      <tbody>${rows}</tbody>
    </table>
  `;
}

async function loadInventory(material = state.inventoryMaterial, { silent = false } = {}) {
  if (state.inventoryLoading && !silent) {
    return;
  }
  const targetMaterial = material || state.inventoryMaterial || 'regular-vinyl';
  state.inventoryLoading = true;
  state.inventoryError = null;
  if (!silent) {
    setInventoryStatus('Loading inventory…', 'muted');
    renderInventoryList();
  }
  try {
    const data = await printStation.fetchInventory({ material: targetMaterial });
    const items = Array.isArray(data?.items) ? data.items.slice() : [];
    items.sort((a, b) => (a.name || '').localeCompare(b.name || ''));
    state.inventoryItems = items;
    state.inventoryMaterial = targetMaterial;
    if (elements.inventoryMaterialSelect) {
      elements.inventoryMaterialSelect.value = targetMaterial;
    }
    const label = targetMaterial === 'all' ? 'All inventory' : formatInventoryMaterial(targetMaterial);
    setInventoryStatus(
      `${items.length} item${items.length === 1 ? '' : 's'} · ${label}`,
      'muted'
    );
    state.inventoryLoading = false;
    renderInventoryList();
    populateInventorySelects();
    state.inventoryInitialized = true;
  } catch (error) {
    console.error('Unable to load inventory:', error);
    state.inventoryItems = [];
    state.inventoryError = error.message || 'Unable to load inventory.';
    setInventoryStatus(state.inventoryError, 'error');
    state.inventoryLoading = false;
    renderInventoryList();
    populateInventorySelects();
    state.inventoryInitialized = false;
  } finally {
    state.inventoryLoading = false;
  }
}

async function handleInventoryAddSubmit(event) {
  event.preventDefault();
  const name = elements.inventoryAddName?.value.trim();
  if (!name) {
    showToast('Enter a name for the inventory item.', 'error');
    return;
  }
  const quantityValue = Number(elements.inventoryAddQuantity?.value);
  const payload = {
    name,
    color: elements.inventoryAddColor?.value.trim() || undefined,
    material: elements.inventoryAddMaterial?.value || 'regular-vinyl',
    quantity: Number.isFinite(quantityValue) ? Math.round(quantityValue) : 0,
    unit: elements.inventoryAddUnit?.value.trim() || 'unit',
    unitCost: elements.inventoryAddCost?.value.trim() || undefined,
    itemUrl: elements.inventoryAddUrl?.value.trim() || undefined,
    notes: elements.inventoryAddNotes?.value.trim() || undefined
  };

  try {
    elements.inventoryAddForm.classList.add('busy');
    setInventoryStatus('Saving inventory item…', 'muted');
    await printStation.createInventoryItem(payload);
    showToast('Inventory item saved.', 'success');
    elements.inventoryAddForm.reset();
    if (elements.inventoryAddUnit) {
      elements.inventoryAddUnit.value = payload.unit || 'unit';
    }
    if (elements.inventoryAddMaterial) {
      elements.inventoryAddMaterial.value = payload.material;
    }
    if (elements.inventoryAddQuantity) {
      elements.inventoryAddQuantity.value = '0';
    }
    await loadInventory(state.inventoryMaterial, { silent: true });
  } catch (error) {
    console.error(error);
    showToast(error.message || 'Unable to save inventory item.', 'error', 6000);
    setInventoryStatus(error.message || 'Unable to save inventory item.', 'error');
  } finally {
    elements.inventoryAddForm.classList.remove('busy');
  }
}

// Apparel Variant Management Functions
let variantCounter = 0;

function addApparelVariantRow() {
  if (!elements.inventoryApparelVariants) return;

  const variantId = `variant-${Date.now()}-${variantCounter++}`;

  const row = document.createElement('div');
  row.className = 'apparel-variant-row';
  row.setAttribute('data-variant-id', variantId);
  row.style.cssText = 'border:1px solid var(--border);border-radius:8px;padding:16px;position:relative;';

  row.innerHTML = `
    <button type="button" class="variant-remove-btn" style="position:absolute;top:8px;right:8px;background:none;border:none;color:var(--danger);cursor:pointer;font-size:20px;" title="Remove variant">×</button>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
      <label>
        <span>Color Name</span>
        <input type="text" class="variant-color-name" placeholder="e.g. Black, Navy" required />
      </label>
      <label>
        <span>Color Hex (optional)</span>
        <input type="text" class="variant-color-hex" placeholder="#000000" />
      </label>
      <label>
        <span>Front Image</span>
        <div style="display:flex;gap:8px;">
          <input type="text" class="variant-image-front" placeholder="/api/library/.../front.jpg" />
          <button type="button" class="variant-choose-front secondary">Choose…</button>
        </div>
        <img class="variant-thumb-front" style="max-height:60px;display:none;margin-top:6px;border:1px solid var(--border);border-radius:4px;" />
      </label>
      <label>
        <span>Back Image</span>
        <div style="display:flex;gap:8px;">
          <input type="text" class="variant-image-back" placeholder="/api/library/.../back.jpg" />
          <button type="button" class="variant-choose-back secondary">Choose…</button>
        </div>
        <img class="variant-thumb-back" style="max-height:60px;display:none;margin-top:6px;border:1px solid var(--border);border-radius:4px;" />
      </label>
    </div>
  `;

  elements.inventoryApparelVariants.appendChild(row);

  // Add event listeners for this variant row
  const removeBtn = row.querySelector('.variant-remove-btn');
  const chooseFrontBtn = row.querySelector('.variant-choose-front');
  const chooseBackBtn = row.querySelector('.variant-choose-back');
  const frontInput = row.querySelector('.variant-image-front');
  const backInput = row.querySelector('.variant-image-back');
  const frontThumb = row.querySelector('.variant-thumb-front');
  const backThumb = row.querySelector('.variant-thumb-back');

  removeBtn?.addEventListener('click', () => {
    row.remove();
    // If no variants left, add one automatically
    if (!elements.inventoryApparelVariants.children.length) {
      addApparelVariantRow();
    }
  });

  chooseFrontBtn?.addEventListener('click', async () => {
    try {
      const result = await printStation.chooseImage();
      if (result && result.relativePath) {
        frontInput.value = result.relativePath;
        if (frontThumb) {
          frontThumb.src = resolveAssetUrl(result.relativePath, { width: 200 });
          frontThumb.style.display = 'block';
        }
      }
    } catch (err) {
      console.error('Error choosing front image:', err);
    }
  });

  chooseBackBtn?.addEventListener('click', async () => {
    try {
      const result = await printStation.chooseImage();
      if (result && result.relativePath) {
        backInput.value = result.relativePath;
        if (backThumb) {
          backThumb.src = resolveAssetUrl(result.relativePath, { width: 200 });
          backThumb.style.display = 'block';
        }
      }
    } catch (err) {
      console.error('Error choosing back image:', err);
    }
  });

  // Show thumbnail when path is entered manually
  frontInput?.addEventListener('blur', () => {
    if (frontInput.value && frontThumb) {
      frontThumb.src = resolveAssetUrl(frontInput.value, { width: 200 });
      frontThumb.style.display = 'block';
    }
  });

  backInput?.addEventListener('blur', () => {
    if (backInput.value && backThumb) {
      backThumb.src = resolveAssetUrl(backInput.value, { width: 200 });
      backThumb.style.display = 'block';
    }
  });
}

function getApparelVariantsData() {
  if (!elements.inventoryApparelVariants) return [];

  const variants = [];
  const rows = elements.inventoryApparelVariants.querySelectorAll('.apparel-variant-row');

  rows.forEach(row => {
    const colorName = row.querySelector('.variant-color-name')?.value.trim();
    const colorHex = row.querySelector('.variant-color-hex')?.value.trim();
    const imageFront = row.querySelector('.variant-image-front')?.value.trim();
    const imageBack = row.querySelector('.variant-image-back')?.value.trim();

    if (colorName) {
      variants.push({
        colorName,
        colorHex: colorHex || null,
        imageFront: imageFront || null,
        imageBack: imageBack || null
      });
    }
  });

  return variants;
}

async function handleInventoryApparelSubmit(event) {
  event.preventDefault();
  if (!elements.inventoryApparelTypeSelect) return;

  // Get apparel type
  let typeValue = elements.inventoryApparelTypeSelect.value || 'tshirt';
  let typeLabel;
  if (typeValue === 'other') {
    const custom = elements.inventoryApparelTypeOtherInput?.value.trim();
    if (!custom) {
      showToast('Enter a new apparel type.', 'error');
      elements.inventoryApparelTypeOtherInput?.focus();
      return;
    }
    typeValue = addApparelType(custom);
    typeLabel = formatApparelTypeLabel(custom);
    renderApparelTypeOptions(typeValue);
  } else {
    const entry = state.apparelTypes.find((item) => item.value === typeValue);
    typeLabel = entry?.label || formatApparelTypeLabel(typeValue);
  }

  if (!typeValue) {
    showToast('Unable to determine apparel type.', 'error');
    return;
  }

  // Get quantity per size
  const quantityRaw = Number(elements.inventoryApparelQuantity?.value);
  if (!Number.isFinite(quantityRaw) || quantityRaw <= 0) {
    showToast('Enter a quantity greater than zero.', 'error');
    elements.inventoryApparelQuantity?.focus();
    return;
  }
  const quantity = Math.round(quantityRaw);

  // Get selected sizes
  let selectedSizes = [];
  try {
    const checks = elements.inventoryApparelSizeChecks?.querySelectorAll('input[type="checkbox"]') || [];
    selectedSizes = Array.from(checks).filter((c) => c.checked).map((c) => c.value);
  } catch (_) {}
  if (!selectedSizes.length) {
    showToast('Select at least one size.', 'error');
    return;
  }

  // Get cost per unit
  const costInput = elements.inventoryApparelCostInput?.value.trim() || '';
  if (!costInput) {
    showToast('Enter the cost per unit.', 'error');
    elements.inventoryApparelCostInput?.focus();
    return;
  }
  const normalizedCostNumber = Number(costInput.replace(/,/g, '.').replace(/[^0-9.]/g, ''));
  if (!Number.isFinite(normalizedCostNumber) || normalizedCostNumber < 0) {
    showToast('Enter a valid cost per unit.', 'error');
    elements.inventoryApparelCostInput?.focus();
    return;
  }

  // Get other fields
  const fabricValue = elements.inventoryApparelFabricInput?.value.trim() || '';
  const descr = elements.inventoryApparelDescription?.value.trim();
  const referenceUrl = elements.inventoryApparelReferenceUrl?.value.trim();

  // Get color variants
  const variants = getApparelVariantsData();
  if (!variants.length) {
    showToast('Add at least one color variant.', 'error');
    return;
  }

  // Validate variants
  for (let i = 0; i < variants.length; i++) {
    if (!variants[i].colorName) {
      showToast(`Variant ${i + 1}: Enter a color name.`, 'error');
      return;
    }
  }

  // Generate variant group ID for all variants of this product
  const variantGroupId = `vg-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

  const hexPattern = /^#?[0-9a-f]{3,6}$/i;

  try {
    elements.inventoryApparelForm?.classList.add('busy');
    setInventoryStatus('Saving apparel variants…', 'muted');

    let itemCount = 0;

    // Create inventory item for each variant × size combination
    for (const variant of variants) {
      const colorPayload = variant.colorHex && hexPattern.test(variant.colorHex) ? variant.colorHex : undefined;
      const colorDisplay = variant.colorName;

      // Build notes for this variant
      const notesParts = [`Apparel type: ${typeLabel}`];
      if (selectedSizes.length) notesParts.push(`Sizes: ${selectedSizes.join(', ')}`);
      if (colorDisplay) notesParts.push(`Color: ${colorDisplay}`);
      if (fabricValue) notesParts.push(`Fabric: ${fabricValue}`);
      const notes = notesParts.join(' | ').slice(0, 160);

      // Common fields for this variant
      const common = {
        material: 'apparel',
        quantity,
        unit: 'unit',
        notes,
        unitCostCents: Math.round(normalizedCostNumber * 100),
        variantGroupId,
        referenceUrl: referenceUrl || null
      };
      if (colorPayload) common.color = colorPayload;
      if (!colorPayload && colorDisplay) common.colorName = colorDisplay;
      if (fabricValue) common.fabric = fabricValue;
      if (descr) common.description = descr;
      if (variant.imageFront) {
        common.imageUrl = variant.imageFront;
      }
      if (variant.imageBack) {
        common.imageUrlBack = variant.imageBack;
      }

      // Create one item per size for this variant
      for (const size of selectedSizes) {
        const name = [typeLabel, colorDisplay, size].filter(Boolean).join(' - ').slice(0, 120);
        const payload = { ...common, name, size };
        await printStation.createInventoryItem(payload);
        itemCount++;
      }
    }

    showToast(`Saved ${itemCount} apparel item(s) across ${variants.length} color variant(s).`, 'success');

    // Reset form
    if (elements.inventoryApparelForm) {
      elements.inventoryApparelForm.reset();
    }
    if (elements.inventoryApparelQuantity) {
      elements.inventoryApparelQuantity.value = '1';
    }
    if (elements.inventoryApparelVariants) {
      elements.inventoryApparelVariants.innerHTML = '';
    }

    // Re-initialize with one variant
    addApparelVariantRow();

    populateInventoryApparelSizes();
    renderApparelTypeOptions(typeValue);
    showInventoryApparelOtherRow(false);

    await loadInventory(state.inventoryMaterial === 'apparel' ? 'apparel' : state.inventoryMaterial, {
      silent: true
    });
  } catch (error) {
    console.error(error);
    showToast(error.message || 'Unable to save apparel item.', 'error', 6000);
    setInventoryStatus(error.message || 'Unable to save apparel item.', 'error');
  } finally {
    elements.inventoryApparelForm?.classList.remove('busy');
  }
}

async function handleInventoryAdjustSubmit(event) {
  event.preventDefault();
  const itemId = elements.inventoryAdjustItemSelect?.value;
  if (!itemId) {
    showToast('Select an inventory item to adjust.', 'error');
    return;
  }
  const changeValue = Number(elements.inventoryAdjustAmount?.value);
  if (!Number.isFinite(changeValue) || Math.round(changeValue) === 0) {
    showToast('Enter a non-zero adjustment amount.', 'error');
    return;
  }
  const payload = {
    itemId,
    change: Math.round(changeValue),
    reason: elements.inventoryAdjustReason?.value.trim() || undefined,
    notes: elements.inventoryAdjustNotes?.value.trim() || undefined
  };

  try {
    elements.inventoryAdjustForm.classList.add('busy');
    setInventoryStatus('Updating inventory…', 'muted');
    await printStation.adjustInventory(payload);
    showToast('Inventory updated.', 'success');
    elements.inventoryAdjustForm.reset();
    await loadInventory(state.inventoryMaterial, { silent: true });
  } catch (error) {
    console.error(error);
    showToast(error.message || 'Unable to adjust inventory.', 'error', 6000);
    setInventoryStatus(error.message || 'Unable to adjust inventory.', 'error');
  } finally {
    elements.inventoryAdjustForm.classList.remove('busy');
  }
}

