async function handleInventoryEditSubmit(event) {
  event.preventDefault();
  const itemId = elements.inventoryEditItemSelect?.value;
  if (!itemId) {
    showToast('Select an inventory item to edit.', 'error');
    return;
  }
  const current = getInventoryItem(itemId);

  // Check if we're in variant group mode
  const isVariantMode = current?.variantGroupId && elements.inventoryEditVariantMode?.style.display !== 'none';

  if (isVariantMode) {
    // Handle variant group update
    await handleVariantGroupEditSubmit(current);
  } else {
    // Handle single item update (original behavior)
    const payload = { itemId };
    const name = elements.inventoryEditName?.value.trim();
    if (name) payload.name = name;
    const size = elements.inventoryEditSize?.value.trim();
    if (size) payload.size = size;
    const material = elements.inventoryEditMaterial?.value;
    if (material) payload.material = material;
    const colorRaw = elements.inventoryEditColor?.value;
    if (colorRaw !== undefined) {
      const color = colorRaw.trim();
      if (color) {
        payload.color = color;
      } else if (current?.color) {
        payload.color = '';
      }
    }
    const unit = elements.inventoryEditUnit?.value.trim();
    if (unit) payload.unit = unit;
    const cost = elements.inventoryEditCost?.value.trim();
    if (cost) {
      payload.unitCost = cost;
    } else if (
      elements.inventoryEditCost &&
      current &&
      current.unitCostCents !== null &&
      current.unitCostCents !== undefined
    ) {
      payload.unitCost = '';
    }
    const url = elements.inventoryEditUrl?.value.trim();
    if (elements.inventoryEditUrl) {
      const rawUrl = elements.inventoryEditUrl.value.trim();
      if (rawUrl) {
        payload.itemUrl = rawUrl;
      } else if (current?.itemUrl) {
        payload.itemUrl = '';
      }
    }
    if (elements.inventoryEditNotes) {
      const notesRaw = elements.inventoryEditNotes.value;
      if (notesRaw.trim()) {
        payload.notes = notesRaw.trim();
      } else if (notesRaw !== undefined && current?.notes) {
        payload.notes = '';
      }
    }
    const colorName = elements.inventoryEditColorName?.value?.trim();
    if (colorName !== undefined) {
      if (colorName) payload.colorName = colorName; else if (current?.colorName) payload.colorName = '';
    }
    const fabric = elements.inventoryEditFabric?.value?.trim();
    if (fabric !== undefined) {
      if (fabric) payload.fabric = fabric; else if (current?.fabric) payload.fabric = '';
    }
    const description = elements.inventoryEditDescription?.value?.trim();
    if (description !== undefined) {
      if (description) payload.description = description; else if (current?.description) payload.description = '';
    }
    if (elements.inventoryEditImageUrl) {
      const urlVal = elements.inventoryEditImageUrl.value.trim();
      if (urlVal) payload.imageUrl = urlVal; else if (current?.imageUrl) payload.imageUrl = '';
    }
    if (elements.inventoryEditImageUrlBack) {
      const urlValBack = elements.inventoryEditImageUrlBack.value.trim();
      if (urlValBack) payload.imageUrlBack = urlValBack; else if (current?.imageUrlBack) payload.imageUrlBack = '';
    }

    if (Object.keys(payload).length === 1) {
      showToast('Enter at least one field to update.', 'warning');
      return;
    }

    try {
      elements.inventoryEditForm?.classList.add('busy');
      setInventoryStatus('Updating inventory item…', 'muted');
      await printStation.updateInventoryItem(payload);
      showToast('Inventory item updated.', 'success');
      await loadInventory(state.inventoryMaterial, { silent: true });
      if (elements.inventoryEditItemSelect) {
        elements.inventoryEditItemSelect.value = itemId;
        fillInventoryEditForm(itemId);
      }
    } catch (error) {
      console.error(error);
      showToast(error.message || 'Unable to update inventory item.', 'error', 6000);
      setInventoryStatus(error.message || 'Unable to update inventory item.', 'error');
    } finally {
      elements.inventoryEditForm?.classList.remove('busy');
    }
  }
}

async function handleVariantGroupEditSubmit(item) {
  if (!item?.variantGroupId) return;

  try {
    elements.inventoryEditForm?.classList.add('busy');
    setInventoryStatus('Updating variant group…', 'muted');

    // Get shared field values
    const cost = elements.inventoryEditVariantCost?.value.trim();
    const fabric = elements.inventoryEditVariantFabric?.value.trim();
    const description = elements.inventoryEditVariantDescription?.value.trim();
    const referenceUrl = elements.inventoryEditVariantRefUrl?.value.trim();

    // Get all variant rows
    const variantRows = elements.inventoryEditVariantsList?.querySelectorAll('.variant-edit-row') || [];
    const updatedVariants = [];
    const newVariants = [];

    variantRows.forEach((row) => {
      const isNew = row.getAttribute('data-is-new') === 'true';
      const itemIdsStr = row.getAttribute('data-item-ids');
      const colorName = row.querySelector('.variant-edit-color-name')?.value.trim();
      const colorHex = row.querySelector('.variant-edit-color-hex')?.value.trim();
      const imageFront = row.querySelector('.variant-edit-image-front')?.value.trim();
      const imageBack = row.querySelector('.variant-edit-image-back')?.value.trim();

      if (colorName) {
        if (isNew) {
          // This is a new variant to be created
          newVariants.push({
            colorName,
            colorHex: colorHex || null,
            imageFront: imageFront || null,
            imageBack: imageBack || null
          });
        } else if (itemIdsStr) {
          // This is an existing variant to be updated
          const itemIds = itemIdsStr.split(',').filter(Boolean);
          updatedVariants.push({
            itemIds,
            colorName,
            colorHex: colorHex || null,
            imageFront: imageFront || null,
            imageBack: imageBack || null
          });
        }
      }
    });

    if (!updatedVariants.length && !newVariants.length) {
      showToast('At least one variant is required.', 'error');
      return;
    }

    console.log('[Variant Submit] Updating', updatedVariants.length, 'variants');
    updatedVariants.forEach((v, idx) => {
      console.log(`  Variant ${idx}: colorName="${v.colorName}", ${v.itemIds.length} items [${v.itemIds.join(', ')}]`);
    });

    let updateCount = 0;

    // Update each variant × size combination
    for (const variant of updatedVariants) {
      console.log(`[Variant Submit] Processing variant "${variant.colorName}" with ${variant.itemIds.length} items`);
      // Update all items (all sizes) for this color variant using the stored item IDs
      for (const itemId of variant.itemIds) {
        console.log(`  Updating item ${itemId}`);
        const payload = {
          itemId
        };

        // Update shared fields (apply to ALL items in variant group)
        if (cost !== undefined && cost !== null) payload.unitCost = cost;
        payload.fabric = fabric || '';
        payload.description = description || '';
        payload.referenceUrl = referenceUrl || '';

        // Update variant-specific fields (apply to all sizes of this color)
        payload.colorName = variant.colorName;
        payload.color = variant.colorHex || '';
        payload.imageUrl = variant.imageFront || '';
        payload.imageUrlBack = variant.imageBack || '';

        await printStation.updateInventoryItem(payload);
        updateCount++;
      }
    }

    // Handle new variants
    if (newVariants.length > 0) {
      console.log(`[Variant Submit] Creating ${newVariants.length} new variants`);

      // Get all sizes from the variant group (from the first item in the group)
      const allItemsInGroup = state.inventoryItems.filter(i => i.variantGroupId === item.variantGroupId);
      const sizes = [...new Set(allItemsInGroup.map(i => i.size).filter(Boolean))];

      console.log(`Sizes in variant group: ${sizes.join(', ')}`);

      for (const newVariant of newVariants) {
        console.log(`Creating new variant "${newVariant.colorName}" with ${sizes.length} sizes`);

        // Extract the type from the existing item name (e.g., "T-Shirt - Black - L" -> "T-Shirt")
        let typeLabel = 'Apparel';
        if (item.name) {
          const nameParts = item.name.split(' - ');
          if (nameParts.length >= 3) {
            typeLabel = nameParts[0]; // First part is the type
          }
        }

        // Create an item for each size
        for (const size of sizes) {
          // Construct name following the pattern: TYPE - COLOR - SIZE
          const name = [typeLabel, newVariant.colorName, size].filter(Boolean).join(' - ').slice(0, 120);

          // Build notes like the standard apparel add process
          const notesParts = [`Apparel type: ${typeLabel}`];
          if (sizes.length) notesParts.push(`Sizes: ${sizes.join(', ')}`);
          if (newVariant.colorName) notesParts.push(`Color: ${newVariant.colorName}`);
          if (fabric) notesParts.push(`Fabric: ${fabric}`);
          const notes = notesParts.join(' | ').slice(0, 160);

          const payload = {
            name: name,
            material: 'apparel',
            variantGroupId: item.variantGroupId,
            size: size,
            colorName: newVariant.colorName,
            color: newVariant.colorHex || '',
            imageUrl: newVariant.imageFront || '',
            imageUrlBack: newVariant.imageBack || '',
            quantity: 0,
            unit: 'ea',
            unitCost: cost || undefined,
            fabric: fabric || undefined,
            description: description || undefined,
            referenceUrl: referenceUrl || undefined,
            notes: notes
          };

          console.log(`Creating item for size ${size}:`, payload);
          await printStation.createInventoryItem(payload);
          updateCount++;
        }
      }
    }

    const message = newVariants.length > 0
      ? `Updated ${updatedVariants.length} variant(s) and created ${newVariants.length} new variant(s).`
      : `Updated ${updateCount} variant item(s).`;
    showToast(message, 'success');
    await loadInventory(state.inventoryMaterial, { silent: true });

    // Keep the same item selected
    if (elements.inventoryEditItemSelect) {
      elements.inventoryEditItemSelect.value = item.id;
      fillInventoryEditForm(item.id);
    }
  } catch (error) {
    console.error(error);
    showToast(error.message || 'Unable to update variant group.', 'error', 6000);
    setInventoryStatus(error.message || 'Unable to update variant group.', 'error');
  } finally {
    elements.inventoryEditForm?.classList.remove('busy');
  }
}

