  /**
   * Generate metadata with real-time progress using Server-Sent Events
   */
  async function generateMetadataWithProgress(categorySlug) {
    const serverBaseUrl = state.config?.serverBaseUrl?.trim();
    if (!serverBaseUrl) {
      throw new Error('Server URL not configured. Please check settings.');
    }
    const url = `${ensureTrailingSlash(serverBaseUrl)}api/admin/catalog/generate-metadata`;

    return new Promise((resolve, reject) => {
      // Use fetch with SSE
      const headers = {
        'Content-Type': 'application/json'
      };
      if (state.config?.apiKey) {
        headers['X-API-Key'] = state.config.apiKey;
      }
      fetch(url, {
        method: 'POST',
        headers,
        body: JSON.stringify({ categorySlug })
      })
        .then(response => {
          if (!response.ok) {
            throw new Error(`HTTP ${response.status}`);
          }

          const reader = response.body.getReader();
          const decoder = new TextDecoder();
          let buffer = '';

          // Read SSE stream
          function readStream() {
            reader.read().then(({ done, value }) => {
              if (done) {
                resolve();
                return;
              }

              buffer += decoder.decode(value, { stream: true });
              const lines = buffer.split('\n');
              buffer = lines.pop() || '';

              for (const line of lines) {
                if (line.startsWith('data: ')) {
                  try {
                    const data = JSON.parse(line.substring(6));
                    handleMetadataEvent(data);
                  } catch (error) {
                    console.error('Failed to parse SSE data:', error);
                  }
                }
              }

              readStream();
            }).catch(reject);
          }

          readStream();
        })
        .catch(reject);
    });
  }

  /**
   * Handle metadata generation events
   */
  function handleMetadataEvent(event) {
    switch (event.type) {
      case 'start':
        console.log('Metadata generation started for:', event.categorySlug);
        break;

      case 'progress':
        updateMetadataProgress(event);
        break;

      case 'complete':
        handleMetadataComplete(event);
        break;

      case 'error':
        handleMetadataError(event);
        break;
    }
  }

  /**
   * Update progress UI
   */
  function updateMetadataProgress(event) {
    const { current, total, processed, failed, item, result } = event;

    // Update progress bar
    const percentage = total > 0 ? (current / total) * 100 : 0;
    elements.metadataProgressBar.style.width = `${percentage.toFixed(1)}%`;
    elements.metadataProgressBar.textContent = `${percentage.toFixed(0)}%`;

    // Update stats
    elements.metadataProgress.textContent = `${current} / ${total}`;
    elements.metadataProcessed.textContent = `✓ Processed: ${processed}`;
    elements.metadataFailed.textContent = `✗ Failed: ${failed}`;

    // Add result to list (prepend to show latest first)
    if (result) {
      addResultItem(result);
    }
  }

  /**
   * Add a result item to the results list
   */
  function addResultItem(result) {
    const resultItem = document.createElement('div');
    resultItem.className = `result-item ${result.success ? 'success' : 'error'}`;

    const header = document.createElement('div');
    header.className = 'result-item-header';

    const name = document.createElement('span');
    name.className = 'result-item-name';
    name.textContent = result.name;

    const status = document.createElement('span');
    status.className = `result-item-status ${result.success ? 'success' : 'error'}`;
    status.textContent = result.success ? '✓ Success' : '✗ Failed';

    header.appendChild(name);
    header.appendChild(status);
    resultItem.appendChild(header);

    if (result.success && result.description) {
      const description = document.createElement('div');
      description.className = 'result-item-description';
      description.textContent = result.description;
      resultItem.appendChild(description);
    } else if (!result.success && result.error) {
      const error = document.createElement('div');
      error.className = 'result-item-error';
      error.textContent = `Error: ${result.error}`;
      resultItem.appendChild(error);
    }

    // Prepend (show latest first)
    if (elements.metadataResults.firstChild?.classList?.contains('muted')) {
      elements.metadataResults.innerHTML = '';
    }
    elements.metadataResults.insertBefore(resultItem, elements.metadataResults.firstChild);

    // Limit to 50 items for performance
    while (elements.metadataResults.children.length > 50) {
      elements.metadataResults.removeChild(elements.metadataResults.lastChild);
    }

    // Scroll to top to show latest
    elements.metadataResults.parentElement.scrollTop = 0;
  }

  /**
   * Handle completion
   */
  function handleMetadataComplete(event) {
    const { processed, failed, total } = event;

    elements.metadataProgressBar.style.width = '100%';
    elements.metadataProgressBar.textContent = '100%';

    // Add completion message
    const completionItem = document.createElement('div');
    completionItem.className = 'result-item success';
    completionItem.innerHTML = `
      <div class="result-item-header">
        <span class="result-item-name">✓ Generation Complete!</span>
        <span class="result-item-status success">Done</span>
      </div>
      <div class="result-item-description">
        Successfully processed ${processed} of ${total} items. ${failed > 0 ? `${failed} failed.` : 'All succeeded!'}
      </div>
    `;
    elements.metadataResults.insertBefore(completionItem, elements.metadataResults.firstChild);

    // Show success notification
    setTimeout(() => {
      alert(`Metadata generation complete!\n\nProcessed: ${processed}\nFailed: ${failed}\n\nCatalog has been updated.`);
    }, 500);

    // Reload catalog to show new metadata
    loadCatalog({ forceRefresh: true });
  }

  /**
   * Handle error
   */
  function handleMetadataError(event) {
    console.error('Metadata generation error:', event.error);

    const errorItem = document.createElement('div');
    errorItem.className = 'result-item error';
    errorItem.innerHTML = `
      <div class="result-item-header">
        <span class="result-item-name">✗ Error Occurred</span>
        <span class="result-item-status error">Failed</span>
      </div>
      <div class="result-item-error">${event.error}</div>
    `;
    elements.metadataResults.insertBefore(errorItem, elements.metadataResults.firstChild);

    alert(`Error: ${event.error}`);
  }

