        // Use native Electron dialog to avoid focus issues
        const ok = await printStation.showConfirm(
          `Delete campaign "${state.campaign.title || slug}"? This cannot be undone.`,
          'Delete Campaign'
        );
        if (!ok) return;
        await printStation.deleteCampaign(slug);
        // Reset to new campaign state directly (don't trigger another confirm via click)
        resetToNewCampaign(false);
        showToast('Campaign deleted.', 'success');
