  // Inbound SMS list
  async function loadInboundMessages() {
    try {
      if (!elements.inboundStatus) return;
      elements.inboundStatus.textContent = 'Loading…';
      const from = (elements.inboundFromFilter?.value || '').trim();
      const data = await printStation.listInboundMessages({ from, limit: 200 });
      const items = Array.isArray(data?.items) ? data.items : [];
      const rows = items.map((m) => {
        const when = m.createdAt ? new Date(m.createdAt).toLocaleString() : '';
        const body = (m.body || '').replace(/</g, '&lt;');
        return `<tr><td>${when}</td><td>${m.from || ''}</td><td>${m.to || ''}</td><td style="max-width:520px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;" title="${body}">${body}</td></tr>`;
      }).join('');
      elements.inboundTableBody.innerHTML = rows || '<tr><td colspan="4" class="placeholder">No messages.</td></tr>';
      elements.inboundStatus.textContent = `Loaded ${items.length}`;
      elements.inboundStatus.className = 'muted';
    } catch (err) {
      elements.inboundStatus.textContent = err?.message || 'Unable to load inbound messages';
      elements.inboundStatus.className = 'warning';
    }
  }
  elements.inboundRefreshButton?.addEventListener('click', loadInboundMessages);
