/**
 * Initialize Schedule Manager event handlers
 */
function initFbScheduleManagerHandlers() {
  // Campaign selector
  if (elements.fbScheduleCampaignSelect) {
    elements.fbScheduleCampaignSelect.addEventListener('change', handleFbScheduleCampaignSelect);
  }

  // Create schedule button
  if (elements.fbScheduleCreateBtn) {
    elements.fbScheduleCreateBtn.addEventListener('click', handleCreateSchedule);
  }

  // Refresh and process buttons
  if (elements.fbScheduleRefreshBtn) {
    elements.fbScheduleRefreshBtn.addEventListener('click', loadScheduledPosts);
  }
  if (elements.fbScheduleProcessNowBtn) {
    elements.fbScheduleProcessNowBtn.addEventListener('click', handleProcessPendingPosts);
  }

  // Insights button
  const fbInsightsBtn = document.getElementById('fbInsightsBtn');
  if (fbInsightsBtn) {
    fbInsightsBtn.addEventListener('click', openFbInsightsModal);
  }

  // Insights modal controls
  const insightsRefreshBtn = document.getElementById('insightsRefreshBtn');
  if (insightsRefreshBtn) {
    insightsRefreshBtn.addEventListener('click', loadFbInsights);
  }
  const insightsDaysFilter = document.getElementById('insightsDaysFilter');
  if (insightsDaysFilter) {
    insightsDaysFilter.addEventListener('change', loadFbInsights);
  }
  const insightsCampaignFilter = document.getElementById('insightsCampaignFilter');
  if (insightsCampaignFilter) {
    insightsCampaignFilter.addEventListener('change', loadFbInsights);
  }

  // Status filter dropdown
  if (elements.fbScheduleFilterStatus) {
    elements.fbScheduleFilterStatus.addEventListener('change', (e) => {
      state.fbSchedule.filter = e.target.value || 'all';
      state.fbSchedule.currentPage = 0; // Reset to first page on filter change
      renderScheduledPosts();
    });
  }

  // Campaign filter dropdown
  if (elements.fbScheduleFilterCampaign) {
    elements.fbScheduleFilterCampaign.addEventListener('change', () => {
      // Clear selection when changing campaign filter
      state.fbSchedule.selectedPostIds.clear();
      state.fbSchedule.currentPage = 0; // Reset to first page on filter change
      renderScheduledPosts();
    });
  }

  // Bulk actions
  if (elements.fbScheduleSelectAll) {
    elements.fbScheduleSelectAll.addEventListener('change', (e) => {
      handleSelectAllScheduledPosts(e.target.checked);
    });
  }
  if (elements.fbScheduleBulkDeleteBtn) {
    elements.fbScheduleBulkDeleteBtn.addEventListener('click', handleBulkDeleteScheduledPosts);
  }

  // Mockup template modal handlers
  if (elements.fbScheduleCreateTemplateBtn) {
    elements.fbScheduleCreateTemplateBtn.addEventListener('click', openMockupTemplateModal);
  }
  if (elements.mockupTemplateChooseBtn) {
    elements.mockupTemplateChooseBtn.addEventListener('click', handleChooseTemplateBaseImage);
  }
  if (elements.mockupTemplateSaveBtn) {
    elements.mockupTemplateSaveBtn.addEventListener('click', handleSaveMockupTemplate);
  }

  // Generate with AI button for post text
  if (elements.fbScheduleGenerateAIBtn) {
    elements.fbScheduleGenerateAIBtn.addEventListener('click', handleFbScheduleGenerateAI);
  }

  // AI per-item checkbox toggle
  if (elements.fbScheduleAiPerItem) {
    elements.fbScheduleAiPerItem.addEventListener('change', () => {
      const checked = elements.fbScheduleAiPerItem.checked;
      // Update hint text
      if (elements.fbSchedulePostTextHint) {
        elements.fbSchedulePostTextHint.textContent = checked ? '(optional - AI will generate)' : '(applies to all)';
      }
      // Disable/enable post text when AI is enabled
      if (elements.fbSchedulePostText) {
        elements.fbSchedulePostText.disabled = checked;
        elements.fbSchedulePostText.placeholder = checked
          ? 'AI will generate unique text for each item'
          : 'Leave empty for AI generation per item, or enter text for all posts';
      }
    });
  }
}

/**
 * Generate sample post text with AI for Facebook scheduler
 * This generates a preview using the first item - actual posts will be generated at post time
 */
async function handleFbScheduleGenerateAI() {
  const btn = elements.fbScheduleGenerateAIBtn;
  const textArea = elements.fbSchedulePostText;
  const campaignSelect = elements.fbScheduleCampaignSelect;

  if (!textArea) {
    showToast('Post text field not found', 'error');
    return;
  }

  // Get selected campaign for context
  const campaignSlug = campaignSelect?.value;
  if (!campaignSlug) {
    showToast('Please select a campaign first', 'warning');
    return;
  }

  // Disable button and show loading state
  if (btn) {
    btn.disabled = true;
    btn.textContent = 'Generating...';
  }

  try {
    // Load full campaign data to get items with images
    const campaignResult = await printStation.getCampaign(campaignSlug);
    if (!campaignResult?.success || !campaignResult.campaign) {
      throw new Error('Failed to load campaign data');
    }

    const campaign = campaignResult.campaign;
    console.log('[FB Schedule] Loaded campaign:', campaign.title, 'with', campaign.items?.length, 'items');

    // Build context from campaign
    const campaignContext = {
      title: campaign.title || '',
      subtitle: campaign.subtitle || '',
      description: campaign.mockupStrategy?.description || campaign.description || '',
      salesInitiative: campaign.salesInitiative || '',
      benefits: campaign.benefits || '',
      socialProof: campaign.socialProof || ''
    };

    // Add campaign-level apparel info if available
    if (campaign.apparel) {
      campaignContext.apparelType = campaign.apparel.styleName || campaign.apparel.styleDescription || '';
      campaignContext.apparelBrand = campaign.apparel.brandName || '';
      campaignContext.apparelColor = campaign.apparel.colorName || '';
      campaignContext.apparelDescription = campaign.apparel.description || campaign.apparel.styleDescription || '';
    }

    // Get first item with an image to generate sample post
    const itemsWithImages = (campaign.items || []).filter(item =>
      item.image || item.imagePath || item.imageUrl || item.mockupImage
    );

    if (itemsWithImages.length === 0) {
      throw new Error('No items with images found in this campaign. Add items with images first.');
    }

    // Use first item for sample generation
    const firstItem = itemsWithImages[0];

    // Extract per-item apparel info (may override campaign-level)
    const itemApparel = firstItem.apparel || {};
    const itemApparelType = itemApparel.styleName || itemApparel.styleDescription || itemApparel.productType || campaignContext.apparelType || '';
    const itemApparelColor = itemApparel.colorName || itemApparel.color || firstItem.colorName || firstItem.color || campaignContext.apparelColor || '';
    const itemApparelBrand = itemApparel.brandName || itemApparel.brand || campaignContext.apparelBrand || '';
    const itemApparelDescription = itemApparel.description || itemApparel.styleDescription || campaignContext.apparelDescription || '';

    // Update campaign context with item-specific apparel info for AI generation
    if (itemApparelType) campaignContext.apparelType = itemApparelType;
    if (itemApparelColor) campaignContext.apparelColor = itemApparelColor;
    if (itemApparelBrand) campaignContext.apparelBrand = itemApparelBrand;
    if (itemApparelDescription) campaignContext.apparelDescription = itemApparelDescription;

    // Build item with per-item apparel info for AI generation
    const items = [{
      name: cleanAiGeneratedName(firstItem.title || firstItem.name) || 'Custom Design',
      title: cleanAiGeneratedName(firstItem.title || firstItem.name) || '',
      description: firstItem.description || '',
      category: firstItem.category || '',
      image: firstItem.image || firstItem.imagePath || firstItem.imageUrl || firstItem.mockupImage || '',
      imagePath: firstItem.image || firstItem.imagePath || firstItem.imageUrl || firstItem.mockupImage || '',
      // Include per-item apparel info so AI can use it
      apparel: firstItem.apparel || null,
      apparelType: itemApparelType || '',
      colorName: itemApparelColor || '',
      color: itemApparel.color || firstItem.color || ''
    }];

    console.log('[FB Schedule] Generating sample with first item:', items[0].name, 'apparel:', itemApparelType || 'none', 'color:', itemApparelColor || 'none', 'image:', items[0].image);

    const result = await printStation.generateFacebookPost({
      items,
      style: 'showcase',
      collectionUrl: elements.fbScheduleCollectionUrl?.value || '',
      productType: campaign.bulkType || 'other',
      campaign: campaignContext
    });

    if (!result.success) {
      throw new Error(result.error || 'Failed to generate post');
    }

    // Get the first post's text - API returns posts array
    const firstPost = result.data?.posts?.[0];
    const generatedText = firstPost?.text || '';
    const hashtags = firstPost?.hashtags?.join(' ') || result.data?.recommendedHashtags?.join(' ') || '';

    if (generatedText) {
      // Set post text with CTA (without hashtags - those go in separate field)
      let fullPost = generatedText;
      if (firstPost?.cta) {
        fullPost += '\n\n' + firstPost.cta;
      }
      textArea.value = fullPost;

      // Populate the hashtags field separately
      if (hashtags && elements.fbScheduleHashtags) {
        elements.fbScheduleHashtags.value = hashtags;
      }

      showToast('Sample post generated! Each scheduled post will have unique AI-generated text.', 'success');
    } else {
      console.log('[FB Schedule] Unexpected response structure:', result.data);
      showToast('No text was generated', 'warning');
    }

  } catch (err) {
    console.error('[FB Schedule] AI generation failed:', err);
    showToast('Failed to generate: ' + (err.message || 'Unknown error'), 'error');
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.textContent = 'Generate with AI';
    }
  }
}

