/**
 * Handle campaign selection in Schedule Manager
 */
async function handleFbScheduleCampaignSelect(e) {
  const slug = e.target.value;
  if (!slug) {
    state.fbSchedule.selectedCampaign = null;
    if (elements.fbScheduleCampaignInfo) {
      elements.fbScheduleCampaignInfo.innerHTML = '<p class="text-muted">Select a campaign to see details</p>';
    }
    return;
  }

  try {
    const result = await printStation.getCampaign(slug);
    if (result?.success) {
      state.fbSchedule.selectedCampaign = result.campaign;
      renderFbScheduleCampaignInfo(result.campaign);
    }
  } catch (err) {
    console.error('[FB Schedule] Failed to load campaign:', err);
    showToast('Failed to load campaign details', 'error');
  }
}

/**
 * Render campaign info box
 */
function renderFbScheduleCampaignInfo(campaign) {
  if (!campaign) return;

  const items = campaign.items || [];
  const hasApparel = items.some(i => i.mockupImage || i.mockup);
  const campaignType = hasApparel ? 'Apparel' : 'Custom Art';

  // Update info display
  if (elements.fbScheduleCampaignInfo) {
    elements.fbScheduleCampaignInfo.style.display = 'block';
  }
  if (elements.fbScheduleItemCount) {
    elements.fbScheduleItemCount.textContent = items.length;
  }
  if (elements.fbScheduleCampaignType) {
    elements.fbScheduleCampaignType.textContent = campaignType;
  }

  // Show template section only for custom art campaigns
  if (elements.fbScheduleTemplateSection) {
    elements.fbScheduleTemplateSection.style.display = hasApparel ? 'none' : 'block';
  }

  // For custom art campaigns, try to auto-select a matching template
  if (!hasApparel && elements.fbScheduleTemplateSelect) {
    const templates = state.fbSchedule.templates || [];
    const matchingTemplate = templates.find(t =>
      t.campaignSlug === campaign.slug ||
      t.name?.toLowerCase().includes(campaign.slug?.toLowerCase())
    );
    if (matchingTemplate) {
      elements.fbScheduleTemplateSelect.value = matchingTemplate.id;
      console.log('[FB Schedule] Auto-selected template:', matchingTemplate.name);
    }
  }

  // Enable create button
  if (elements.fbScheduleCreateBtn) {
    elements.fbScheduleCreateBtn.disabled = false;
  }
  if (elements.fbScheduleCreateStatus) {
    elements.fbScheduleCreateStatus.textContent = `Ready to schedule ${items.length} posts`;
  }
}

/**
 * Load scheduled posts from server
 */
async function loadScheduledPosts() {
  try {
    state.fbSchedule.loading = true;
    const result = await printStation.listFbScheduledPosts();

    if (result?.success && Array.isArray(result.posts)) {
      state.fbSchedule.scheduledPosts = result.posts;
      populateCampaignFilterDropdown(result.posts);
      renderScheduledPosts();
      updateScheduleStats();
    }
  } catch (err) {
    console.error('[FB Schedule] Failed to load scheduled posts:', err);
    showToast('Failed to load scheduled posts', 'error');
  } finally {
    state.fbSchedule.loading = false;
  }
}

/**
 * Populate the campaign filter dropdown based on scheduled posts
 */
function populateCampaignFilterDropdown(posts) {
  const select = elements.fbScheduleFilterCampaign;
  if (!select) return;

  // Get unique campaign slugs from posts
  const campaigns = [...new Set(posts.map(p => p.campaignSlug).filter(Boolean))].sort();

  // Remember current selection
  const currentValue = select.value;

  // Rebuild options
  select.innerHTML = '<option value="">All Campaigns</option>';
  campaigns.forEach(slug => {
    const option = document.createElement('option');
    option.value = slug;
    option.textContent = slug;
    select.appendChild(option);
  });

  // Restore selection if it still exists
  if (campaigns.includes(currentValue)) {
    select.value = currentValue;
  }
}

/**
 * Render the list of scheduled posts
 */
function renderScheduledPosts() {
  const container = elements.fbScheduleList;
  if (!container) return;

  let posts = state.fbSchedule.scheduledPosts || [];

  // Apply status filter
  if (state.fbSchedule.filter !== 'all') {
    posts = posts.filter(p => p.status === state.fbSchedule.filter);
  }

  // Apply campaign filter if set
  const campaignFilter = elements.fbScheduleFilterCampaign?.value;
  if (campaignFilter) {
    posts = posts.filter(p => p.campaignSlug === campaignFilter);
  }

  // Store total filtered count for pagination
  const totalFilteredCount = posts.length;

  // Apply pagination
  const { currentPage, pageSize } = state.fbSchedule;
  const totalPages = Math.ceil(totalFilteredCount / pageSize);

  // Ensure current page is valid
  if (state.fbSchedule.currentPage >= totalPages && totalPages > 0) {
    state.fbSchedule.currentPage = totalPages - 1;
  }

  const startIndex = state.fbSchedule.currentPage * pageSize;
  const paginatedPosts = posts.slice(startIndex, startIndex + pageSize);

  // Show/hide bulk actions bar based on whether there are posts
  if (elements.fbScheduleBulkActions) {
    elements.fbScheduleBulkActions.style.display = posts.length > 0 ? 'flex' : 'none';
  }

  // Clear selection if posts changed
  const currentPostIds = new Set(posts.map(p => p.id));
  state.fbSchedule.selectedPostIds = new Set(
    [...state.fbSchedule.selectedPostIds].filter(id => currentPostIds.has(id))
  );
  updateBulkSelectionUI();

  // Update pagination UI
  updateSchedulePaginationUI(totalFilteredCount, totalPages);

  if (posts.length === 0) {
    container.innerHTML = `
      <div class="schedule-empty">
        <div>No ${state.fbSchedule.filter === 'all' ? '' : state.fbSchedule.filter + ' '}posts</div>
      </div>
    `;
    return;
  }

  // Use paginated posts for rendering
  posts = paginatedPosts;

  // Helper to resolve image URLs for display
  const resolveImageUrl = (imagePath) => {
    if (!imagePath) return '';

    let finalUrl;
    // Already a full URL
    if (imagePath.startsWith('http://') || imagePath.startsWith('https://')) {
      finalUrl = imagePath;
    } else {
      // Server-relative path - prepend server URL
      const serverUrl = state.config?.serverBaseUrl || 'https://blueridgecustomco.com';
      const cleanPath = imagePath.replace(/^\//, '');
      finalUrl = `${serverUrl}/${cleanPath}`;
    }

    // URL-encode spaces and special characters in the path
    try {
      const urlObj = new URL(finalUrl);
      // Encode each path segment separately to avoid double-encoding
      const pathSegments = urlObj.pathname.split('/').map(seg => encodeURIComponent(decodeURIComponent(seg)));
      urlObj.pathname = pathSegments.join('/');
      // Add width/quality parameters for smaller preview images
      urlObj.searchParams.set('w', '300');
      urlObj.searchParams.set('q', '80');
      return urlObj.toString();
    } catch (e) {
      // If URL parsing fails, fall back to simple space encoding
      return finalUrl.replace(/ /g, '%20');
    }
  };

  container.innerHTML = posts.map(post => {
    const imageSrc = resolveImageUrl(post.mockupPath || post.generatedMockupPath || post.artworkPath);
    const isSelected = state.fbSchedule.selectedPostIds.has(post.id);
    return `
    <div class="schedule-post-card${isSelected ? ' selected' : ''}" data-id="${post.id}">
      <div class="post-checkbox">
        <input type="checkbox" ${isSelected ? 'checked' : ''} onchange="handleSchedulePostCheckbox('${post.id}', this.checked)" />
      </div>
      <img class="post-thumbnail" src="${imageSrc}"
           alt="" onerror="this.src='data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 width=%2260%22 height=%2260%22><rect fill=%22%23333%22 width=%2260%22 height=%2260%22/></svg>'">
      <div class="post-info">
        <div class="post-name">${post.productName || 'Unknown Product'}</div>
        <div class="post-campaign">${post.campaignSlug || ''}</div>
        <div class="post-scheduled">${formatScheduledTime(post.scheduledFor)}</div>
      </div>
      <span class="post-status ${post.status}">${post.status}</span>
      <div class="post-actions">
        ${post.status === 'pending' ? `
          <button onclick="handlePostNow('${post.id}')">Post Now</button>
          <button onclick="handleDeleteScheduledPost('${post.id}')">Delete</button>
        ` : ''}
        ${post.status === 'failed' ? `
          <button onclick="handleRetryPost('${post.id}')">Retry</button>
        ` : ''}
      </div>
    </div>
  `;
  }).join('');
}

/**
 * Update the schedule pagination UI
 */
function updateSchedulePaginationUI(totalCount, totalPages) {
  const paginationEl = document.getElementById('fbSchedulePagination');
  if (!paginationEl) return;

  const { currentPage, pageSize } = state.fbSchedule;
  const start = totalCount > 0 ? currentPage * pageSize + 1 : 0;
  const end = Math.min((currentPage + 1) * pageSize, totalCount);

  paginationEl.innerHTML = `
    <span style="font-size:12px; color:var(--text-muted);">Showing ${start}-${end} of ${totalCount}</span>
    <div style="display:flex; gap:8px;">
      <button class="secondary" onclick="goToSchedulePage('prev')" ${currentPage <= 0 ? 'disabled' : ''} style="padding:4px 12px; font-size:12px;">← Prev</button>
      <button class="secondary" onclick="goToSchedulePage('next')" ${currentPage >= totalPages - 1 ? 'disabled' : ''} style="padding:4px 12px; font-size:12px;">Next →</button>
    </div>
  `;
}

/**
 * Navigate to a different page of scheduled posts
 */
function goToSchedulePage(direction) {
  if (direction === 'prev' && state.fbSchedule.currentPage > 0) {
    state.fbSchedule.currentPage--;
  } else if (direction === 'next') {
    state.fbSchedule.currentPage++;
  }
  renderScheduledPosts();
}
window.goToSchedulePage = goToSchedulePage;

/**
 * Handle individual post checkbox change
 */
function handleSchedulePostCheckbox(postId, checked) {
  if (checked) {
    state.fbSchedule.selectedPostIds.add(postId);
  } else {
    state.fbSchedule.selectedPostIds.delete(postId);
  }
  updateBulkSelectionUI();

  // Update the card's visual state
  const card = document.querySelector(`.schedule-post-card[data-id="${postId}"]`);
  if (card) {
    card.classList.toggle('selected', checked);
  }
}
window.handleSchedulePostCheckbox = handleSchedulePostCheckbox;

/**
 * Update the bulk selection UI (count, select all checkbox, delete button)
 */
function updateBulkSelectionUI() {
  const selectedCount = state.fbSchedule.selectedPostIds.size;
  const posts = getFilteredScheduledPosts();
  const totalCount = posts.length;

  // Update selected count text
  if (elements.fbScheduleSelectedCount) {
    elements.fbScheduleSelectedCount.textContent = `${selectedCount} selected`;
  }

  // Update select all checkbox state
  if (elements.fbScheduleSelectAll) {
    elements.fbScheduleSelectAll.checked = totalCount > 0 && selectedCount === totalCount;
    elements.fbScheduleSelectAll.indeterminate = selectedCount > 0 && selectedCount < totalCount;
  }

  // Enable/disable bulk delete button
  if (elements.fbScheduleBulkDeleteBtn) {
    elements.fbScheduleBulkDeleteBtn.disabled = selectedCount === 0;
  }
}

/**
 * Get currently filtered posts (for select all functionality)
 */
function getFilteredScheduledPosts() {
  let posts = state.fbSchedule.scheduledPosts || [];

  if (state.fbSchedule.filter !== 'all') {
    posts = posts.filter(p => p.status === state.fbSchedule.filter);
  }

  const campaignFilter = elements.fbScheduleFilterCampaign?.value;
  if (campaignFilter) {
    posts = posts.filter(p => p.campaignSlug === campaignFilter);
  }

  return posts;
}

/**
 * Handle select all checkbox
 */
function handleSelectAllScheduledPosts(checked) {
  const posts = getFilteredScheduledPosts();

  if (checked) {
    posts.forEach(p => state.fbSchedule.selectedPostIds.add(p.id));
  } else {
    posts.forEach(p => state.fbSchedule.selectedPostIds.delete(p.id));
  }

  renderScheduledPosts();
}

/**
 * Handle bulk delete of selected posts
 */
async function handleBulkDeleteScheduledPosts() {
  const selectedIds = [...state.fbSchedule.selectedPostIds];
  if (selectedIds.length === 0) {
    showToast('No posts selected', 'warning');
    return;
  }

  const confirmed = await nativeConfirm(
    `Are you sure you want to delete ${selectedIds.length} scheduled post${selectedIds.length > 1 ? 's' : ''}? This cannot be undone.`,
    'Delete Scheduled Posts'
  );

  if (!confirmed) return;

  // Disable button during deletion
  if (elements.fbScheduleBulkDeleteBtn) {
    elements.fbScheduleBulkDeleteBtn.disabled = true;
    elements.fbScheduleBulkDeleteBtn.textContent = 'Deleting...';
  }

  let successCount = 0;
  let failCount = 0;

  for (const postId of selectedIds) {
    try {
      const result = await printStation.deleteFbScheduledPost(postId);
      if (result?.success) {
        successCount++;
        state.fbSchedule.selectedPostIds.delete(postId);
      } else {
        failCount++;
        console.error(`[FB Schedule] Failed to delete post ${postId}:`, result?.error);
      }
    } catch (err) {
      failCount++;
      console.error(`[FB Schedule] Error deleting post ${postId}:`, err);
    }
  }

  // Restore button
  if (elements.fbScheduleBulkDeleteBtn) {
    elements.fbScheduleBulkDeleteBtn.textContent = 'Delete Selected';
  }

  // Show result
  if (failCount === 0) {
    showToast(`Deleted ${successCount} post${successCount > 1 ? 's' : ''}`, 'success');
  } else {
    showToast(`Deleted ${successCount}, failed ${failCount}`, 'warning');
  }

  // Reload the posts list
  loadScheduledPosts();
}

/**
 * Format scheduled time for display
 */
function formatScheduledTime(isoString) {
  if (!isoString) return 'Not scheduled';
  const date = new Date(isoString);
  return date.toLocaleString('en-US', {
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true
  });
}

/**
 * Update schedule stats display
 */
function updateScheduleStats() {
  const posts = state.fbSchedule.scheduledPosts || [];
  const pending = posts.filter(p => p.status === 'pending').length;
  const published = posts.filter(p => p.status === 'published').length;
  const failed = posts.filter(p => p.status === 'failed').length;

  if (elements.fbScheduleStatPending) elements.fbScheduleStatPending.textContent = pending;
  if (elements.fbScheduleStatPublished) elements.fbScheduleStatPublished.textContent = published;
  if (elements.fbScheduleStatFailed) elements.fbScheduleStatFailed.textContent = failed;
}

/**
 * Handle creating a new schedule
 */
async function handleCreateSchedule() {
  const campaign = state.fbSchedule.selectedCampaign;
  if (!campaign) {
    showToast('Please select a campaign first', 'warning');
    return;
  }

  const templateId = elements.fbScheduleTemplateSelect?.value || null;
  const postText = elements.fbSchedulePostText?.value || '';
  const postHashtags = elements.fbScheduleHashtags?.value || '';
  const collectionUrl = elements.fbScheduleCollectionUrl?.value || '';
  const startDate = elements.fbScheduleStartDate?.value || '';
  const startTime = elements.fbScheduleStartTime?.value || '10:00';
  const intervalHours = parseInt(elements.fbScheduleInterval?.value || '24', 10);
  const generateAiPerItem = elements.fbScheduleAiPerItem?.checked || false;
  const aiStyle = elements.fbScheduleAiStyle?.value || 'showcase';

  // Only require post text if NOT generating AI per item
  if (!postText.trim() && !generateAiPerItem) {
    showToast('Please enter post text or enable "Generate unique AI text for each item"', 'warning');
    return;
  }

  // Build start datetime
  const startDateTime = startDate
    ? new Date(`${startDate}T${startTime}:00`).toISOString()
    : new Date().toISOString();

  try {
    // Show progress for AI generation
    if (generateAiPerItem) {
      showToast(`Scheduling ${campaign.items?.length || 0} posts with AI text generation...`, 'info', 5000);
    }

    const result = await printStation.scheduleCampaignPosts({
      campaignSlug: campaign.slug,
      templateId: templateId || undefined,
      postText: generateAiPerItem ? '' : postText,  // Empty text triggers AI generation on server
      postHashtags,
      collectionUrl,
      startDate: startDateTime,
      intervalHours,
      generateAiPerItem,
      aiStyle
    });

    if (result?.success) {
      showToast(`Scheduled ${result.postsScheduled} posts!`, 'success');
      loadScheduledPosts();

      // Clear form
      if (elements.fbSchedulePostText) elements.fbSchedulePostText.value = '';
      if (elements.fbScheduleHashtags) elements.fbScheduleHashtags.value = '';
    } else {
      showToast(result?.error || 'Failed to schedule posts', 'error');
    }
  } catch (err) {
    console.error('[FB Schedule] Failed to create schedule:', err);
    showToast('Failed to create schedule', 'error');
  }
}

/**
 * Preview schedule before creating
 */
function handlePreviewSchedule() {
  const campaign = state.fbSchedule.selectedCampaign;
  if (!campaign) {
    showToast('Please select a campaign first', 'warning');
    return;
  }

  const items = campaign.items || [];
  const intervalHours = parseInt(elements.fbScheduleInterval?.value || '24', 10);
  const startDate = elements.fbScheduleStartDate?.value;
  const startTime = elements.fbScheduleStartTime?.value || '10:00';

  let currentDate = startDate
    ? new Date(`${startDate}T${startTime}:00`)
    : new Date();

  const previewHtml = items.slice(0, 5).map(item => {
    const time = formatScheduledTime(currentDate.toISOString());
    currentDate = new Date(currentDate.getTime() + intervalHours * 60 * 60 * 1000);
    return `<div style="margin-bottom: 8px;">${cleanAiGeneratedName(item.name) || 'Product'} - ${time}</div>`;
  }).join('');

  const remaining = items.length > 5 ? `<div style="color: var(--text-secondary);">...and ${items.length - 5} more</div>` : '';

  showToast(`Preview: ${items.length} posts will be scheduled`, 'info', 5000);
}

/**
 * Handle processing pending posts now
 */
async function handleProcessPendingPosts() {
  try {
    const result = await printStation.processPendingPosts();
    if (result?.success) {
      showToast(`Processed: ${result.successful} successful, ${result.failed} failed`,
                result.failed > 0 ? 'warning' : 'success');
      loadScheduledPosts();
    } else {
      showToast(result?.error || 'Failed to process posts', 'error');
    }
  } catch (err) {
    console.error('[FB Schedule] Failed to process posts:', err);
    showToast('Failed to process pending posts', 'error');
  }
}

/**
 * Handle posting a single scheduled post now
 */
async function handlePostNow(postId) {
  try {
    console.log('[FB Schedule] Posting now, postId:', postId);
    const result = await printStation.postScheduledNow(postId);
    console.log('[FB Schedule] Post now result:', result);
    if (result?.success) {
      showToast('Posted successfully!', 'success');
      loadScheduledPosts();
    } else {
      const errorMsg = result?.error || 'Failed to post - unknown error';
      console.error('[FB Schedule] Post failed:', errorMsg);
      showToast(errorMsg, 'error');
    }
  } catch (err) {
    console.error('[FB Schedule] Failed to post:', err);
    showToast('Failed to post: ' + (err.message || err), 'error');
  }
}
// Make available globally for inline onclick
window.handlePostNow = handlePostNow;

/**
 * Handle deleting a scheduled post
 */
async function handleDeleteScheduledPost(postId) {
  if (!await nativeConfirm('Delete this scheduled post?', 'Delete Post')) return;

  try {
    const result = await printStation.deleteFbScheduledPost(postId);
    if (result?.success) {
      showToast('Post deleted', 'success');
      loadScheduledPosts();
    } else {
      showToast(result?.error || 'Failed to delete', 'error');
    }
  } catch (err) {
    console.error('[FB Schedule] Failed to delete post:', err);
    showToast('Failed to delete post', 'error');
  }
}
window.handleDeleteScheduledPost = handleDeleteScheduledPost;

/**
 * Handle retrying a failed post
 */
async function handleRetryPost(postId) {
  try {
    const result = await printStation.retryScheduledPost(postId);
    if (result?.success) {
      showToast('Post queued for retry', 'success');
      loadScheduledPosts();
    } else {
      showToast(result?.error || 'Failed to retry', 'error');
    }
  } catch (err) {
    console.error('[FB Schedule] Failed to retry post:', err);
    showToast('Failed to retry post', 'error');
  }
}
window.handleRetryPost = handleRetryPost;

// ========== Facebook Insights Modal Functions ==========

// Pagination state for insights
const insightsPagination = {
  limit: 20,
  offset: 0,
  totalCount: 0
};

/**
 * Open the Facebook Insights modal and load data
 */
async function openFbInsightsModal() {
  console.log('[FB Insights] openFbInsightsModal called');
  const modal = document.getElementById('fbInsightsModal');
  console.log('[FB Insights] Modal element:', modal);
  if (modal) {
    // Force remove any hidden attributes or pointer-events that might be blocking
    modal.removeAttribute('hidden');
    modal.style.display = 'flex';
    modal.style.pointerEvents = 'auto';
    // Reset pagination when opening modal
    insightsPagination.offset = 0;
    await loadFbInsights();
  } else {
    console.error('[FB Insights] Modal not found!');
  }
}
window.openFbInsightsModal = openFbInsightsModal;

/**
 * Close the Facebook Insights modal
 */
function closeFbInsightsModal() {
  const modal = document.getElementById('fbInsightsModal');
  if (modal) {
    modal.style.display = 'none';
  }
}
window.closeFbInsightsModal = closeFbInsightsModal;

/**
 * Load a specific page of insights (prev/next)
 */
function loadInsightsPage(direction) {
  if (direction === 'prev' && insightsPagination.offset > 0) {
    insightsPagination.offset = Math.max(0, insightsPagination.offset - insightsPagination.limit);
  } else if (direction === 'next' && insightsPagination.offset + insightsPagination.limit < insightsPagination.totalCount) {
    insightsPagination.offset += insightsPagination.limit;
  }
  loadFbInsights();
}
window.loadInsightsPage = loadInsightsPage;

/**
 * Update pagination UI controls
 */
function updateInsightsPaginationUI() {
  const infoEl = document.getElementById('insightsPaginationInfo');
  const prevBtn = document.getElementById('insightsPrevBtn');
  const nextBtn = document.getElementById('insightsNextBtn');

  const start = insightsPagination.totalCount > 0 ? insightsPagination.offset + 1 : 0;
  const end = Math.min(insightsPagination.offset + insightsPagination.limit, insightsPagination.totalCount);

  if (infoEl) {
    infoEl.textContent = `Showing ${start}-${end} of ${insightsPagination.totalCount}`;
  }

  if (prevBtn) {
    prevBtn.disabled = insightsPagination.offset <= 0;
  }

  if (nextBtn) {
    nextBtn.disabled = insightsPagination.offset + insightsPagination.limit >= insightsPagination.totalCount;
  }
}

/**
 * Load Facebook insights data
 */
async function loadFbInsights() {
  const statusEl = document.getElementById('insightsStatus');
  const daysFilter = document.getElementById('insightsDaysFilter');
  const campaignFilter = document.getElementById('insightsCampaignFilter');

  const days = daysFilter?.value || 30;
  const campaignSlug = campaignFilter?.value || '';

  if (statusEl) statusEl.textContent = 'Loading insights...';

  try {
    // Populate campaign filter dropdown if needed
    await populateInsightsCampaignFilter();

    // Fetch summary data
    const summaryResult = await printStation.getFbInsightsSummary({ days: parseInt(days), campaignSlug });

    if (summaryResult?.success && summaryResult?.summary) {
      const summary = summaryResult.summary;

      // Update summary cards
      document.getElementById('insightTotalPosts').textContent = summary.totalPosts || 0;
      document.getElementById('insightTotalLikes').textContent = formatInsightNumber(summary.totalLikes);
      document.getElementById('insightTotalComments').textContent = formatInsightNumber(summary.totalComments);
      document.getElementById('insightTotalShares').textContent = formatInsightNumber(summary.totalShares);
      document.getElementById('insightTotalReach').textContent = formatInsightNumber(summary.totalReach);
      document.getElementById('insightEngagementRate').textContent = summary.avgEngagementRate + '%';

      // Render top posts
      renderTopPosts(summary.topPosts || []);

      if (statusEl) statusEl.textContent = `Updated: ${new Date().toLocaleTimeString()}`;
    } else {
      if (statusEl) statusEl.textContent = summaryResult?.error || 'Failed to load';
    }

    // Fetch posts insights for the table with pagination
    const allResult = await printStation.getFbScheduledPostsInsights({
      limit: insightsPagination.limit,
      offset: insightsPagination.offset
    });
    if (allResult?.success && allResult?.insights) {
      // Update pagination state from server response
      insightsPagination.totalCount = allResult.totalCount || 0;
      renderInsightsTable(allResult.insights);
      updateInsightsPaginationUI();
    }

  } catch (err) {
    console.error('[FB Insights] Error loading:', err);
    if (statusEl) statusEl.textContent = 'Error: ' + (err.message || 'Unknown');
  }
}
window.loadFbInsights = loadFbInsights;

/**
 * Format number with K/M suffix for insights display
 */
function formatInsightNumber(num) {
  if (!num || num === 0) return '0';
  if (num >= 1000000) return (num / 1000000).toFixed(1) + 'M';
  if (num >= 1000) return (num / 1000).toFixed(1) + 'K';
  return num.toString();
}

/**
 * Populate the insights campaign filter dropdown
 */
async function populateInsightsCampaignFilter() {
  const select = document.getElementById('insightsCampaignFilter');
  if (!select) return;

  // Get unique campaigns from scheduled posts
  try {
    const posts = await printStation.listFbScheduledPosts();
    if (posts?.length) {
      const campaigns = [...new Set(posts.map(p => p.campaignSlug).filter(Boolean))];

      // Clear existing options except first
      while (select.options.length > 1) {
        select.remove(1);
      }

      campaigns.forEach(slug => {
        const option = document.createElement('option');
        option.value = slug;
        option.textContent = slug;
        select.appendChild(option);
      });
    }
  } catch (err) {
    console.error('[FB Insights] Error loading campaigns:', err);
  }
}

/**
 * Render top performing posts
 */
function renderTopPosts(posts) {
  const container = document.getElementById('insightsTopPosts');
  if (!container) return;

  if (!posts || posts.length === 0) {
    container.innerHTML = '<p class="placeholder">No published posts with insights yet.</p>';
    return;
  }

  const rankClasses = ['gold', 'silver', 'bronze', '', ''];

  container.innerHTML = posts.map((post, index) => `
    <div class="insights-post-item">
      <span class="post-rank ${rankClasses[index] || ''}">#${index + 1}</span>
      <div class="post-info">
        <div class="post-name">${escapeHtml(post.productName || 'Unknown')}</div>
        <div class="post-campaign">${escapeHtml(post.campaignSlug || '')}</div>
      </div>
      <div class="post-stats">
        <div class="stat">
          <span class="stat-value">${post.likes || 0}</span>
          <span class="stat-label">Likes</span>
        </div>
        <div class="stat">
          <span class="stat-value">${post.comments || 0}</span>
          <span class="stat-label">Comments</span>
        </div>
        <div class="stat">
          <span class="stat-value">${post.shares || 0}</span>
          <span class="stat-label">Shares</span>
        </div>
        <div class="stat">
          <span class="stat-value">${formatInsightNumber(post.reach)}</span>
          <span class="stat-label">Reach</span>
        </div>
        <div class="stat">
          <span class="stat-value">${post.engagementRate || 0}%</span>
          <span class="stat-label">Eng.</span>
        </div>
      </div>
      ${post.permalinkUrl ? `<a href="${post.permalinkUrl}" target="_blank" class="post-link">View</a>` : ''}
    </div>
  `).join('');
}

/**
 * Render all posts insights table
 */
function renderInsightsTable(insights) {
  const tbody = document.getElementById('insightsTableBody');
  if (!tbody) return;

  if (!insights || insights.length === 0) {
    tbody.innerHTML = '<tr><td colspan="8" class="placeholder" style="text-align:center; padding:20px;">No published posts with insights.</td></tr>';
    return;
  }

  // Sort by total engagement descending
  const sorted = [...insights].sort((a, b) => {
    const aEng = (a.likes || 0) + (a.comments || 0) + (a.shares || 0);
    const bEng = (b.likes || 0) + (b.comments || 0) + (b.shares || 0);
    return bEng - aEng;
  });

  tbody.innerHTML = sorted.map(post => {
    if (post.error) {
      return `
        <tr style="opacity:0.6;">
          <td>${escapeHtml(post.productName || 'Unknown')}</td>
          <td>${escapeHtml(post.campaignSlug || '')}</td>
          <td colspan="5" style="color:var(--danger); font-size:11px;">${escapeHtml(post.error)}</td>
          <td>-</td>
        </tr>
      `;
    }

    return `
      <tr>
        <td>${escapeHtml(post.productName || 'Unknown')}</td>
        <td>${escapeHtml(post.campaignSlug || '')}</td>
        <td style="text-align:right;">${post.likes || 0}</td>
        <td style="text-align:right;">${post.comments || 0}</td>
        <td style="text-align:right;">${post.shares || 0}</td>
        <td style="text-align:right;">${formatInsightNumber(post.reach)}</td>
        <td style="text-align:right;">${post.engagementRate || 0}%</td>
        <td style="text-align:center;">
          ${post.permalinkUrl ? `<a href="${post.permalinkUrl}" target="_blank" class="external-link">View</a>` : '-'}
        </td>
      </tr>
    `;
  }).join('');
}

