function openMockupTemplateModal() {
  if (elements.mockupTemplateModal) {
    elements.mockupTemplateModal.style.display = 'flex';
  }
}

function closeMockupTemplateModal() {
  if (elements.mockupTemplateModal) {
    elements.mockupTemplateModal.style.display = 'none';
  }
}

async function handleChooseTemplateBaseImage() {
  try {
    const filePaths = await printStation.selectFiles({
      title: 'Select Base Mockup Image',
      filters: [
        { name: 'Images', extensions: ['jpg', 'jpeg', 'png', 'webp'] }
      ],
      properties: ['openFile']
    });

    if (filePaths && filePaths.length > 0) {
      const imagePath = filePaths[0];
      if (elements.mockupTemplateImagePath) {
        elements.mockupTemplateImagePath.value = imagePath;
      }
      if (elements.mockupTemplatePreview) {
        elements.mockupTemplatePreview.innerHTML = `<img src="file://${imagePath}" alt="Preview" style="max-width:100%;max-height:300px;" />`;
      }
    }
  } catch (err) {
    console.error('[Mockup Template] Failed to select image:', err);
  }
}

async function handleSaveMockupTemplate() {
  const name = elements.mockupTemplateName?.value?.trim();
  const baseImage = elements.mockupTemplateImagePath?.value?.trim();

  if (!name || !baseImage) {
    showToast('Please provide template name and base image', 'warning');
    return;
  }

  const template = {
    name,
    mockupImagePath: baseImage,
    artworkPosition: {
      x: parseInt(elements.mockupTemplatePosX?.value || '100', 10),
      y: parseInt(elements.mockupTemplatePosY?.value || '100', 10),
      width: parseInt(elements.mockupTemplatePosW?.value || '400', 10),
      height: parseInt(elements.mockupTemplatePosH?.value || '400', 10),
      rotation: parseInt(elements.mockupTemplatePosR?.value || '0', 10)
    },
    blendMode: elements.mockupTemplateBlendMode?.value || 'normal'
  };

  try {
    const result = await printStation.createMockupTemplate(template);
    if (result?.success) {
      showToast('Template saved!', 'success');
      closeMockupTemplateModal();
      loadFbScheduleTemplates();
    } else {
      showToast(result?.error || 'Failed to save template', 'error');
    }
  } catch (err) {
    console.error('[Mockup Template] Failed to save:', err);
    showToast('Failed to save template', 'error');
  }
}

