function setCustomArtStatus(msg, isError = false) {
  if (customArtElements.status) {
    customArtElements.status.textContent = msg;
    customArtElements.status.classList.toggle('error', isError);
  }
}

/**
 * Resolve artwork image URL - handles server-relative paths and local paths
 * Server-relative paths (starting with /) need the server base URL prepended
 * Local Windows paths (C:\...) need to be converted to file:// URLs
 * @param {string} path - The image path
 * @param {Object} options - Optional sizing parameters
 * @param {number} options.width - Desired width for resizing
 * @param {number} options.quality - JPEG quality (1-100)
 */
function resolveArtworkUrl(path, options = {}) {
  if (!path) return '';
  // If path starts with http, it's already a full URL - apply image options for resizing
  if (path.startsWith('http://') || path.startsWith('https://')) {
    return applyImageOptions(path, options);
  }
  // If path starts with data:, it's a data URL
  if (path.startsWith('data:')) {
    return path;
  }
  // If path starts with file://, it's already a file URL
  if (path.startsWith('file://')) {
    return path;
  }
  // If path is a Windows absolute path (e.g., C:\...), convert to file:// URL
  if (/^[A-Za-z]:[\\/]/.test(path)) {
    return 'file:///' + path.replace(/\\/g, '/');
  }
  // If path is a Unix absolute path to user/system directories, convert to file:// URL
  if (path.startsWith('/home') || path.startsWith('/tmp') || path.startsWith('/var') || path.startsWith('/Users')) {
    return 'file://' + path;
  }
  // For server-relative paths, prepend server base URL
  const serverBase = state.config?.serverBaseUrl?.trim() || '';
  let fullUrl;
  if (path.startsWith('/')) {
    fullUrl = serverBase + path;
  } else {
    // Relative path - add leading slash and server base
    fullUrl = serverBase + '/' + path;
  }
  return applyImageOptions(fullUrl, options);
}

function switchCustomArtSubtab(subtab) {
  console.log('[Custom Art] switchCustomArtSubtab called with:', subtab);
  // Always refresh elements to ensure they're current
  initCustomArtElements();
  customArtState.currentSubtab = subtab;

  // Get elements fresh each time (in case they weren't ready at load time)
  const roomsTab = document.getElementById('customArtRoomsTab');
  const artworkTab = document.getElementById('customArtArtworkTab');
  const materialsTab = document.getElementById('customArtMaterialsTab');
  const productsTab = document.getElementById('customArtProductsTab');
  const mockupTab = document.getElementById('customArtMockupTab');
  const savedMockupsTab = document.getElementById('customArtSavedMockupsTab');

  const roomsPanel = document.getElementById('customArtRoomsPanel');
  const artworkPanel = document.getElementById('customArtArtworkPanel');
  const materialsPanel = document.getElementById('customArtMaterialsPanel');
  const productsPanel = document.getElementById('customArtProductsPanel');
  const mockupPanel = document.getElementById('customArtMockupPanel');
  const savedMockupsPanel = document.getElementById('customArtSavedMockupsPanel');

  console.log('[Custom Art] Panels found:', {
    rooms: !!roomsPanel,
    artwork: !!artworkPanel,
    materials: !!materialsPanel,
    products: !!productsPanel,
    mockup: !!mockupPanel,
    savedMockups: !!savedMockupsPanel
  });

  // Update tab buttons
  [roomsTab, artworkTab, materialsTab, productsTab, mockupTab, savedMockupsTab].forEach(btn => {
    if (btn) btn.classList.toggle('active', btn.dataset.subtab === subtab);
  });

  // Update panels - show only the active one using setAttribute to force style change
  const panels = [
    { el: roomsPanel, name: 'rooms' },
    { el: artworkPanel, name: 'artwork' },
    { el: materialsPanel, name: 'materials' },
    { el: productsPanel, name: 'products' },
    { el: mockupPanel, name: 'mockup' },
    { el: savedMockupsPanel, name: 'savedMockups' }
  ];

  panels.forEach(({ el, name }) => {
    if (el) {
      const shouldShow = name === subtab;
      el.setAttribute('style', shouldShow ? 'display: block !important;' : 'display: none !important;');
    }
  });

  console.log('[Custom Art] Panel display after set:', {
    rooms: roomsPanel?.getAttribute('style'),
    artwork: artworkPanel?.getAttribute('style')
  });
  console.log('[Custom Art] Loading data for subtab:', subtab);
  // Load data for the active subtab
  if (subtab === 'rooms') loadCustomArtRooms();
  else if (subtab === 'artwork') loadCustomArtArtwork();
  else if (subtab === 'materials') loadCustomArtMaterials();
  else if (subtab === 'products') loadCustomArtProducts();
  else if (subtab === 'mockup') initCustomArtMockup();
  else if (subtab === 'savedMockups') loadSavedMockups();
}

// --- ROOMS ---
async function loadCustomArtRooms() {
  setCustomArtStatus('Loading rooms...');
  try {
    const result = await printStation.customArt.listRooms({ activeOnly: false, limit: 500 });
    customArtState.rooms = result?.rooms || [];
    renderCustomArtRooms();
    setCustomArtStatus(`${customArtState.rooms.length} room(s) loaded`);
  } catch (e) {
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

function renderCustomArtRooms() {
  if (!customArtElements.roomsGrid) return;

  // Apply search and type filter
  const searchTerm = (customArtElements.roomSearch?.value || '').toLowerCase().trim();
  const typeFilter = customArtElements.roomTypeFilter?.value || '';

  let filtered = customArtState.rooms;
  if (searchTerm) {
    filtered = filtered.filter(r =>
      (r.title || '').toLowerCase().includes(searchTerm) ||
      (r.description || '').toLowerCase().includes(searchTerm) ||
      (r.tags || '').toLowerCase().includes(searchTerm)
    );
  }
  if (typeFilter) {
    filtered = filtered.filter(r => r.roomType === typeFilter);
  }

  if (!filtered.length) {
    customArtElements.roomsGrid.innerHTML = '<div class="placeholder">No rooms found. Click "Add Room" or "Bulk Upload" to add room photos.</div>';
    updateRoomSelectionUI();
    return;
  }

  const roomTypeLabels = {
    'living-room': 'Living Room',
    'bedroom': 'Bedroom',
    'office': 'Office',
    'dining-room': 'Dining Room',
    'hallway': 'Hallway',
    'bathroom': 'Bathroom',
    'kitchen': 'Kitchen',
    'garage': 'Garage',
    'art-studio': 'Art Studio',
    'front-porch': 'Front Porch',
    'staircase': 'Staircase',
    'workbench': 'Workbench',
    'other': 'Other'
  };

  // Populate room type filter from actual data
  if (customArtElements.roomTypeFilter) {
    const types = [...new Set(customArtState.rooms.map(r => r.roomType).filter(Boolean))].sort();
    const current = customArtElements.roomTypeFilter.value;
    customArtElements.roomTypeFilter.innerHTML = '<option value="">All Types</option>' +
      types.map(t => `<option value="${t}">${roomTypeLabels[t] || t}</option>`).join('');
    customArtElements.roomTypeFilter.value = current;
  }

  // Collect URLs for prefetching
  const roomPreviewUrls = [];

  customArtElements.roomsGrid.innerHTML = filtered.map(room => {
    const isSelected = customArtState.selectedRoomIds.has(String(room.id));
    const typeLabel = roomTypeLabels[room.roomType] || room.roomType || 'Unspecified';
    const isActive = room.active !== false;
    const statusClass = isActive ? 'success' : 'muted';
    const statusLabel = isActive ? 'Active' : 'Inactive';
    const rawImgSrc = room.thumbnailPath || room.imagePath || '';
    // Convert relative paths to full server URLs
    const serverUrl = rawImgSrc.startsWith('http') ? rawImgSrc : resolveAssetUrl(rawImgSrc, { width: 300, quality: 80 });
    // Use cached URL if available
    const imgSrc = getCachedPreviewUrl(serverUrl);
    // Track for background prefetch
    if (serverUrl && !previewCacheMap.has(serverUrl)) {
      roomPreviewUrls.push(serverUrl);
    }
    const fallbackImg = 'data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 200 150%22><rect fill=%22%231a1a2e%22 width=%22200%22 height=%22150%22/><text x=%22100%22 y=%2280%22 fill=%22%23666%22 text-anchor=%22middle%22 font-size=%2214%22>No Image</text></svg>';

    return `
    <div class="custom-art-card ${isSelected ? 'selected' : ''}" data-room-id="${room.id}" style="cursor:pointer;">
      ${isSelected ? '<div class="room-selected-indicator" style="position:absolute;top:8px;right:8px;background:#4a9;color:#fff;border-radius:50%;width:24px;height:24px;display:flex;align-items:center;justify-content:center;font-size:14px;">✓</div>' : ''}
      <img src="${escapeHtml(imgSrc)}" alt="${escapeHtml(room.title)}" class="custom-art-thumb" data-cache-url="${escapeHtml(serverUrl)}" onerror="this.src='${fallbackImg}'" />
      <div class="custom-art-info">
        <div class="title">${room.title}</div>
        <div class="meta">${typeLabel}</div>
        <div style="display:flex;gap:6px;align-items:center;margin-top:4px;">
          <span class="badge ${statusClass}" style="font-size:10px;">${statusLabel}</span>
          <button class="secondary room-edit-btn" data-room-id="${room.id}" style="padding:3px 8px;font-size:10px;">Edit</button>
        </div>
      </div>
    </div>
    `;
  }).join('');

  // Background prefetch for uncached room previews
  if (roomPreviewUrls.length > 0) {
    prefetchCatalogPreviews(roomPreviewUrls);
  }

  // Note: Click handlers are set up via event delegation in initCustomArtEventListeners()
  updateRoomSelectionUI();
}

// Global function for editing rooms from table
window.editCustomArtRoom = function(id) {
  const room = customArtState.rooms.find(r => r.id === id);
  if (room) showRoomForm(room);
};

function showRoomForm(room = null) {
  customArtState.editingRoom = room;
  if (customArtElements.roomFormCard) customArtElements.roomFormCard.style.display = '';
  if (customArtElements.roomFormTitle) customArtElements.roomFormTitle.textContent = room ? 'Edit Room' : 'Add Room';
  if (customArtElements.roomDeleteBtn) customArtElements.roomDeleteBtn.style.display = room ? '' : 'none';

  // Populate form
  if (customArtElements.roomTitle) customArtElements.roomTitle.value = room?.title || '';
  if (customArtElements.roomFilename) {
    // Extract filename from path without extension
    const filename = room?.imagePath ? room.imagePath.split(/[/\\]/).pop().replace(/\.[^.]+$/, '') : '';
    customArtElements.roomFilename.value = filename;
  }
  if (customArtElements.roomType) customArtElements.roomType.value = room?.roomType || '';
  if (customArtElements.roomDescription) customArtElements.roomDescription.value = room?.description || '';
  if (customArtElements.roomTags) customArtElements.roomTags.value = room?.tags || '';
  if (customArtElements.roomStatus) customArtElements.roomStatus.value = room?.active === false ? 'inactive' : 'active';
  if (customArtElements.roomId) customArtElements.roomId.value = room?.id || '';
  if (customArtElements.roomImagePath) customArtElements.roomImagePath.value = room?.imagePath || '';
  if (customArtElements.roomImageName) customArtElements.roomImageName.textContent = room?.imagePath ? 'Image selected' : 'No image selected';
  if (customArtElements.roomImagePreview) {
    if (room?.imagePath) {
      // Convert relative paths to full server URLs
      const previewSrc = room.imagePath.startsWith('http') ? room.imagePath : resolveAssetUrl(room.imagePath);
      customArtElements.roomImagePreview.src = previewSrc;
      customArtElements.roomImagePreview.style.display = '';
    } else {
      customArtElements.roomImagePreview.style.display = 'none';
    }
  }
}

function hideRoomForm() {
  customArtState.editingRoom = null;
  if (customArtElements.roomFormCard) customArtElements.roomFormCard.style.display = 'none';
}

async function saveRoom() {
  const title = customArtElements.roomTitle?.value?.trim();
  const imagePath = customArtElements.roomImagePath?.value;
  const newFilename = customArtElements.roomFilename?.value?.trim();

  if (!title) {
    setCustomArtStatus('Title is required', true);
    return;
  }
  if (!imagePath) {
    setCustomArtStatus('Please select an image', true);
    return;
  }

  const payload = {
    title,
    roomType: customArtElements.roomType?.value || null,
    description: customArtElements.roomDescription?.value || null,
    tags: customArtElements.roomTags?.value || null,
    active: customArtElements.roomStatus?.value !== 'inactive',
    imagePath,
    newFilename: newFilename || null
  };

  setCustomArtStatus('Saving room...');
  try {
    if (customArtState.editingRoom) {
      await printStation.customArt.updateRoom(customArtState.editingRoom.id, payload);
    } else {
      await printStation.customArt.createRoom(payload);
    }
    hideRoomForm();
    await loadCustomArtRooms();
    setCustomArtStatus('Room saved successfully');
  } catch (e) {
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

async function deleteRoom() {
  if (!customArtState.editingRoom) return;
  if (!await nativeConfirm(`Delete room "${customArtState.editingRoom.title}"?`, 'Delete Room')) return;

  setCustomArtStatus('Deleting room...');
  try {
    await printStation.customArt.deleteRoom(customArtState.editingRoom.id);
    hideRoomForm();
    await loadCustomArtRooms();
    setCustomArtStatus('Room deleted');
  } catch (e) {
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

async function selectRoomImage() {
  const result = await printStation.customArt.selectFile({ title: 'Select Room Image' });
  if (result.canceled) return;

  setCustomArtStatus('Uploading image...');
  try {
    const uploadResult = await printStation.customArt.uploadFile(result.filePath, 'room');
    if (!uploadResult.success) throw new Error(uploadResult.error);

    if (customArtElements.roomImagePath) customArtElements.roomImagePath.value = uploadResult.filePath;
    if (customArtElements.roomImageName) customArtElements.roomImageName.textContent = uploadResult.filename;
    if (customArtElements.roomImagePreview) {
      // Convert relative paths to full server URLs
      const previewSrc = uploadResult.filePath.startsWith('http') ? uploadResult.filePath : resolveAssetUrl(uploadResult.filePath);
      customArtElements.roomImagePreview.src = previewSrc;
      customArtElements.roomImagePreview.style.display = '';
    }
    setCustomArtStatus('Image uploaded');
  } catch (e) {
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

async function bulkUploadRooms() {
  // Select multiple image files or ZIP files
  const result = await printStation.customArt.selectFiles({
    title: 'Select Room Images or ZIP File for Bulk Upload',
    filters: [
      { name: 'Images & Archives', extensions: ['jpg', 'jpeg', 'png', 'webp', 'zip'] }
    ],
    properties: ['openFile', 'multiSelections']
  });

  if (!result || result.canceled || !result.filePaths?.length) return;

  // Collect all image paths (extracting from ZIPs if necessary)
  let allImagePaths = [];
  let zipCount = 0;
  const tempDirs = [];

  setCustomArtStatus('Processing selected files...');

  for (const filePath of result.filePaths) {
    const ext = filePath.toLowerCase().split('.').pop();

    if (ext === 'zip') {
      // Extract ZIP file
      setCustomArtStatus(`Extracting ZIP file...`);
      const extractResult = await printStation.customArt.extractZip(filePath);
      if (extractResult.success && extractResult.filePaths?.length) {
        allImagePaths.push(...extractResult.filePaths);
        if (extractResult.tempDir) tempDirs.push(extractResult.tempDir);
        zipCount++;
        console.log(`[Custom Art] Extracted ${extractResult.filePaths.length} room images from ZIP`);
      } else {
        console.error('[Custom Art] ZIP extraction failed:', extractResult.error);
        setCustomArtStatus(`Error extracting ZIP: ${extractResult.error}`, true);
      }
    } else {
      // Regular image file
      allImagePaths.push(filePath);
    }
  }

  if (!allImagePaths.length) {
    setCustomArtStatus('No images found to upload', true);
    return;
  }

  const totalCount = allImagePaths.length;
  setCustomArtStatus(`Uploading ${totalCount} room image${totalCount > 1 ? 's' : ''}${zipCount ? ` (from ${zipCount} ZIP${zipCount > 1 ? 's' : ''})` : ''}...`);

  let successCount = 0;
  let errorCount = 0;

  for (let i = 0; i < allImagePaths.length; i++) {
    const filePath = allImagePaths[i];
    const fileName = filePath.split(/[/\\]/).pop();
    // Generate title from filename (remove extension, replace dashes/underscores with spaces)
    const title = fileName
      .replace(/\.[^.]+$/, '') // Remove extension
      .replace(/[-_]/g, ' ')   // Replace dashes/underscores with spaces
      .replace(/\s+/g, ' ')    // Collapse multiple spaces
      .trim();

    setCustomArtStatus(`Uploading ${i + 1}/${totalCount}: ${fileName}...`);

    try {
      // Upload the image file
      const uploadResult = await printStation.customArt.uploadFile(filePath, 'room');
      if (!uploadResult.success) throw new Error(uploadResult.error);

      // Create the room record
      await printStation.customArt.createRoom({
        title: title || `Room ${Date.now()}`,
        roomType: null,
        description: null,
        active: true,
        imagePath: uploadResult.filePath
      });

      successCount++;
    } catch (e) {
      console.error(`[Custom Art] Failed to upload room ${fileName}:`, e);
      errorCount++;
    }
  }

  // Clean up temp directories from ZIP extraction
  for (const dir of tempDirs) {
    try { await printStation.cleanupTempDir(dir); } catch (_) {}
  }

  // Reload rooms list
  await loadCustomArtRooms();

  if (errorCount === 0) {
    setCustomArtStatus(`Successfully uploaded ${successCount} room(s)${zipCount ? ` from ${zipCount} ZIP file(s)` : ''}`);
  } else {
    setCustomArtStatus(`Uploaded ${successCount} room(s), ${errorCount} failed`, true);
  }
}

// --- ARTWORK ---
async function loadCustomArtArtwork() {
  console.log('[Custom Art] loadCustomArtArtwork STARTED');
  setCustomArtStatus('Loading artwork...');
  try {
    console.log('[Custom Art] Fetching artwork from API...');
    const [artworkResult, categoriesResult] = await Promise.all([
      printStation.customArt.listArtwork({ activeOnly: false, limit: 10000 }),
      printStation.customArt.getArtworkCategories()
    ]);
    console.log('[Custom Art] API returned:', artworkResult, categoriesResult);
    customArtState.artwork = artworkResult?.artwork || [];
    customArtState.categories = categoriesResult?.categories || [];
    console.log('[Custom Art] State updated, calling renderCustomArtArtwork...');
    renderCustomArtArtwork();
    renderArtworkCategoryFilter();
    setCustomArtStatus(`${customArtState.artwork.length} artwork(s) loaded`);
    console.log('[Custom Art] loadCustomArtArtwork COMPLETED');
  } catch (e) {
    console.error('[Custom Art] loadCustomArtArtwork ERROR:', e);
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

function renderCustomArtArtwork() {
  console.log('[Custom Art] renderCustomArtArtwork called, artworkGrid:', customArtElements.artworkGrid);
  if (!customArtElements.artworkGrid) {
    console.log('[Custom Art] artworkGrid not found, trying to get it fresh');
    customArtElements.artworkGrid = document.getElementById('customArtArtworkGrid');
    if (!customArtElements.artworkGrid) {
      console.error('[Custom Art] Still no artworkGrid!');
      return;
    }
  }
  const search = customArtElements.artworkSearch?.value?.toLowerCase() || '';
  const category = customArtElements.artworkCategoryFilter?.value || '';

  let filtered = customArtState.artwork;
  if (search) {
    filtered = filtered.filter(a =>
      a.title?.toLowerCase().includes(search) ||
      a.tags?.toLowerCase().includes(search) ||
      a.description?.toLowerCase().includes(search)
    );
  }
  if (category) {
    filtered = filtered.filter(a => a.category === category);
  }

  if (!filtered.length) {
    customArtElements.artworkGrid.innerHTML = '<div class="placeholder">No artwork found.</div>';
    return;
  }

  // Collect URLs for prefetching
  const artworkPreviewUrls = [];

  customArtElements.artworkGrid.innerHTML = filtered.map(art => {
    const isSelected = customArtState.selectedArtworkIds.has(String(art.id));
    const serverUrl = resolveArtworkUrl(art.thumbnailPath || art.optimizedPath || art.filePath, { width: 300, quality: 80 });
    // Use cached URL if available
    const imageSrc = getCachedPreviewUrl(serverUrl);
    // Track for background prefetch (only for http URLs, not file:// or data:)
    if (serverUrl && serverUrl.startsWith('http') && !previewCacheMap.has(serverUrl)) {
      artworkPreviewUrls.push(serverUrl);
    }
    const cleanedTitle = cleanAiGeneratedName(art.title) || art.title || 'Untitled';
    return `
    <div class="custom-art-card ${isSelected ? 'selected' : ''}" data-artwork-id="${art.id}" style="cursor:pointer;">
      ${isSelected ? '<div class="artwork-selected-indicator" style="position:absolute;top:8px;right:8px;background:#4a9;color:#fff;border-radius:50%;width:24px;height:24px;display:flex;align-items:center;justify-content:center;font-size:14px;">✓</div>' : ''}
      <img class="custom-art-card-image" src="${imageSrc}" alt="${cleanedTitle}" data-cache-url="${escapeHtml(serverUrl)}" onerror="this.src='data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 75%22><rect fill=%22%231a1a2e%22 width=%22100%22 height=%2275%22/><text x=%2250%22 y=%2240%22 fill=%22%23666%22 text-anchor=%22middle%22 font-size=%228%22>No Image</text></svg>'"/>
      <div class="custom-art-card-body">
        <div class="custom-art-card-title">${cleanedTitle}</div>
        <div class="custom-art-card-meta">${art.category || 'Uncategorized'}${art.dimensions?.width ? ` • ${art.dimensions.width}×${art.dimensions.height}${art.dimensions.unit === 'inches' ? '"' : 'cm'}` : ''}</div>
        ${art.description ? `<div class="custom-art-card-desc" style="font-size:11px;color:#aaa;margin-top:4px;line-height:1.3;max-height:40px;overflow:hidden;text-overflow:ellipsis;">${art.description}</div>` : (art.tags ? `<div class="custom-art-card-desc" style="font-size:11px;color:#7a8;margin-top:4px;line-height:1.3;max-height:28px;overflow:hidden;text-overflow:ellipsis;">${art.tags}</div>` : '')}
        ${art.seoFilename ? `<div class="custom-art-card-filename" style="font-size:10px;color:#6a9;margin-top:2px;font-family:monospace;">${art.seoFilename}</div>` : ''}
        <div style="display:flex;gap:6px;align-items:center;margin-top:6px;flex-wrap:wrap;">
          <span class="custom-art-card-badge ${art.status}">${art.status}</span>
          <button class="secondary artwork-edit-btn" data-artwork-id="${art.id}" style="padding:4px 8px;font-size:11px;">Edit</button>
          <button class="secondary artwork-create-product-btn" data-artwork-id="${art.id}" style="padding:4px 8px;font-size:11px;">+ Product</button>
          <button class="secondary artwork-print-btn" data-artwork-id="${art.id}" data-artwork-path="${escapeHtml(art.filePath || art.optimizedPath || '')}" style="padding:4px 8px;font-size:11px;">🖨️ Print</button>
          <button class="secondary artwork-download-btn" data-artwork-id="${art.id}" data-artwork-path="${escapeHtml(art.filePath || art.optimizedPath || '')}" data-artwork-title="${escapeHtml(cleanedTitle)}" style="padding:4px 8px;font-size:11px;">⬇️ Download</button>
        </div>
      </div>
    </div>
  `}).join('');

  // Background prefetch for uncached artwork previews
  if (artworkPreviewUrls.length > 0) {
    prefetchCatalogPreviews(artworkPreviewUrls);
  }

  // Note: Checkbox and button handlers are set up via event delegation in initCustomArtEventListeners()
  // to avoid attaching duplicate handlers on every render

  // Update bulk actions bar visibility
  updateArtworkSelectionUI();
}

function renderArtworkCategoryFilter() {
  if (!customArtElements.artworkCategoryFilter) return;
  const current = customArtElements.artworkCategoryFilter.value;
  customArtElements.artworkCategoryFilter.innerHTML = '<option value="">All Categories</option>' +
    customArtState.categories.map(c => `<option value="${c}">${c}</option>`).join('');
  customArtElements.artworkCategoryFilter.value = current;

  // Also update datalist
  if (customArtElements.categoryList) {
    customArtElements.categoryList.innerHTML = customArtState.categories.map(c => `<option value="${c}">`).join('');
  }

  // Update bulk category dropdown
  const bulkCategorySelect = document.getElementById('customArtBulkCategorySelect');
  if (bulkCategorySelect) {
    bulkCategorySelect.innerHTML = '<option value="">Set Category...</option>' +
      customArtState.categories.map(c => `<option value="${c}">${c}</option>`).join('') +
      '<option value="__add_new__">+ Add New Category...</option>';
  }
}

// --- ARTWORK SELECTION & BULK ACTIONS ---
function updateArtworkSelectionUI() {
  const count = customArtState.selectedArtworkIds.size;
  const bulkBar = document.getElementById('customArtBulkActionsBar');
  const countLabel = document.getElementById('customArtSelectionCount');
  const selectAllCheckbox = document.getElementById('customArtSelectAll');
  const selectAllBtn = document.getElementById('customArtSelectAllBtn');

  if (bulkBar) {
    bulkBar.style.display = count > 0 ? 'flex' : 'none';
  }
  if (countLabel) {
    countLabel.textContent = `${count} selected`;
  }
  if (selectAllCheckbox) {
    selectAllCheckbox.checked = count > 0 && count === customArtState.artwork.length;
    selectAllCheckbox.indeterminate = count > 0 && count < customArtState.artwork.length;
  }

  // Update Select All button text
  if (selectAllBtn) {
    const allSelected = customArtState.artwork.length > 0 && count === customArtState.artwork.length;
    selectAllBtn.textContent = allSelected ? 'Deselect All' : 'Select All';
  }

  // Update card visual states only
  document.querySelectorAll('.custom-art-card[data-artwork-id]').forEach(card => {
    const id = card.dataset.artworkId; // Already a string from dataset
    const isSelected = customArtState.selectedArtworkIds.has(id);
    card.classList.toggle('selected', isSelected);
  });
}

function initArtworkBulkActions() {
  // Select All checkbox - only selects currently filtered/visible items
  const selectAllCheckbox = document.getElementById('customArtSelectAll');
  if (selectAllCheckbox) {
    selectAllCheckbox.addEventListener('change', () => {
      if (selectAllCheckbox.checked) {
        // Only select filtered/visible items
        const search = customArtElements.artworkSearch?.value?.toLowerCase() || '';
        const category = customArtElements.artworkCategoryFilter?.value || '';
        let filtered = customArtState.artwork;
        if (search) {
          filtered = filtered.filter(a =>
            a.title?.toLowerCase().includes(search) ||
            a.tags?.toLowerCase().includes(search) ||
            a.description?.toLowerCase().includes(search)
          );
        }
        if (category) {
          filtered = filtered.filter(a => a.category === category);
        }
        filtered.forEach(a => customArtState.selectedArtworkIds.add(String(a.id)));
      } else {
        customArtState.selectedArtworkIds.clear();
      }
      renderCustomArtArtwork();
    });
  }

  // Clear selection button
  const clearBtn = document.getElementById('customArtBulkClear');
  if (clearBtn) {
    clearBtn.addEventListener('click', () => {
      customArtState.selectedArtworkIds.clear();
      renderCustomArtArtwork();
    });
  }

  // AI Metadata button
  const aiMetadataBtn = document.getElementById('customArtBulkAIMetadata');
  if (aiMetadataBtn) {
    aiMetadataBtn.addEventListener('click', runBulkAIMetadata);
  }

  // Bulk Category change
  const bulkCategorySelect = document.getElementById('customArtBulkCategorySelect');
  if (bulkCategorySelect) {
    bulkCategorySelect.addEventListener('change', async () => {
      let category = bulkCategorySelect.value;
      if (!category) return;

      // Handle "Add New" option
      if (category === '__add_new__') {
        const newCategory = await showPrompt('Enter new category name:');
        if (!newCategory || !newCategory.trim()) {
          bulkCategorySelect.value = '';
          return;
        }
        category = newCategory.trim();
        // Add to categories list if not already there
        if (!customArtState.categories.includes(category)) {
          customArtState.categories.push(category);
          renderArtworkCategoryFilter();
        }
      }

      await bulkUpdateArtworkCategory(category);
      bulkCategorySelect.value = '';
    });
  }

  // Bulk Status change
  const bulkStatusSelect = document.getElementById('customArtBulkStatusSelect');
  if (bulkStatusSelect) {
    bulkStatusSelect.addEventListener('change', async () => {
      const status = bulkStatusSelect.value;
      if (!status) return;
      await bulkUpdateArtworkStatus(status);
      bulkStatusSelect.value = '';
    });
  }
}

// --- ROOM SELECTION & BULK ACTIONS ---
function updateRoomSelectionUI() {
  const count = customArtState.selectedRoomIds.size;
  const bulkBar = document.getElementById('customArtRoomBulkActionsBar');
  const countLabel = document.getElementById('customArtRoomSelectionCount');
  const selectAllCheckbox = document.getElementById('customArtRoomSelectAll');
  const selectAllBtn = document.getElementById('customArtRoomSelectAllBtn');

  if (bulkBar) {
    bulkBar.style.display = count > 0 ? 'flex' : 'none';
  }
  if (countLabel) {
    countLabel.textContent = `${count} selected`;
  }
  if (selectAllCheckbox) {
    selectAllCheckbox.checked = count > 0 && count === customArtState.rooms.length;
    selectAllCheckbox.indeterminate = count > 0 && count < customArtState.rooms.length;
  }

  // Update Select All button text
  if (selectAllBtn) {
    const allSelected = customArtState.rooms.length > 0 && count === customArtState.rooms.length;
    selectAllBtn.textContent = allSelected ? 'Deselect All' : 'Select All';
  }

  // Update card visual states
  document.querySelectorAll('.custom-art-card[data-room-id]').forEach(card => {
    const id = card.dataset.roomId;
    card.classList.toggle('selected', customArtState.selectedRoomIds.has(id));
  });
}

function initRoomBulkActions() {
  // Select All checkbox - only selects currently filtered/visible items
  const selectAllCheckbox = document.getElementById('customArtRoomSelectAll');
  if (selectAllCheckbox) {
    selectAllCheckbox.addEventListener('change', () => {
      if (selectAllCheckbox.checked) {
        // Only select filtered/visible items
        const searchTerm = (customArtElements.roomSearch?.value || '').toLowerCase().trim();
        const typeFilter = customArtElements.roomTypeFilter?.value || '';
        let filtered = customArtState.rooms;
        if (searchTerm) {
          filtered = filtered.filter(r =>
            (r.title || '').toLowerCase().includes(searchTerm) ||
            (r.description || '').toLowerCase().includes(searchTerm) ||
            (r.tags || '').toLowerCase().includes(searchTerm)
          );
        }
        if (typeFilter) {
          filtered = filtered.filter(r => r.roomType === typeFilter);
        }
        filtered.forEach(r => customArtState.selectedRoomIds.add(r.id));
      } else {
        customArtState.selectedRoomIds.clear();
      }
      renderCustomArtRooms();
    });
  }

  // Clear selection button
  const clearBtn = document.getElementById('customArtRoomBulkClear');
  if (clearBtn) {
    clearBtn.addEventListener('click', () => {
      customArtState.selectedRoomIds.clear();
      renderCustomArtRooms();
    });
  }

  // AI Metadata button
  const aiMetadataBtn = document.getElementById('customArtRoomBulkAIMetadata');
  if (aiMetadataBtn) {
    aiMetadataBtn.addEventListener('click', runBulkRoomAIMetadata);
  }

  // Bulk Type change
  const bulkTypeSelect = document.getElementById('customArtRoomBulkTypeSelect');
  console.log('[initRoomBulkActions] bulkTypeSelect element:', bulkTypeSelect);
  if (bulkTypeSelect) {
    bulkTypeSelect.addEventListener('change', async () => {
      let roomType = bulkTypeSelect.value;
      console.log('[BulkTypeSelect] Changed to:', roomType);
      if (!roomType) return;

      // Handle "Add New" option
      if (roomType === '__add_new__') {
        console.log('[BulkTypeSelect] Add New selected, calling showPrompt...');
        const newType = await showPrompt('Enter new room type (e.g. "Game Room"):');
        console.log('[BulkTypeSelect] showPrompt returned:', newType);
        if (!newType || !newType.trim()) {
          bulkTypeSelect.value = '';
          return;
        }
        roomType = newType.trim().toLowerCase().replace(/\s+/g, '-');
        // Add to dropdown if not already there
        const existingOption = bulkTypeSelect.querySelector(`option[value="${roomType}"]`);
        if (!existingOption) {
          const newOption = document.createElement('option');
          newOption.value = roomType;
          newOption.textContent = roomType.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
          // Insert before "Add New" option
          const addNewOption = bulkTypeSelect.querySelector('option[value="__add_new__"]');
          bulkTypeSelect.insertBefore(newOption, addNewOption);
        }
      }

      await bulkUpdateRoomType(roomType);
      bulkTypeSelect.value = '';
    });
  }

  // Bulk Status change
  const bulkStatusSelect = document.getElementById('customArtRoomBulkStatusSelect');
  if (bulkStatusSelect) {
    bulkStatusSelect.addEventListener('change', async () => {
      const status = bulkStatusSelect.value;
      if (!status) return;
      await bulkUpdateRoomStatus(status);
      bulkStatusSelect.value = '';
    });
  }

  // Search and filter handlers
  if (customArtElements.roomSearch) {
    customArtElements.roomSearch.addEventListener('input', renderCustomArtRooms);
  }
  if (customArtElements.roomTypeFilter) {
    customArtElements.roomTypeFilter.addEventListener('change', renderCustomArtRooms);
  }

  // Room grid click delegation
  if (customArtElements.roomsGrid) {
    customArtElements.roomsGrid.addEventListener('click', (e) => {
      // Handle Edit button clicks
      const editBtn = e.target.closest('.room-edit-btn');
      if (editBtn) {
        e.stopPropagation();
        const roomId = editBtn.dataset.roomId;
        const room = customArtState.rooms.find(r => String(r.id) === roomId);
        if (room) showRoomForm(room);
        return;
      }

      // Handle card clicks to toggle selection
      const card = e.target.closest('.custom-art-card[data-room-id]');
      if (card) {
        const roomId = card.dataset.roomId;
        if (customArtState.selectedRoomIds.has(roomId)) {
          customArtState.selectedRoomIds.delete(roomId);
        } else {
          customArtState.selectedRoomIds.add(roomId);
        }
        renderCustomArtRooms();
      }
    });
  }

  // Select All button for rooms - only selects currently filtered/visible items
  const roomSelectAllBtn = document.getElementById('customArtRoomSelectAllBtn');
  if (roomSelectAllBtn) {
    roomSelectAllBtn.addEventListener('click', () => {
      // Get filtered items
      const searchTerm = (customArtElements.roomSearch?.value || '').toLowerCase().trim();
      const typeFilter = customArtElements.roomTypeFilter?.value || '';
      let filtered = customArtState.rooms;
      if (searchTerm) {
        filtered = filtered.filter(r =>
          (r.title || '').toLowerCase().includes(searchTerm) ||
          (r.description || '').toLowerCase().includes(searchTerm) ||
          (r.tags || '').toLowerCase().includes(searchTerm)
        );
      }
      if (typeFilter) {
        filtered = filtered.filter(r => r.roomType === typeFilter);
      }

      const allFilteredSelected = filtered.length > 0 &&
                          filtered.every(r => customArtState.selectedRoomIds.has(String(r.id)));
      if (allFilteredSelected) {
        // Deselect only filtered items
        filtered.forEach(r => customArtState.selectedRoomIds.delete(String(r.id)));
      } else {
        filtered.forEach(r => customArtState.selectedRoomIds.add(String(r.id)));
      }
      renderCustomArtRooms();
    });
  }

  // Single room AI metadata button
  if (customArtElements.roomAIMetadataBtn) {
    customArtElements.roomAIMetadataBtn.addEventListener('click', runSingleRoomAIMetadata);
  }
}

async function runBulkRoomAIMetadata() {
  const selectedIds = Array.from(customArtState.selectedRoomIds);
  if (!selectedIds.length) {
    setCustomArtStatus('No rooms selected', true);
    return;
  }

  setCustomArtStatus(`Generating AI metadata for ${selectedIds.length} room(s)...`);
  let successCount = 0;
  let failCount = 0;

  for (const id of selectedIds) {
    const room = customArtState.rooms.find(r => r.id === id);
    if (!room || !room.imagePath) {
      failCount++;
      continue;
    }

    try {
      const result = await printStation.customArt.generateRoomMetadata(room.imagePath);
      if (result?.metadata) {
        await printStation.customArt.updateRoom(id, {
          title: result.metadata.title || room.title,
          description: result.metadata.description || room.description,
          roomType: result.metadata.roomType || room.roomType,
          tags: result.metadata.tags || room.tags
        });
        successCount++;
      } else {
        failCount++;
      }
    } catch (e) {
      console.error(`AI metadata failed for room ${id}:`, e);
      failCount++;
    }
  }

  setCustomArtStatus(`AI metadata complete: ${successCount} succeeded, ${failCount} failed`);
  customArtState.selectedRoomIds.clear();
  await loadCustomArtRooms();
}

async function runSingleRoomAIMetadata() {
  const imagePath = customArtElements.roomImagePath?.value;
  if (!imagePath) {
    setCustomArtStatus('Please select an image first', true);
    return;
  }

  setCustomArtStatus('Generating AI metadata...');
  try {
    const result = await printStation.customArt.generateRoomMetadata(imagePath);
    if (result?.metadata) {
      if (customArtElements.roomTitle && result.metadata.title) {
        customArtElements.roomTitle.value = result.metadata.title;
      }
      if (customArtElements.roomDescription && result.metadata.description) {
        customArtElements.roomDescription.value = result.metadata.description;
      }
      if (customArtElements.roomType && result.metadata.roomType) {
        customArtElements.roomType.value = result.metadata.roomType;
      }
      if (customArtElements.roomTags && result.metadata.tags) {
        customArtElements.roomTags.value = result.metadata.tags;
      }
      // Generate filename from title
      if (customArtElements.roomFilename && result.metadata.title) {
        const filename = result.metadata.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
        customArtElements.roomFilename.value = filename;
      }
      setCustomArtStatus('AI metadata generated');
    } else {
      setCustomArtStatus('AI metadata generation failed', true);
    }
  } catch (e) {
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

async function bulkUpdateRoomType(roomType) {
  const selectedIds = Array.from(customArtState.selectedRoomIds);
  if (!selectedIds.length) return;

  setCustomArtStatus(`Setting type to "${roomType}" for ${selectedIds.length} room(s)...`);

  let successCount = 0;
  for (const id of selectedIds) {
    try {
      await printStation.customArt.updateRoom(id, { roomType });
      successCount++;
    } catch (e) {
      console.error(`Failed to update room ${id}:`, e);
    }
  }

  setCustomArtStatus(`Updated ${successCount} room(s)`);
  customArtState.selectedRoomIds.clear();
  await loadCustomArtRooms();
}

async function bulkUpdateRoomStatus(status) {
  const selectedIds = Array.from(customArtState.selectedRoomIds);
  if (!selectedIds.length) return;

  const active = status === 'active';
  setCustomArtStatus(`Setting status to "${status}" for ${selectedIds.length} room(s)...`);

  let successCount = 0;
  for (const id of selectedIds) {
    try {
      await printStation.customArt.updateRoom(id, { active });
      successCount++;
    } catch (e) {
      console.error(`Failed to update room ${id}:`, e);
    }
  }

  setCustomArtStatus(`Updated ${successCount} room(s)`);
  customArtState.selectedRoomIds.clear();
  await loadCustomArtRooms();
}

