// --- PRODUCT SELECTION & BULK ACTIONS ---
function updateProductSelectionUI() {
  const count = customArtState.selectedProductIds.size;
  const bulkBar = document.getElementById('customArtProductBulkActionsBar');
  const countLabel = document.getElementById('customArtProductSelectionCount');
  const selectAllCheckbox = document.getElementById('customArtProductSelectAll');
  const selectAllHeader = document.getElementById('customArtProductSelectAllHeader');

  if (bulkBar) {
    bulkBar.style.display = count > 0 ? 'flex' : 'none';
  }
  if (countLabel) {
    countLabel.textContent = `${count} selected`;
  }
  if (selectAllCheckbox) {
    selectAllCheckbox.checked = count > 0 && count === customArtState.products.length;
    selectAllCheckbox.indeterminate = count > 0 && count < customArtState.products.length;
  }
  if (selectAllHeader) {
    selectAllHeader.checked = count > 0 && count === customArtState.products.length;
    selectAllHeader.indeterminate = count > 0 && count < customArtState.products.length;
  }

  // Update row visual states
  document.querySelectorAll('#customArtProductsBody tr[data-product-id]').forEach(row => {
    const id = row.dataset.productId;
    row.classList.toggle('selected', customArtState.selectedProductIds.has(id));
  });
}

function initProductBulkActions() {
  // Select All checkbox in toolbar
  const selectAllCheckbox = document.getElementById('customArtProductSelectAll');
  if (selectAllCheckbox) {
    selectAllCheckbox.addEventListener('change', () => {
      if (selectAllCheckbox.checked) {
        customArtState.products.forEach(p => customArtState.selectedProductIds.add(p.id));
      } else {
        customArtState.selectedProductIds.clear();
      }
      renderCustomArtProducts();
    });
  }

  // Select All checkbox in header
  const selectAllHeader = document.getElementById('customArtProductSelectAllHeader');
  if (selectAllHeader) {
    selectAllHeader.addEventListener('change', () => {
      if (selectAllHeader.checked) {
        customArtState.products.forEach(p => customArtState.selectedProductIds.add(p.id));
      } else {
        customArtState.selectedProductIds.clear();
      }
      renderCustomArtProducts();
    });
  }

  // Clear selection button
  const clearBtn = document.getElementById('customArtProductBulkClear');
  if (clearBtn) {
    clearBtn.addEventListener('click', () => {
      customArtState.selectedProductIds.clear();
      renderCustomArtProducts();
    });
  }

  // Bulk Status change
  const bulkStatusSelect = document.getElementById('customArtProductBulkStatusSelect');
  if (bulkStatusSelect) {
    bulkStatusSelect.addEventListener('change', async () => {
      const status = bulkStatusSelect.value;
      if (!status) return;
      await bulkUpdateProductStatus(status);
      bulkStatusSelect.value = '';
    });
  }

  // Bulk Export button
  const bulkExportBtn = document.getElementById('customArtProductBulkExport');
  if (bulkExportBtn) {
    bulkExportBtn.addEventListener('click', bulkExportProducts);
  }

  // Bulk Delete button
  const bulkDeleteBtn = document.getElementById('customArtProductBulkDelete');
  if (bulkDeleteBtn) {
    bulkDeleteBtn.addEventListener('click', bulkDeleteProducts);
  }
}

async function bulkUpdateProductStatus(status) {
  const selectedIds = Array.from(customArtState.selectedProductIds);
  if (!selectedIds.length) return;

  setCustomArtStatus(`Setting status to "${status}" for ${selectedIds.length} product(s)...`);
  let successCount = 0;

  for (const id of selectedIds) {
    try {
      await printStation.customArt.updateProduct(id, { status });
      successCount++;
    } catch (e) {
      console.error('[Custom Art] Failed to update product status:', e);
    }
  }

  setCustomArtStatus(`Status updated for ${successCount} product(s)`);
  customArtState.selectedProductIds.clear();
  await loadCustomArtProducts();
}

async function bulkExportProducts() {
  const selectedIds = Array.from(customArtState.selectedProductIds);
  if (!selectedIds.length) {
    setCustomArtStatus('No products selected', true);
    return;
  }

  setCustomArtStatus(`Exporting ${selectedIds.length} product(s) to Shopify...`);

  try {
    const result = await printStation.customArt.exportToShopify({ productIds: selectedIds });
    if (result.success) {
      setCustomArtStatus(`Exported ${result.exportedCount || selectedIds.length} product(s) to Shopify`);
    } else {
      setCustomArtStatus(`Export error: ${result.error}`, true);
    }
  } catch (e) {
    setCustomArtStatus(`Export error: ${e.message}`, true);
  }

  customArtState.selectedProductIds.clear();
  renderCustomArtProducts();
}

async function bulkDeleteProducts() {
  const selectedIds = Array.from(customArtState.selectedProductIds);
  if (!selectedIds.length) return;

  const confirmed = await nativeConfirm(`Are you sure you want to delete ${selectedIds.length} product(s)? This cannot be undone.`, 'Delete Products');
  if (!confirmed) return;

  setCustomArtStatus(`Deleting ${selectedIds.length} product(s)...`);
  let successCount = 0;

  for (const id of selectedIds) {
    try {
      await printStation.customArt.deleteProduct(id);
      successCount++;
    } catch (e) {
      console.error('[Custom Art] Failed to delete product:', e);
    }
  }

  setCustomArtStatus(`Deleted ${successCount} product(s)`);
  customArtState.selectedProductIds.clear();
  await loadCustomArtProducts();
}

// --- MATERIALS ---
async function loadCustomArtMaterials() {
  setCustomArtStatus('Loading materials...');
  try {
    const result = await printStation.customArt.listMaterials({ activeOnly: false });
    customArtState.materials = result?.materials || [];
    renderCustomArtMaterials();
    setCustomArtStatus(`${customArtState.materials.length} material(s) loaded`);
  } catch (e) {
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

function renderCustomArtMaterials() {
  if (!customArtElements.materialsBody) return;
  if (!customArtState.materials.length) {
    customArtElements.materialsBody.innerHTML = '<tr><td colspan="6" class="placeholder">No materials found.</td></tr>';
    return;
  }
  customArtElements.materialsBody.innerHTML = customArtState.materials.map(mat => `
    <tr data-material-id="${mat.id}">
      <td>${mat.name}</td>
      <td>${mat.description || '-'}</td>
      <td>${mat.filterType || 'none'}</td>
      <td>$${((mat.baseCostCents || 0) / 100).toFixed(2)}</td>
      <td>${mat.active ? 'Yes' : 'No'}</td>
      <td><button class="secondary" onclick="editCustomArtMaterial('${mat.id}')">Edit</button></td>
    </tr>
  `).join('');
}

window.editCustomArtMaterial = function(id) {
  const mat = customArtState.materials.find(m => m.id === id);
  if (mat) showMaterialForm(mat);
};

function showMaterialForm(mat = null) {
  customArtState.editingMaterial = mat;
  if (customArtElements.materialFormCard) customArtElements.materialFormCard.style.display = '';
  if (customArtElements.materialFormTitle) customArtElements.materialFormTitle.textContent = mat ? 'Edit Material' : 'Add Material';
  if (customArtElements.materialDeleteBtn) customArtElements.materialDeleteBtn.style.display = mat ? '' : 'none';

  if (customArtElements.materialName) customArtElements.materialName.value = mat?.name || '';
  if (customArtElements.materialDesc) customArtElements.materialDesc.value = mat?.description || '';
  if (customArtElements.materialFilter) customArtElements.materialFilter.value = mat?.filterType || 'none';
  if (customArtElements.materialCost) customArtElements.materialCost.value = mat?.baseCostCents || 0;
  if (customArtElements.materialId) customArtElements.materialId.value = mat?.id || '';
}

function hideMaterialForm() {
  customArtState.editingMaterial = null;
  if (customArtElements.materialFormCard) customArtElements.materialFormCard.style.display = 'none';
}

async function saveMaterial() {
  const name = customArtElements.materialName?.value?.trim();
  if (!name) {
    setCustomArtStatus('Name is required', true);
    return;
  }

  const payload = {
    name,
    description: customArtElements.materialDesc?.value || null,
    filterType: customArtElements.materialFilter?.value || 'none',
    baseCostCents: parseInt(customArtElements.materialCost?.value) || 0
  };

  setCustomArtStatus('Saving material...');
  try {
    if (customArtState.editingMaterial) {
      await printStation.customArt.updateMaterial(customArtState.editingMaterial.id, payload);
    } else {
      await printStation.customArt.createMaterial(payload);
    }
    hideMaterialForm();
    await loadCustomArtMaterials();
    setCustomArtStatus('Material saved');
  } catch (e) {
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

async function deleteMaterial() {
  if (!customArtState.editingMaterial) return;
  if (!await nativeConfirm(`Delete material "${customArtState.editingMaterial.name}"?`, 'Delete Material')) return;

  try {
    await printStation.customArt.deleteMaterial(customArtState.editingMaterial.id);
    hideMaterialForm();
    await loadCustomArtMaterials();
    setCustomArtStatus('Material deleted');
  } catch (e) {
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

// --- PRODUCTS ---
async function loadCustomArtProducts() {
  setCustomArtStatus('Loading products...');
  try {
    const [productsResult, materialsResult, artworkResult] = await Promise.all([
      printStation.customArt.listProducts({ activeOnly: false }),
      printStation.customArt.listMaterials({ activeOnly: true }),
      printStation.customArt.listArtwork({ activeOnly: true, limit: 1000 })
    ]);
    customArtState.products = productsResult?.products || [];
    customArtState.materials = materialsResult?.materials || [];
    customArtState.artwork = artworkResult?.artwork || [];
    renderCustomArtProducts();
    populateProductDropdowns();
    initProductBulkActions();
    setCustomArtStatus(`${customArtState.products.length} product(s) loaded`);
  } catch (e) {
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

function renderCustomArtProducts() {
  if (!customArtElements.productsBody) return;
  if (!customArtState.products.length) {
    customArtElements.productsBody.innerHTML = '<tr><td colspan="9" class="placeholder">No products created yet.</td></tr>';
    return;
  }
  customArtElements.productsBody.innerHTML = customArtState.products.map(prod => {
    const isSelected = customArtState.selectedProductIds.has(prod.id);
    return `
    <tr data-product-id="${prod.id}" class="${isSelected ? 'selected' : ''}">
      <td><input type="checkbox" class="product-checkbox" data-product-id="${prod.id}" ${isSelected ? 'checked' : ''} /></td>
      <td>${prod.title}</td>
      <td>${prod.artwork?.title || '-'}</td>
      <td>${prod.material?.name || '-'}</td>
      <td>${prod.singleSize?.width && prod.singleSize?.height ? `${prod.singleSize.width}×${prod.singleSize.height}${prod.singleSize.unit === 'inches' ? '"' : 'cm'}` : '-'}</td>
      <td>$${((prod.basePriceCents || 0) / 100).toFixed(2)}</td>
      <td>${prod.hasVariants ? 'Yes' : 'No'}</td>
      <td><span class="custom-art-card-badge ${prod.status}">${prod.status}</span></td>
      <td><button class="secondary" onclick="editCustomArtProduct('${prod.id}')">Edit</button></td>
    </tr>
  `}).join('');

  // Add checkbox handlers
  customArtElements.productsBody.querySelectorAll('.product-checkbox').forEach(cb => {
    cb.addEventListener('change', (e) => {
      const productId = cb.dataset.productId;
      if (cb.checked) {
        customArtState.selectedProductIds.add(productId);
      } else {
        customArtState.selectedProductIds.delete(productId);
      }
      updateProductSelectionUI();
    });
  });

  updateProductSelectionUI();
}

function populateProductDropdowns() {
  // Artwork dropdown
  const artworkDropdown = customArtElements.productArtwork || document.getElementById('customArtProductArtwork');
  if (artworkDropdown) {
    console.log('[populateProductDropdowns] Populating artwork dropdown with', customArtState.artwork.length, 'items');
    artworkDropdown.innerHTML = '<option value="">Select artwork...</option>' +
      customArtState.artwork.map(a => `<option value="${a.id}">${cleanAiGeneratedName(a.title) || a.title || 'Untitled'}</option>`).join('');
    console.log('[populateProductDropdowns] Artwork dropdown now has', artworkDropdown.options.length, 'options');
  } else {
    console.warn('[populateProductDropdowns] Artwork dropdown not found!');
  }
  // Material dropdown
  const materialDropdown = customArtElements.productMaterial || document.getElementById('customArtProductMaterial');
  if (materialDropdown) {
    materialDropdown.innerHTML = '<option value="">Select material...</option>' +
      customArtState.materials.map(m => `<option value="${m.id}">${m.name}</option>`).join('');
  }
}

window.editCustomArtProduct = function(id) {
  const prod = customArtState.products.find(p => p.id === id);
  if (prod) showProductForm(prod);
};

// Create a new product from selected artwork
function createProductFromArtwork(artworkId) {
  const artwork = customArtState.artwork.find(a => String(a.id) === artworkId);
  if (!artwork) {
    setCustomArtStatus('Artwork not found', true);
    return;
  }

  // Switch to Products tab
  switchCustomArtSubtab('products');

  // Wait a moment for the tab to render, then show the product form pre-filled
  setTimeout(() => {
    // Ensure materials are loaded for the dropdown
    if (!customArtState.materials.length) {
      printStation.customArt.listMaterials({ activeOnly: true }).then(result => {
        customArtState.materials = result?.materials || [];
        populateProductDropdowns();
        showProductFormWithArtwork(artwork);
      });
    } else {
      populateProductDropdowns();
      showProductFormWithArtwork(artwork);
    }
  }, 100);
}

// Print artwork directly from the artwork card
// =============== SUBLIMATION PRINT ===============

const SUBLIMATION_BLANK_SIZES = [
  { label: '5 × 7"', width: 5, height: 7 },
  { label: '8 × 10"', width: 8, height: 10 },
  { label: '11 × 14"', width: 11, height: 14 },
  { label: '11 × 17"', width: 11, height: 17 }
];

const SUBLIMATION_PAPER_SIZES = [
  { label: '8.5 × 11" (Letter)', value: 'Letter', width: 8.5, height: 11 },
  { label: '11 × 17" (Tabloid)', value: 'Tabloid', width: 11, height: 17 },
  { label: '13 × 19"', value: '13x19', width: 13, height: 19 }
];

async function printArtworkFromCard(artworkId, artworkPath) {
  const artwork = customArtState.artwork.find(a => String(a.id) === artworkId);
  if (!artwork) {
    showToast('Artwork not found', 'error');
    return;
  }

  if (!(artwork.filePath || artwork.optimizedPath || artworkPath)) {
    showToast('No image file available for this artwork', 'error');
    return;
  }

  // Load inkjet printers + source image dimensions in parallel
  let printers = [];
  let srcInfo = null;
  try {
    const [p, info] = await Promise.all([
      printStation.inkjetFleet.listPrinters().catch(() => []),
      printStation.customArt.prepareSublimation({ artworkId, infoOnly: true }).catch(() => null)
    ]);
    printers = p || [];
    srcInfo = info;
  } catch (e) {
    console.warn('[Sublimation] Init error:', e.message);
  }

  const srcW = srcInfo?.sourceWidth || 0;
  const srcH = srcInfo?.sourceHeight || 0;
  const srcAspect = srcW && srcH ? srcW / srcH : 1;

  const cleanedTitle = cleanAiGeneratedName(artwork.title) || artwork.title || 'Untitled';
  const previewUrl = resolveArtworkUrl(artwork.thumbnailPath || artwork.optimizedPath || artwork.filePath, { width: 600, quality: 85 });
  const previewSrc = getCachedPreviewUrl(previewUrl);

  const modal = document.createElement('div');
  modal.className = 'modal-overlay';
  modal.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.6);display:flex;align-items:center;justify-content:center;z-index:9999;';
  modal.innerHTML = `
    <div style="background:var(--surface);border-radius:10px;padding:24px;width:600px;max-height:92vh;overflow-y:auto;">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;">
        <h3 style="margin:0;">Sublimation Print</h3>
        <button id="subPrintClose" style="background:none;border:none;font-size:1.2rem;cursor:pointer;color:var(--text);">✕</button>
      </div>

      <div style="display:flex;gap:16px;margin-bottom:16px;">
        <div style="flex:1;">
          <div style="font-weight:600;font-size:1rem;margin-bottom:4px;">${escapeHtml(cleanedTitle)}</div>
          <div class="muted" style="font-size:0.85rem;">Source: ${srcW}×${srcH}px${srcW && srcH ? ` (${srcAspect.toFixed(2)}:1)` : ''}</div>
          <div style="margin-top:6px;font-size:0.8rem;color:var(--accent);">Mirrored + bleed for sublimation transfer</div>
        </div>
      </div>

      <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
        <div>
          <label style="display:block;margin-bottom:4px;font-size:0.85rem;font-weight:600;">Blank Size</label>
          <select id="subPrintBlankSize" style="width:100%;padding:8px;border-radius:6px;">
            ${SUBLIMATION_BLANK_SIZES.map((s, i) => `<option value="${i}">${s.label}</option>`).join('')}
          </select>
        </div>
        <div>
          <label style="display:block;margin-bottom:4px;font-size:0.85rem;font-weight:600;">Paper Loaded</label>
          <select id="subPrintPaperSize" style="width:100%;padding:8px;border-radius:6px;">
            ${SUBLIMATION_PAPER_SIZES.map((s, i) => `<option value="${i}">${s.label}</option>`).join('')}
          </select>
        </div>
        <div>
          <label style="display:block;margin-bottom:4px;font-size:0.85rem;font-weight:600;">Bleed (per side)</label>
          <select id="subPrintBleed" style="width:100%;padding:8px;border-radius:6px;">
            <option value="0.125">1/8"</option>
            <option value="0.25" selected>1/4"</option>
            <option value="0.375">3/8"</option>
            <option value="0.5">1/2"</option>
          </select>
        </div>
        <div>
          <label style="display:block;margin-bottom:4px;font-size:0.85rem;font-weight:600;">Printer</label>
          <select id="subPrintPrinter" style="width:100%;padding:8px;border-radius:6px;">
            ${printers.length
              ? printers.map(p => `<option value="${p.id}">${escapeHtml(p.name)}</option>`).join('')
              : '<option value="">No inkjet printers found</option>'}
          </select>
        </div>
      </div>

      <!-- Crop position (shown only when aspect ratios mismatch) -->
      <div id="subPrintCropSection" style="margin-top:14px;display:none;">
        <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px;">
          <label style="font-size:0.85rem;font-weight:600;">Crop Position</label>
          <span id="subPrintCropWarning" style="font-size:0.8rem;color:var(--warning,#f59e0b);"></span>
        </div>
        <div style="display:flex;gap:16px;align-items:flex-start;">
          <!-- Position grid (3x3) -->
          <div id="subPrintCropGrid" style="display:grid;grid-template-columns:repeat(3,32px);grid-template-rows:repeat(3,32px);gap:3px;flex-shrink:0;">
            <button class="sub-crop-pos secondary" data-pos="top-left" style="padding:0;font-size:16px;" title="Top Left">&#8598;</button>
            <button class="sub-crop-pos secondary" data-pos="top" style="padding:0;font-size:16px;" title="Top">&#8593;</button>
            <button class="sub-crop-pos secondary" data-pos="top-right" style="padding:0;font-size:16px;" title="Top Right">&#8599;</button>
            <button class="sub-crop-pos secondary" data-pos="left" style="padding:0;font-size:16px;" title="Left">&#8592;</button>
            <button class="sub-crop-pos secondary" data-pos="center" style="padding:0;font-size:16px;background:var(--accent);color:#fff;" title="Center">&#9679;</button>
            <button class="sub-crop-pos secondary" data-pos="right" style="padding:0;font-size:16px;" title="Right">&#8594;</button>
            <button class="sub-crop-pos secondary" data-pos="bottom-left" style="padding:0;font-size:16px;" title="Bottom Left">&#8601;</button>
            <button class="sub-crop-pos secondary" data-pos="bottom" style="padding:0;font-size:16px;" title="Bottom">&#8595;</button>
            <button class="sub-crop-pos secondary" data-pos="bottom-right" style="padding:0;font-size:16px;" title="Bottom Right">&#8600;</button>
          </div>
          <!-- Crop preview canvas -->
          <div style="flex:1;position:relative;overflow:hidden;border-radius:6px;border:1px solid var(--border);background:#111;">
            <div id="subPrintCropPreview" style="position:relative;width:100%;overflow:hidden;">
              <img id="subPrintCropImg" src="${previewSrc}" style="display:block;width:100%;"/>
              <div id="subPrintCropOverlay" style="position:absolute;border:2px dashed #4a9;pointer-events:none;box-shadow:0 0 0 9999px rgba(0,0,0,0.5);"></div>
            </div>
          </div>
        </div>
        <div id="subPrintCropInfo" style="margin-top:6px;font-size:0.8rem;color:var(--muted);"></div>
      </div>

      <!-- Aspect match message -->
      <div id="subPrintAspectOk" style="margin-top:14px;padding:10px;background:var(--bg);border-radius:6px;font-size:0.85rem;color:var(--success);display:none;">
        Aspect ratio matches — no cropping needed
      </div>

      <div id="subPrintInfo" style="margin-top:14px;padding:10px;background:var(--bg);border-radius:6px;font-size:0.85rem;"></div>

      <div id="subPrintFinalPreviewWrap" style="margin-top:14px;text-align:center;display:none;">
        <div style="font-size:0.8rem;color:var(--muted);margin-bottom:6px;">Final output (mirrored)</div>
        <img id="subPrintFinalPreviewImg" style="max-width:100%;max-height:180px;border-radius:6px;border:1px solid var(--border);"/>
      </div>

      <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:18px;">
        <button id="subPrintCancel" class="secondary" style="padding:8px 18px;">Cancel</button>
        <button id="subPrintSubmit" class="primary" style="padding:8px 18px;" ${!printers.length ? 'disabled' : ''}>Print</button>
      </div>
    </div>`;

  document.body.appendChild(modal);

  // --- State ---
  let selectedCropPos = 'center';

  // --- Crop position buttons ---
  modal.querySelectorAll('.sub-crop-pos').forEach(btn => {
    btn.addEventListener('click', () => {
      selectedCropPos = btn.dataset.pos;
      modal.querySelectorAll('.sub-crop-pos').forEach(b => {
        b.style.background = '';
        b.style.color = '';
      });
      btn.style.background = 'var(--accent)';
      btn.style.color = '#fff';
      updateCropPreview();
    });
  });

  // --- Crop preview logic (client-side, purely visual) ---
  function updateCropPreview() {
    const blankIdx = parseInt(modal.querySelector('#subPrintBlankSize').value);
    const bleed = parseFloat(modal.querySelector('#subPrintBleed').value);
    const blank = SUBLIMATION_BLANK_SIZES[blankIdx];
    const targetW = blank.width + bleed * 2;
    const targetH = blank.height + bleed * 2;
    const targetAspect = targetW / targetH;

    const cropSection = modal.querySelector('#subPrintCropSection');
    const aspectOk = modal.querySelector('#subPrintAspectOk');
    const tolerance = 0.02;
    const needsCrop = Math.abs(srcAspect - targetAspect) > tolerance;

    if (!needsCrop || !srcW) {
      cropSection.style.display = 'none';
      aspectOk.style.display = srcW ? 'block' : 'none';
      return;
    }

    cropSection.style.display = 'block';
    aspectOk.style.display = 'none';

    // Figure out which axis gets cropped
    const croppedAxis = srcAspect > targetAspect ? 'width' : 'height';
    const cropWarning = modal.querySelector('#subPrintCropWarning');
    const cropInfoEl = modal.querySelector('#subPrintCropInfo');

    if (croppedAxis === 'width') {
      // Image is wider than target — sides get cropped
      const visibleFraction = targetAspect / srcAspect;
      const cropPercent = Math.round((1 - visibleFraction) * 100);
      cropWarning.textContent = `${cropPercent}% of width will be cropped`;
      cropInfoEl.textContent = 'Image is wider than the blank — sides will be trimmed. Use arrows to shift the crop window.';
    } else {
      // Image is taller than target — top/bottom get cropped
      const visibleFraction = srcAspect / targetAspect;
      const cropPercent = Math.round((1 - visibleFraction) * 100);
      cropWarning.textContent = `${cropPercent}% of height will be cropped`;
      cropInfoEl.textContent = 'Image is taller than the blank — top/bottom will be trimmed. Use arrows to shift the crop window.';
    }

    // Position the overlay on the preview image
    const img = modal.querySelector('#subPrintCropImg');
    const imgRect = img.getBoundingClientRect();
    const previewW = img.offsetWidth;
    const previewH = img.offsetHeight || (previewW / srcAspect);
    const overlay = modal.querySelector('#subPrintCropOverlay');

    let cropW, cropH;
    if (croppedAxis === 'width') {
      // Full height visible, partial width
      cropH = previewH;
      cropW = previewH * targetAspect;
    } else {
      // Full width visible, partial height
      cropW = previewW;
      cropH = previewW / targetAspect;
    }

    // Clamp to image bounds
    cropW = Math.min(cropW, previewW);
    cropH = Math.min(cropH, previewH);

    // Position based on selected crop position
    let left = 0, top = 0;
    const hPos = selectedCropPos.includes('left') ? 'left' : selectedCropPos.includes('right') ? 'right' : 'center';
    const vPos = selectedCropPos.includes('top') ? 'top' : selectedCropPos.includes('bottom') ? 'bottom' : 'center';

    if (hPos === 'left') left = 0;
    else if (hPos === 'right') left = previewW - cropW;
    else left = (previewW - cropW) / 2;

    if (vPos === 'top') top = 0;
    else if (vPos === 'bottom') top = previewH - cropH;
    else top = (previewH - cropH) / 2;

    overlay.style.left = `${Math.max(0, left)}px`;
    overlay.style.top = `${Math.max(0, top)}px`;
    overlay.style.width = `${cropW}px`;
    overlay.style.height = `${cropH}px`;
  }

  // Wait for the preview image to load before computing overlay dimensions
  const cropImg = modal.querySelector('#subPrintCropImg');
  cropImg.addEventListener('load', () => updateCropPreview());

  // --- Info display ---
  function updateInfo() {
    const blankIdx = parseInt(modal.querySelector('#subPrintBlankSize').value);
    const paperIdx = parseInt(modal.querySelector('#subPrintPaperSize').value);
    const bleed = parseFloat(modal.querySelector('#subPrintBleed').value);
    const blank = SUBLIMATION_BLANK_SIZES[blankIdx];
    const paper = SUBLIMATION_PAPER_SIZES[paperIdx];
    const totalW = blank.width + bleed * 2;
    const totalH = blank.height + bleed * 2;
    const fits = totalW <= paper.width && totalH <= paper.height;
    const fitsRotated = totalW <= paper.height && totalH <= paper.width;
    const willFit = fits || fitsRotated;
    const orientation = fits ? 'Portrait' : fitsRotated ? 'Landscape' : 'N/A';

    const infoEl = modal.querySelector('#subPrintInfo');
    infoEl.innerHTML = `
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:4px 16px;">
        <span>Print size:</span><strong>${totalW}" × ${totalH}"</strong>
        <span>Paper:</span><strong>${paper.label}</strong>
        <span>Orientation:</span><strong>${orientation}</strong>
        <span>Fits on paper:</span><strong style="color:${willFit ? 'var(--success)' : 'var(--danger)'};">${willFit ? 'Yes' : 'NO — choose larger paper'}</strong>
      </div>
      <div style="margin-top:6px;color:var(--muted);font-size:0.8rem;">300 DPI · Mirrored · Photo/Glossy · Borderless · Max Quality</div>`;

    const submitBtn = modal.querySelector('#subPrintSubmit');
    submitBtn.disabled = !willFit || !printers.length;

    updateCropPreview();
  }

  modal.querySelector('#subPrintBlankSize').addEventListener('change', updateInfo);
  modal.querySelector('#subPrintPaperSize').addEventListener('change', updateInfo);
  modal.querySelector('#subPrintBleed').addEventListener('change', updateInfo);
  updateInfo();

  // --- Close handlers ---
  modal.querySelector('#subPrintClose').addEventListener('click', () => modal.remove());
  modal.querySelector('#subPrintCancel').addEventListener('click', () => modal.remove());
  modal.addEventListener('click', (e) => { if (e.target === modal) modal.remove(); });

  // --- Submit ---
  modal.querySelector('#subPrintSubmit').addEventListener('click', async () => {
    const blankIdx = parseInt(modal.querySelector('#subPrintBlankSize').value);
    const paperIdx = parseInt(modal.querySelector('#subPrintPaperSize').value);
    const bleed = parseFloat(modal.querySelector('#subPrintBleed').value);
    const printerId = parseInt(modal.querySelector('#subPrintPrinter').value);
    const blank = SUBLIMATION_BLANK_SIZES[blankIdx];
    const paper = SUBLIMATION_PAPER_SIZES[paperIdx];

    const totalW = blank.width + bleed * 2;
    const totalH = blank.height + bleed * 2;
    const fits = totalW <= paper.width && totalH <= paper.height;
    const orientation = fits ? 'Portrait' : 'Landscape';

    const submitBtn = modal.querySelector('#subPrintSubmit');
    submitBtn.disabled = true;
    submitBtn.textContent = 'Preparing image...';

    try {
      // Step 1: Server prepares the image (resize + crop + mirror + bleed)
      const prepared = await printStation.customArt.prepareSublimation({
        artworkId,
        blankWidth: blank.width,
        blankHeight: blank.height,
        bleedInches: bleed,
        cropPosition: selectedCropPos
      });

      if (!prepared?.success || !prepared?.base64) {
        throw new Error(prepared?.error || 'Server failed to prepare sublimation image');
      }

      // Show final mirrored preview
      const previewWrap = modal.querySelector('#subPrintFinalPreviewWrap');
      const previewImg = modal.querySelector('#subPrintFinalPreviewImg');
      previewImg.src = `data:image/png;base64,${prepared.base64}`;
      previewWrap.style.display = 'block';

      // Step 2: Submit to inkjet printer via fleet
      submitBtn.textContent = 'Sending to printer...';

      const job = {
        printer_id: printerId,
        filename: `sublimation_${cleanedTitle.replace(/[^a-zA-Z0-9_-]/g, '_')}_${blank.width}x${blank.height}.png`,
        title: `Sublimation: ${cleanedTitle} (${blank.label})`,
        copies: 1,
        page_size: paper.value,
        color_mode: 'Color',
        media_type: 'Photo',
        print_quality: '1200dpi',
        duplex: 'None',
        orientation: orientation,
        borders: 'none',
        custom_options: {},
        file_base64: prepared.base64,
        submitted_by: 'sublimation-print'
      };

      await printStation.inkjetFleet.submitJob(job);

      showToast(`Sublimation print sent: ${blank.label} on ${paper.label}`, 'success', 5000);
      modal.remove();
    } catch (err) {
      console.error('[Sublimation] Print error:', err);
      showToast('Sublimation print failed: ' + err.message, 'error', 8000);
      submitBtn.disabled = false;
      submitBtn.textContent = 'Print';
    }
  });
}

// Download artwork directly from the artwork card
async function downloadArtworkFromCard(artworkId, artworkPath, artworkTitle) {
  const artwork = customArtState.artwork.find(a => String(a.id) === artworkId);
  if (!artwork) {
    showToast('Artwork not found', 'error');
    return;
  }

  // Get the full file path - prefer original file for best quality
  let filePath = artwork.filePath || artwork.optimizedPath || artworkPath;

  if (!filePath) {
    showToast('No image file available for this artwork', 'error');
    return;
  }

  // Build full URL if it's a relative path
  let downloadUrl = filePath;
  if (!filePath.startsWith('http://') && !filePath.startsWith('https://') && !filePath.startsWith('file://')) {
    const serverBase = state.config?.serverBaseUrl?.trim() || '';
    downloadUrl = filePath.startsWith('/') ? serverBase + filePath : serverBase + '/' + filePath;
  }

  // Generate a clean filename
  const cleanTitle = (artworkTitle || artwork.title || 'artwork').replace(/[^a-zA-Z0-9-_]/g, '-').replace(/-+/g, '-');
  const ext = filePath.split('.').pop()?.toLowerCase() || 'png';
  const filename = `${cleanTitle}.${ext}`;

  try {
    // Use the downloadFile IPC - shows save dialog
    if (window.printStation?.downloadFile) {
      const result = await window.printStation.downloadFile({ url: downloadUrl, filename });
      if (result.canceled) {
        // User cancelled the save dialog
        return;
      }
      if (result.filePath) {
        showToast(`Downloaded: ${result.filePath.split(/[/\\]/).pop()}`, 'success');
      }
    } else {
      // Fallback: open in new tab/trigger browser download
      const a = document.createElement('a');
      a.href = downloadUrl;
      a.download = filename;
      a.target = '_blank';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      showToast(`Download started: ${filename}`, 'success');
    }
  } catch (error) {
    console.error('[Custom Art] Download error:', error);
    showToast('Download failed: ' + error.message, 'error');
  }
}

function showProductFormWithArtwork(artwork) {
  // Re-initialize elements in case they weren't found before
  initCustomArtElements();

  const cleanedTitle = cleanAiGeneratedName(artwork.title) || artwork.title || 'Untitled';

  // Create a mock product with artwork pre-filled - pass it to showProductForm
  const prefilled = {
    title: cleanedTitle,
    description: artwork.description || '',
    artworkId: artwork.id,
    status: 'draft'
  };

  // Pass the prefilled data directly to showProductForm
  showProductForm(prefilled);

  // Update the form title to indicate we're creating from artwork
  if (customArtElements.productFormTitle) customArtElements.productFormTitle.textContent = `Create Product from "${cleanedTitle}"`;

  // Hide delete button since this is a new product
  if (customArtElements.productDeleteBtn) customArtElements.productDeleteBtn.style.display = 'none';

  // Ensure artwork dropdown has the correct value (may need re-check after DOM updates)
  setTimeout(() => {
    const artworkSelect = document.getElementById('customArtProductArtwork');
    if (artworkSelect && artworkSelect.value !== String(artwork.id)) {
      artworkSelect.value = String(artwork.id);
      console.log('[Product] Set artwork dropdown to:', artwork.id, 'Current value:', artworkSelect.value);
    }
  }, 100);

  setCustomArtStatus(`Creating product from "${artwork.title}"`);
}

function showProductForm(prod = null) {
  customArtState.editingProduct = prod;
  customArtState.pendingVariants = prod?.variants || [];

  if (customArtElements.productFormCard) customArtElements.productFormCard.style.display = '';
  if (customArtElements.productFormTitle) customArtElements.productFormTitle.textContent = prod ? 'Edit Product' : 'Create Product';
  if (customArtElements.productDeleteBtn) customArtElements.productDeleteBtn.style.display = prod ? '' : 'none';

  if (customArtElements.productTitle) customArtElements.productTitle.value = prod?.title || '';
  if (customArtElements.productDesc) customArtElements.productDesc.value = prod?.description || '';

  // Set artwork dropdown with debugging
  const artworkDropdown = customArtElements.productArtwork || document.getElementById('customArtProductArtwork');
  if (artworkDropdown) {
    const artworkIdStr = prod?.artworkId ? String(prod.artworkId) : '';
    console.log('[showProductForm] Setting artwork dropdown:', artworkIdStr, 'Options count:', artworkDropdown.options?.length);
    artworkDropdown.value = artworkIdStr;
    console.log('[showProductForm] Artwork dropdown value after set:', artworkDropdown.value);
  } else {
    console.warn('[showProductForm] Artwork dropdown not found!');
  }

  if (customArtElements.productMaterial) customArtElements.productMaterial.value = prod?.materialId ? String(prod.materialId) : '';
  if (customArtElements.productWidth) customArtElements.productWidth.value = prod?.singleSize?.width || '';
  if (customArtElements.productHeight) customArtElements.productHeight.value = prod?.singleSize?.height || '';
  if (customArtElements.productUnit) customArtElements.productUnit.value = prod?.singleSize?.unit || 'inches';
  if (customArtElements.productPrice) customArtElements.productPrice.value = prod?.basePriceCents ? (prod.basePriceCents / 100).toFixed(2) : '';
  if (customArtElements.productCost) customArtElements.productCost.value = prod?.costCents ? (prod.costCents / 100).toFixed(2) : '';
  if (customArtElements.productStatus) customArtElements.productStatus.value = prod?.status || 'draft';
  if (customArtElements.productId) customArtElements.productId.value = prod?.id || '';

  // Set pricing type radio
  const pricingRadios = document.querySelectorAll('input[name="customArtPricingType"]');
  pricingRadios.forEach(r => r.checked = (r.value === (prod?.hasVariants ? 'variants' : 'single')));
  updateProductPricingType();
}

function hideProductForm() {
  customArtState.editingProduct = null;
  customArtState.pendingVariants = [];
  if (customArtElements.productFormCard) customArtElements.productFormCard.style.display = 'none';
}

function updateProductPricingType() {
  const pricingType = document.querySelector('input[name="customArtPricingType"]:checked')?.value || 'single';
  if (customArtElements.singlePieceFields) customArtElements.singlePieceFields.style.display = pricingType === 'single' ? '' : 'none';
  if (customArtElements.variantsSection) customArtElements.variantsSection.style.display = pricingType === 'variants' ? '' : 'none';

  // If showing variants section, render existing variants
  if (pricingType === 'variants') {
    renderCustomArtVariants();
  }
}

function renderCustomArtVariants() {
  if (!customArtElements.variantsBody) return;

  const variants = customArtState.pendingVariants || [];
  if (!variants.length) {
    customArtElements.variantsBody.innerHTML = '<tr><td colspan="5" class="placeholder">No variants. Click "+ Add Variant" to add one.</td></tr>';
    return;
  }

  customArtElements.variantsBody.innerHTML = variants.map((v, idx) => `
    <tr data-variant-index="${idx}">
      <td>
        <input type="number" class="variant-width" value="${v.size?.width || v.sizeWidth || ''}" style="width:50px;" placeholder="W" />
        x
        <input type="number" class="variant-height" value="${v.size?.height || v.sizeHeight || ''}" style="width:50px;" placeholder="H" />
        <select class="variant-unit" style="width:60px;">
          <option value="inches" ${(v.size?.unit || v.sizeUnit || 'inches') === 'inches' ? 'selected' : ''}>in</option>
          <option value="cm" ${(v.size?.unit || v.sizeUnit) === 'cm' ? 'selected' : ''}>cm</option>
        </select>
      </td>
      <td>
        <select class="variant-material" style="width:100px;">
          <option value="">--</option>
          ${customArtState.materials.map(m => `<option value="${m.id}" ${(v.materialId || '') === m.id ? 'selected' : ''}>${m.name}</option>`).join('')}
        </select>
      </td>
      <td><input type="number" class="variant-price" value="${((v.priceCents || 0) / 100).toFixed(2)}" step="0.01" style="width:70px;" /></td>
      <td><input type="number" class="variant-cost" value="${((v.costCents || 0) / 100).toFixed(2)}" step="0.01" style="width:70px;" /></td>
      <td><button type="button" class="danger variant-remove-btn" style="padding:4px 8px;">X</button></td>
    </tr>
  `).join('');

  // Add remove button handlers
  customArtElements.variantsBody.querySelectorAll('.variant-remove-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const row = e.target.closest('tr');
      const idx = parseInt(row.dataset.variantIndex, 10);
      customArtState.pendingVariants.splice(idx, 1);
      renderCustomArtVariants();
    });
  });

  // Add change handlers to update pendingVariants
  customArtElements.variantsBody.querySelectorAll('tr').forEach(row => {
    const idx = parseInt(row.dataset.variantIndex, 10);
    row.querySelector('.variant-width')?.addEventListener('change', (e) => {
      if (customArtState.pendingVariants[idx]) customArtState.pendingVariants[idx].sizeWidth = parseFloat(e.target.value) || 0;
    });
    row.querySelector('.variant-height')?.addEventListener('change', (e) => {
      if (customArtState.pendingVariants[idx]) customArtState.pendingVariants[idx].sizeHeight = parseFloat(e.target.value) || 0;
    });
    row.querySelector('.variant-unit')?.addEventListener('change', (e) => {
      if (customArtState.pendingVariants[idx]) customArtState.pendingVariants[idx].sizeUnit = e.target.value;
    });
    row.querySelector('.variant-material')?.addEventListener('change', (e) => {
      if (customArtState.pendingVariants[idx]) customArtState.pendingVariants[idx].materialId = e.target.value || null;
    });
    row.querySelector('.variant-price')?.addEventListener('change', (e) => {
      if (customArtState.pendingVariants[idx]) customArtState.pendingVariants[idx].priceCents = Math.round(parseFloat(e.target.value || 0) * 100);
    });
    row.querySelector('.variant-cost')?.addEventListener('change', (e) => {
      if (customArtState.pendingVariants[idx]) customArtState.pendingVariants[idx].costCents = Math.round(parseFloat(e.target.value || 0) * 100);
    });
  });
}

function addCustomArtVariant() {
  if (!customArtState.pendingVariants) customArtState.pendingVariants = [];
  customArtState.pendingVariants.push({
    sizeWidth: '',
    sizeHeight: '',
    sizeUnit: 'inches',
    materialId: null,
    priceCents: 0,
    costCents: 0
  });
  renderCustomArtVariants();
}

// --- MOCKUP ---
function initCustomArtMockup() {
  console.log('[Custom Art] initCustomArtMockup called');
  // Refresh elements
  initCustomArtElements();

  // Load the wall-art-mockup.html into the iframe
  const frame = customArtElements.mockupFrame;
  console.log('[Custom Art] mockupFrame element:', frame);
  console.log('[Custom Art] mockupFrame current src:', frame?.src);

  if (frame && (!frame.src || frame.src === '' || frame.src === window.location.href)) {
    // Load from server URL for packaged app compatibility and better CORS
    const serverUrl = state.config?.serverBaseUrl || 'https://blueridgecustomco.com';
    const mockupUrl = `${serverUrl}/web/wall-art-mockup.html`;
    console.log('[Custom Art] Setting mockupFrame src to:', mockupUrl);
    frame.src = mockupUrl;
  }

  // Populate dropdowns
  populateMockupDropdowns();
}

// Store full artwork list for filtering
let mockupArtworkFullList = [];

// Render artwork as visual grid for mockup generator
function renderMockupArtworkGrid(artworkList, isFiltered = false) {
  const grid = document.getElementById('customArtMockupArtworkGrid');
  const hiddenInput = document.getElementById('customArtMockupArtwork');
  if (!grid) return;

  // Store full list if not filtering
  if (!isFiltered) {
    mockupArtworkFullList = artworkList || [];
  }

  if (!artworkList || artworkList.length === 0) {
    grid.innerHTML = '<div class="placeholder" style="padding:20px;text-align:center;color:#888;">No artwork available</div>';
    return;
  }

  // Collect URLs for batch prefetch
  const previewUrls = [];

  grid.innerHTML = artworkList.map(art => {
    // Use thumbnailPath first, then optimizedPath, then filePath (API returns camelCase from db.js mapCustomArtArtwork)
    const serverUrl = resolveArtworkUrl(art.thumbnailPath || art.optimizedPath || art.filePath, { width: 200, quality: 80 });
    // Use cached URL if available
    const imageSrc = getCachedPreviewUrl(serverUrl);
    // Track for background prefetch (only for http URLs)
    if (serverUrl && serverUrl.startsWith('http') && !previewCacheMap.has(serverUrl)) {
      previewUrls.push(serverUrl);
    }

    return `
      <div class="artwork-card mockup-artwork-item" data-artwork-id="${art.id}" data-image="${art.filePath || art.imagePath || ''}" data-cache-url="${serverUrl}" style="cursor:pointer;border:2px solid transparent;border-radius:8px;overflow:hidden;background:#1e293b;">
        <div class="artwork-card-image">
          <img src="${imageSrc}" data-cache-url="${serverUrl}" alt="${art.title || 'Artwork'}" style="width:100%;height:100%;object-fit:cover;" onerror="this.src='data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><rect fill=%22%23334155%22 width=%22100%22 height=%22100%22/><text x=%2250%22 y=%2255%22 text-anchor=%22middle%22 fill=%22%2394a3b8%22 font-size=%2212%22>No Image</text></svg>'"/>
        </div>
        <div style="padding:6px;font-size:11px;color:#e2e8f0;text-align:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">
          ${art.title || 'Untitled'}
        </div>
      </div>
    `;
  }).join('');

  // Trigger batch prefetch for uncached URLs
  if (previewUrls.length > 0) {
    prefetchCatalogPreviews(previewUrls);
  }

  // Add click handlers for selection
  grid.querySelectorAll('.mockup-artwork-item').forEach(card => {
    card.addEventListener('click', () => {
      // Remove selection from all cards
      grid.querySelectorAll('.mockup-artwork-item').forEach(c => {
        c.style.borderColor = 'transparent';
        c.classList.remove('selected');
      });
      // Select this card
      card.style.borderColor = '#3b82f6';
      card.classList.add('selected');
      // Set hidden input value
      if (hiddenInput) {
        hiddenInput.value = card.dataset.artworkId;
      }
      // Also update customArtElements for compatibility
      if (customArtElements.mockupArtwork) {
        customArtElements.mockupArtwork.value = card.dataset.artworkId;
        customArtElements.mockupArtwork.dataset.image = card.dataset.image;
      }
    });
  });
}

// Filter mockup artwork grid by search term
function filterMockupArtworkGrid(searchTerm) {
  if (!searchTerm || searchTerm.trim() === '') {
    renderMockupArtworkGrid(mockupArtworkFullList, true);
    return;
  }
  const term = searchTerm.toLowerCase().trim();
  const filtered = mockupArtworkFullList.filter(art =>
    (art.title || '').toLowerCase().includes(term) ||
    (art.tags || '').toLowerCase().includes(term) ||
    (art.category || '').toLowerCase().includes(term)
  );
  renderMockupArtworkGrid(filtered, true);
}

// Wire up the artwork search input
function initMockupArtworkSearch() {
  const searchInput = document.getElementById('customArtMockupArtworkSearch');
  if (searchInput && !searchInput.dataset.initialized) {
    searchInput.dataset.initialized = 'true';
    let debounceTimer;
    searchInput.addEventListener('input', (e) => {
      clearTimeout(debounceTimer);
      debounceTimer = setTimeout(() => {
        filterMockupArtworkGrid(e.target.value);
      }, 200);
    });
  }
}

async function populateMockupDropdowns() {
  try {
    const [roomsResult, artworkResult, materialsResult] = await Promise.all([
      printStation.customArt.listRooms({ activeOnly: true, limit: 500 }),
      printStation.customArt.listArtwork({ activeOnly: true, limit: 1000 }),
      printStation.customArt.listMaterials({ activeOnly: true })
    ]);

    if (customArtElements.mockupRoom) {
      customArtElements.mockupRoom.innerHTML = '<option value="">Choose room background...</option>' +
        (roomsResult?.rooms || []).map(r => `<option value="${r.id}" data-image="${r.imagePath}">${r.title}</option>`).join('');
    }
    // Render artwork grid instead of dropdown
    renderMockupArtworkGrid(artworkResult?.artwork || []);
    // Initialize search input handler
    initMockupArtworkSearch();
    if (customArtElements.mockupMaterial) {
      customArtElements.mockupMaterial.innerHTML = '<option value="">Choose material...</option>' +
        (materialsResult?.materials || []).map(m => `<option value="${m.id}" data-filter="${m.filterType}">${m.name}</option>`).join('');
    }
  } catch (e) {
    console.error('Error loading mockup dropdowns:', e);
  }
}

// --- SAVED MOCKUPS ---
async function loadSavedMockups() {
  setCustomArtStatus('Loading saved mockups...');
  try {
    const mockups = await printStation.customArt.listMockups({ activeOnly: true });
    customArtState.savedMockups = mockups || [];
    renderSavedMockups();
    setCustomArtStatus(`${customArtState.savedMockups.length} mockup(s) loaded`);
  } catch (e) {
    setCustomArtStatus(`Error: ${e.message}`, true);
    console.error('[Saved Mockups] Error loading:', e);
  }
}

function renderSavedMockups() {
  const grid = document.getElementById('savedMockupsGrid');
  if (!grid) return;

  const searchTerm = (document.getElementById('savedMockupsSearch')?.value || '').toLowerCase().trim();
  const filter = document.getElementById('savedMockupsFilter')?.value || '';

  let filtered = customArtState.savedMockups;

  // Apply search filter
  if (searchTerm) {
    filtered = filtered.filter(m =>
      (m.title || '').toLowerCase().includes(searchTerm) ||
      (m.notes || '').toLowerCase().includes(searchTerm) ||
      (m.tags || '').toLowerCase().includes(searchTerm)
    );
  }

  // Apply dropdown filter
  if (filter === 'recent') {
    const sevenDaysAgo = new Date();
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
    filtered = filtered.filter(m => new Date(m.createdAt) > sevenDaysAgo);
  } else if (filter === 'with-product') {
    filtered = filtered.filter(m => m.productId);
  } else if (filter === 'orphaned') {
    filtered = filtered.filter(m => !m.productId);
  }

  if (filtered.length === 0) {
    grid.innerHTML = '<div class="placeholder">No mockups found</div>';
    return;
  }

  const serverBase = state.config?.serverBaseUrl || 'https://blueridgecustomco.com';

  grid.innerHTML = filtered.map(m => {
    const imgSrc = m.url || (m.filePath ? `${serverBase}/${m.filePath}` : '');
    const title = m.title || m.filename || 'Untitled';
    const date = m.createdAt ? new Date(m.createdAt).toLocaleDateString() : '';
    const sourceLabel = m.source === 'filesystem' ? '<span style="background:#666;padding:2px 6px;border-radius:3px;font-size:10px;">File</span>' : '';
    const sizeLabel = m.fileSize ? `<span style="color:#888;font-size:11px;">${(m.fileSize / 1024).toFixed(0)}KB</span>` : '';

    return `
      <div class="artwork-card" data-mockup-id="${m.id}" onclick="selectSavedMockup('${m.id}')">
        <div class="artwork-card-image">
          <img src="${imgSrc}" alt="${title}" loading="lazy" onerror="this.src='data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 width=%22100%22 height=%22100%22><rect fill=%22%23333%22 width=%22100%22 height=%22100%22/><text x=%2250%22 y=%2255%22 fill=%22%23666%22 text-anchor=%22middle%22>No Image</text></svg>'" />
        </div>
        <div class="artwork-card-info">
          <div class="artwork-card-title" style="display:flex;gap:6px;align-items:center;">${title.substring(0, 25)}${title.length > 25 ? '...' : ''} ${sourceLabel}</div>
          <div class="artwork-card-meta" style="display:flex;justify-content:space-between;">${date} ${sizeLabel}</div>
        </div>
      </div>
    `;
  }).join('');
}

function selectSavedMockup(id) {
  const mockup = customArtState.savedMockups.find(m => m.id === id);
  if (!mockup) return;

  customArtState.selectedMockup = mockup;
  const serverBase = state.config?.serverBaseUrl || 'https://blueridgecustomco.com';

  // Show detail card
  const detailCard = document.getElementById('savedMockupsDetailCard');
  if (detailCard) detailCard.style.display = 'block';

  // Populate detail fields
  const img = document.getElementById('savedMockupsDetailImage');
  if (img) img.src = mockup.url || (mockup.filePath ? `${serverBase}/${mockup.filePath}` : '');

  const titleInput = document.getElementById('savedMockupsDetailTitle');
  if (titleInput) titleInput.value = mockup.title || '';

  const notesInput = document.getElementById('savedMockupsDetailNotes');
  if (notesInput) notesInput.value = mockup.notes || '';

  const tagsInput = document.getElementById('savedMockupsDetailTags');
  if (tagsInput) tagsInput.value = mockup.tags || '';

  const idInput = document.getElementById('savedMockupsDetailId');
  if (idInput) idInput.value = mockup.id;

  // Show metadata
  document.getElementById('savedMockupsDetailSource').textContent = mockup.source === 'filesystem' ? 'File on disk' : 'Database';
  document.getElementById('savedMockupsDetailSize').textContent = mockup.fileSize ? `${(mockup.fileSize / 1024).toFixed(1)} KB` : '-';
  document.getElementById('savedMockupsDetailProduct').textContent = mockup.productId || '-';
  document.getElementById('savedMockupsDetailArtwork').textContent = mockup.artworkId || '-';
  document.getElementById('savedMockupsDetailRoom').textContent = mockup.roomId || '-';
  document.getElementById('savedMockupsDetailCreated').textContent = mockup.createdAt ? new Date(mockup.createdAt).toLocaleString() : '-';

  // Highlight selected card
  document.querySelectorAll('#savedMockupsGrid .artwork-card').forEach(card => {
    card.classList.toggle('selected', card.dataset.mockupId === id);
  });
}

async function saveMockupDetails() {
  const id = document.getElementById('savedMockupsDetailId')?.value;
  if (!id) return;

  const title = document.getElementById('savedMockupsDetailTitle')?.value || '';
  const notes = document.getElementById('savedMockupsDetailNotes')?.value || '';
  const tags = document.getElementById('savedMockupsDetailTags')?.value || '';

  setCustomArtStatus('Saving mockup...');
  try {
    await printStation.customArt.updateMockup(id, { title, notes, tags });
    setCustomArtStatus('Mockup saved!');
    await loadSavedMockups();
    // Re-select the mockup to refresh detail view
    selectSavedMockup(id);
  } catch (e) {
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

async function deleteSavedMockup(hard = false) {
  const id = document.getElementById('savedMockupsDetailId')?.value;
  if (!id) return;

  const confirmMsg = hard
    ? 'Permanently delete this mockup and its file? This cannot be undone.'
    : 'Delete this mockup?';

  if (!confirm(confirmMsg)) return;

  setCustomArtStatus('Deleting mockup...');
  try {
    await printStation.customArt.deleteMockup(id, hard);
    setCustomArtStatus('Mockup deleted');
    customArtState.selectedMockup = null;
    document.getElementById('savedMockupsDetailCard').style.display = 'none';
    await loadSavedMockups();
  } catch (e) {
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

function copyMockupUrl() {
  const mockup = customArtState.selectedMockup;
  if (!mockup) return;

  const serverBase = state.config?.serverBaseUrl || 'https://blueridgecustomco.com';
  const url = mockup.url || (mockup.filePath ? `${serverBase}/${mockup.filePath}` : '');

  navigator.clipboard.writeText(url).then(() => {
    setCustomArtStatus('URL copied to clipboard!');
  }).catch(() => {
    setCustomArtStatus('Failed to copy URL', true);
  });
}

function openMockupInBrowser() {
  const mockup = customArtState.selectedMockup;
  if (!mockup) return;

  const serverBase = state.config?.serverBaseUrl || 'https://blueridgecustomco.com';
  const url = mockup.url || (mockup.filePath ? `${serverBase}/${mockup.filePath}` : '');

  if (url) {
    window.open(url, '_blank');
  }
}

function initSavedMockupsEventListeners() {
  // Search
  document.getElementById('savedMockupsSearch')?.addEventListener('input', renderSavedMockups);

  // Filter dropdown
  document.getElementById('savedMockupsFilter')?.addEventListener('change', renderSavedMockups);

  // Refresh button
  document.getElementById('savedMockupsRefreshBtn')?.addEventListener('click', loadSavedMockups);

  // Close detail card
  document.getElementById('savedMockupsCloseDetailBtn')?.addEventListener('click', () => {
    document.getElementById('savedMockupsDetailCard').style.display = 'none';
    customArtState.selectedMockup = null;
  });

  // Save button
  document.getElementById('savedMockupsDetailSaveBtn')?.addEventListener('click', saveMockupDetails);

  // Delete button
  document.getElementById('savedMockupsDetailDeleteBtn')?.addEventListener('click', () => deleteSavedMockup(true));

  // Copy URL button
  document.getElementById('savedMockupsDetailCopyUrlBtn')?.addEventListener('click', copyMockupUrl);

  // Open in browser button
  document.getElementById('savedMockupsDetailOpenBtn')?.addEventListener('click', openMockupInBrowser);
}

// Expose functions globally
window.selectSavedMockup = selectSavedMockup;

// --- ROOM PICKER MODAL ---
const roomPickerState = {
  rooms: [],
  callback: null,
  targetInput: null,
  targetBtn: null,
  targetPreview: null,
  targetThumb: null
};

const roomPickerElements = {
  modal: null,
  closeBtn: null,
  search: null,
  category: null,
  count: null,
  grid: null
};

function initRoomPickerElements() {
  roomPickerElements.modal = document.getElementById('roomPickerModal');
  roomPickerElements.closeBtn = document.getElementById('roomPickerCloseBtn');
  roomPickerElements.search = document.getElementById('roomPickerSearch');
  roomPickerElements.category = document.getElementById('roomPickerCategory');
  roomPickerElements.count = document.getElementById('roomPickerCount');
  roomPickerElements.grid = document.getElementById('roomPickerGrid');
}

async function openRoomPicker(options = {}) {
  console.log('[Room Picker] openRoomPicker called');
  initRoomPickerElements();

  const { onSelect, inputEl, btnEl, previewEl, thumbEl } = options;
  roomPickerState.callback = onSelect;
  roomPickerState.targetInput = inputEl;
  roomPickerState.targetBtn = btnEl;
  roomPickerState.targetPreview = previewEl;
  roomPickerState.targetThumb = thumbEl;

  // Load rooms
  try {
    const result = await printStation.customArt.listRooms({ activeOnly: true, limit: 500 });
    roomPickerState.rooms = result?.rooms || [];
    console.log('[Room Picker] Loaded rooms:', roomPickerState.rooms.length);
  } catch (e) {
    console.error('Error loading rooms for picker:', e);
    roomPickerState.rooms = [];
  }

  // Populate category filter from actual room data
  if (roomPickerElements.category) {
    const roomTypeLabelsLocal = {
      'living-room': 'Living Room', 'bedroom': 'Bedroom', 'office': 'Office',
      'dining-room': 'Dining Room', 'hallway': 'Hallway', 'bathroom': 'Bathroom',
      'kitchen': 'Kitchen', 'garage': 'Garage', 'art-studio': 'Art Studio',
      'front-porch': 'Front Porch', 'staircase': 'Staircase', 'workbench': 'Workbench',
      'other': 'Other'
    };
    const types = [...new Set(roomPickerState.rooms.map(r => r.roomType).filter(Boolean))].sort();
    roomPickerElements.category.innerHTML = '<option value="">All Categories</option>' +
      types.map(t => `<option value="${t}">${roomTypeLabelsLocal[t] || t}</option>`).join('');
  }

  // Reset filters
  if (roomPickerElements.search) roomPickerElements.search.value = '';
  if (roomPickerElements.category) roomPickerElements.category.value = '';

  renderRoomPickerGrid();

  if (roomPickerElements.modal) {
    // Remove hidden attribute and clear any blocking styles
    roomPickerElements.modal.removeAttribute('hidden');
    roomPickerElements.modal.style.display = 'block';
    roomPickerElements.modal.style.pointerEvents = 'auto';
    roomPickerElements.modal.style.visibility = 'visible';
    console.log('[Room Picker] Modal should now be visible');
  } else {
    console.error('[Room Picker] Modal element not found!');
  }
}

function closeRoomPicker() {
  if (roomPickerElements.modal) {
    roomPickerElements.modal.style.display = 'none';
    roomPickerElements.modal.style.pointerEvents = 'none';
  }
  roomPickerState.callback = null;
}

function renderRoomPickerGrid() {
  if (!roomPickerElements.grid) return;

  const searchTerm = (roomPickerElements.search?.value || '').toLowerCase().trim();
  const categoryFilter = roomPickerElements.category?.value || '';

  let filtered = roomPickerState.rooms;

  if (searchTerm) {
    filtered = filtered.filter(r =>
      (r.title || '').toLowerCase().includes(searchTerm) ||
      (r.description || '').toLowerCase().includes(searchTerm) ||
      (r.tags || '').toLowerCase().includes(searchTerm)
    );
  }

  if (categoryFilter) {
    filtered = filtered.filter(r => r.roomType === categoryFilter);
  }

  if (roomPickerElements.count) {
    roomPickerElements.count.textContent = `${filtered.length} room${filtered.length !== 1 ? 's' : ''}`;
  }

  if (!filtered.length) {
    roomPickerElements.grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;color:#888;padding:40px;">No rooms found</div>';
    return;
  }

  const roomTypeLabels = {
    'living-room': 'Living Room',
    'bedroom': 'Bedroom',
    'office': 'Office',
    'dining-room': 'Dining Room',
    'hallway': 'Hallway',
    'bathroom': 'Bathroom',
    'kitchen': 'Kitchen',
    'garage': 'Garage',
    'art-studio': 'Art Studio',
    'front-porch': 'Front Porch',
    'staircase': 'Staircase',
    'workbench': 'Workbench',
    'other': 'Other'
  };

  roomPickerElements.grid.innerHTML = filtered.map(room => {
    const imageUrl = room.thumbnailPath || room.imagePath || '';
    // Convert relative paths to full server URLs
    const fullImageUrl = imageUrl.startsWith('http') ? imageUrl : resolveAssetUrl(imageUrl, { width: 400, quality: 80 });
    const typeLabel = roomTypeLabels[room.roomType] || room.roomType || 'Unknown';

    return `
      <div class="room-picker-card" data-room-id="${room.id}" data-image="${room.imagePath || ''}" style="cursor:pointer;background:#2a2a3e;border-radius:10px;overflow:visible;transition:transform 0.15s, box-shadow 0.15s;border:2px solid transparent;">
        <div style="width:100%;height:240px;min-height:240px;background:#1a1a2e;">
          ${fullImageUrl ? `<img src="${fullImageUrl}" style="width:100%;height:240px;object-fit:cover;display:block;" loading="lazy" onerror="this.outerHTML='<div style=\\'width:100%;height:240px;display:flex;align-items:center;justify-content:center;color:#666;\\'>No image</div>'" />` : '<div style="width:100%;height:240px;display:flex;align-items:center;justify-content:center;color:#666;">No image</div>'}
        </div>
        <div style="padding:14px;">
          <div style="font-weight:600;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${room.title || 'Untitled'}</div>
          <div style="font-size:12px;color:#888;margin-top:4px;">${typeLabel}</div>
        </div>
      </div>
    `;
  }).join('');
}

function selectRoomFromPicker(roomId, imagePath) {
  const room = roomPickerState.rooms.find(r => String(r.id) === String(roomId));
  if (!room) return;

  // Update the target input
  if (roomPickerState.targetInput) {
    roomPickerState.targetInput.value = roomId;
  }

  // Update the button text
  if (roomPickerState.targetBtn) {
    roomPickerState.targetBtn.textContent = room.title || 'Selected Room';
  }

  // Show thumbnail preview
  if (roomPickerState.targetPreview && roomPickerState.targetThumb) {
    const imageUrl = room.thumbnailPath || room.imagePath || '';
    // Convert relative paths to full server URLs
    const fullImageUrl = imageUrl.startsWith('http') ? imageUrl : resolveAssetUrl(imageUrl);
    if (fullImageUrl) {
      roomPickerState.targetThumb.src = fullImageUrl;
      roomPickerState.targetPreview.style.display = 'block';
    }
  }

  // Call the callback if provided
  if (typeof roomPickerState.callback === 'function') {
    roomPickerState.callback(room);
  }

  closeRoomPicker();
}

function initRoomPickerEventListeners() {
  initRoomPickerElements();

  // Close button
  if (roomPickerElements.closeBtn) {
    roomPickerElements.closeBtn.addEventListener('click', closeRoomPicker);
  }

  // Click outside to close
  if (roomPickerElements.modal) {
    roomPickerElements.modal.addEventListener('click', (e) => {
      if (e.target === roomPickerElements.modal) {
        closeRoomPicker();
      }
    });
  }

  // Search and filter
  if (roomPickerElements.search) {
    roomPickerElements.search.addEventListener('input', renderRoomPickerGrid);
  }
  if (roomPickerElements.category) {
    roomPickerElements.category.addEventListener('change', renderRoomPickerGrid);
  }

  // Grid click delegation
  if (roomPickerElements.grid) {
    roomPickerElements.grid.addEventListener('click', (e) => {
      const card = e.target.closest('.room-picker-card');
      if (card) {
        const roomId = card.dataset.roomId;
        const imagePath = card.dataset.image;
        selectRoomFromPicker(roomId, imagePath);
      }
    });
  }

  // Mockup room picker button
  const mockupRoomPickerBtn = document.getElementById('customArtMockupRoomPickerBtn');
  if (mockupRoomPickerBtn) {
    mockupRoomPickerBtn.addEventListener('click', () => {
      openRoomPicker({
        inputEl: document.getElementById('customArtMockupRoom'),
        btnEl: mockupRoomPickerBtn,
        previewEl: document.getElementById('customArtMockupRoomPreview'),
        thumbEl: document.getElementById('customArtMockupRoomThumb')
      });
    });
  }

  // Tiled product room picker button
  const tiledRoomPickerBtn = document.getElementById('tiledProductRoomPickerBtn');
  if (tiledRoomPickerBtn) {
    tiledRoomPickerBtn.addEventListener('click', () => {
      openRoomPicker({
        inputEl: document.getElementById('tiledProductRoom'),
        btnEl: tiledRoomPickerBtn,
        previewEl: document.getElementById('tiledProductRoomPreview'),
        thumbEl: document.getElementById('tiledProductRoomThumb')
      });
    });
  }
}

// Wire up Custom Art event listeners (called lazily when Custom Art view is opened)
let customArtInitialized = false;
function initCustomArtEventListeners() {
  if (customArtInitialized) return;
  customArtInitialized = true;

  console.log('[Custom Art] Initializing event listeners...');

  // Initialize room picker modal event listeners
  initRoomPickerEventListeners();

  // NOTE: Sub-tab switching is handled via event delegation in switchView()
  // Do NOT add tab click listeners here to avoid duplicate calls

  // Rooms
  const addRoomBtn = document.getElementById('customArtAddRoomBtn');
  const bulkUploadRoomsBtn = document.getElementById('customArtBulkUploadRoomsBtn');
  const roomSaveBtn = document.getElementById('customArtRoomSaveBtn');
  const roomCancelBtn = document.getElementById('customArtRoomCancelBtn');
  const roomDeleteBtn = document.getElementById('customArtRoomDeleteBtn');
  const roomSelectImage = document.getElementById('customArtRoomSelectImage');

  if (addRoomBtn) addRoomBtn.addEventListener('click', () => showRoomForm());
  if (bulkUploadRoomsBtn) bulkUploadRoomsBtn.addEventListener('click', bulkUploadRooms);
  if (roomSaveBtn) roomSaveBtn.addEventListener('click', saveRoom);
  if (roomCancelBtn) roomCancelBtn.addEventListener('click', hideRoomForm);
  if (roomDeleteBtn) roomDeleteBtn.addEventListener('click', deleteRoom);
  if (roomSelectImage) roomSelectImage.addEventListener('click', selectRoomImage);

  // Artwork
  const artworkSearch = document.getElementById('customArtArtworkSearch');
  const artworkCategoryFilter = document.getElementById('customArtArtworkCategoryFilter');
  const artworkGrid = document.getElementById('customArtArtworkGrid');
  const addArtworkBtn = document.getElementById('customArtAddArtworkBtn');
  const artworkSaveBtn = document.getElementById('customArtArtworkSaveBtn');
  const artworkCancelBtn = document.getElementById('customArtArtworkCancelBtn');
  const artworkDeleteBtn = document.getElementById('customArtArtworkDeleteBtn');
  const artworkSelectImage = document.getElementById('customArtArtworkSelectImage');
  const bulkUploadBtn = document.getElementById('customArtBulkUploadBtn');

  if (artworkSearch) artworkSearch.addEventListener('input', renderCustomArtArtwork);
  if (artworkCategoryFilter) artworkCategoryFilter.addEventListener('change', renderCustomArtArtwork);
  if (artworkGrid) {
    // Handle all clicks on artwork grid via delegation
    artworkGrid.addEventListener('click', (e) => {
      // Handle Edit button clicks
      const editBtn = e.target.closest('.artwork-edit-btn');
      if (editBtn) {
        e.stopPropagation();
        const artworkId = editBtn.dataset.artworkId;
        const art = customArtState.artwork.find(a => String(a.id) === artworkId);
        if (art) showArtworkForm(art);
        return;
      }

      // Handle Create Product button clicks
      const productBtn = e.target.closest('.artwork-create-product-btn');
      if (productBtn) {
        e.stopPropagation();
        const artworkId = productBtn.dataset.artworkId;
        createProductFromArtwork(artworkId);
        return;
      }

      // Handle Print button clicks
      const printBtn = e.target.closest('.artwork-print-btn');
      if (printBtn) {
        e.stopPropagation();
        const artworkId = printBtn.dataset.artworkId;
        const artworkPath = printBtn.dataset.artworkPath;
        printArtworkFromCard(artworkId, artworkPath);
        return;
      }

      // Handle Download button clicks
      const downloadBtn = e.target.closest('.artwork-download-btn');
      if (downloadBtn) {
        e.stopPropagation();
        const artworkId = downloadBtn.dataset.artworkId;
        const artworkPath = downloadBtn.dataset.artworkPath;
        const artworkTitle = downloadBtn.dataset.artworkTitle;
        downloadArtworkFromCard(artworkId, artworkPath, artworkTitle);
        return;
      }

      // Handle card clicks to toggle selection
      const card = e.target.closest('.custom-art-card[data-artwork-id]');
      if (card) {
        const artworkId = card.dataset.artworkId;
        if (customArtState.selectedArtworkIds.has(artworkId)) {
          customArtState.selectedArtworkIds.delete(artworkId);
        } else {
          customArtState.selectedArtworkIds.add(artworkId);
        }
        renderCustomArtArtwork();
      }
    });
  }
  if (addArtworkBtn) addArtworkBtn.addEventListener('click', () => showArtworkForm());
  if (artworkSaveBtn) artworkSaveBtn.addEventListener('click', saveArtwork);
  if (artworkCancelBtn) artworkCancelBtn.addEventListener('click', hideArtworkForm);
  if (artworkDeleteBtn) artworkDeleteBtn.addEventListener('click', deleteArtwork);
  if (artworkSelectImage) artworkSelectImage.addEventListener('click', selectArtworkImage);
  if (bulkUploadBtn) bulkUploadBtn.addEventListener('click', openArtworkBulkUploadModal);

  // Artwork Bulk Upload Modal handlers
  const bulkUploadModal = document.getElementById('artworkBulkUploadModal');
  const bulkUploadClose = document.getElementById('artworkBulkUploadClose');
  const bulkUploadCancelBtn = document.getElementById('artworkBulkUploadCancelBtn');
  const bulkUploadContinueBtn = document.getElementById('artworkBulkUploadContinueBtn');

  if (bulkUploadClose) bulkUploadClose.addEventListener('click', closeArtworkBulkUploadModal);
  if (bulkUploadCancelBtn) bulkUploadCancelBtn.addEventListener('click', closeArtworkBulkUploadModal);
  if (bulkUploadContinueBtn) bulkUploadContinueBtn.addEventListener('click', bulkUploadArtwork);
  if (bulkUploadModal) {
    bulkUploadModal.addEventListener('click', (e) => {
      if (e.target?.getAttribute?.('data-bulk-upload-close') === 'true') closeArtworkBulkUploadModal();
    });
  }

  // Select All button
  const selectAllBtn = document.getElementById('customArtSelectAllBtn');
  if (selectAllBtn) {
    selectAllBtn.addEventListener('click', () => {
      // Toggle: if all selected, deselect all; otherwise select all
      const allSelected = customArtState.artwork.length > 0 &&
                          customArtState.selectedArtworkIds.size === customArtState.artwork.length;
      if (allSelected) {
        customArtState.selectedArtworkIds.clear();
        selectAllBtn.textContent = 'Select All';
      } else {
        customArtState.artwork.forEach(a => customArtState.selectedArtworkIds.add(String(a.id)));
        selectAllBtn.textContent = 'Deselect All';
      }
      renderCustomArtArtwork();
    });
  }

  // Materials
  const addMaterialBtn = document.getElementById('customArtAddMaterialBtn');
  const materialSaveBtn = document.getElementById('customArtMaterialSaveBtn');
  const materialCancelBtn = document.getElementById('customArtMaterialCancelBtn');
  const materialDeleteBtn = document.getElementById('customArtMaterialDeleteBtn');

  if (addMaterialBtn) addMaterialBtn.addEventListener('click', () => showMaterialForm());
  if (materialSaveBtn) materialSaveBtn.addEventListener('click', saveMaterial);
  if (materialCancelBtn) materialCancelBtn.addEventListener('click', hideMaterialForm);
  if (materialDeleteBtn) materialDeleteBtn.addEventListener('click', deleteMaterial);

  // Products
  const addProductBtn = document.getElementById('customArtAddProductBtn');
  const productSaveBtn = document.getElementById('customArtProductSaveBtn');
  const productCancelBtn = document.getElementById('customArtProductCancelBtn');
  const productDeleteBtn = document.getElementById('customArtProductDeleteBtn');

  if (addProductBtn) addProductBtn.addEventListener('click', () => {
    populateProductDropdowns();
    showProductForm();
  });
  if (productSaveBtn) productSaveBtn.addEventListener('click', saveProduct);
  if (productCancelBtn) productCancelBtn.addEventListener('click', hideProductForm);
  if (productDeleteBtn) productDeleteBtn.addEventListener('click', deleteProduct);

  // Pricing type toggle
  document.querySelectorAll('input[name="customArtPricingType"]').forEach(r => {
    r.addEventListener('change', updateProductPricingType);
  });

  // Add Variant button
  const addVariantBtn = document.getElementById('customArtAddVariantBtn');
  if (addVariantBtn) addVariantBtn.addEventListener('click', addCustomArtVariant);

  // Mockup controls
  const mockupApplyBtn = document.getElementById('customArtMockupApplyBtn');
  const mockupSaveBtn = document.getElementById('customArtMockupSaveBtn');
  const mockupSaveImageBtn = document.getElementById('customArtSaveMockupBtn'); // "Save Mockup Image" button in Quick Actions
  const mockupModalClose = document.getElementById('customArtMockupModalClose');
  const createProductFromMockupBtn = document.getElementById('customArtCreateProductFromMockupBtn');
  const mockupFbAdsBtn = document.getElementById('customArtMockupFbAdsBtn');
  const mockupMarketplaceBtn = document.getElementById('customArtMockupMarketplaceBtn');
  const exportShopifyBtn = document.getElementById('customArtExportShopifyBtn');

  if (mockupApplyBtn) mockupApplyBtn.addEventListener('click', () => { console.log('[Button Debug] mockupApplyBtn clicked'); applyMockupSettings(); });
  if (mockupSaveBtn) mockupSaveBtn.addEventListener('click', () => { console.log('[Button Debug] mockupSaveBtn (Save Mockup in header) clicked'); saveMockupToProduct(); });
  if (mockupSaveImageBtn) mockupSaveImageBtn.addEventListener('click', () => { console.log('[Button Debug] mockupSaveImageBtn (Quick Actions) clicked'); saveQuickMockup(); });
  if (mockupModalClose) mockupModalClose.addEventListener('click', () => { console.log('[Button Debug] mockupModalClose (X Close) clicked'); closeMockupModal(); });
  if (createProductFromMockupBtn) createProductFromMockupBtn.addEventListener('click', createProductFromMockup);
  if (mockupFbAdsBtn) mockupFbAdsBtn.addEventListener('click', generateFbAdsFromMockup);
  if (mockupMarketplaceBtn) mockupMarketplaceBtn.addEventListener('click', postToMarketplace);
  if (exportShopifyBtn) exportShopifyBtn.addEventListener('click', exportCustomArtToShopify);

  // Campaign mockup checkbox handler
  const campaignMockupCheckbox = document.getElementById('customArtCampaignMockupCheckbox');
  const campaignMockupOptions = document.getElementById('customArtCampaignMockupOptions');
  const campaignMockupSelect = document.getElementById('customArtCampaignMockupSelect');

  if (campaignMockupCheckbox) {
    campaignMockupCheckbox.addEventListener('change', async () => {
      if (campaignMockupCheckbox.checked) {
        campaignMockupOptions.style.display = 'block';
        // Populate campaigns dropdown
        await populateCampaignMockupDropdown();
      } else {
        campaignMockupOptions.style.display = 'none';
      }
    });
  }

  // Tiled product modal
  initTiledProductModal();

  // Initialize bulk action handlers for artwork selection
  initArtworkBulkActions();

  // Initialize bulk action handlers for room selection
  initRoomBulkActions();

  console.log('[Custom Art] Event listeners initialized');
}

async function saveProduct() {
  const title = customArtElements.productTitle?.value?.trim();
  if (!title) {
    setCustomArtStatus('Title is required', true);
    return;
  }

  const pricingType = document.querySelector('input[name="customArtPricingType"]:checked')?.value || 'single';

  const payload = {
    title,
    description: customArtElements.productDesc?.value || null,
    artworkId: customArtElements.productArtwork?.value || null,
    hasVariants: pricingType === 'variants',
    status: customArtElements.productStatus?.value || 'draft'
  };

  if (pricingType === 'single') {
    payload.materialId = customArtElements.productMaterial?.value || null;
    payload.singleSizeWidth = parseFloat(customArtElements.productWidth?.value) || null;
    payload.singleSizeHeight = parseFloat(customArtElements.productHeight?.value) || null;
    payload.sizeUnit = customArtElements.productUnit?.value || 'inches';
    payload.basePriceCents = Math.round(parseFloat(customArtElements.productPrice?.value || 0) * 100);
    payload.costCents = Math.round(parseFloat(customArtElements.productCost?.value || 0) * 100);
  } else {
    // Include variants
    payload.variants = (customArtState.pendingVariants || []).map(v => ({
      sizeWidth: parseFloat(v.sizeWidth) || 0,
      sizeHeight: parseFloat(v.sizeHeight) || 0,
      sizeUnit: v.sizeUnit || 'inches',
      materialId: v.materialId || null,
      priceCents: v.priceCents || 0,
      costCents: v.costCents || 0
    }));
  }

  setCustomArtStatus('Saving product...');
  try {
    let productId;
    // Only update if we have an actual product ID (not just prefilled data)
    if (customArtState.editingProduct?.id) {
      await printStation.customArt.updateProduct(customArtState.editingProduct.id, payload);
      productId = customArtState.editingProduct.id;
    } else {
      const result = await printStation.customArt.createProduct(payload);
      productId = result?.product?.id;
    }

    // If we have variants, save them
    if (pricingType === 'variants' && productId && payload.variants?.length) {
      // Delete existing variants first (if editing)
      if (customArtState.editingProduct) {
        const existingVariants = await printStation.customArt.listVariants(productId);
        for (const v of (existingVariants?.variants || [])) {
          await printStation.customArt.deleteVariant(v.id);
        }
      }
      // Create new variants
      for (const v of payload.variants) {
        await printStation.customArt.createVariant(productId, v);
      }
    }

    hideProductForm();
    await loadCustomArtProducts();
    setCustomArtStatus('Product saved');
  } catch (e) {
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

async function deleteProduct() {
  if (!customArtState.editingProduct) return;
  if (!await nativeConfirm(`Delete product "${customArtState.editingProduct.title}"?`, 'Delete Product')) return;

  try {
    await printStation.customArt.deleteProduct(customArtState.editingProduct.id);
    hideProductForm();
    await loadCustomArtProducts();
    setCustomArtStatus('Product deleted');
  } catch (e) {
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

// --- ARTWORK FORM ---
function showArtworkForm(art = null) {
  customArtState.editingArtwork = art;
  if (customArtElements.artworkFormCard) customArtElements.artworkFormCard.style.display = '';
  if (customArtElements.artworkFormTitle) customArtElements.artworkFormTitle.textContent = art ? 'Edit Artwork' : 'Add Artwork';
  if (customArtElements.artworkDeleteBtn) customArtElements.artworkDeleteBtn.style.display = art ? '' : 'none';

  if (customArtElements.artworkTitle) customArtElements.artworkTitle.value = cleanAiGeneratedName(art?.title) || art?.title || '';
  if (customArtElements.artworkDesc) customArtElements.artworkDesc.value = art?.description || '';
  if (customArtElements.artworkTags) customArtElements.artworkTags.value = art?.tags || '';
  if (customArtElements.artworkCategory) customArtElements.artworkCategory.value = art?.category || '';
  if (customArtElements.artworkStyle) customArtElements.artworkStyle.value = art?.style || '';
  if (customArtElements.artworkWidth) customArtElements.artworkWidth.value = art?.dimensions?.width || '';
  if (customArtElements.artworkHeight) customArtElements.artworkHeight.value = art?.dimensions?.height || '';
  if (customArtElements.artworkUnit) customArtElements.artworkUnit.value = art?.dimensions?.unit || 'inches';
  if (customArtElements.artworkStatus) customArtElements.artworkStatus.value = art?.status || 'draft';
  if (customArtElements.artworkId) customArtElements.artworkId.value = art?.id || '';
  if (customArtElements.artworkFilePath) customArtElements.artworkFilePath.value = art?.filePath || '';
  if (customArtElements.artworkImageName) customArtElements.artworkImageName.textContent = art?.filePath ? 'Image selected' : 'No image selected';
  if (customArtElements.artworkImagePreview) {
    if (art?.filePath || art?.thumbnailPath) {
      customArtElements.artworkImagePreview.src = resolveArtworkUrl(art.thumbnailPath || art.filePath);
      customArtElements.artworkImagePreview.style.display = '';
    } else {
      customArtElements.artworkImagePreview.style.display = 'none';
    }
  }
}

function hideArtworkForm() {
  customArtState.editingArtwork = null;
  if (customArtElements.artworkFormCard) customArtElements.artworkFormCard.style.display = 'none';
}

async function selectArtworkImage() {
  const result = await printStation.customArt.selectFile({ title: 'Select Artwork Image' });
  if (result.canceled) return;

  setCustomArtStatus('Uploading artwork...');
  try {
    const uploadResult = await printStation.customArt.uploadFile(result.filePath, 'artwork');
    if (!uploadResult.success) throw new Error(uploadResult.error);

    if (customArtElements.artworkFilePath) customArtElements.artworkFilePath.value = uploadResult.filePath;
    if (customArtElements.artworkImageName) customArtElements.artworkImageName.textContent = uploadResult.filename;
    if (customArtElements.artworkImagePreview) {
      customArtElements.artworkImagePreview.src = uploadResult.filePath;
      customArtElements.artworkImagePreview.style.display = '';
    }
    setCustomArtStatus('Artwork uploaded');
  } catch (e) {
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

async function saveArtwork() {
  const title = customArtElements.artworkTitle?.value?.trim();
  const filePath = customArtElements.artworkFilePath?.value;

  if (!title) {
    setCustomArtStatus('Title is required', true);
    return;
  }
  if (!filePath && !customArtState.editingArtwork) {
    setCustomArtStatus('Please select an image', true);
    return;
  }

  const payload = {
    title,
    description: customArtElements.artworkDesc?.value || null,
    tags: customArtElements.artworkTags?.value || null,
    category: customArtElements.artworkCategory?.value || null,
    style: customArtElements.artworkStyle?.value || null,
    dimensionsWidth: parseFloat(customArtElements.artworkWidth?.value) || null,
    dimensionsHeight: parseFloat(customArtElements.artworkHeight?.value) || null,
    dimensionsUnit: customArtElements.artworkUnit?.value || 'inches',
    status: customArtElements.artworkStatus?.value || 'draft'
  };

  if (filePath) {
    payload.filePath = filePath;
  }

  setCustomArtStatus('Saving artwork...');
  try {
    if (customArtState.editingArtwork) {
      await printStation.customArt.updateArtwork(customArtState.editingArtwork.id, payload);
    } else {
      await printStation.customArt.createArtwork(payload);
    }
    hideArtworkForm();
    await loadCustomArtArtwork();
    setCustomArtStatus('Artwork saved successfully');
  } catch (e) {
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

async function deleteArtwork() {
  if (!customArtState.editingArtwork) return;
  if (!await nativeConfirm(`Delete artwork "${customArtState.editingArtwork.title}"?`, 'Delete Artwork')) return;

  setCustomArtStatus('Deleting artwork...');
  try {
    await printStation.customArt.deleteArtwork(customArtState.editingArtwork.id);
    hideArtworkForm();
    await loadCustomArtArtwork();
    setCustomArtStatus('Artwork deleted');
  } catch (e) {
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

// Bulk upload state
let bulkUploadCategory = '';
let bulkUploadStatus = 'draft';

function openArtworkBulkUploadModal() {
  const modal = document.getElementById('artworkBulkUploadModal');
  if (!modal) return;

  // Populate category dropdown with existing categories
  const categorySelect = document.getElementById('artworkBulkUploadCategorySelect');
  if (categorySelect) {
    categorySelect.innerHTML = '<option value="">No category (leave blank)</option>' +
      customArtState.categories.map(c => `<option value="${c}">${c}</option>`).join('');
  }

  // Clear the new category input
  const newCategoryInput = document.getElementById('artworkBulkUploadNewCategory');
  if (newCategoryInput) newCategoryInput.value = '';

  // Reset status to draft
  const statusSelect = document.getElementById('artworkBulkUploadStatus');
  if (statusSelect) statusSelect.value = 'draft';

  openModal(modal);
}

function closeArtworkBulkUploadModal() {
  const modal = document.getElementById('artworkBulkUploadModal');
  if (modal) closeModal(modal);
}

async function bulkUploadArtwork() {
  // Get category from modal inputs
  const categorySelect = document.getElementById('artworkBulkUploadCategorySelect');
  const newCategoryInput = document.getElementById('artworkBulkUploadNewCategory');
  const statusSelect = document.getElementById('artworkBulkUploadStatus');

  // New category input takes precedence over dropdown
  const category = newCategoryInput?.value?.trim() || categorySelect?.value || '';
  const status = statusSelect?.value || 'draft';

  closeArtworkBulkUploadModal();

  const result = await printStation.customArt.selectFiles({ title: 'Select Artwork Images or ZIP File' });
  if (result.canceled || !result.filePaths?.length) return;

  // Collect all image paths (extracting from ZIPs if necessary)
  let allImagePaths = [];
  let zipCount = 0;
  const tempDirs = [];

  setCustomArtStatus('Processing selected files...');

  for (const filePath of result.filePaths) {
    const ext = filePath.toLowerCase().split('.').pop();

    if (ext === 'zip') {
      // Extract ZIP file
      setCustomArtStatus(`Extracting ZIP file...`);
      const extractResult = await printStation.customArt.extractZip(filePath);
      if (extractResult.success && extractResult.filePaths?.length) {
        allImagePaths.push(...extractResult.filePaths);
        if (extractResult.tempDir) tempDirs.push(extractResult.tempDir);
        zipCount++;
        console.log(`Extracted ${extractResult.filePaths.length} images from ZIP`);
      } else {
        console.error('ZIP extraction failed:', extractResult.error);
        setCustomArtStatus(`Error extracting ZIP: ${extractResult.error}`, true);
      }
    } else {
      // Regular image file
      allImagePaths.push(filePath);
    }
  }

  if (!allImagePaths.length) {
    setCustomArtStatus('No images found to upload', true);
    return;
  }

  const totalCount = allImagePaths.length;
  const categoryLabel = category ? ` to "${category}"` : '';
  setCustomArtStatus(`Uploading ${totalCount} artwork file${totalCount > 1 ? 's' : ''}${categoryLabel}${zipCount ? ` (from ${zipCount} ZIP${zipCount > 1 ? 's' : ''})` : ''}...`);

  let successCount = 0;
  let errorCount = 0;

  for (const filePath of allImagePaths) {
    try {
      const uploadResult = await printStation.customArt.uploadFile(filePath, 'artwork');
      if (!uploadResult.success) throw new Error(uploadResult.error);

      // Extract filename and clean AI-generated tags for searchable title
      const filename = filePath.split(/[\\/]/).pop();
      const title = cleanAiGeneratedName(filename);

      await printStation.customArt.createArtwork({
        title,
        filePath: uploadResult.filePath,
        category: category || null,
        status: status
      });
      successCount++;
      setCustomArtStatus(`Uploaded ${successCount}/${totalCount}...`);
    } catch (e) {
      console.error('Bulk upload error:', e);
      errorCount++;
    }
  }

  // Clean up temp directories from ZIP extraction
  for (const dir of tempDirs) {
    try { await printStation.cleanupTempDir(dir); } catch (_) {}
  }

  await loadCustomArtArtwork();
  setCustomArtStatus(`Bulk upload complete: ${successCount} uploaded, ${errorCount} failed`);
}

// --- MOCKUP IFRAME COMMUNICATION ---
// Track previously focused element for focus restoration
let mockupModalPreviousFocus = null;

function openMockupModal() {
  initCustomArtElements();
  const modal = customArtElements.mockupModal;
  if (modal) {
    // Save the currently focused element to restore later
    mockupModalPreviousFocus = document.activeElement;

    // IMPORTANT: Mark this modal as intentionally open to prevent auto-cleanup
    intentionallyOpenModals.add('customArtMockupModal');

    // Show modal using both class and inline style for maximum compatibility
    // IMPORTANT: Remove hidden attribute to prevent auto-cleanup from closing it
    modal.removeAttribute('hidden');
    modal.classList.add('modal-visible');
    modal.style.display = 'flex';
    modal.style.pointerEvents = 'auto';
    modal.style.visibility = 'visible';

    // Load iframe if not already loaded - use server URL for better CORS compatibility
    const frame = customArtElements.mockupFrame;
    if (frame && (!frame.src || frame.src === '' || frame.src === window.location.href || !frame.src.includes('wall-art-mockup'))) {
      // Use server URL to avoid CORS issues when loading images
      // Add cache-busting parameter to ensure fresh version
      const serverUrl = window.printStationConfig?.serverBaseUrl || 'https://blueridgecustomco.com';
      frame.src = `${serverUrl}/web/wall-art-mockup.html?v=${Date.now()}`;
      console.log('[openMockupModal] Setting iframe src to:', frame.src);
    }

    // Focus the modal for accessibility
    modal.setAttribute('tabindex', '-1');
    modal.focus();
    console.log('[openMockupModal] Modal opened and marked as intentionally open');
  }
}

function closeMockupModal() {
  // Log stack trace to identify what's calling this
  console.log('[closeMockupModal] Called from:', new Error().stack);

  // Remove from intentionally open set
  intentionallyOpenModals.delete('customArtMockupModal');

  initCustomArtElements();
  const modal = customArtElements.mockupModal;
  if (modal) {
    // Hide modal using both class and inline style
    modal.setAttribute('hidden', '');
    modal.classList.remove('modal-visible');
    modal.style.display = 'none';
    modal.style.pointerEvents = 'none';
    modal.style.visibility = 'hidden';

    // Restore focus to the previously focused element
    if (mockupModalPreviousFocus && typeof mockupModalPreviousFocus.focus === 'function') {
      try {
        mockupModalPreviousFocus.focus();
      } catch (e) {
        // Element may no longer exist, focus the main content
        document.body.focus();
      }
    }
    mockupModalPreviousFocus = null;
  }
}

function applyMockupSettings() {
  console.log('[Custom Art] applyMockupSettings called');
  // Refresh elements to ensure we have current references
  initCustomArtElements();

  // Get the hidden room ID (from room picker) and find the room data
  const roomId = document.getElementById('customArtMockupRoom')?.value;
  // Get selected artwork from grid instead of dropdown
  const selectedArtworkCard = document.querySelector('#customArtMockupArtworkGrid .mockup-artwork-item.selected');
  const materialOption = customArtElements.mockupMaterial?.selectedOptions?.[0];

  // Get room image from the rooms list using the hidden input value
  let roomImage = '';
  if (roomId) {
    let room = roomPickerState.rooms?.find(r => String(r.id) === String(roomId));
    if (!room) {
      room = customArtState.rooms?.find(r => String(r.id) === String(roomId));
    }
    if (room) {
      roomImage = room.url || room.image_url || '';
    }
  }
  const artworkImage = selectedArtworkCard?.dataset?.image || customArtElements.mockupArtwork?.dataset?.image || '';
  const materialFilter = materialOption?.dataset?.filter || 'none';

  console.log('[Custom Art] applyMockupSettings - roomId:', roomId, 'roomImage:', roomImage, 'artworkImage:', artworkImage?.substring(0, 50));

  // Validate selections
  if (!roomImage && !artworkImage) {
    setCustomArtStatus('Please select a room or artwork first', true);
    return;
  }

  const frame = customArtElements.mockupFrame;

  // Open the fullscreen modal first
  openMockupModal();

  if (frame) {
    const sendSettings = () => {
      if (frame.contentWindow) {
        console.log('[applyMockupSettings] Sending SET_MOCKUP with roomImage:', roomImage?.substring(0, 50), 'artworkImage:', artworkImage?.substring(0, 50));
        frame.contentWindow.postMessage({
          type: 'SET_MOCKUP',
          roomImage,
          artworkImage,
          materialFilter
        }, '*');
        setCustomArtStatus('Mockup opened');
      }
    };

    // Set up listener for MOCKUP_READY signal BEFORE forcing reload
    const handleReady = (event) => {
      if (event.data?.type === 'MOCKUP_READY') {
        console.log('[applyMockupSettings] Received MOCKUP_READY, sending settings');
        window.removeEventListener('message', handleReady);
        // Small delay to ensure React state is fully initialized
        setTimeout(sendSettings, 150);
      }
    };
    window.addEventListener('message', handleReady);

    // Force reload the iframe to get a fresh React instance
    // This ensures we catch the MOCKUP_READY signal
    const serverUrl = window.printStationConfig?.serverBaseUrl || 'https://blueridgecustomco.com';
    const newSrc = `${serverUrl}/web/wall-art-mockup.html?v=${Date.now()}`;
    console.log('[applyMockupSettings] Forcing iframe reload:', newSrc);
    frame.src = newSrc;

    // Timeout fallback in case MOCKUP_READY is missed
    setTimeout(() => {
      window.removeEventListener('message', handleReady);
      console.log('[applyMockupSettings] Fallback timeout - sending settings anyway');
      sendSettings();
    }, 3000);
  }
}

/**
 * Quick Mockup - Opens the mockup generator with the selected room/artwork
 * Used by the "Save Mockup Image" button in the Quick Actions panel
 * This opens the mockup editor so user can adjust placement before saving
 */
async function saveQuickMockup() {
  console.log('[Custom Art] saveQuickMockup (open generator) called');
  initCustomArtElements();

  // Get the hidden room ID (from room picker) instead of the removed dropdown
  const roomId = document.getElementById('customArtMockupRoom')?.value;
  // Get selected artwork from grid instead of dropdown
  const selectedArtworkCard = document.querySelector('#customArtMockupArtworkGrid .mockup-artwork-item.selected');
  const materialOption = customArtElements.mockupMaterial?.selectedOptions[0];

  console.log('[Custom Art] roomId:', roomId);
  console.log('[Custom Art] roomPickerState.rooms count:', roomPickerState.rooms?.length);
  console.log('[Custom Art] customArtState.rooms count:', customArtState.rooms?.length);

  // Get room image from the preview or rooms list
  let roomImage = '';
  if (roomId) {
    // First try roomPickerState (most recent selection), then customArtState.rooms
    let room = roomPickerState.rooms?.find(r => String(r.id) === String(roomId));
    if (!room) {
      room = customArtState.rooms?.find(r => String(r.id) === String(roomId));
    }

    // If room not found in cached arrays, fetch it from server
    if (!room) {
      console.log('[Custom Art] Room not in cache, fetching from server...');
      try {
        const result = await printStation.customArt.listRooms({ activeOnly: true, limit: 500 });
        const rooms = result?.rooms || [];
        room = rooms.find(r => String(r.id) === String(roomId));
        // Cache for future use
        if (rooms.length > 0) {
          roomPickerState.rooms = rooms;
        }
      } catch (e) {
        console.error('[Custom Art] Failed to fetch rooms:', e);
      }
    }

    if (room) {
      roomImage = room.imagePath || room.image_path || room.file_path;
      console.log('[Custom Art] Found room, imagePath:', roomImage);

      // Check if this is a local Windows path (C:\... or D:\...)
      const isLocalWindowsPath = /^[A-Za-z]:[\\/]/.test(roomImage);

      if (isLocalWindowsPath) {
        // For local paths, we need to read the file and convert to base64 data URL
        console.log('[Custom Art] Room image is a local path, will convert to data URL');
        try {
          const base64 = await printStation.readFileAsBase64(roomImage);
          const ext = roomImage.split('.').pop().toLowerCase();
          const mimeType = ext === 'png' ? 'image/png' : ext === 'webp' ? 'image/webp' : 'image/jpeg';
          roomImage = `data:${mimeType};base64,${base64}`;
          console.log('[Custom Art] Converted room image to data URL, length:', roomImage.length);
        } catch (e) {
          console.error('[Custom Art] Failed to read room image:', e);
          setCustomArtStatus('Failed to load room image', true);
          return;
        }
      } else if (roomImage && !roomImage.startsWith('http') && !roomImage.startsWith('data:')) {
        // Server-relative path - convert to full URL using resolveAssetUrl
        roomImage = resolveAssetUrl(roomImage);
      }
      console.log('[Custom Art] Final roomImage URL:', roomImage?.substring(0, 100));
    } else {
      console.log('[Custom Art] Room not found for id:', roomId);
    }
  }

  // Get artwork image from selected grid card
  let artworkImage = selectedArtworkCard?.dataset?.image || customArtElements.mockupArtwork?.dataset?.image || '';

  // Check if artwork is also a local path
  if (artworkImage) {
    const isLocalArtworkPath = /^[A-Za-z]:[\\/]/.test(artworkImage);
    if (isLocalArtworkPath) {
      console.log('[Custom Art] Artwork image is a local path, will convert to data URL');
      try {
        const base64 = await printStation.readFileAsBase64(artworkImage);
        const ext = artworkImage.split('.').pop().toLowerCase();
        const mimeType = ext === 'png' ? 'image/png' : ext === 'webp' ? 'image/webp' : 'image/jpeg';
        artworkImage = `data:${mimeType};base64,${base64}`;
        console.log('[Custom Art] Converted artwork image to data URL, length:', artworkImage.length);
      } catch (e) {
        console.error('[Custom Art] Failed to read artwork image:', e);
        setCustomArtStatus('Failed to load artwork image', true);
        return;
      }
    } else if (artworkImage.startsWith('/')) {
      artworkImage = `${window.printStationConfig?.serverBaseUrl || ''}${artworkImage}`;
    }
  }
  const materialFilter = materialOption?.dataset?.filter || 'none';

  // Validate selections
  if (!roomImage) {
    setCustomArtStatus('Please select a room background first', true);
    return;
  }
  if (!artworkImage) {
    setCustomArtStatus('Please select artwork first', true);
    return;
  }

  // Check if this is a campaign mockup - just validate selection
  const campaignMockupCheckbox = document.getElementById('customArtCampaignMockupCheckbox');
  const campaignMockupSelect = document.getElementById('customArtCampaignMockupSelect');

  if (campaignMockupCheckbox?.checked) {
    const campaignId = campaignMockupSelect?.value;
    if (!campaignId) {
      setCustomArtStatus('Please select a campaign for this mockup', true);
      return;
    }
  }

  setCustomArtStatus('Opening mockup generator...');

  // Open the fullscreen modal
  openMockupModal();

  // Wait for iframe to load, then apply settings
  const frame = customArtElements.mockupFrame;
  if (frame) {
    const sendSettings = () => {
      if (frame.contentWindow) {
        // Send mockup settings to the iframe
        console.log('[Custom Art] Sending SET_MOCKUP to iframe:', { roomImage, artworkImage, materialFilter });
        frame.contentWindow.postMessage({
          type: 'SET_MOCKUP',
          roomImage,
          artworkImage,
          materialFilter
        }, '*');
        setCustomArtStatus('Mockup generator ready - adjust placement and click Save Mockup');
      } else {
        console.log('[Custom Art] frame.contentWindow not available');
      }
    };

    // If iframe is already loaded, send immediately; otherwise wait for load
    console.log('[Custom Art] frame.src:', frame.src, 'frame.contentWindow:', !!frame.contentWindow);
    if (frame.contentWindow && frame.src && frame.src !== window.location.href) {
      setTimeout(sendSettings, 300); // Small delay for iframe to be ready
    } else {
      frame.addEventListener('load', () => setTimeout(sendSettings, 300), { once: true });
    }
  } else {
    console.log('[Custom Art] mockupFrame not found');
  }
}

// Track pending mockup save state
let pendingMockupSave = null;

/**
 * Populate the campaign dropdown for campaign mockups
 * Fetches campaigns from server and filters for metal-print campaigns
 */
async function populateCampaignMockupDropdown() {
  const campaignSelect = document.getElementById('customArtCampaignMockupSelect');
  if (!campaignSelect) return;

  // Clear existing options
  campaignSelect.innerHTML = '<option value="">Loading campaigns...</option>';

  try {
    // Fetch campaigns from server
    const resp = await printStation.listCampaigns();
    const allCampaigns = Array.isArray(resp?.campaigns) ? resp.campaigns : [];

    // Filter for metal-print campaigns
    const metalPrintCampaigns = allCampaigns.filter(c => c.bulkType === 'metal-print');

    // Clear and set default option
    campaignSelect.innerHTML = '<option value="">Choose campaign...</option>';

    if (metalPrintCampaigns.length === 0) {
      // Also show current campaign if it's a metal-print type
      if (state.campaign?.bulkType === 'metal-print' && state.campaign?.slug) {
        const option = document.createElement('option');
        option.value = state.campaign.slug;
        option.textContent = state.campaign.name || state.campaign.slug;
        if (state.campaign.mockupImage) {
          option.textContent += ' (has mockup)';
        }
        campaignSelect.appendChild(option);
      } else {
        campaignSelect.innerHTML = '<option value="">No metal print campaigns found</option>';
        return;
      }
    }

    // Add each campaign as an option
    for (const campaign of metalPrintCampaigns) {
      const option = document.createElement('option');
      option.value = campaign.slug || campaign.id;
      option.textContent = campaign.title || campaign.name || `Campaign ${campaign.slug}`;
      if (campaign.mockupImage) {
        option.textContent += ' (has mockup)';
      }
      campaignSelect.appendChild(option);
    }

    // If current campaign is metal-print and not in list, add it
    if (state.campaign?.bulkType === 'metal-print' && state.campaign?.slug) {
      const exists = metalPrintCampaigns.some(c => (c.slug || c.id) === state.campaign.slug);
      if (!exists) {
        const option = document.createElement('option');
        option.value = state.campaign.slug;
        option.textContent = (state.campaign.name || state.campaign.slug) + ' (current)';
        if (state.campaign.mockupImage) {
          option.textContent += ' (has mockup)';
        }
        campaignSelect.appendChild(option);
      }
    }
  } catch (err) {
    console.error('[populateCampaignMockupDropdown] Error:', err);
    campaignSelect.innerHTML = '<option value="">Error loading campaigns</option>';
  }
}

async function saveMockupToProduct() {
  console.log('[Mockup Save] saveMockupToProduct called');
  initCustomArtElements();
  const frame = customArtElements.mockupFrame;
  console.log('[Mockup Save] frame exists:', !!frame, 'contentWindow:', !!frame?.contentWindow);
  console.log('[Mockup Save] mockupArtwork element:', customArtElements.mockupArtwork);
  console.log('[Mockup Save] mockupArtwork value:', customArtElements.mockupArtwork?.value);
  if (!frame?.contentWindow) {
    setCustomArtStatus('Mockup iframe not ready', true);
    console.log('[Mockup Save] ERROR: iframe not ready, returning');
    return;
  }

  // Check if this is a campaign mockup
  const campaignMockupCheckbox = document.getElementById('customArtCampaignMockupCheckbox');
  const campaignMockupSelect = document.getElementById('customArtCampaignMockupSelect');

  if (campaignMockupCheckbox?.checked) {
    const campaignId = campaignMockupSelect?.value;
    if (!campaignId) {
      setCustomArtStatus('Please select a campaign for this mockup', true);
      return;
    }

    // Store campaign info for when we receive the mockup data
    pendingMockupSave = { campaignId, isCampaignMockup: true };

    // Request mockup image from iframe
    frame.contentWindow.postMessage({ type: 'EXPORT_MOCKUP' }, '*');
    setCustomArtStatus('Saving campaign mockup...');
    return;
  }

  let productId = null;
  let artworkId = null;

  // Check if we're saving a tiled product mockup (product was already created)
  if (customArtState.currentTiledProductId) {
    productId = customArtState.currentTiledProductId;
    // Get artwork ID from stored tiled data, or find the product
    artworkId = customArtState.currentTiledArtworkId;
    if (!artworkId) {
      const tiledProduct = customArtState.products.find(p => p.id === productId);
      artworkId = tiledProduct?.artworkId;
    }
    console.log('[Mockup Save] Using tiled product ID:', productId, 'artworkId:', artworkId);
  } else {
    // Normal flow - find product by selected artwork
    artworkId = customArtElements.mockupArtwork?.value;
    console.log('[Mockup Save] Normal flow, artworkId:', artworkId);
    if (!artworkId) {
      console.log('[Mockup Save] ERROR: No artworkId, returning early');
      setCustomArtStatus('Please select artwork to associate mockup with', true);
      return;
    }

    // Find the product that uses this artwork
    console.log('[Mockup Save] Looking for product with artworkId:', artworkId, 'in products:', customArtState.products?.length);
    let product = customArtState.products.find(p => String(p.artworkId) === String(artworkId));
    console.log('[Mockup Save] Found product:', product);
    if (!product) {
      // Auto-create a product for this artwork
      console.log('[Mockup Save] No product found, auto-creating...');
      setCustomArtStatus('Creating product for artwork...');
      try {
        const artwork = customArtState.artwork.find(a => String(a.id) === String(artworkId));
        console.log('[Mockup Save] Found artwork for product creation:', artwork?.title);
        const materialId = customArtElements.mockupMaterial?.value || null;
        console.log('[Mockup Save] Calling createProduct API...');

        const newProduct = await printStation.customArt.createProduct({
          title: artwork?.title || 'Untitled',
          artworkId: artworkId,
          materialId: materialId,
          status: 'draft',
          description: artwork?.description || ''
        });
        console.log('[Mockup Save] createProduct API returned:', newProduct);

        // API returns {success: true, product: {...}} so extract the product object
        const createdProduct = newProduct?.product || newProduct;
        if (createdProduct?.id) {
          productId = createdProduct.id;
          // Reload products list
          await loadCustomArtProducts();
          console.log('[Mockup Save] Auto-created product:', productId);
        } else {
          setCustomArtStatus('Failed to create product for artwork', true);
          return;
        }
      } catch (e) {
        console.error('[Mockup Save] Failed to auto-create product:', e);
        setCustomArtStatus(`Error creating product: ${e.message}`, true);
        return;
      }
    } else {
      productId = product.id;
      console.log('[Mockup Save] Using existing product:', productId);
    }
  }

  console.log('[Mockup Save] Ready to save, productId:', productId, 'artworkId:', artworkId);

  // Gather additional context for the mockup record
  const materialId = customArtElements.mockupMaterial?.value || null;
  const roomId = customArtElements.mockupRoom?.value || null;
  const artwork = customArtState.artwork.find(a => String(a.id) === String(artworkId));
  const room = customArtState.rooms?.find(r => String(r.id) === String(roomId));
  const material = customArtState.materials?.find(m => String(m.id) === String(materialId));

  // Generate a descriptive title
  const artworkTitle = artwork?.title || 'Artwork';
  const roomName = room?.name || 'Room';
  const mockupTitle = `${artworkTitle} - ${roomName}`;

  // Store the product ID and metadata for when we receive the mockup data
  pendingMockupSave = {
    productId,
    artworkId,
    materialId,
    roomId,
    title: mockupTitle,
    mockupType: 'product'
  };

  // Request mockup image from iframe
  console.log('[Mockup Save] Sending EXPORT_MOCKUP to iframe, pendingMockupSave:', pendingMockupSave);
  console.log('[Mockup Save] iframe src:', frame.src);
  console.log('[Mockup Save] iframe contentWindow exists:', !!frame.contentWindow);
  frame.contentWindow.postMessage({ type: 'EXPORT_MOCKUP' }, '*');
  setCustomArtStatus('Saving mockup...');
}

async function createProductFromMockup() {
  initCustomArtElements();
  const artworkId = customArtElements.mockupArtwork?.value;
  const materialId = customArtElements.mockupMaterial?.value;

  if (!artworkId) {
    setCustomArtStatus('Please select artwork first', true);
    return;
  }

  // First, save the mockup (this will also auto-create a product if needed)
  // Set pending state to indicate we want to open product form after save
  const frame = customArtElements.mockupFrame;
  if (!frame?.contentWindow) {
    setCustomArtStatus('Mockup iframe not ready', true);
    return;
  }

  // Get room info for mockup title
  const roomId = customArtElements.mockupRoom?.value || null;
  const artwork = customArtState.artwork.find(a => String(a.id) === String(artworkId));
  const room = customArtState.rooms?.find(r => String(r.id) === String(roomId));
  const artworkTitle = artwork?.title || 'Artwork';
  const roomName = room?.name || 'Room';
  const mockupTitle = `${artworkTitle} - ${roomName}`;

  // Store pending save with flag to open product form after
  pendingMockupSave = {
    productId: null, // Will be auto-created
    artworkId,
    materialId,
    roomId,
    title: mockupTitle,
    mockupType: 'product',
    openProductFormAfter: true // Flag to open product form after save
  };

  // Request mockup image from iframe
  frame.contentWindow.postMessage({ type: 'EXPORT_MOCKUP' }, '*');
  setCustomArtStatus('Saving mockup and creating product...');
}

// Listen for messages from the mockup iframe
window.addEventListener('message', async (event) => {
  // Debug: Log all messages from iframes
  if (event.data?.type) {
    console.log('[Message Handler] Received message type:', event.data.type, 'from origin:', event.origin);
  }

  if (event.data?.type === 'MOCKUP_EXPORTED') {
    console.log('[Mockup Save] Received MOCKUP_EXPORTED!');
    console.log('[Mockup Save] dataUrl exists:', !!event.data.dataUrl);
    console.log('[Mockup Save] dataUrl length:', event.data.dataUrl?.length || 0);
    console.log('[Mockup Save] pendingMockupSave:', pendingMockupSave);
    const { dataUrl, filename, artworks, roomImage, roomSize, productSizeInfo } = event.data;
    if (dataUrl && pendingMockupSave) {
      // Check if this is a campaign mockup save
      if (pendingMockupSave.isCampaignMockup) {
        try {
          const base64Data = dataUrl.split(',')[1];
          const ext = filename?.split('.').pop() || 'jpg';
          const campaignId = pendingMockupSave.campaignId;

          // Save campaign mockup to server
          const result = await printStation.campaign.saveCampaignMockup({
            campaignId,
            mockupBase64: base64Data,
            filename: `campaign-mockup-${campaignId}-${Date.now()}.${ext}`
          });

          if (result?.success) {
            setCustomArtStatus('Campaign mockup saved successfully!');
            // Update the campaign in state with the mockup path
            // The mockupPath is stored on the campaign object itself, not on items
            if (result.mockupPath) {
              // If we're saving to the currently loaded campaign, update it
              if (state.campaign && (state.campaign.slug === campaignId || state.campaign.id === campaignId)) {
                state.campaign.mockupImage = result.mockupPath;
                console.log('[Campaign Mockup] Updated state.campaign.mockupImage:', result.mockupPath);
              }
            }

            // Also save a mockup template for Facebook scheduling if we have position data
            if (artworks?.length > 0 && roomImage && roomSize) {
              const art = artworks[0]; // Use first artwork's position as template
              try {
                const templateResult = await printStation.createMockupTemplate({
                  campaignSlug: campaignId,
                  name: `${campaignId} Template`,
                  mockupImagePath: roomImage, // The room/background image
                  artworkPosition: {
                    x: Math.round(art.x),
                    y: Math.round(art.y),
                    width: Math.round(art.width),
                    height: Math.round(art.height),
                    rotation: art.rotation || 0
                  },
                  blendMode: 'normal',
                  outputFormat: 'jpeg',
                  outputQuality: 90
                });
                if (templateResult?.success) {
                  console.log('[Campaign Mockup] Also saved mockup template for FB scheduling');
                }
              } catch (templateErr) {
                console.warn('[Campaign Mockup] Failed to save template:', templateErr);
                // Don't fail the whole operation if template save fails
              }
            }

            // Close the mockup modal
            closeMockupModal();
            // Reset the checkbox
            const checkbox = document.getElementById('customArtCampaignMockupCheckbox');
            if (checkbox) checkbox.checked = false;
            const options = document.getElementById('customArtCampaignMockupOptions');
            if (options) options.style.display = 'none';

            showToast('Campaign mockup saved! You can now export to Shopify.', 'success');
          } else {
            setCustomArtStatus(`Error saving campaign mockup: ${result?.error || 'Unknown error'}`, true);
          }
        } catch (e) {
          console.error('[Custom Art] Save campaign mockup error:', e);
          setCustomArtStatus(`Error: ${e.message}`, true);
        }
        pendingMockupSave = null;
        return;
      }

      // Save mockup to server and associate with product
      // Remember if this was a tiled product before any async operations
      const wasTiledProduct = !!customArtState.currentTiledProductId;

      try {
        // Convert data URL to base64
        const base64Data = dataUrl.split(',')[1];
        const ext = filename?.split('.').pop() || 'jpg';

        // Get original artwork info for naming tiled files
        const originalArtwork = customArtState.artwork.find(a => String(a.id) === pendingMockupSave.artworkId);
        const baseTitle = originalArtwork?.title || 'Artwork';
        // Sanitize title for filename (remove special chars)
        const safeTitle = baseTitle.replace(/[^a-zA-Z0-9\s-]/g, '').replace(/\s+/g, '-');

        // If no productId and we want to create a product (openProductFormAfter), create one first
        if (!pendingMockupSave.productId && pendingMockupSave.openProductFormAfter && pendingMockupSave.artworkId) {
          setCustomArtStatus('Creating product for artwork...');
          try {
            const newProduct = await printStation.customArt.createProduct({
              title: originalArtwork?.title || 'Untitled',
              artworkId: pendingMockupSave.artworkId,
              materialId: pendingMockupSave.materialId || null,
              status: 'draft',
              description: originalArtwork?.description || ''
            });
            if (newProduct?.id) {
              pendingMockupSave.productId = newProduct.id;
              console.log('[Mockup Save] Auto-created product:', newProduct.id);
            }
          } catch (e) {
            console.error('[Mockup Save] Failed to auto-create product:', e);
            // Continue without product - mockup will still be saved
          }
        }

        // Save to server via API - include all metadata for proper tracking
        const result = await printStation.customArt.saveMockup({
          productId: pendingMockupSave.productId,
          mockupBase64: base64Data,
          filename: `mockup-${pendingMockupSave.productId || 'general'}-${Date.now()}.${ext}`,
          artworkId: pendingMockupSave.artworkId,
          roomId: pendingMockupSave.roomId,
          materialId: pendingMockupSave.materialId,
          campaignSlug: pendingMockupSave.campaignSlug,
          mockupType: pendingMockupSave.mockupType || 'product',
          title: pendingMockupSave.title
        });

        if (result?.success) {
          // If there are multiple artworks (tiled versions), save them too
          // Skip the first one (index 0) as that's the original
          if (artworks && artworks.length > 1) {
            setCustomArtStatus(`Saving ${artworks.length - 1} tiled artwork(s)...`);
            let tiledCount = 0;
            for (let i = 1; i < artworks.length; i++) {
              const art = artworks[i];
              if (art.src && art.src.startsWith('data:')) {
                // It's a data URL, save it
                const tiledBase64 = art.src.split(',')[1];
                const tiledNum = String(i).padStart(3, '0'); // 001, 002, etc.
                const tiledFilename = `${safeTitle}-${tiledNum}.jpg`;
                try {
                  await printStation.customArt.saveTiledArtwork({
                    productId: pendingMockupSave.productId,
                    artworkBase64: tiledBase64,
                    filename: tiledFilename,
                    originalArtworkId: pendingMockupSave.artworkId
                  });
                  tiledCount++;
                } catch (e) {
                  console.warn('[Custom Art] Failed to save tiled artwork:', e);
                }
              }
            }
            setCustomArtStatus(`Mockup saved! ${tiledCount} tiled artwork(s) added.`);
          } else {
            setCustomArtStatus('Mockup saved successfully!');
          }

          // Update product with size info from mockup
          // NOTE: For tiled products, we do NOT update the singleSize from the mockup
          // because the product size should be based on the original tile dimensions,
          // not whatever size the user stretched them to in the mockup
          if (productSizeInfo && pendingMockupSave.productId && !wasTiledProduct) {
            try {
              const sizeUpdate = {
                singleSize: {
                  width: parseFloat(productSizeInfo.productWidth),
                  height: parseFloat(productSizeInfo.productHeight),
                  unit: 'inches'
                }
              };

              console.log('[Custom Art] Updating product size info:', sizeUpdate);
              await printStation.customArt.updateProduct(pendingMockupSave.productId, sizeUpdate);
            } catch (sizeErr) {
              console.warn('[Custom Art] Failed to update product size:', sizeErr);
              // Don't fail the whole operation
            }
          }

          // Reload products to reflect the new mockup path
          await loadCustomArtProducts();

          // If this was a tiled product, close the mockup modal
          if (wasTiledProduct) {
            closeMockupModal();
          }

          // Check if we should open the product form after save
          if (pendingMockupSave.openProductFormAfter && pendingMockupSave.productId) {
            closeMockupModal();
            // Switch to products tab and open the product for editing
            switchCustomArtSubtab('products');
            setTimeout(async () => {
              await populateProductDropdowns();
              // Find and edit the newly created product
              const product = customArtState.products.find(p => p.id === pendingMockupSave.productId);
              if (product) {
                showProductFormWithArtwork(product);
                setCustomArtStatus('Product created from mockup - edit details below');
              }
            }, 300);
          }

          // Clear tiled product state after successful save
          customArtState.currentTiledProductId = null;
          customArtState.currentTiledArtworkId = null;
          customArtState.currentTiledData = null;
        } else {
          setCustomArtStatus(`Error saving mockup: ${result?.error || 'Unknown error'}`, true);
        }
      } catch (e) {
        console.error('[Custom Art] Save mockup error:', e);
        setCustomArtStatus(`Error: ${e.message}`, true);
      }
      pendingMockupSave = null;
    } else if (dataUrl) {
      // No pending save - just download
      const link = document.createElement('a');
      link.href = dataUrl;
      link.download = filename || 'mockup.jpg';
      link.click();
      setCustomArtStatus('Mockup exported successfully');
    }
  }

  // Handle request for artwork list from database
  if (event.data?.type === 'GET_ARTWORK_LIST') {
    console.log('[Custom Art] Received GET_ARTWORK_LIST from mockup iframe');
    try {
      // Get artwork from the database
      // IMPORTANT: Must use HTTP URLs for iframe (file:// won't work due to cross-origin)
      const serverBase = (state.config?.serverBaseUrl || 'https://blueridgecustomco.com').replace(/\/$/, '');

      // If artwork hasn't been loaded yet, fetch it from the server
      let artworkList = customArtState.artwork || [];
      if (artworkList.length === 0) {
        console.log('[Custom Art] No artwork in state, fetching from server...');
        try {
          // Use string 'false' to ensure server parses it correctly
          const artworkResult = await printStation.customArt.listArtwork({ activeOnly: 'false', limit: 1000 });
          console.log('[Custom Art] Server returned:', artworkResult);
          artworkList = artworkResult?.artwork || [];
          customArtState.artwork = artworkList;
          console.log('[Custom Art] Fetched', artworkList.length, 'artwork items from server');
        } catch (fetchErr) {
          console.error('[Custom Art] Failed to fetch artwork:', fetchErr);
        }
      }

      const artworksForModal = artworkList.map(art => {
        // Helper to build HTTP URL from path
        const toHttpUrl = (path) => {
          if (!path) return '';
          // Already an HTTP URL
          if (path.startsWith('http://') || path.startsWith('https://')) return path;
          // Data URL - pass through
          if (path.startsWith('data:')) return path;
          // Server-relative path starting with /library/ - use as-is
          if (path.startsWith('/library/')) return serverBase + path;
          // Server-relative path with /uploads/ - needs /library prefix since files are in LIBRARY_ROOT
          if (path.startsWith('/uploads/')) return serverBase + '/library' + path;
          // Other server-relative paths (e.g., /api/...)
          if (path.startsWith('/')) return serverBase + path;
          // Extract server path from local file path if present
          // e.g., /home/ubuntu/vinylApp/library/uploads/... -> /library/uploads/...
          const libraryMatch = path.match(/\/library\/.*$/);
          if (libraryMatch) return serverBase + libraryMatch[0];
          // Check for uploads path without library prefix - need to add /library prefix
          const uploadsMatch = path.match(/\/uploads\/.*$/);
          if (uploadsMatch) return serverBase + '/library' + uploadsMatch[0];
          // Relative path starting with library/
          if (path.startsWith('library/')) return serverBase + '/' + path;
          // Relative path starting with uploads/ - needs library prefix since files are in LIBRARY_ROOT
          if (path.startsWith('uploads/')) return serverBase + '/library/' + path;
          // Other relative path
          return serverBase + '/' + path;
        };

        const url = toHttpUrl(art.optimizedPath || art.filePath || art.serverPath);
        const thumbnail = toHttpUrl(art.thumbnailPath || art.optimizedPath || art.filePath || art.serverPath);

        console.log('[Custom Art] Art item:', art.id, {
          thumbnailPath: art.thumbnailPath,
          optimizedPath: art.optimizedPath,
          filePath: art.filePath,
          serverPath: art.serverPath,
          resolvedUrl: url,
          resolvedThumb: thumbnail
        });

        return {
          id: art.id,
          name: art.title || art.filename || 'Untitled',
          url,
          thumbnail
        };
      });
      console.log('[Custom Art] Sending ARTWORK_LIST with', artworksForModal.length, 'items');
      if (artworksForModal.length > 0) {
        console.log('[Custom Art] Sample artwork:', artworksForModal[0]);
      }

      // Send the artwork list back to the iframe
      // Try multiple selectors to find the mockup iframe
      const mockupFrame = document.getElementById('customArtMockupFrame') ||
                          document.querySelector('iframe[src*="wall-art-mockup"]');
      console.log('[Custom Art] Found mockup frame:', mockupFrame ? 'yes' : 'no', 'src:', mockupFrame?.src);
      if (mockupFrame?.contentWindow) {
        mockupFrame.contentWindow.postMessage({
          type: 'ARTWORK_LIST',
          artworks: artworksForModal
        }, '*');
        console.log('[Custom Art] Sent ARTWORK_LIST to iframe');
      } else {
        console.error('[Custom Art] Could not find mockup iframe to send ARTWORK_LIST');
      }
    } catch (e) {
      console.error('[Custom Art] Error getting artwork list:', e);
    }
  }

  // Handle tile/split artwork request
  if (event.data?.type === 'TILE_ARTWORK') {
    const { artworkId, artworkSrc, artworkName, cols, rows, tileWidth, tileHeight, tileAspectRatio } = event.data;
    console.log('[Custom Art] Received TILE_ARTWORK:', { artworkId, artworkName, cols, rows, tileWidth, tileHeight, tileAspectRatio });

    try {
      setCustomArtStatus(`Splitting artwork into ${cols}x${rows} tiles...`);

      // Call the server to split the artwork
      const result = await printStation.customArt.splitArtwork({
        imageSrc: artworkSrc,
        cols,
        rows,
        name: artworkName
      });

      if (result?.success && result.tiles) {
        console.log('[Custom Art] Tile split successful, got', result.tiles.length, 'tiles');

        // Convert tile URLs to full URLs
        const serverBase = (state.config?.serverBaseUrl || 'https://blueridgecustomco.com').replace(/\/$/, '');
        const tilesWithUrls = result.tiles.map(tile => ({
          ...tile,
          url: tile.url.startsWith('http') ? tile.url : `${serverBase}${tile.url}`
        }));

        // Send the tiles back to the mockup iframe
        const mockupFrame = document.querySelector('iframe[src*="wall-art-mockup"]');
        if (mockupFrame?.contentWindow) {
          mockupFrame.contentWindow.postMessage({
            type: 'TILED_ARTWORK_RESULT',
            artworkId,  // Pass back the original artwork ID so it can be removed
            tiles: tilesWithUrls,
            cols,
            rows,
            tileWidth,     // Pass back the tile dimensions for aspect ratio
            tileHeight,
            tileAspectRatio
          }, '*');
        }

        setCustomArtStatus(`Artwork split into ${cols * rows} tiles`);
      } else {
        setCustomArtStatus(`Error splitting artwork: ${result?.error || 'Unknown error'}`, true);
      }
    } catch (e) {
      console.error('[Custom Art] Error splitting artwork:', e);
      setCustomArtStatus(`Error: ${e.message}`, true);
    }
  }
});

// --- SHOPIFY EXPORT ---
async function exportCustomArtToShopify() {
  console.log('[Custom Art] exportCustomArtToShopify called');

  // Reload products to ensure we have the latest data (including mockupPath)
  setCustomArtStatus('Refreshing product data...');
  try {
    const productsResult = await printStation.customArt.listProducts({ activeOnly: false });
    customArtState.products = productsResult?.products || [];
    console.log('[Custom Art] Refreshed products from server');
  } catch (e) {
    console.error('[Custom Art] Error refreshing products:', e);
  }

  console.log('[Custom Art] All products:', customArtState.products);

  // Get all active products (both new and existing in Shopify)
  const selectedProducts = customArtState.products.filter(p => {
    console.log('[Custom Art] Product:', p.id, 'status:', p.status, 'shopifyProductId:', p.shopifyProductId, 'mockupPath:', p.mockupPath);
    return p.status === 'active';
  });

  console.log('[Custom Art] Selected products for export:', selectedProducts);

  if (!selectedProducts.length) {
    setCustomArtStatus('No active products to export', true);
    return;
  }

  const newCount = selectedProducts.filter(p => !p.shopifyProductId).length;
  const updateCount = selectedProducts.filter(p => p.shopifyProductId).length;
  const confirmMsg = newCount && updateCount
    ? `Export ${newCount} new product(s) and update ${updateCount} existing product(s) in Shopify?`
    : newCount
      ? `Export ${newCount} new product(s) to Shopify?`
      : `Update ${updateCount} existing product(s) in Shopify?`;

  if (!await nativeConfirm(confirmMsg, 'Export to Shopify')) return;

  setCustomArtStatus(`Reading images and preparing export...`);

  try {
    // For each product, read the artwork and mockup images and convert to base64
    const productsWithImages = [];
    for (const p of selectedProducts) {
      const productData = { id: p.id };

      // Get artwork image - could be server URL, server-relative path, or local file
      if (p.artwork?.filePath) {
        const artworkPath = p.artwork.filePath;
        const serverUrl = state.config?.serverBaseUrl || 'https://blueridgecustomco.com';
        console.log('[Custom Art] Processing artwork path:', artworkPath);

        // Check if it's a full URL
        if (artworkPath.startsWith('http://') || artworkPath.startsWith('https://')) {
          // Already a full URL - pass it directly
          console.log('[Custom Art] Artwork is already a full URL');
          productData.artworkUrl = artworkPath;
        } else if (artworkPath.match(/^[A-Za-z]:[\\/]/)) {
          // Local Windows path - read as base64
          try {
            console.log('[Custom Art] Reading local artwork file:', artworkPath);
            const imageData = await printStation.readFileAsBase64(artworkPath);
            if (imageData) {
              productData.artworkBase64 = imageData;
              productData.artworkFilename = artworkPath.split(/[/\\]/).pop();
              console.log('[Custom Art] Got artwork base64, length:', imageData.length);
            }
          } catch (e) {
            console.warn('[Custom Art] Could not read local artwork image:', e);
          }
        } else {
          // Server-relative path - build full URL
          const cleanPath = artworkPath.replace(/^\//, '');
          const artworkFullUrl = `${serverUrl}/${cleanPath}`;
          console.log('[Custom Art] Artwork is server-relative, full URL:', artworkFullUrl);
          productData.artworkUrl = artworkFullUrl;
        }
      }

      // Get mockup - if it's a URL (already on server), pass the URL directly
      // If it's a local path, read as base64
      console.log('[Custom Art] Checking mockup for product:', p.id, 'mockupPath:', p.mockupPath);
      if (p.mockupPath) {
        if (p.mockupPath.startsWith('http://') || p.mockupPath.startsWith('https://')) {
          // Mockup is already on server, just pass the URL
          console.log('[Custom Art] Mockup is already on server:', p.mockupPath);
          productData.mockupUrl = p.mockupPath;
        } else {
          // Local file path - read as base64
          try {
            console.log('[Custom Art] Reading mockup file:', p.mockupPath);
            const mockupData = await printStation.readFileAsBase64(p.mockupPath);
            if (mockupData) {
              productData.mockupBase64 = mockupData;
              productData.mockupFilename = p.mockupPath.split(/[/\\]/).pop();
              console.log('[Custom Art] Got mockup base64, length:', mockupData.length);
            }
          } catch (e) {
            console.warn('[Custom Art] Could not read mockup image:', e);
          }
        }
      } else {
        console.log('[Custom Art] No mockupPath for product:', p.id);
      }

      productsWithImages.push(productData);
    }

    setCustomArtStatus(`Exporting ${selectedProducts.length} products to Shopify...`);
    console.log('[Custom Art] Calling API with products:', productsWithImages.length);
    const result = await printStation.customArt.exportToShopify({
      products: productsWithImages
    });
    console.log('[Custom Art] API result:', result);

    if (result.success) {
      const successCount = result.results?.filter(r => r.success).length || 0;
      const failCount = result.results?.filter(r => !r.success).length || 0;
      setCustomArtStatus(`Shopify export complete: ${successCount} succeeded, ${failCount} failed`);
      // Reload products to reflect shopifyProductId updates
      await loadCustomArtProducts();
    } else {
      setCustomArtStatus(`Export error: ${result.error}`, true);
    }
  } catch (e) {
    console.error('[Custom Art] Export error:', e);
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

// --- FACEBOOK ADS ---
async function generateFbAdsFromMockup() {
  const artworkId = customArtElements.mockupArtwork?.value;
  if (!artworkId) {
    setCustomArtStatus('Please select artwork first', true);
    return;
  }

  const artwork = customArtState.artwork.find(a => String(a.id) === artworkId);
  if (!artwork) {
    setCustomArtStatus('Artwork not found', true);
    return;
  }

  // Find associated product for pricing
  const product = customArtState.products.find(p => String(p.artworkId) === artworkId);
  const price = product ? (product.basePriceCents / 100) : 49.99;

  setCustomArtStatus('Generating Facebook Ads...');
  try {
    // Build campaign object matching what facebook-ai.js expects
    const campaign = {
      title: artwork.title,
      subtitle: artwork.description || 'Premium Wall Art',
      items: [{
        title: artwork.title,
        price: price,
        category: artwork.category || 'Wall Art',
        style: artwork.style || ''
      }]
    };

    // Use artwork image path - prefer preview for faster loading
    const imagePath = artwork.previewPath || artwork.thumbnailPath || artwork.optimizedPath || artwork.filePath;

    const result = await printStation.generateFacebookAds({
      campaign,
      imagePath,
      budget: 20 // Default daily budget
    });

    if (result.success) {
      const data = result.data || {};
      setCustomArtStatus(`Facebook Ads generated! ${data.adSets?.length || 0} ad set(s) created.`);
      // Log the result for viewing
      console.log('Generated Facebook Ads:', data);
      // Could show modal with results here
    } else {
      setCustomArtStatus(`Error: ${result.error}`, true);
    }
  } catch (e) {
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

// --- FACEBOOK MARKETPLACE / SOCIAL POST ---
async function postToMarketplace() {
  const artworkId = customArtElements.mockupArtwork?.value;
  if (!artworkId) {
    setCustomArtStatus('Please select artwork first', true);
    return;
  }

  const artwork = customArtState.artwork.find(a => String(a.id) === artworkId);
  if (!artwork) {
    setCustomArtStatus('Artwork not found', true);
    return;
  }

  // Find associated product for pricing
  const product = customArtState.products.find(p => String(p.artworkId) === artworkId);
  const price = product ? (product.basePriceCents / 100) : 49.99;

  setCustomArtStatus('Generating Facebook post...');
  try {
    // Build items array matching what social-marketing.js expects
    const displayPath = artwork.previewPath || artwork.thumbnailPath || artwork.optimizedPath || artwork.filePath;
    const items = [{
      name: artwork.title,
      image: displayPath,
      imagePath: displayPath,
      price: price,
      category: artwork.category || 'Wall Art',
      description: artwork.description || ''
    }];

    const result = await printStation.generateFacebookPost({
      items,
      style: 'showcase',
      productType: 'wall-art'
    });

    if (result.success) {
      const data = result.data || {};
      const variations = data.variations?.length || 0;
      setCustomArtStatus(`Facebook post generated! ${variations} variation(s) available.`);
      console.log('Generated Facebook Post:', data);
      // Could show modal with post preview/variations here
    } else {
      setCustomArtStatus(`Error: ${result.error}`, true);
    }
  } catch (e) {
    setCustomArtStatus(`Error: ${e.message}`, true);
  }
}

