// ==================================================================================
// AI IMAGE GENERATOR (Gemini)
// ==================================================================================

function getLeonardoApiBase() {
  return state.config?.serverBaseUrl?.trim() || '';
}

const leonardoState = {
  category: 'vehicle',
  aspectRatio: '1:1',
  initialized: false,
  generatedImages: []
};

let leonardoElements = {};

function initLeonardoElements() {
  leonardoElements = {
    tokens: document.getElementById('leonardoTokens'),
    refreshStatus: document.getElementById('leonardoRefreshStatus'),
    keywords: document.getElementById('leonardoKeywords'),
    numImages: document.getElementById('leonardoNumImages'),
    model: document.getElementById('leonardoModel'),
    addToArtwork: document.getElementById('leonardoAddToArtwork'),
    generateBtn: document.getElementById('leonardoGenerateBtn'),
    previewPromptBtn: document.getElementById('leonardoPreviewPromptBtn'),
    progress: document.getElementById('leonardoProgress'),
    progressText: document.getElementById('leonardoProgressText'),
    promptPreview: document.getElementById('leonardoPromptPreview'),
    promptText: document.getElementById('leonardoPromptText'),
    resultsGrid: document.getElementById('leonardoResultsGrid'),
    clearResults: document.getElementById('leonardoClearResults'),
    historyList: document.getElementById('leonardoHistoryList'),
    refreshHistory: document.getElementById('leonardoRefreshHistory'),
    promptsGrid: document.getElementById('leonardoPromptsGrid'),
    promptCategoryFilter: document.getElementById('leonardoPromptCategoryFilter'),
    refreshPrompts: document.getElementById('leonardoRefreshPrompts')
  };
}

function initLeonardoView() {
  if (leonardoState.initialized) return;

  initLeonardoElements();

  // Category buttons
  document.querySelectorAll('.leonardo-category-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.leonardo-category-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      leonardoState.category = btn.dataset.category;
    });
  });

  // Aspect ratio buttons
  document.querySelectorAll('.leonardo-aspect-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      document.querySelectorAll('.leonardo-aspect-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      leonardoState.aspectRatio = btn.dataset.aspect;
    });
  });

  // Generate button
  if (leonardoElements.generateBtn) {
    leonardoElements.generateBtn.addEventListener('click', handleLeonardoGenerate);
  }

  // Preview prompt button
  if (leonardoElements.previewPromptBtn) {
    leonardoElements.previewPromptBtn.addEventListener('click', handleLeonardoPreviewPrompt);
  }

  // Refresh status
  if (leonardoElements.refreshStatus) {
    leonardoElements.refreshStatus.addEventListener('click', loadLeonardoStatus);
  }

  // Clear results
  if (leonardoElements.clearResults) {
    leonardoElements.clearResults.addEventListener('click', () => {
      leonardoState.generatedImages = [];
      renderLeonardoResults();
    });
  }

  // Refresh history
  if (leonardoElements.refreshHistory) {
    leonardoElements.refreshHistory.addEventListener('click', loadLeonardoHistory);
  }

  // Refresh prompts
  if (leonardoElements.refreshPrompts) {
    leonardoElements.refreshPrompts.addEventListener('click', loadLeonardoPrompts);
  }

  // Prompt category filter
  if (leonardoElements.promptCategoryFilter) {
    leonardoElements.promptCategoryFilter.addEventListener('change', loadLeonardoPrompts);
  }

  // Load initial data
  loadLeonardoStatus();
  loadLeonardoHistory();
  loadLeonardoPrompts();

  leonardoState.initialized = true;
  console.log('[AI Image] View initialized');
}

async function loadLeonardoStatus() {
  try {
    const serverBase = getLeonardoApiBase();
    if (!serverBase) return;
    const resp = await fetch(`${serverBase}/api/ai-images/status`);
    const data = await resp.json();
    if (data.success && leonardoElements.tokens) {
      const tokens = data.api?.apiSubscriptionTokens || data.api?.subscriptionTokens || '--';
      leonardoElements.tokens.textContent = `Tokens: ${tokens}`;
    }
  } catch (e) {
    console.error('[AI Image] Status error:', e);
    if (leonardoElements.tokens) {
      leonardoElements.tokens.textContent = 'Tokens: Error';
    }
  }
}

async function loadLeonardoHistory() {
  try {
    const serverBase = getLeonardoApiBase();
    if (!serverBase) return;
    const resp = await fetch(`${serverBase}/api/ai-images/images?limit=20`);
    const data = await resp.json();

    if (!leonardoElements.historyList) return;

    if (data.success && data.images?.length > 0) {
      leonardoElements.historyList.innerHTML = data.images.map(img => `
        <div style="display:flex;gap:12px;padding:8px;border-bottom:1px solid #3a3a4e;align-items:center;">
          <img src="${serverBase}${img.file_path || '/images/ai-generated/text-to-image/' + img.filename}"
               style="width:60px;height:60px;object-fit:cover;border-radius:4px;"
               onerror="this.src='data:image/svg+xml,<svg xmlns=\\'http://www.w3.org/2000/svg\\' width=\\'60\\' height=\\'60\\'><rect fill=\\'%23333\\' width=\\'60\\' height=\\'60\\'/></svg>'" />
          <div style="flex:1;min-width:0;">
            <div style="font-size:12px;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">
              ${img.filename}
            </div>
            <div style="font-size:11px;color:#888;">
              ${img.category || 'uncategorized'} • ${new Date(img.created_at).toLocaleDateString()}
            </div>
          </div>
          <button class="secondary" style="font-size:11px;padding:4px 8px;" onclick="useSavedPrompt(\`${escapeHtml(img.prompt)}\`)">
            Use
          </button>
        </div>
      `).join('');
    } else {
      leonardoElements.historyList.innerHTML = '<div class="placeholder" style="text-align:center;padding:20px;color:#888;">No recent generations</div>';
    }
  } catch (e) {
    console.error('[AI Image] History error:', e);
  }
}

async function loadLeonardoPrompts() {
  try {
    const serverBase = getLeonardoApiBase();
    if (!serverBase) return;
    const category = leonardoElements.promptCategoryFilter?.value || '';
    const resp = await fetch(`${serverBase}/api/ai-images/prompts?limit=20${category ? `&category=${category}` : ''}`);
    const data = await resp.json();

    if (!leonardoElements.promptsGrid) return;

    if (data.success && data.prompts?.length > 0) {
      leonardoElements.promptsGrid.innerHTML = data.prompts.map(p => `
        <div style="padding:12px;background:#2a2a3e;border-radius:6px;cursor:pointer;" onclick="useSavedPrompt(\`${escapeHtml(p.prompt)}\`, '${p.category || ''}')">
          <div style="font-size:12px;color:#60a5fa;margin-bottom:4px;">${p.category || 'uncategorized'}</div>
          <div style="font-size:11px;color:#fff;margin-bottom:4px;font-weight:500;">${escapeHtml(p.keywords)}</div>
          <div style="font-size:10px;color:#888;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">
            ${escapeHtml(p.prompt.substring(0, 100))}...
          </div>
        </div>
      `).join('');
    } else {
      leonardoElements.promptsGrid.innerHTML = '<div class="placeholder" style="text-align:center;padding:20px;color:#888;">No saved prompts</div>';
    }
  } catch (e) {
    console.error('[AI Image] Prompts error:', e);
  }
}

window.useSavedPrompt = function(prompt, category) {
  if (leonardoElements.keywords) {
    leonardoElements.keywords.value = prompt;
  }
  if (category) {
    document.querySelectorAll('.leonardo-category-btn').forEach(btn => {
      btn.classList.toggle('active', btn.dataset.category === category);
    });
    leonardoState.category = category;
  }
};

async function handleLeonardoPreviewPrompt() {
  const keywords = leonardoElements.keywords?.value?.trim();
  if (!keywords) {
    alert('Please enter keywords or a description');
    return;
  }

  const serverBase = getLeonardoApiBase();
  if (!serverBase) {
    alert('Server not configured. Please set the server URL in Settings.');
    return;
  }

  showLeonardoProgress('Generating prompt with Claude...');

  try {
    const resp = await fetch(`${serverBase}/api/ai-images/prompt`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        keywords,
        category: leonardoState.category
      })
    });

    const data = await resp.json();
    hideLeonardoProgress();

    if (data.success && data.prompts?.[0]) {
      leonardoElements.promptPreview.style.display = 'block';
      leonardoElements.promptText.textContent = data.prompts[0];
    } else {
      alert('Error: ' + (data.error || 'Failed to generate prompt'));
    }
  } catch (e) {
    hideLeonardoProgress();
    alert('Error: ' + e.message);
  }
}

async function handleLeonardoGenerate() {
  const keywords = leonardoElements.keywords?.value?.trim();
  if (!keywords) {
    alert('Please enter keywords or a description');
    return;
  }

  const serverBase = getLeonardoApiBase();
  if (!serverBase) {
    alert('Server not configured. Please set the server URL in Settings.');
    return;
  }

  const numImages = parseInt(leonardoElements.numImages?.value || '1', 10);
  const model = leonardoElements.model?.value || 'PHOENIX_1_0';
  const addToArtwork = leonardoElements.addToArtwork?.checked !== false;

  showLeonardoProgress('Generating prompt with Claude...');

  try {
    // Step 1: Generate prompt
    setTimeout(() => {
      if (leonardoElements.progress.style.display !== 'none') {
        leonardoElements.progressText.textContent = 'Generating with Gemini...';
      }
    }, 2000);

    const resp = await fetch(`${serverBase}/api/ai-images/generate`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        keywords,
        aspectRatio: leonardoState.aspectRatio,
        numImages,
        model,
        category: leonardoState.category,
        addToArtwork
      })
    });

    const data = await resp.json();
    hideLeonardoProgress();

    if (data.success && data.images?.length > 0) {
      // Show the generated prompt
      if (data.steps?.promptGeneration?.prompt) {
        leonardoElements.promptPreview.style.display = 'block';
        leonardoElements.promptText.textContent = data.steps.promptGeneration.prompt;
      }

      // Add to results
      leonardoState.generatedImages = [...data.images, ...leonardoState.generatedImages];
      renderLeonardoResults();

      // Refresh history
      loadLeonardoHistory();
      loadLeonardoPrompts();

      // Update token count
      loadLeonardoStatus();

      // Clear input
      leonardoElements.keywords.value = '';
    } else {
      alert('Error: ' + (data.error || 'Failed to generate images'));
    }
  } catch (e) {
    hideLeonardoProgress();
    alert('Error: ' + e.message);
  }
}

function showLeonardoProgress(text) {
  if (leonardoElements.progress) {
    leonardoElements.progress.style.display = 'block';
  }
  if (leonardoElements.progressText) {
    leonardoElements.progressText.textContent = text;
  }
  if (leonardoElements.generateBtn) {
    leonardoElements.generateBtn.disabled = true;
  }
  if (leonardoElements.previewPromptBtn) {
    leonardoElements.previewPromptBtn.disabled = true;
  }
}

function hideLeonardoProgress() {
  if (leonardoElements.progress) {
    leonardoElements.progress.style.display = 'none';
  }
  if (leonardoElements.generateBtn) {
    leonardoElements.generateBtn.disabled = false;
  }
  if (leonardoElements.previewPromptBtn) {
    leonardoElements.previewPromptBtn.disabled = false;
  }
}

function renderLeonardoResults() {
  if (!leonardoElements.resultsGrid) return;

  if (leonardoState.generatedImages.length === 0) {
    leonardoElements.resultsGrid.innerHTML = `
      <div class="placeholder" style="grid-column:1/-1;text-align:center;padding:40px;color:#888;">
        Generated images will appear here
      </div>
    `;
    return;
  }

  const serverBase = getLeonardoApiBase();
  leonardoElements.resultsGrid.innerHTML = leonardoState.generatedImages.map(img => `
    <div style="position:relative;border-radius:8px;overflow:hidden;background:#1e1e2e;">
      <img src="${serverBase}${img.file_path || '/images/ai-generated/text-to-image/' + img.filename}"
           style="width:100%;aspect-ratio:1;object-fit:cover;"
           onerror="this.src='data:image/svg+xml,<svg xmlns=\\'http://www.w3.org/2000/svg\\' width=\\'200\\' height=\\'200\\'><rect fill=\\'%23333\\' width=\\'200\\' height=\\'200\\'/><text x=\\'50%\\' y=\\'50%\\' fill=\\'%23666\\' text-anchor=\\'middle\\' dy=\\'.3em\\'>Loading...</text></svg>'" />
      <div style="position:absolute;bottom:0;left:0;right:0;padding:8px;background:linear-gradient(transparent, rgba(0,0,0,0.8));">
        <div style="font-size:11px;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">
          ${img.category || 'Generated'}
        </div>
        <div style="display:flex;gap:4px;margin-top:4px;">
          <a href="${serverBase}${img.file_path || '/images/ai-generated/text-to-image/' + img.filename}" target="_blank"
             style="font-size:10px;color:#60a5fa;text-decoration:none;">View</a>
          ${img.artworkId ? `<span style="font-size:10px;color:#22c55e;">✓ In DB</span>` : ''}
        </div>
      </div>
    </div>
  `).join('');
}

// ==================================================================================
// HUMAN MODELS VIEW
// ==================================================================================

const humanModelsState = {
  initialized: false,
  models: [],
  categories: [],
  selectedIds: new Set(),
  currentModel: null,
  pendingImagePath: null
};

const humanModelsElements = {
  grid: null,
  search: null,
  categoryFilter: null,
  selectAllBtn: null,
  addBtn: null,
  bulkUploadBtn: null,
  bulkActionsBar: null,
  selectionCount: null,
  bulkCategorySelect: null,
  bulkStatusSelect: null,
  bulkClear: null,
  bulkAIMetadataBtn: null,
  formCard: null,
  formTitle: null,
  title: null,
  seoFilename: null,
  description: null,
  category: null,
  categoryList: null,
  poseType: null,
  gender: null,
  status: null,
  tags: null,
  selectImage: null,
  imageLabel: null,
  imagePreview: null,
  saveBtn: null,
  cancelBtn: null,
  deleteBtn: null,
  statusBar: null
};

function initHumanModelsElements() {
  humanModelsElements.grid = document.getElementById('humanModelsGrid');
  humanModelsElements.search = document.getElementById('humanModelsSearch');
  humanModelsElements.categoryFilter = document.getElementById('humanModelsCategoryFilter');
  humanModelsElements.selectAllBtn = document.getElementById('humanModelsSelectAllBtn');
  humanModelsElements.addBtn = document.getElementById('humanModelsAddBtn');
  humanModelsElements.bulkUploadBtn = document.getElementById('humanModelsBulkUploadBtn');
  humanModelsElements.bulkActionsBar = document.getElementById('humanModelsBulkActionsBar');
  humanModelsElements.selectionCount = document.getElementById('humanModelsSelectionCount');
  humanModelsElements.bulkCategorySelect = document.getElementById('humanModelsBulkCategorySelect');
  humanModelsElements.bulkStatusSelect = document.getElementById('humanModelsBulkStatusSelect');
  humanModelsElements.bulkClear = document.getElementById('humanModelsBulkClear');
  humanModelsElements.bulkGroupSelect = document.getElementById('humanModelsBulkGroupSelect');
  humanModelsElements.bulkAIMetadataBtn = document.getElementById('humanModelsBulkAIMetadata');
  humanModelsElements.formCard = document.getElementById('humanModelsFormCard');
  humanModelsElements.formTitle = document.getElementById('humanModelsFormTitle');
  humanModelsElements.title = document.getElementById('humanModelsTitle');
  humanModelsElements.seoFilename = document.getElementById('humanModelsSeoFilename');
  humanModelsElements.description = document.getElementById('humanModelsDescription');
  humanModelsElements.category = document.getElementById('humanModelsCategory');
  humanModelsElements.categoryList = document.getElementById('humanModelsCategoryList');
  humanModelsElements.poseType = document.getElementById('humanModelsPoseType');
  humanModelsElements.gender = document.getElementById('humanModelsGender');
  humanModelsElements.status = document.getElementById('humanModelsStatus');
  humanModelsElements.tags = document.getElementById('humanModelsTags');
  humanModelsElements.selectImage = document.getElementById('humanModelsSelectImage');
  humanModelsElements.imageLabel = document.getElementById('humanModelsImageLabel');
  humanModelsElements.imagePreview = document.getElementById('humanModelsImagePreview');
  humanModelsElements.saveBtn = document.getElementById('humanModelsSaveBtn');
  humanModelsElements.cancelBtn = document.getElementById('humanModelsCancelBtn');
  humanModelsElements.deleteBtn = document.getElementById('humanModelsDeleteBtn');
  humanModelsElements.statusBar = document.getElementById('humanModelsStatus');
}

function initHumanModelsView() {
  if (humanModelsState.initialized) {
    loadHumanModels();
    return;
  }

  initHumanModelsElements();

  // Search and filter
  if (humanModelsElements.search) {
    humanModelsElements.search.addEventListener('input', renderHumanModels);
  }
  if (humanModelsElements.categoryFilter) {
    humanModelsElements.categoryFilter.addEventListener('change', renderHumanModels);
  }

  // Select All button
  if (humanModelsElements.selectAllBtn) {
    humanModelsElements.selectAllBtn.addEventListener('click', () => {
      const allSelected = humanModelsState.models.length > 0 &&
                          humanModelsState.selectedIds.size === humanModelsState.models.length;
      if (allSelected) {
        humanModelsState.selectedIds.clear();
      } else {
        humanModelsState.models.forEach(m => humanModelsState.selectedIds.add(String(m.id)));
      }
      renderHumanModels();
    });
  }

  // Add button
  if (humanModelsElements.addBtn) {
    humanModelsElements.addBtn.addEventListener('click', () => showHumanModelForm());
  }

  // Bulk upload button
  if (humanModelsElements.bulkUploadBtn) {
    humanModelsElements.bulkUploadBtn.addEventListener('click', bulkUploadHumanModels);
  }

  // Bulk clear
  if (humanModelsElements.bulkClear) {
    humanModelsElements.bulkClear.addEventListener('click', () => {
      humanModelsState.selectedIds.clear();
      renderHumanModels();
    });
  }

  // Bulk category
  if (humanModelsElements.bulkCategorySelect) {
    humanModelsElements.bulkCategorySelect.addEventListener('change', async () => {
      let category = humanModelsElements.bulkCategorySelect.value;
      if (!category) return;
      if (category === '__new__') {
        category = prompt('Enter new category name:');
        if (!category || !category.trim()) {
          humanModelsElements.bulkCategorySelect.value = '';
          return;
        }
        category = category.trim();
      }
      await bulkUpdateHumanModels({ category });
      humanModelsElements.bulkCategorySelect.value = '';
    });
  }

  // Bulk status
  if (humanModelsElements.bulkStatusSelect) {
    humanModelsElements.bulkStatusSelect.addEventListener('change', async () => {
      const status = humanModelsElements.bulkStatusSelect.value;
      if (!status) return;
      await bulkUpdateHumanModels({ status });
      humanModelsElements.bulkStatusSelect.value = '';
    });
  }

  // Bulk add to group
  if (humanModelsElements.bulkGroupSelect) {
    humanModelsElements.bulkGroupSelect.addEventListener('change', async () => {
      let groupId = humanModelsElements.bulkGroupSelect.value;
      if (!groupId) return;
      if (groupId === '__new__') {
        const name = prompt('New group name:');
        if (!name || !name.trim()) {
          humanModelsElements.bulkGroupSelect.value = '';
          return;
        }
        try {
          const resp = await printStation.modelGroups.create({ name: name.trim() });
          groupId = resp.group?.id;
          if (!groupId) throw new Error('No group ID returned');
        } catch (err) {
          alert('Failed to create group: ' + (err.message || err));
          humanModelsElements.bulkGroupSelect.value = '';
          return;
        }
      }
      const modelIds = Array.from(humanModelsState.selectedIds);
      if (!modelIds.length) return;
      try {
        await printStation.modelGroups.addModels(groupId, modelIds);
        setHumanModelsStatus(`Added ${modelIds.length} model(s) to group`);
      } catch (err) {
        setHumanModelsStatus(`Failed to add to group: ${err.message}`, true);
      }
      humanModelsElements.bulkGroupSelect.value = '';
      loadHumanModelGroupsDropdown();
    });
    loadHumanModelGroupsDropdown();
  }

  // AI Metadata analysis button
  if (humanModelsElements.bulkAIMetadataBtn) {
    humanModelsElements.bulkAIMetadataBtn.addEventListener('click', analyzeSelectedHumanModels);
  }

  // Select image button
  if (humanModelsElements.selectImage) {
    humanModelsElements.selectImage.addEventListener('click', selectHumanModelImage);
  }

  // Save button
  if (humanModelsElements.saveBtn) {
    humanModelsElements.saveBtn.addEventListener('click', saveHumanModel);
  }

  // Cancel button
  if (humanModelsElements.cancelBtn) {
    humanModelsElements.cancelBtn.addEventListener('click', hideHumanModelForm);
  }

  // Delete button
  if (humanModelsElements.deleteBtn) {
    humanModelsElements.deleteBtn.addEventListener('click', deleteHumanModel);
  }

  // Grid click delegation
  if (humanModelsElements.grid) {
    humanModelsElements.grid.addEventListener('click', (e) => {
      // Handle Edit button
      const editBtn = e.target.closest('.human-model-edit-btn');
      if (editBtn) {
        e.stopPropagation();
        const modelId = editBtn.dataset.modelId;
        const model = humanModelsState.models.find(m => String(m.id) === modelId);
        if (model) showHumanModelForm(model);
        return;
      }

      // Handle card click for selection
      const card = e.target.closest('.custom-art-card[data-model-id]');
      if (card) {
        const modelId = card.dataset.modelId;
        if (humanModelsState.selectedIds.has(modelId)) {
          humanModelsState.selectedIds.delete(modelId);
        } else {
          humanModelsState.selectedIds.add(modelId);
        }
        renderHumanModels();
      }
    });
  }

  humanModelsState.initialized = true;
  loadHumanModels();
}

async function loadHumanModels() {
  setHumanModelsStatus('Loading models...');
  try {
    const [modelsResult, categoriesResult] = await Promise.all([
      printStation.humanModels.list({ activeOnly: false, limit: 1000 }),
      printStation.humanModels.getCategories()
    ]);
    humanModelsState.models = modelsResult?.models || [];
    humanModelsState.categories = categoriesResult?.categories || [];
    renderHumanModels();
    renderHumanModelsCategoryFilter();
    setHumanModelsStatus(`${humanModelsState.models.length} model(s) loaded`);
  } catch (e) {
    setHumanModelsStatus(`Error: ${e.message}`, true);
  }
}

function renderHumanModels() {
  if (!humanModelsElements.grid) return;

  const searchTerm = (humanModelsElements.search?.value || '').toLowerCase().trim();
  const categoryFilter = humanModelsElements.categoryFilter?.value || '';

  let filtered = humanModelsState.models;
  if (searchTerm) {
    filtered = filtered.filter(m =>
      (m.title || '').toLowerCase().includes(searchTerm) ||
      (m.description || '').toLowerCase().includes(searchTerm) ||
      (m.tags || '').toLowerCase().includes(searchTerm)
    );
  }
  if (categoryFilter) {
    filtered = filtered.filter(m => m.category === categoryFilter);
  }

  if (!filtered.length) {
    humanModelsElements.grid.innerHTML = '<div class="placeholder">No models found.</div>';
    updateHumanModelsSelectionUI();
    return;
  }

  humanModelsElements.grid.innerHTML = filtered.map(model => {
    const isSelected = humanModelsState.selectedIds.has(String(model.id));
    const imageSrc = resolveArtworkUrl(model.thumbnailPath || model.filePath);
    // Build metadata string from AI-analyzed fields
    const metaParts = [];
    if (model.gender) metaParts.push(model.gender);
    if (model.ethnicity) metaParts.push(model.ethnicity);
    if (model.apparelType || model.apparel_type) metaParts.push(model.apparelType || model.apparel_type);
    if (model.facing) metaParts.push(model.facing);
    const metaStr = metaParts.length ? metaParts.join(' • ') : (model.category || 'Uncategorized');
    return `
    <div class="custom-art-card ${isSelected ? 'selected' : ''}" data-model-id="${model.id}" style="cursor:pointer;">
      ${isSelected ? '<div style="position:absolute;top:8px;right:8px;background:#4a9;color:#fff;border-radius:50%;width:24px;height:24px;display:flex;align-items:center;justify-content:center;font-size:14px;">✓</div>' : ''}
      <img class="custom-art-card-image" src="${imageSrc}" alt="${model.title}" onerror="this.src='data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 75%22><rect fill=%22%231a1a2e%22 width=%22100%22 height=%2275%22/><text x=%2250%22 y=%2240%22 fill=%22%23666%22 text-anchor=%22middle%22 font-size=%228%22>No Image</text></svg>'"/>
      <div class="custom-art-card-body">
        <div class="custom-art-card-title">${model.title}</div>
        <div class="custom-art-card-meta">${metaStr}</div>
        ${model.poseType ? `<div style="font-size:10px;color:#888;margin-top:2px;">${model.poseType}</div>` : ''}
        <div style="display:flex;gap:6px;align-items:center;margin-top:6px;flex-wrap:wrap;">
          <span class="custom-art-card-badge ${model.status}">${model.status}</span>
          <button class="secondary human-model-edit-btn" data-model-id="${model.id}" style="padding:4px 8px;font-size:11px;">Edit</button>
        </div>
      </div>
    </div>
  `}).join('');

  updateHumanModelsSelectionUI();
}

async function loadHumanModelGroupsDropdown() {
  const select = humanModelsElements.bulkGroupSelect;
  if (!select) return;
  try {
    const resp = await printStation.modelGroups.list();
    const groups = resp.groups || resp || [];
    select.innerHTML = '<option value="">Add to Group...</option>' +
      '<option value="__new__">+ New Group...</option>' +
      groups.map(g => `<option value="${g.id}">${g.name} (${g.member_count || 0})</option>`).join('');
  } catch (err) {
    console.warn('[HumanModels] groups dropdown load failed:', err.message);
  }
}

function renderHumanModelsCategoryFilter() {
  if (!humanModelsElements.categoryFilter) return;
  const current = humanModelsElements.categoryFilter.value;
  humanModelsElements.categoryFilter.innerHTML = '<option value="">All Categories</option>' +
    humanModelsState.categories.map(c => `<option value="${c}">${c}</option>`).join('');
  humanModelsElements.categoryFilter.value = current;

  // Update datalist
  if (humanModelsElements.categoryList) {
    humanModelsElements.categoryList.innerHTML = humanModelsState.categories.map(c => `<option value="${c}">`).join('');
  }

  // Update bulk category dropdown
  if (humanModelsElements.bulkCategorySelect) {
    humanModelsElements.bulkCategorySelect.innerHTML = '<option value="">Set Category...</option>' +
      '<option value="__new__">+ New Category...</option>' +
      humanModelsState.categories.map(c => `<option value="${c}">${c}</option>`).join('');
  }
}

function updateHumanModelsSelectionUI() {
  const count = humanModelsState.selectedIds.size;

  if (humanModelsElements.bulkActionsBar) {
    humanModelsElements.bulkActionsBar.style.display = count > 0 ? 'flex' : 'none';
  }
  if (humanModelsElements.selectionCount) {
    humanModelsElements.selectionCount.textContent = `${count} selected`;
  }
  if (humanModelsElements.selectAllBtn) {
    const allSelected = humanModelsState.models.length > 0 && count === humanModelsState.models.length;
    humanModelsElements.selectAllBtn.textContent = allSelected ? 'Deselect All' : 'Select All';
  }

  document.querySelectorAll('.custom-art-card[data-model-id]').forEach(card => {
    const id = card.dataset.modelId;
    card.classList.toggle('selected', humanModelsState.selectedIds.has(id));
  });
}

function showHumanModelForm(model = null) {
  humanModelsState.currentModel = model;
  humanModelsState.pendingImagePath = null;

  if (humanModelsElements.formCard) {
    humanModelsElements.formCard.style.display = 'block';
  }
  if (humanModelsElements.formTitle) {
    humanModelsElements.formTitle.textContent = model ? 'Edit Model' : 'Add Model';
  }
  if (humanModelsElements.deleteBtn) {
    humanModelsElements.deleteBtn.style.display = model ? '' : 'none';
  }

  // Populate form fields
  if (humanModelsElements.title) humanModelsElements.title.value = model?.title || '';
  if (humanModelsElements.seoFilename) humanModelsElements.seoFilename.value = model?.seoFilename || '';
  if (humanModelsElements.description) humanModelsElements.description.value = model?.description || '';
  if (humanModelsElements.category) humanModelsElements.category.value = model?.category || '';
  if (humanModelsElements.poseType) humanModelsElements.poseType.value = model?.poseType || '';
  if (humanModelsElements.gender) humanModelsElements.gender.value = model?.gender || '';
  const statusEl = document.getElementById('humanModelsStatus');
  if (statusEl && statusEl.tagName === 'SELECT') statusEl.value = model?.status || 'active';
  if (humanModelsElements.tags) humanModelsElements.tags.value = model?.tags || '';

  // Image preview
  if (humanModelsElements.imageLabel) {
    humanModelsElements.imageLabel.textContent = model?.filePath ? 'Image selected' : 'No image selected';
  }
  if (humanModelsElements.imagePreview) {
    if (model?.filePath) {
      humanModelsElements.imagePreview.src = resolveArtworkUrl(model.thumbnailPath || model.filePath);
      humanModelsElements.imagePreview.style.display = 'block';
    } else {
      humanModelsElements.imagePreview.style.display = 'none';
    }
  }
}

function hideHumanModelForm() {
  humanModelsState.currentModel = null;
  humanModelsState.pendingImagePath = null;
  if (humanModelsElements.formCard) {
    humanModelsElements.formCard.style.display = 'none';
  }
}

async function selectHumanModelImage() {
  try {
    const result = await printStation.humanModels.selectFile({ title: 'Select Model Image' });
    if (result.canceled) return;

    setHumanModelsStatus('Uploading image...');
    const uploadResult = await printStation.humanModels.uploadFile(result.filePath);
    if (!uploadResult.success) {
      setHumanModelsStatus(`Upload failed: ${uploadResult.error}`, true);
      return;
    }

    humanModelsState.pendingImagePath = uploadResult.filePath;
    if (humanModelsElements.imageLabel) {
      humanModelsElements.imageLabel.textContent = uploadResult.filename;
    }
    if (humanModelsElements.imagePreview) {
      humanModelsElements.imagePreview.src = resolveArtworkUrl(uploadResult.thumbnailPath || uploadResult.filePath);
      humanModelsElements.imagePreview.style.display = 'block';
    }
    setHumanModelsStatus('Image uploaded');
  } catch (e) {
    setHumanModelsStatus(`Error: ${e.message}`, true);
  }
}

async function saveHumanModel() {
  const title = humanModelsElements.title?.value?.trim();
  if (!title) {
    setHumanModelsStatus('Title is required', true);
    return;
  }

  const filePath = humanModelsState.pendingImagePath || humanModelsState.currentModel?.filePath;
  if (!filePath && !humanModelsState.currentModel) {
    setHumanModelsStatus('Image is required', true);
    return;
  }

  const statusEl = document.getElementById('humanModelsStatus');
  const payload = {
    title,
    seoFilename: humanModelsElements.seoFilename?.value?.trim() || null,
    description: humanModelsElements.description?.value?.trim() || null,
    category: humanModelsElements.category?.value?.trim() || null,
    poseType: humanModelsElements.poseType?.value || null,
    gender: humanModelsElements.gender?.value || null,
    status: (statusEl && statusEl.tagName === 'SELECT') ? statusEl.value : 'active',
    tags: humanModelsElements.tags?.value?.trim() || null
  };

  if (humanModelsState.pendingImagePath) {
    payload.filePath = humanModelsState.pendingImagePath;
  }

  try {
    setHumanModelsStatus('Saving...');
    if (humanModelsState.currentModel) {
      await printStation.humanModels.update(humanModelsState.currentModel.id, payload);
    } else {
      payload.filePath = filePath;
      await printStation.humanModels.create(payload);
    }
    hideHumanModelForm();
    await loadHumanModels();
    setHumanModelsStatus('Model saved successfully');
  } catch (e) {
    setHumanModelsStatus(`Error: ${e.message}`, true);
  }
}

async function deleteHumanModel() {
  if (!humanModelsState.currentModel) return;
  if (!await nativeConfirm(`Delete "${humanModelsState.currentModel.title}"?`, 'Delete Model')) return;

  try {
    setHumanModelsStatus('Deleting...');
    await printStation.humanModels.delete(humanModelsState.currentModel.id);
    hideHumanModelForm();
    await loadHumanModels();
    setHumanModelsStatus('Model deleted');
  } catch (e) {
    setHumanModelsStatus(`Error: ${e.message}`, true);
  }
}

async function bulkUploadHumanModels() {
  try {
    const result = await printStation.humanModels.selectFiles({ title: 'Select Model Images or ZIP Files' });
    if (result.canceled || !result.filePaths.length) return;

    // Separate ZIP files from image files
    const zipFiles = [];
    const imageFiles = [];

    for (const filePath of result.filePaths) {
      const ext = filePath.toLowerCase().split('.').pop();
      if (ext === 'zip') {
        zipFiles.push(filePath);
      } else if (['png', 'jpg', 'jpeg', 'webp', 'gif'].includes(ext)) {
        imageFiles.push(filePath);
      }
    }

    // Extract images from ZIP files
    const tempDirs = [];
    if (zipFiles.length > 0) {
      setHumanModelsStatus(`Extracting ${zipFiles.length} ZIP file(s)...`);
      for (const zipPath of zipFiles) {
        try {
          const extractResult = await printStation.humanModels.extractZip(zipPath);
          if (extractResult.success && extractResult.extractedPaths) {
            imageFiles.push(...extractResult.extractedPaths);
            if (extractResult.tempDir) tempDirs.push(extractResult.tempDir);
          }
        } catch (e) {
          console.error('ZIP extraction failed:', e);
        }
      }
    }

    if (!imageFiles.length) {
      setHumanModelsStatus('No valid image files found', true);
      return;
    }

    setHumanModelsStatus(`Uploading ${imageFiles.length} image(s)...`);
    let successCount = 0;
    let failCount = 0;

    for (const filePath of imageFiles) {
      try {
        const uploadResult = await printStation.humanModels.uploadFile(filePath);
        if (!uploadResult.success) {
          console.error('Upload failed for:', filePath, uploadResult.error);
          failCount++;
          continue;
        }

        // Extract title from filename
        const filename = uploadResult.filename.replace(/\.[^/.]+$/, '').replace(/[-_]/g, ' ');
        const title = filename.charAt(0).toUpperCase() + filename.slice(1);

        await printStation.humanModels.create({
          title,
          filePath: uploadResult.filePath,
          thumbnailPath: uploadResult.thumbnailPath,
          status: 'draft'
        });
        successCount++;
      } catch (e) {
        console.error('Error creating model:', e);
        failCount++;
      }
    }

    // Clean up temp directories from ZIP extraction
    for (const dir of tempDirs) {
      try { await printStation.cleanupTempDir(dir); } catch (_) {}
    }

    await loadHumanModels();
    setHumanModelsStatus(`Uploaded ${successCount} model(s)${failCount > 0 ? `, ${failCount} failed` : ''}`);
  } catch (e) {
    setHumanModelsStatus(`Error: ${e.message}`, true);
  }
}

async function bulkUpdateHumanModels(updates) {
  const selectedIds = Array.from(humanModelsState.selectedIds);
  if (!selectedIds.length) return;

  setHumanModelsStatus(`Updating ${selectedIds.length} model(s)...`);
  let successCount = 0;

  for (const id of selectedIds) {
    try {
      await printStation.humanModels.update(id, updates);
      successCount++;
    } catch (e) {
      console.error('Bulk update failed for:', id, e);
    }
  }

  humanModelsState.selectedIds.clear();
  await loadHumanModels();
  setHumanModelsStatus(`Updated ${successCount} model(s)`);
}

async function analyzeSelectedHumanModels() {
  const selectedIds = Array.from(humanModelsState.selectedIds);
  if (!selectedIds.length) {
    setHumanModelsStatus('No models selected for analysis', true);
    return;
  }

  // Disable the button during analysis
  if (humanModelsElements.bulkAIMetadataBtn) {
    humanModelsElements.bulkAIMetadataBtn.disabled = true;
    humanModelsElements.bulkAIMetadataBtn.textContent = 'Analyzing...';
  }

  setHumanModelsStatus(`Analyzing ${selectedIds.length} model(s) with AI...`);
  let successCount = 0;
  let failCount = 0;

  for (let i = 0; i < selectedIds.length; i++) {
    const modelId = selectedIds[i];
    const model = humanModelsState.models.find(m => String(m.id) === modelId);

    setHumanModelsStatus(`Analyzing ${i + 1}/${selectedIds.length}: ${model?.title || modelId}...`);

    try {
      const result = await printStation.humanModels.analyzeMetadata(modelId);
      if (result.success) {
        successCount++;
        console.log(`[AI Metadata] ${modelId}:`, result.metadata);
      } else {
        console.error(`[AI Metadata] Failed for ${modelId}:`, result.error);
        failCount++;
      }
    } catch (e) {
      console.error('AI analysis failed for:', modelId, e);
      failCount++;
    }
  }

  // Re-enable the button
  if (humanModelsElements.bulkAIMetadataBtn) {
    humanModelsElements.bulkAIMetadataBtn.disabled = false;
    humanModelsElements.bulkAIMetadataBtn.textContent = 'AI Metadata';
  }

  humanModelsState.selectedIds.clear();
  await loadHumanModels();
  setHumanModelsStatus(`AI Analysis complete: ${successCount} success${failCount > 0 ? `, ${failCount} failed` : ''}`);
}

function setHumanModelsStatus(message, isError = false) {
  const statusBar = document.querySelector('#humanModelsView .status-bar');
  if (statusBar) {
    statusBar.textContent = message;
    statusBar.className = `status-bar ${isError ? 'danger' : 'muted'}`;
  }
}

