function openMetalPrintArtModal() {
  console.log('[Metal Print Art] openMetalPrintArtModal called');
  console.log('[Metal Print Art] metalPrintArtModal element:', elements.metalPrintArtModal);
  if (!elements.metalPrintArtModal) {
    console.error('[Metal Print Art] Modal element not found!');
    return;
  }
  openModal(elements.metalPrintArtModal);
  state.metalPrintArt.selected.clear();
  updateMetalPrintArtSelectedCount();
  loadMetalPrintArtwork();
}

function closeMetalPrintArtModal() {
  if (!elements.metalPrintArtModal) return;
  closeModal(elements.metalPrintArtModal);
}

function updateMetalPrintArtSelectedCount() {
  if (elements.metalPrintArtSelectedCount) {
    elements.metalPrintArtSelectedCount.textContent = `${state.metalPrintArt.selected.size} selected`;
  }
}

async function loadMetalPrintArtwork() {
  try {
    if (elements.metalPrintArtStatus) elements.metalPrintArtStatus.textContent = 'Loading artwork...';
    state.metalPrintArt.loading = true;

    const [artworkResult, categoriesResult] = await Promise.all([
      printStation.customArt.listArtwork({ activeOnly: true, limit: 1000 }),
      printStation.customArt.getArtworkCategories()
    ]);

    state.metalPrintArt.artworks = artworkResult?.artwork || [];
    state.metalPrintArt.categories = categoriesResult?.categories || [];

    renderMetalPrintArtCategoryFilter();
    renderMetalPrintArtGrid();

    if (elements.metalPrintArtStatus) {
      elements.metalPrintArtStatus.innerHTML = `<span id="metalPrintArtSelectedCount">${state.metalPrintArt.selected.size} selected</span> • ${state.metalPrintArt.artworks.length} artwork(s) available`;
    }
  } catch (e) {
    console.error('[Metal Print Art] Load error:', e);
    if (elements.metalPrintArtStatus) elements.metalPrintArtStatus.textContent = `Error: ${e.message}`;
  } finally {
    state.metalPrintArt.loading = false;
  }
}

function renderMetalPrintArtCategoryFilter() {
  const select = elements.metalPrintArtCategoryFilter;
  if (!select) return;
  const currentVal = select.value;
  select.innerHTML = '<option value="">All categories</option>' +
    state.metalPrintArt.categories.map(c => `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`).join('');
  select.value = currentVal;
}

function renderMetalPrintArtGrid() {
  const grid = elements.metalPrintArtGrid;
  if (!grid) return;

  const search = (elements.metalPrintArtSearch?.value || '').toLowerCase().trim();
  const category = elements.metalPrintArtCategoryFilter?.value || '';

  let filtered = state.metalPrintArt.artworks;

  if (search) {
    // Search across all text fields including cleaned title
    filtered = filtered.filter(a => {
      const cleanedTitle = (cleanAiGeneratedName(a.title) || '').toLowerCase();
      const rawTitle = (a.title || '').toLowerCase();
      const tags = (a.tags || '').toLowerCase();
      const description = (a.description || '').toLowerCase();
      const cat = (a.category || '').toLowerCase();
      const style = (a.style || '').toLowerCase();
      return cleanedTitle.includes(search) ||
             rawTitle.includes(search) ||
             tags.includes(search) ||
             description.includes(search) ||
             cat.includes(search) ||
             style.includes(search);
    });
  }

  if (category) {
    filtered = filtered.filter(a => a.category === category);
  }

  if (!filtered.length) {
    grid.innerHTML = '<div class="placeholder" style="padding:20px;text-align:center;">No artwork found. Add artwork in Custom Art first.</div>';
    return;
  }

  grid.innerHTML = filtered.map(art => {
    const isSelected = state.metalPrintArt.selected.has(String(art.id));
    const imageSrc = resolveArtworkUrl(art.thumbnailPath || art.optimizedPath || art.filePath, { width: 300, quality: 80 });
    const cleanedTitle = cleanAiGeneratedName(art.title) || art.title || 'Untitled';
    return `
      <div class="custom-art-card ${isSelected ? 'selected' : ''}" data-artwork-id="${art.id}" style="cursor:pointer;position:relative;">
        ${isSelected ? '<div style="position:absolute;top:8px;right:8px;background:#22d3ee;color:#000;padding:2px 8px;border-radius:4px;font-size:11px;font-weight:600;z-index:1;">Selected</div>' : ''}
        <img class="custom-art-card-image" src="${escapeHtml(imageSrc)}" alt="${escapeHtml(cleanedTitle)}" loading="lazy" onerror="this.src='data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 75%22><rect fill=%22%231a1a2e%22 width=%22100%22 height=%2275%22/><text x=%2250%22 y=%2240%22 fill=%22%23666%22 text-anchor=%22middle%22 font-size=%228%22>No Image</text></svg>'" />
        <div class="custom-art-card-body">
          <div class="custom-art-card-title">${escapeHtml(cleanedTitle)}</div>
          <div class="custom-art-card-meta">${escapeHtml(art.category || 'Uncategorized')}</div>
        </div>
      </div>
    `;
  }).join('');

  // Click handlers for selection
  grid.querySelectorAll('.custom-art-card').forEach(card => {
    card.addEventListener('click', () => {
      const id = String(card.getAttribute('data-artwork-id'));
      if (state.metalPrintArt.selected.has(id)) {
        state.metalPrintArt.selected.delete(id);
        card.classList.remove('selected');
      } else {
        state.metalPrintArt.selected.add(id);
        card.classList.add('selected');
      }
      updateMetalPrintArtSelectedCount();
    });
  });
}

async function addMetalPrintArtToCarpaign() {
  const selectedIds = Array.from(state.metalPrintArt.selected);
  if (!selectedIds.length) {
    showToast('Select at least one artwork.', 'warning');
    return;
  }

  // Get selected artwork items
  const selectedArtworks = state.metalPrintArt.artworks.filter(a => selectedIds.includes(String(a.id)));

  // Add each as a campaign item with metal-print type
  for (const art of selectedArtworks) {
    const imageSrc = resolveArtworkUrl(art.optimizedPath || art.filePath);

    // Check if already in campaign
    const exists = (state.campaign.items || []).some(it =>
      it.designId === String(art.id) && it.productType === 'metal-print'
    );
    if (exists) continue;

    const item = {
      name: art.title || 'Metal Print',
      productType: 'metal-print',
      designId: String(art.id),
      image: imageSrc,
      categorySlug: art.category || '',
      uid: `mp-${art.id}-${Date.now()}`,
      // Metal print specific - sizes will be variants
      metalPrintSizes: ['5x7', '8x10', '11x14'],
      // Source artwork info for processing
      sourceArtwork: {
        id: art.id,
        title: art.title,
        filePath: art.filePath,
        optimizedPath: art.optimizedPath,
        category: art.category
      }
    };

    state.campaign.items.push(item);
  }

  // Set campaign bulk type to metal-print so export uses metal print flow
  state.campaign.bulkType = 'metal-print';
  if (elements.campaignBulkTypeSelect) {
    elements.campaignBulkTypeSelect.value = 'metal-print';
  }

  renderCampaignItems();
  closeMetalPrintArtModal();
  showToast(`Added ${selectedArtworks.length} metal print item(s) to campaign.`, 'success');
}

