// =============== Sticker Sheets ===============
const stickerSheetsState = {
  categories: [],
  stickers: [],
  filteredStickers: [],
  selection: new Map(), // Map of imagePath -> { ...sticker, quantity }
  gridInfo: null,
  outputDir: null,
  initialized: false
};

async function initStickerSheetsView() {
  if (!stickerSheetsState.initialized) {
    stickerSheetsState.initialized = true;
    setupStickerSheetsEventListeners();
  }

  // Load categories and stickers
  await loadStickerCategories();
  await loadStickerCatalog();
  await updateGridInfo();
}

function setupStickerSheetsEventListeners() {
  // Category filter
  const categorySelect = document.getElementById('stickerSheetCategorySelect');
  if (categorySelect) {
    categorySelect.addEventListener('change', () => loadStickerCatalog(categorySelect.value));
  }

  // Search
  const searchInput = document.getElementById('stickerSheetSearch');
  if (searchInput) {
    searchInput.addEventListener('input', debounce(filterStickerCatalog, 300));
  }

  // Size change
  const sizeSelect = document.getElementById('stickerSheetSize');
  if (sizeSelect) {
    sizeSelect.addEventListener('change', updateGridInfo);
  }

  // Select all
  const selectAllBtn = document.getElementById('stickerSheetSelectAllBtn');
  if (selectAllBtn) {
    selectAllBtn.addEventListener('click', selectAllVisibleStickers);
  }

  // Clear selection
  const clearBtn = document.getElementById('stickerSheetClearBtn');
  if (clearBtn) {
    clearBtn.addEventListener('click', clearStickerSelection);
  }

  // Generate sheets
  const generateBtn = document.getElementById('stickerSheetGenerateBtn');
  if (generateBtn) {
    generateBtn.addEventListener('click', generateStickerSheets);
  }

  // Import from order
  const importOrderBtn = document.getElementById('stickerSheetImportOrderBtn');
  if (importOrderBtn) {
    importOrderBtn.addEventListener('click', importStickerOrder);
  }

  // View generated sheets button
  const viewSheetsBtn = document.getElementById('stickerSheetViewSheetsBtn');
  if (viewSheetsBtn) {
    viewSheetsBtn.addEventListener('click', openStickerSheetsBrowser);
  }
}

async function loadStickerCategories() {
  try {
    const result = await printStation.stickerSheets.getCategories();
    if (result?.success && result.categories) {
      stickerSheetsState.categories = result.categories;

      const select = document.getElementById('stickerSheetCategorySelect');
      if (select) {
        select.innerHTML = '<option value="">All Categories</option>' +
          result.categories.map(cat => `<option value="${cat}">${cat}</option>`).join('');
      }
    }
  } catch (err) {
    console.error('Failed to load sticker categories:', err);
  }
}

async function loadStickerCatalog(category = null) {
  const grid = document.getElementById('stickerSheetCatalogGrid');
  if (grid) {
    grid.innerHTML = '<div class="placeholder" style="grid-column:1/-1;text-align:center;padding:40px;">Loading stickers...</div>';
  }

  try {
    const result = await printStation.stickerSheets.getCatalog(category || undefined);
    if (result?.success && result.stickers) {
      stickerSheetsState.stickers = result.stickers;
      stickerSheetsState.filteredStickers = result.stickers;
      renderStickerCatalog();
    }
  } catch (err) {
    console.error('Failed to load sticker catalog:', err);
    if (grid) {
      grid.innerHTML = '<div class="placeholder" style="grid-column:1/-1;text-align:center;padding:40px;color:#f44;">Error loading stickers</div>';
    }
  }
}

function filterStickerCatalog() {
  const searchInput = document.getElementById('stickerSheetSearch');
  const query = (searchInput?.value || '').toLowerCase().trim();

  if (!query) {
    stickerSheetsState.filteredStickers = stickerSheetsState.stickers;
  } else {
    stickerSheetsState.filteredStickers = stickerSheetsState.stickers.filter(s =>
      s.title.toLowerCase().includes(query) ||
      s.category.toLowerCase().includes(query) ||
      s.filename.toLowerCase().includes(query)
    );
  }

  renderStickerCatalog();
}

function renderStickerCatalog() {
  const grid = document.getElementById('stickerSheetCatalogGrid');
  if (!grid) return;

  if (stickerSheetsState.filteredStickers.length === 0) {
    grid.innerHTML = '<div class="placeholder" style="grid-column:1/-1;text-align:center;padding:40px;">No stickers found</div>';
    return;
  }

  // Get the server base URL for thumbnail loading
  const serverUrl = window.APP_CONFIG?.serverUrl || 'https://store.swayzecustomvinyl.com';

  grid.innerHTML = stickerSheetsState.filteredStickers.map(sticker => {
    const isSelected = stickerSheetsState.selection.has(sticker.imagePath);
    const selectedClass = isSelected ? 'selected' : '';
    // Use thumbnailUrl from API if available, otherwise construct from imagePath
    const thumbnailSrc = sticker.thumbnailUrl
      ? `${serverUrl}${sticker.thumbnailUrl}`
      : `file://${sticker.imagePath.replace(/\\/g, '/')}`;

    return `
      <div class="sticker-card ${selectedClass}"
           data-path="${sticker.imagePath}"
           onclick="toggleStickerSelection('${sticker.imagePath.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}')"
           title="${sticker.title}\n${sticker.category}">
        <div class="sticker-thumb" style="background-image:url('${thumbnailSrc}');background-size:contain;background-position:center;background-repeat:no-repeat;aspect-ratio:1;"></div>
        <div class="sticker-title" style="font-size:10px;padding:4px;text-align:center;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">
          ${sticker.title}
        </div>
        ${isSelected ? `<div class="sticker-selected-badge" style="position:absolute;top:4px;right:4px;background:#4ade80;color:#000;font-size:10px;padding:2px 6px;border-radius:10px;">x${stickerSheetsState.selection.get(sticker.imagePath).quantity}</div>` : ''}
      </div>
    `;
  }).join('');
}

function toggleStickerSelection(imagePath) {
  if (stickerSheetsState.selection.has(imagePath)) {
    // Already selected - increment quantity
    const item = stickerSheetsState.selection.get(imagePath);
    item.quantity++;
  } else {
    // Add to selection
    const sticker = stickerSheetsState.stickers.find(s => s.imagePath === imagePath);
    if (sticker) {
      stickerSheetsState.selection.set(imagePath, { ...sticker, quantity: 1 });
    }
  }

  updateSelectionUI();
  renderStickerCatalog();
}

function removeFromSelection(imagePath) {
  stickerSheetsState.selection.delete(imagePath);
  updateSelectionUI();
  renderStickerCatalog();
}

function updateQuantity(imagePath, delta) {
  const item = stickerSheetsState.selection.get(imagePath);
  if (!item) return;

  item.quantity = Math.max(1, item.quantity + delta);
  updateSelectionUI();
  renderStickerCatalog();
}

function selectAllVisibleStickers() {
  for (const sticker of stickerSheetsState.filteredStickers) {
    if (!stickerSheetsState.selection.has(sticker.imagePath)) {
      stickerSheetsState.selection.set(sticker.imagePath, { ...sticker, quantity: 1 });
    }
  }
  updateSelectionUI();
  renderStickerCatalog();
}

function clearStickerSelection() {
  stickerSheetsState.selection.clear();
  updateSelectionUI();
  renderStickerCatalog();
}

function updateSelectionUI() {
  const countEl = document.getElementById('stickerSheetSelectionCount');
  const sheetsEl = document.getElementById('stickerSheetSheetsNeeded');
  const generateBtn = document.getElementById('stickerSheetGenerateBtn');
  const listEl = document.getElementById('stickerSheetSelectionList');

  // Count total stickers (including quantities)
  let totalCount = 0;
  for (const item of stickerSheetsState.selection.values()) {
    totalCount += item.quantity;
  }

  // Calculate sheets needed
  const capacity = stickerSheetsState.gridInfo?.capacity || 6;
  const sheetsNeeded = Math.ceil(totalCount / capacity);

  if (countEl) countEl.textContent = totalCount;
  if (sheetsEl) sheetsEl.textContent = sheetsNeeded;

  if (generateBtn) {
    generateBtn.disabled = totalCount === 0;
    generateBtn.textContent = `Generate Sheets (${totalCount})`;
  }

  // Render selection list
  if (listEl) {
    if (stickerSheetsState.selection.size === 0) {
      listEl.innerHTML = '<div class="placeholder" style="text-align:center;padding:20px;color:#888;">Click stickers to add them to your selection</div>';
    } else {
      const serverUrl = window.APP_CONFIG?.serverUrl || 'https://store.swayzecustomvinyl.com';
      listEl.innerHTML = Array.from(stickerSheetsState.selection.values()).map(item => {
        // Use thumbnailUrl from API if available
        const thumbSrc = item.thumbnailUrl ? `${serverUrl}${item.thumbnailUrl}` : `file://${item.imagePath.replace(/\\/g, '/')}`;
        return `
        <div class="selection-item" style="display:flex;align-items:center;gap:8px;padding:6px;border-bottom:1px solid rgba(255,255,255,0.1);">
          <div style="width:40px;height:40px;background-image:url('${thumbSrc}');background-size:contain;background-position:center;background-repeat:no-repeat;flex-shrink:0;"></div>
          <div style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px;">${item.title}</div>
          <div style="display:flex;align-items:center;gap:4px;">
            <button onclick="updateQuantity('${item.imagePath.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}', -1)" style="width:24px;height:24px;padding:0;font-size:14px;">-</button>
            <span style="min-width:20px;text-align:center;">${item.quantity}</span>
            <button onclick="updateQuantity('${item.imagePath.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}', 1)" style="width:24px;height:24px;padding:0;font-size:14px;">+</button>
            <button onclick="removeFromSelection('${item.imagePath.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}')" style="width:24px;height:24px;padding:0;font-size:12px;color:#f44;">&times;</button>
          </div>
        </div>
      `}).join('');
    }
  }
}

async function updateGridInfo() {
  const sizeSelect = document.getElementById('stickerSheetSize');
  const size = parseFloat(sizeSelect?.value || 3);

  try {
    const result = await printStation.stickerSheets.getGridInfo(size);
    if (result?.success && result.grid) {
      stickerSheetsState.gridInfo = result.grid;

      const infoEl = document.getElementById('stickerSheetGridInfo');
      if (infoEl) {
        infoEl.textContent = `Grid: ${result.grid.cols}x${result.grid.rows} (${result.grid.capacity} stickers per sheet) | Sheet: ${result.grid.sheetWidthInches}" x ${result.grid.sheetHeightInches}"`;
      }

      updateSelectionUI();
    }
  } catch (err) {
    console.error('Failed to get grid info:', err);
  }
}

async function generateStickerSheets() {
  const generateBtn = document.getElementById('stickerSheetGenerateBtn');
  const statusEl = document.getElementById('stickerSheetStatus');
  const outputInfoEl = document.getElementById('stickerSheetOutputInfo');
  const outputDetailsEl = document.getElementById('stickerSheetOutputDetails');

  if (stickerSheetsState.selection.size === 0) return;

  const sizeSelect = document.getElementById('stickerSheetSize');
  const size = parseFloat(sizeSelect?.value || 3);

  // Prepare designs array
  const designs = Array.from(stickerSheetsState.selection.values()).map(item => ({
    imagePath: item.imagePath,
    quantity: item.quantity,
    title: item.title
  }));

  if (generateBtn) {
    generateBtn.disabled = true;
    generateBtn.textContent = 'Generating...';
  }
  if (statusEl) statusEl.textContent = 'Generating sheets...';

  try {
    const result = await printStation.stickerSheets.generate({
      designs,
      stickerSizeInches: size,
      offsetMm: 3,
      filenamePrefix: 'sticker-sheet'
    });

    if (result?.success) {
      stickerSheetsState.outputDir = result.outputDir;

      if (statusEl) statusEl.textContent = `Generated ${result.totalSheets} sheet(s)`;

      if (outputInfoEl) outputInfoEl.style.display = 'block';
      if (outputDetailsEl) {
        outputDetailsEl.innerHTML = `
          <div style="font-size:13px;color:#666;">
            <div><strong>Total Stickers:</strong> ${result.totalStickers}</div>
            <div><strong>Sheets Generated:</strong> ${result.totalSheets}</div>
            <div><strong>Grid:</strong> ${result.grid.cols}x${result.grid.rows}</div>
            <div style="margin-top:8px;font-size:11px;color:#888;">
              Output: ${result.outputDir}
            </div>
          </div>
        `;
      }
    } else {
      if (statusEl) statusEl.textContent = `Error: ${result?.error || 'Unknown error'}`;
    }
  } catch (err) {
    console.error('Failed to generate sheets:', err);
    if (statusEl) statusEl.textContent = `Error: ${err.message}`;
  } finally {
    if (generateBtn) {
      generateBtn.disabled = false;
      let count = 0;
      for (const item of stickerSheetsState.selection.values()) count += item.quantity;
      generateBtn.textContent = `Generate Sheets (${count})`;
    }
  }
}

async function importStickerOrder() {
  const orderIdInput = document.getElementById('stickerSheetOrderId');
  const statusEl = document.getElementById('stickerSheetOrderStatus');
  const importBtn = document.getElementById('stickerSheetImportOrderBtn');

  const orderId = orderIdInput?.value?.trim();
  if (!orderId) {
    if (statusEl) statusEl.textContent = 'Please enter an order ID';
    return;
  }

  if (importBtn) {
    importBtn.disabled = true;
    importBtn.textContent = 'Importing...';
  }
  if (statusEl) statusEl.textContent = 'Fetching order...';

  const sizeSelect = document.getElementById('stickerSheetSize');
  const size = parseFloat(sizeSelect?.value || 3);

  try {
    const result = await printStation.stickerSheets.fromOrder({
      orderId,
      stickerSizeInches: size,
      offsetMm: 3
    });

    if (result?.success) {
      stickerSheetsState.outputDir = result.outputDir;

      if (statusEl) {
        statusEl.innerHTML = `Order #${result.orderNumber || orderId}: Generated ${result.totalSheets} sheet(s) with ${result.totalStickers} stickers`;
        if (result.notFound?.length) {
          statusEl.innerHTML += `<br><span style="color:#f90;">⚠ ${result.notFound.length} items not found in catalog</span>`;
        }
      }

      // Show output info
      const outputInfoEl = document.getElementById('stickerSheetOutputInfo');
      const outputDetailsEl = document.getElementById('stickerSheetOutputDetails');
      if (outputInfoEl) outputInfoEl.style.display = 'block';
      if (outputDetailsEl) {
        outputDetailsEl.innerHTML = `
          <div style="font-size:13px;color:#666;">
            <div><strong>Order:</strong> #${result.orderNumber || orderId}</div>
            <div><strong>Total Stickers:</strong> ${result.totalStickers}</div>
            <div><strong>Sheets Generated:</strong> ${result.totalSheets}</div>
            <div style="margin-top:8px;font-size:11px;color:#888;">
              Output: ${result.outputDir}
            </div>
          </div>
        `;
      }
    } else {
      if (statusEl) statusEl.textContent = `Error: ${result?.error || 'Unknown error'}`;
    }
  } catch (err) {
    console.error('Failed to import order:', err);
    if (statusEl) statusEl.textContent = `Error: ${err.message}`;
  } finally {
    if (importBtn) {
      importBtn.disabled = false;
      importBtn.textContent = 'Import';
    }
  }
}

// Sticker Sheets Browser Modal Functions
async function openStickerSheetsBrowser() {
  console.log('[StickerSheets] openStickerSheetsBrowser called');
  const modal = document.getElementById('stickerSheetsBrowserModal');
  const content = document.getElementById('stickerSheetsBrowserContent');

  console.log('[StickerSheets] modal element:', modal);
  console.log('[StickerSheets] content element:', content);

  if (!modal || !content) {
    console.error('[StickerSheets] Modal or content element not found!');
    return;
  }

  // Remove any blocking attributes set by the cleanup function
  modal.removeAttribute('hidden');
  modal.style.pointerEvents = '';
  modal.style.visibility = '';
  modal.style.display = 'flex';
  console.log('[StickerSheets] Modal display set to flex');
  content.innerHTML = '<div class="placeholder" style="text-align:center;padding:40px;color:#888;">Loading generated sheets...</div>';

  try {
    const result = await printStation.stickerSheets.list();

    if (!result?.success || !result.batches || result.batches.length === 0) {
      content.innerHTML = '<div class="placeholder" style="text-align:center;padding:40px;color:#888;">No sticker sheets have been generated yet.</div>';
      return;
    }

    const serverUrl = window.APP_CONFIG?.serverUrl || 'https://store.swayzecustomvinyl.com';

    content.innerHTML = result.batches.map(batch => {
      const createdDate = new Date(batch.createdAt);
      const dateStr = createdDate.toLocaleDateString('en-US', {
        year: 'numeric', month: 'short', day: 'numeric',
        hour: '2-digit', minute: '2-digit'
      });

      return `
        <div class="sticker-sheet-batch" style="border:1px solid var(--border);border-radius:8px;margin-bottom:16px;overflow:hidden;">
          <div style="background:var(--card);padding:12px 16px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;">
            <div>
              <strong style="font-size:14px;">${batch.name}</strong>
              <span style="color:#888;font-size:12px;margin-left:12px;">${batch.sheetCount} sheet${batch.sheetCount !== 1 ? 's' : ''}</span>
            </div>
            <span style="color:#888;font-size:12px;">${dateStr}</span>
          </div>
          <div style="padding:12px;display:grid;grid-template-columns:repeat(auto-fill, minmax(200px, 1fr));gap:12px;">
            ${batch.sheets.map(sheet => `
              <div style="border:1px solid var(--border);border-radius:6px;overflow:hidden;background:#1a1a2e;">
                <img src="${serverUrl}${sheet.printUrl}" alt="Sheet ${sheet.sheetNumber}"
                     style="width:100%;aspect-ratio:8.5/11;object-fit:contain;background:#111;"
                     onclick="window.open('${serverUrl}${sheet.printUrl}', '_blank')"
                     title="Click to open full size" />
                <div style="padding:8px;display:flex;flex-direction:column;gap:6px;align-items:center;">
                  <button class="btn primary" style="font-size:11px;padding:4px 12px;width:100%;"
                          onclick="downloadCricutFile('${sheet.cricutUrl ? serverUrl + sheet.cricutUrl : ''}', '${sheet.cricutFilename || 'cricut.svg'}')">
                    🎯 Download Cricut SVG
                  </button>
                  <div style="display:flex;gap:6px;width:100%;">
                    <button class="btn secondary" style="font-size:10px;padding:3px 8px;flex:1;"
                            onclick="downloadSingleFile('${serverUrl}${sheet.printUrl}', '${sheet.printFilename || 'print.png'}')">
                      Print PNG
                    </button>
                    <button class="btn secondary" style="font-size:10px;padding:3px 8px;flex:1;"
                            onclick="downloadSingleFile('${sheet.cutUrl ? serverUrl + sheet.cutUrl : ''}', '${sheet.cutFilename || 'cut.svg'}')">
                      Cut SVG
                    </button>
                  </div>
                </div>
              </div>
            `).join('')}
          </div>
        </div>
      `;
    }).join('');

  } catch (err) {
    console.error('Failed to load sticker sheets:', err);
    content.innerHTML = `<div class="placeholder" style="text-align:center;padding:40px;color:#f44;">Error loading sheets: ${err.message}</div>`;
  }
}

function closeStickerSheetsBrowser() {
  const modal = document.getElementById('stickerSheetsBrowserModal');
  if (modal) modal.style.display = 'none';
}

/**
 * Helper to trigger file download
 */
function triggerFileDownload(url, filename) {
  if (!url) return;
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.style.display = 'none';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
}

/**
 * Download the Cricut SVG file (embedded PNG print layer + vector cut paths)
 * Import this ONE file into Cricut Design Space for Print Then Cut
 */
function downloadCricutFile(cricutUrl, cricutFilename) {
  if (!cricutUrl) {
    alert('Cricut SVG not available for this sheet. Try regenerating the sticker sheets.');
    return;
  }
  triggerFileDownload(cricutUrl, cricutFilename);
}

/**
 * Download a single file (print PNG or cut SVG)
 */
function downloadSingleFile(url, filename) {
  if (!url) {
    alert('File not available.');
    return;
  }
  triggerFileDownload(url, filename);
}

/**
 * Download both print and cut files for a sticker sheet (legacy)
 */
function downloadStickerSheetFiles(printUrl, cutUrl, printFilename, cutFilename) {
  // Download print file first
  triggerFileDownload(printUrl, printFilename);

  // Download cut file after a small delay to avoid browser blocking
  if (cutUrl) {
    setTimeout(() => {
      triggerFileDownload(cutUrl, cutFilename);
    }, 500);
  }
}

// Make sticker sheet browser functions available globally for onclick handlers
window.toggleStickerSelection = toggleStickerSelection;
window.removeFromSelection = removeFromSelection;
window.updateQuantity = updateQuantity;
window.openStickerSheetsBrowser = openStickerSheetsBrowser;
window.closeStickerSheetsBrowser = closeStickerSheetsBrowser;
window.downloadStickerSheetFiles = downloadStickerSheetFiles;
window.downloadCricutFile = downloadCricutFile;
window.downloadSingleFile = downloadSingleFile;

// =============== Shopify Manager ===============
const shopifyManagerState = {
  products: [],
  collections: [],
  selectedProducts: new Set(),
  editingProduct: null,
  loading: false,
  initialized: false
};

async function initShopifyManager() {
  if (shopifyManagerState.initialized && shopifyManagerState.products.length > 0) {
    return; // Already loaded
  }

  // Set up event listeners once
  if (!shopifyManagerState.initialized) {
    shopifyManagerState.initialized = true;

    // Search and filters
    if (elements.shopifyManagerSearch) {
      elements.shopifyManagerSearch.addEventListener('input', debounce(renderShopifyProductList, 300));
    }
    if (elements.shopifyManagerCollectionFilter) {
      elements.shopifyManagerCollectionFilter.addEventListener('change', () => loadShopifyProducts(true));
    }
    if (elements.shopifyManagerStatusFilter) {
      elements.shopifyManagerStatusFilter.addEventListener('change', renderShopifyProductList);
    }
    if (elements.shopifyManagerRefreshBtn) {
      elements.shopifyManagerRefreshBtn.addEventListener('click', () => loadShopifyProducts(true));
    }

    // Edit panel
    if (elements.shopifyEditCancelBtn) {
      elements.shopifyEditCancelBtn.addEventListener('click', closeShopifyEditPanel);
    }
    if (elements.shopifyEditSaveBtn) {
      elements.shopifyEditSaveBtn.addEventListener('click', saveShopifyProduct);
    }

    // Bulk operations
    if (elements.shopifyBulkOperationSelect) {
      elements.shopifyBulkOperationSelect.addEventListener('change', handleBulkOperationChange);
    }
    if (elements.shopifyBulkApplyBtn) {
      elements.shopifyBulkApplyBtn.addEventListener('click', applyBulkOperation);
    }
    if (elements.shopifyBulkSelectAll) {
      elements.shopifyBulkSelectAll.addEventListener('click', selectAllShopifyProducts);
    }
    if (elements.shopifyBulkDeselectAll) {
      elements.shopifyBulkDeselectAll.addEventListener('click', deselectAllShopifyProducts);
    }
  }

  // Load data
  await Promise.all([
    loadShopifyProducts(),
    loadShopifyCollections()
  ]);
}

async function loadShopifyProducts(force = false) {
  if (shopifyManagerState.loading) return;
  shopifyManagerState.loading = true;

  try {
    if (elements.shopifyManagerRefreshBtn) {
      elements.shopifyManagerRefreshBtn.disabled = true;
      elements.shopifyManagerRefreshBtn.textContent = 'Loading...';
    }

    // Get collection filter value
    const collectionId = elements.shopifyManagerCollectionFilter?.value || '';
    const query = {};
    if (collectionId) {
      query.collection_id = collectionId;
    }

    const result = await printStation.shopifyManager.listProducts(query);
    shopifyManagerState.products = result.products || [];

    renderShopifyProductList();
    const collectionName = collectionId
      ? shopifyManagerState.collections.find(c => String(c.id) === collectionId)?.title || 'collection'
      : 'all';
    showToast(`Loaded ${shopifyManagerState.products.length} products from ${collectionName}`, 'success');
  } catch (err) {
    console.error('[Shopify Manager] Failed to load products:', err);
    showToast('Failed to load products: ' + (err.message || err), 'error');
  } finally {
    shopifyManagerState.loading = false;
    if (elements.shopifyManagerRefreshBtn) {
      elements.shopifyManagerRefreshBtn.disabled = false;
      elements.shopifyManagerRefreshBtn.textContent = 'Refresh';
    }
  }
}

async function loadShopifyCollections() {
  try {
    const result = await printStation.shopifyManager.listCollections();
    shopifyManagerState.collections = result.collections || [];

    // Populate collection filter dropdown
    if (elements.shopifyManagerCollectionFilter) {
      elements.shopifyManagerCollectionFilter.innerHTML = '<option value="">All Collections</option>';
      shopifyManagerState.collections.forEach(col => {
        const opt = document.createElement('option');
        opt.value = col.id;
        opt.textContent = col.title;
        elements.shopifyManagerCollectionFilter.appendChild(opt);
      });
    }
  } catch (err) {
    console.error('[Shopify Manager] Failed to load collections:', err);
  }
}

function getFilteredShopifyProducts() {
  let filtered = [...shopifyManagerState.products];

  // Search filter
  const search = (elements.shopifyManagerSearch?.value || '').toLowerCase().trim();
  if (search) {
    filtered = filtered.filter(p =>
      p.title.toLowerCase().includes(search) ||
      (p.vendor || '').toLowerCase().includes(search) ||
      (p.product_type || '').toLowerCase().includes(search) ||
      (p.tags || '').toLowerCase().includes(search)
    );
  }

  // Status filter
  const statusFilter = elements.shopifyManagerStatusFilter?.value || '';
  if (statusFilter) {
    filtered = filtered.filter(p => p.status === statusFilter);
  }

  return filtered;
}

function renderShopifyProductList() {
  const container = elements.shopifyManagerProductList;
  if (!container) return;

  const filtered = getFilteredShopifyProducts();

  // Update count
  if (elements.shopifyManagerProductCount) {
    elements.shopifyManagerProductCount.textContent = `${filtered.length} products`;
  }

  if (filtered.length === 0) {
    container.innerHTML = '<div class="shopify-empty-state">No products found</div>';
    return;
  }

  container.innerHTML = filtered.map(product => {
    const isSelected = shopifyManagerState.selectedProducts.has(String(product.id));
    const img = product.image?.src || product.images?.[0]?.src || '';
    const statusClass = product.status === 'active' ? 'status-active' : 'status-draft';

    return `
      <div class="shopify-product-item ${isSelected ? 'selected' : ''}" data-product-id="${product.id}">
        <input type="checkbox" class="shopify-product-checkbox" ${isSelected ? 'checked' : ''}>
        <div class="shopify-product-image">
          ${img ? `<img src="${img}" alt="${escapeHtml(product.title)}">` : '<div class="no-image">No Image</div>'}
        </div>
        <div class="shopify-product-info">
          <div class="shopify-product-title">${escapeHtml(product.title)}</div>
          <div class="shopify-product-meta">
            <span class="shopify-product-status ${statusClass}">${product.status}</span>
            ${product.product_type ? `<span class="shopify-product-type">${escapeHtml(product.product_type)}</span>` : ''}
            <span class="shopify-product-variants">${product.variants?.length || 0} variants</span>
          </div>
          <div class="shopify-product-price">
            ${product.variants?.[0]?.price ? `$${product.variants[0].price}` : ''}
            ${product.variants?.length > 1 ? '+' : ''}
          </div>
        </div>
        <button class="shopify-edit-btn" data-product-id="${product.id}">Edit</button>
      </div>
    `;
  }).join('');

  // Add event listeners
  container.querySelectorAll('.shopify-product-item').forEach(item => {
    const productId = item.dataset.productId;

    // Checkbox click
    const checkbox = item.querySelector('.shopify-product-checkbox');
    checkbox?.addEventListener('change', (e) => {
      e.stopPropagation();
      toggleShopifyProductSelection(productId);
    });

    // Edit button click
    const editBtn = item.querySelector('.shopify-edit-btn');
    editBtn?.addEventListener('click', (e) => {
      e.stopPropagation();
      openShopifyEditPanel(productId);
    });

    // Row click (toggle selection)
    item.addEventListener('click', (e) => {
      if (e.target.closest('.shopify-edit-btn') || e.target.closest('.shopify-product-checkbox')) return;
      toggleShopifyProductSelection(productId);
    });
  });

  updateBulkSelectedCount();
}

function toggleShopifyProductSelection(productId) {
  const id = String(productId);
  if (shopifyManagerState.selectedProducts.has(id)) {
    shopifyManagerState.selectedProducts.delete(id);
  } else {
    shopifyManagerState.selectedProducts.add(id);
  }
  renderShopifyProductList();
}

function selectAllShopifyProducts() {
  const filtered = getFilteredShopifyProducts();
  filtered.forEach(p => shopifyManagerState.selectedProducts.add(String(p.id)));
  renderShopifyProductList();
}

function deselectAllShopifyProducts() {
  shopifyManagerState.selectedProducts.clear();
  renderShopifyProductList();
}

function updateBulkSelectedCount() {
  if (elements.shopifyBulkSelectedCount) {
    const count = shopifyManagerState.selectedProducts.size;
    elements.shopifyBulkSelectedCount.textContent = `${count} selected`;
  }
}

async function openShopifyEditPanel(productId) {
  try {
    // Fetch full product details
    const result = await printStation.shopifyManager.getProduct(productId);
    const product = result.product;
    if (!product) {
      showToast('Product not found', 'error');
      return;
    }

    shopifyManagerState.editingProduct = product;

    // Populate form
    if (elements.shopifyEditTitle) elements.shopifyEditTitle.value = product.title || '';
    if (elements.shopifyEditDescription) elements.shopifyEditDescription.value = product.body_html || '';
    if (elements.shopifyEditTags) elements.shopifyEditTags.value = product.tags || '';
    if (elements.shopifyEditStatus) elements.shopifyEditStatus.value = product.status || 'draft';
    if (elements.shopifyEditProductType) elements.shopifyEditProductType.value = product.product_type || '';
    if (elements.shopifyEditVendor) elements.shopifyEditVendor.value = product.vendor || '';

    // Render variants
    renderShopifyEditVariants(product.variants || []);

    // Show edit form, hide placeholder
    if (elements.shopifyManagerEditForm) elements.shopifyManagerEditForm.style.display = 'block';
    if (elements.shopifyManagerEditPlaceholder) elements.shopifyManagerEditPlaceholder.style.display = 'none';
  } catch (err) {
    console.error('[Shopify Manager] Failed to load product:', err);
    showToast('Failed to load product: ' + (err.message || err), 'error');
  }
}

function renderShopifyEditVariants(variants) {
  const container = elements.shopifyEditVariants;
  if (!container) return;

  if (!variants || variants.length === 0) {
    container.innerHTML = '<div class="no-variants">No variants</div>';
    return;
  }

  container.innerHTML = variants.map(v => `
    <div class="shopify-variant-row" data-variant-id="${v.id}">
      <div class="variant-title">${escapeHtml(v.title || 'Default')}</div>
      <div class="variant-fields">
        <label>
          Price
          <input type="number" step="0.01" class="variant-price" value="${v.price || 0}">
        </label>
        <label>
          Compare at
          <input type="number" step="0.01" class="variant-compare-price" value="${v.compare_at_price || ''}">
        </label>
        <label>
          SKU
          <input type="text" class="variant-sku" value="${escapeHtml(v.sku || '')}">
        </label>
        <label>
          Inventory
          <input type="number" class="variant-inventory" value="${v.inventory_quantity || 0}">
        </label>
      </div>
    </div>
  `).join('');
}

function closeShopifyEditPanel() {
  shopifyManagerState.editingProduct = null;
  // Hide edit form, show placeholder
  if (elements.shopifyManagerEditForm) elements.shopifyManagerEditForm.style.display = 'none';
  if (elements.shopifyManagerEditPlaceholder) elements.shopifyManagerEditPlaceholder.style.display = 'block';
}

async function saveShopifyProduct() {
  const product = shopifyManagerState.editingProduct;
  if (!product) return;

  try {
    if (elements.shopifyEditSaveBtn) {
      elements.shopifyEditSaveBtn.disabled = true;
      elements.shopifyEditSaveBtn.textContent = 'Saving...';
    }

    // Gather product updates
    const updates = {
      title: elements.shopifyEditTitle?.value || product.title,
      body_html: elements.shopifyEditDescription?.value || '',
      tags: elements.shopifyEditTags?.value || '',
      status: elements.shopifyEditStatus?.value || 'draft',
      product_type: elements.shopifyEditProductType?.value || '',
      vendor: elements.shopifyEditVendor?.value || ''
    };

    // Gather variant updates
    const variantRows = elements.shopifyEditVariants?.querySelectorAll('.shopify-variant-row') || [];
    const variants = [];
    variantRows.forEach(row => {
      const variantId = row.dataset.variantId;
      const price = row.querySelector('.variant-price')?.value;
      const comparePrice = row.querySelector('.variant-compare-price')?.value;
      const sku = row.querySelector('.variant-sku')?.value;
      const inventory = row.querySelector('.variant-inventory')?.value;

      variants.push({
        id: variantId,
        price: price || '0',
        compare_at_price: comparePrice || null,
        sku: sku || '',
        inventory_quantity: parseInt(inventory, 10) || 0
      });
    });

    updates.variants = variants;

    // Save
    await printStation.shopifyManager.updateProduct(product.id, updates);

    showToast('Product saved successfully', 'success');
    closeShopifyEditPanel();

    // Refresh the list
    await loadShopifyProducts(true);
  } catch (err) {
    console.error('[Shopify Manager] Failed to save product:', err);
    showToast('Failed to save product: ' + (err.message || err), 'error');
  } finally {
    if (elements.shopifyEditSaveBtn) {
      elements.shopifyEditSaveBtn.disabled = false;
      elements.shopifyEditSaveBtn.textContent = 'Save Changes';
    }
  }
}

function handleBulkOperationChange() {
  const operation = elements.shopifyBulkOperationSelect?.value || '';

  // Hide all input groups
  if (elements.shopifyBulkValueInput) elements.shopifyBulkValueInput.style.display = 'none';
  if (elements.shopifyBulkPriceInputs) elements.shopifyBulkPriceInputs.style.display = 'none';
  if (elements.shopifyBulkInventoryInputs) elements.shopifyBulkInventoryInputs.style.display = 'none';
  if (elements.shopifyBulkTagsInputs) elements.shopifyBulkTagsInputs.style.display = 'none';

  // Show relevant input group
  switch (operation) {
    case 'adjust_price':
      if (elements.shopifyBulkPriceInputs) elements.shopifyBulkPriceInputs.style.display = 'flex';
      break;
    case 'set_inventory':
      if (elements.shopifyBulkInventoryInputs) elements.shopifyBulkInventoryInputs.style.display = 'flex';
      break;
    case 'add_tags':
    case 'remove_tags':
      if (elements.shopifyBulkTagsInputs) elements.shopifyBulkTagsInputs.style.display = 'flex';
      break;
    case 'set_status_active':
    case 'set_status_draft':
      // No additional inputs needed
      break;
  }
}

async function applyBulkOperation() {
  const operation = elements.shopifyBulkOperationSelect?.value || '';
  const selectedIds = Array.from(shopifyManagerState.selectedProducts);

  if (selectedIds.length === 0) {
    showToast('Please select products first', 'warning');
    return;
  }

  if (!operation) {
    showToast('Please select an operation', 'warning');
    return;
  }

  try {
    if (elements.shopifyBulkApplyBtn) {
      elements.shopifyBulkApplyBtn.disabled = true;
      elements.shopifyBulkApplyBtn.textContent = 'Applying...';
    }
    if (elements.shopifyBulkStatus) {
      elements.shopifyBulkStatus.textContent = `Processing ${selectedIds.length} products...`;
    }

    const payload = {
      operation,
      productIds: selectedIds
    };

    // Add operation-specific values
    switch (operation) {
      case 'adjust_price':
        payload.adjustType = elements.shopifyBulkPriceAdjustType?.value || 'percent';
        payload.adjustValue = parseFloat(elements.shopifyBulkPriceAdjustValue?.value || 0);
        break;
      case 'set_inventory':
        payload.inventoryValue = parseInt(elements.shopifyBulkInventoryValue?.value || 0, 10);
        break;
      case 'add_tags':
      case 'remove_tags':
        payload.tags = elements.shopifyBulkTagsValue?.value || '';
        break;
      case 'set_status_active':
        payload.status = 'active';
        break;
      case 'set_status_draft':
        payload.status = 'draft';
        break;
    }

    const result = await printStation.shopifyManager.bulkUpdate(payload);

    const successCount = result.results?.filter(r => r.success).length || 0;
    const failCount = result.results?.filter(r => !r.success).length || 0;

    if (elements.shopifyBulkStatus) {
      elements.shopifyBulkStatus.textContent = `Completed: ${successCount} success, ${failCount} failed`;
    }

    showToast(`Bulk operation complete: ${successCount} updated`, failCount > 0 ? 'warning' : 'success');

    // Refresh product list
    await loadShopifyProducts(true);
  } catch (err) {
    console.error('[Shopify Manager] Bulk operation failed:', err);
    showToast('Bulk operation failed: ' + (err.message || err), 'error');
    if (elements.shopifyBulkStatus) {
      elements.shopifyBulkStatus.textContent = 'Operation failed';
    }
  } finally {
    if (elements.shopifyBulkApplyBtn) {
      elements.shopifyBulkApplyBtn.disabled = false;
      elements.shopifyBulkApplyBtn.textContent = 'Apply to Selected';
    }
  }
}

// =====================================================
// Shopify Product Sync - Fix all existing products
// =====================================================
const shopifySyncElements = {
  syncBtn: document.getElementById('shopifySyncAllBtn'),
  inventoryInput: document.getElementById('shopifySyncInventoryInput'),
  progressContainer: document.getElementById('shopifySyncProgressContainer'),
  progressBar: document.getElementById('shopifySyncProgressBar'),
  progressLabel: document.getElementById('shopifySyncProgressLabel'),
  syncLog: document.getElementById('shopifySyncLog')
};

function appendShopifySyncLog(html, type = 'info') {
  if (!shopifySyncElements.syncLog) return;
  const entry = document.createElement('div');
  entry.style.padding = '2px 0';
  entry.style.borderBottom = '1px solid rgba(255,255,255,0.05)';
  entry.innerHTML = html;
  shopifySyncElements.syncLog.appendChild(entry);
  shopifySyncElements.syncLog.scrollTop = shopifySyncElements.syncLog.scrollHeight;
}

function updateShopifySyncProgress(current, total) {
  if (!shopifySyncElements.progressBar || !shopifySyncElements.progressLabel) return;
  const pct = total > 0 ? Math.round((current / total) * 100) : 0;
  shopifySyncElements.progressBar.style.width = `${pct}%`;
  shopifySyncElements.progressLabel.textContent = `${current}/${total}`;
}

async function startShopifyProductSync() {
  if (!shopifySyncElements.syncBtn) return;

  const serverUrl = state.config?.serverBaseUrl || '';
  if (!serverUrl) {
    showToast('Server URL not configured. Go to Settings first.', 'error');
    return;
  }

  const defaultInventory = parseInt(shopifySyncElements.inventoryInput?.value || '999', 10);
  const apiKey = state.config?.apiKey || 'internal';

  // Reset UI
  shopifySyncElements.syncBtn.disabled = true;
  shopifySyncElements.syncBtn.textContent = 'Syncing...';
  shopifySyncElements.progressContainer.style.display = 'block';
  shopifySyncElements.syncLog.style.display = 'block';
  shopifySyncElements.syncLog.innerHTML = '';
  updateShopifySyncProgress(0, 0);

  try {
    const response = await fetch(`${serverUrl}/api/admin/shopify/sync-all-products`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey
      },
      body: JSON.stringify({ defaultInventory })
    });

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() || '';

      for (const line of lines) {
        if (line.startsWith('data: ')) {
          try {
            const data = JSON.parse(line.slice(6));
            handleShopifySyncEvent(data);
          } catch (e) {
            // Ignore parse errors
          }
        }
      }
    }

    showToast('Shopify product sync complete!', 'success');

  } catch (error) {
    showToast(`Sync error: ${error.message}`, 'error');
    appendShopifySyncLog(`<span style="color:#ef4444;">Error: ${error.message}</span>`, 'error');
  } finally {
    shopifySyncElements.syncBtn.disabled = false;
    shopifySyncElements.syncBtn.textContent = 'Sync All Products';
  }
}

function handleShopifySyncEvent(data) {
  if (data.message) {
    if (data.total !== undefined) {
      // Complete event
      appendShopifySyncLog(`<strong style="color:#10b981;">${escapeHtmlForSync(data.message)}</strong>`, 'complete');
    } else {
      appendShopifySyncLog(`<span style="color:#94a3b8;">${escapeHtmlForSync(data.message)}</span>`, 'status');
    }
  }

  if (data.index !== undefined && data.total !== undefined) {
    updateShopifySyncProgress(data.index, data.total);

    if (data.error) {
      appendShopifySyncLog(
        `<span style="color:#ef4444;">✗ [${data.index}/${data.total}] ${escapeHtmlForSync(data.title)} - ${escapeHtmlForSync(data.error)}</span>`,
        'error'
      );
    } else if (data.actions) {
      const actionsHtml = data.actions.map(a => `<span style="color:#64748b;font-size:10px;margin-left:8px;">• ${escapeHtmlForSync(a)}</span>`).join('<br>');
      appendShopifySyncLog(
        `<span style="color:#10b981;">✓</span> [${data.index}/${data.total}] ${escapeHtmlForSync(data.title)}<br>${actionsHtml}`,
        'product'
      );
    }
  }
}

function escapeHtmlForSync(text) {
  const div = document.createElement('div');
  div.textContent = text || '';
  return div.innerHTML;
}

// Bind sync button
if (shopifySyncElements.syncBtn) {
  shopifySyncElements.syncBtn.addEventListener('click', startShopifyProductSync);
}

// ============================================================================
// PRINTER VIEW
// ============================================================================

// Printer state
const printerState = {
  selectedFile: null,
  selectedFilePath: null,
  printers: [],
  defaultPrinter: null,
  handlersInitialized: false
};

// Format file size
function formatFileSize(bytes) {
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return (bytes / (1024 * 1024)).toFixed(2) + ' MB';
}

// Initialize printer view
async function initPrinterView() {
  console.log('[Printer] Initializing view');

  // Load printers
  await loadPrinters();

  // Initialize event handlers (only once)
  if (!printerState.handlersInitialized) {
    initPrinterHandlers();
    printerState.handlersInitialized = true;
  }
}

// Load available printers
async function loadPrinters() {
  const printerSelect = document.getElementById('printerSelect');
  const defaultIndicator = document.getElementById('printerDefaultIndicator');

  if (!printerSelect) return;

  printerSelect.innerHTML = '<option value="">Loading printers...</option>';

  try {
    const result = await printStation.printer.getPrinters();

    if (!result.success || !result.printers.length) {
      printerSelect.innerHTML = '<option value="">No printers found</option>';
      if (defaultIndicator) defaultIndicator.textContent = '';
      return;
    }

    printerState.printers = result.printers;
    printerState.defaultPrinter = result.printers.find(p => p.isDefault);

    // Populate dropdown
    printerSelect.innerHTML = result.printers.map(p =>
      `<option value="${p.name}" ${p.isDefault ? 'selected' : ''}>${p.displayName || p.name}</option>`
    ).join('');

    // Show default indicator
    if (defaultIndicator && printerState.defaultPrinter) {
      defaultIndicator.textContent = `Default: ${printerState.defaultPrinter.displayName || printerState.defaultPrinter.name}`;
    }

    console.log('[Printer] Loaded', result.printers.length, 'printers');
  } catch (error) {
    console.error('[Printer] Error loading printers:', error);
    printerSelect.innerHTML = '<option value="">Error loading printers</option>';
  }
}

// Initialize printer event handlers
function initPrinterHandlers() {
  console.log('[Printer] Initializing handlers');

  // Drop zone
  const dropZone = document.getElementById('printerDropZone');
  const fileInput = document.getElementById('printerFileInput');

  if (dropZone) {
    dropZone.addEventListener('click', async () => {
      const result = await printStation.printer.selectFile();
      if (result.success) {
        handleFileSelected(result);
      }
    });

    dropZone.addEventListener('dragover', (e) => {
      e.preventDefault();
      dropZone.style.borderColor = '#3b82f6';
      dropZone.style.background = '#f0f7ff';
    });

    dropZone.addEventListener('dragleave', () => {
      dropZone.style.borderColor = '#ccc';
      dropZone.style.background = '';
    });

    dropZone.addEventListener('drop', (e) => {
      e.preventDefault();
      dropZone.style.borderColor = '#ccc';
      dropZone.style.background = '';

      const files = e.dataTransfer.files;
      if (files.length > 0) {
        const file = files[0];
        if (file.type.startsWith('image/')) {
          handleFileSelected({
            success: true,
            path: file.path,
            name: file.name,
            size: file.size
          });
        } else {
          showToast('Please select an image file', 'error');
        }
      }
    });
  }

  // File input fallback
  if (fileInput) {
    fileInput.addEventListener('change', (e) => {
      const file = e.target.files[0];
      if (file) {
        handleFileSelected({
          success: true,
          path: file.path,
          name: file.name,
          size: file.size
        });
      }
    });
  }

  // Clear file button
  const clearBtn = document.getElementById('printerClearFile');
  if (clearBtn) {
    clearBtn.addEventListener('click', clearSelectedFile);
  }

  // Refresh printers button
  const refreshBtn = document.getElementById('printerRefreshBtn');
  if (refreshBtn) {
    refreshBtn.addEventListener('click', loadPrinters);
  }

  // Paper size change - show/hide custom size inputs
  const paperSizeSelect = document.getElementById('printerPaperSize');
  const customSizeGroup = document.getElementById('printerCustomSizeGroup');
  if (paperSizeSelect && customSizeGroup) {
    paperSizeSelect.addEventListener('change', () => {
      customSizeGroup.style.display = paperSizeSelect.value === 'Custom' ? 'block' : 'none';
    });
  }

  // DPI change - show/hide custom DPI input
  const dpiSelect = document.getElementById('printerDpi');
  const customDpiInput = document.getElementById('printerCustomDpi');
  if (dpiSelect && customDpiInput) {
    dpiSelect.addEventListener('change', () => {
      customDpiInput.style.display = dpiSelect.value === 'Custom' ? 'block' : 'none';
    });
  }

  // Print button
  const printBtn = document.getElementById('printerPrintBtn');
  if (printBtn) {
    printBtn.addEventListener('click', handlePrint);
  }

  // Print with dialog button
  const printDialogBtn = document.getElementById('printerPrintDialogBtn');
  if (printDialogBtn) {
    printDialogBtn.addEventListener('click', handlePrintWithDialog);
  }

  // Save as PDF button
  const savePdfBtn = document.getElementById('printerSavePdfBtn');
  if (savePdfBtn) {
    savePdfBtn.addEventListener('click', handleSavePdf);
  }
}

// Handle file selection
function handleFileSelected(result) {
  if (!result.success) return;

  printerState.selectedFile = result;
  printerState.selectedFilePath = result.path;

  // Update UI
  const selectedFileDiv = document.getElementById('printerSelectedFile');
  const fileNameSpan = document.getElementById('printerFileName');
  const fileSizeSpan = document.getElementById('printerFileSize');
  const dropZone = document.getElementById('printerDropZone');
  const previewImg = document.getElementById('printerPreviewImage');
  const previewPlaceholder = document.getElementById('printerPreviewPlaceholder');
  const imageInfo = document.getElementById('printerImageInfo');
  const imageDimensions = document.getElementById('printerImageDimensions');
  const printBtn = document.getElementById('printerPrintBtn');
  const statusEl = document.getElementById('printerStatus');

  // Show file info
  if (selectedFileDiv) selectedFileDiv.style.display = 'block';
  if (fileNameSpan) fileNameSpan.textContent = result.name;
  if (fileSizeSpan) fileSizeSpan.textContent = formatFileSize(result.size);
  if (dropZone) dropZone.style.display = 'none';

  // Show preview
  if (previewImg && previewPlaceholder) {
    previewPlaceholder.style.display = 'none';
    previewImg.style.display = 'block';
    previewImg.src = `file://${result.path.replace(/\\/g, '/')}`;

    // Get image dimensions once loaded
    previewImg.onload = () => {
      if (imageInfo && imageDimensions) {
        imageInfo.style.display = 'block';
        imageDimensions.textContent = `${previewImg.naturalWidth} x ${previewImg.naturalHeight} pixels`;
      }
    };
  }

  // Enable print button
  if (printBtn) printBtn.disabled = false;

  // Update status
  if (statusEl) statusEl.textContent = 'Ready to print';

  console.log('[Printer] File selected:', result.path);
}

// Clear selected file
function clearSelectedFile() {
  printerState.selectedFile = null;
  printerState.selectedFilePath = null;

  const selectedFileDiv = document.getElementById('printerSelectedFile');
  const dropZone = document.getElementById('printerDropZone');
  const previewImg = document.getElementById('printerPreviewImage');
  const previewPlaceholder = document.getElementById('printerPreviewPlaceholder');
  const imageInfo = document.getElementById('printerImageInfo');
  const printBtn = document.getElementById('printerPrintBtn');
  const statusEl = document.getElementById('printerStatus');

  if (selectedFileDiv) selectedFileDiv.style.display = 'none';
  if (dropZone) dropZone.style.display = 'block';
  if (previewImg) {
    previewImg.style.display = 'none';
    previewImg.src = '';
  }
  if (previewPlaceholder) previewPlaceholder.style.display = 'block';
  if (imageInfo) imageInfo.style.display = 'none';
  if (printBtn) printBtn.disabled = true;
  if (statusEl) statusEl.textContent = 'Select an image to print';
}

// Get current print settings
function getPrintSettings() {
  return {
    printerName: document.getElementById('printerSelect')?.value,
    paperSize: document.getElementById('printerPaperSize')?.value,
    customWidth: parseFloat(document.getElementById('printerCustomWidth')?.value) || 8.5,
    customHeight: parseFloat(document.getElementById('printerCustomHeight')?.value) || 11,
    paperType: document.getElementById('printerPaperType')?.value,
    quality: document.getElementById('printerQuality')?.value,
    dpi: document.getElementById('printerDpi')?.value === 'Custom'
      ? parseInt(document.getElementById('printerCustomDpi')?.value) || 300
      : parseInt(document.getElementById('printerDpi')?.value) || 300,
    colorMode: document.getElementById('printerColorMode')?.value,
    orientation: document.getElementById('printerOrientation')?.value,
    fitMode: document.getElementById('printerFitMode')?.value,
    copies: parseInt(document.getElementById('printerCopies')?.value) || 1
  };
}

// Handle print
async function handlePrint() {
  if (!printerState.selectedFilePath) {
    showToast('Please select an image first', 'error');
    return;
  }

  const settings = getPrintSettings();
  const statusEl = document.getElementById('printerPrintStatus');

  if (statusEl) statusEl.textContent = 'Sending to printer...';

  try {
    const result = await printStation.printer.print({
      imagePath: printerState.selectedFilePath,
      printerName: settings.printerName,
      copies: settings.copies,
      color: settings.colorMode !== 'BlackWhite',
      landscape: settings.orientation === 'Landscape' ||
        (settings.orientation === 'Auto' && printerState.selectedFile &&
         document.getElementById('printerPreviewImage')?.naturalWidth >
         document.getElementById('printerPreviewImage')?.naturalHeight)
    });

    if (result.success) {
      showToast('Print job sent successfully', 'success');
      if (statusEl) statusEl.textContent = 'Print job sent!';
    } else {
      showToast(`Print failed: ${result.error}`, 'error');
      if (statusEl) statusEl.textContent = 'Print failed';
    }
  } catch (error) {
    console.error('[Printer] Print error:', error);
    showToast('Print failed: ' + error.message, 'error');
    if (statusEl) statusEl.textContent = 'Print failed';
  }
}

// Handle print with dialog
async function handlePrintWithDialog() {
  if (!printerState.selectedFilePath) {
    showToast('Please select an image first', 'error');
    return;
  }

  const statusEl = document.getElementById('printerPrintStatus');
  if (statusEl) statusEl.textContent = 'Opening print dialog...';

  try {
    const result = await printStation.printer.printWithDialog({
      imagePath: printerState.selectedFilePath
    });

    if (result.success) {
      showToast('Print job sent successfully', 'success');
      if (statusEl) statusEl.textContent = 'Print job sent!';
    } else {
      if (statusEl) statusEl.textContent = result.error || 'Print cancelled';
    }
  } catch (error) {
    console.error('[Printer] Print dialog error:', error);
    showToast('Print failed: ' + error.message, 'error');
    if (statusEl) statusEl.textContent = 'Print failed';
  }
}

// Handle save as PDF
async function handleSavePdf() {
  if (!printerState.selectedFilePath) {
    showToast('Please select an image first', 'error');
    return;
  }

  const statusEl = document.getElementById('printerPrintStatus');

  try {
    // Get save location
    const saveResult = await printStation.printer.savePdfDialog();
    if (!saveResult.success) {
      if (statusEl && !saveResult.canceled) statusEl.textContent = 'Save cancelled';
      return;
    }

    if (statusEl) statusEl.textContent = 'Generating PDF...';

    const settings = getPrintSettings();
    const result = await printStation.printer.printToPdf({
      imagePath: printerState.selectedFilePath,
      savePath: saveResult.path,
      landscape: settings.orientation === 'Landscape' ||
        (settings.orientation === 'Auto' &&
         document.getElementById('printerPreviewImage')?.naturalWidth >
         document.getElementById('printerPreviewImage')?.naturalHeight),
      pageSize: settings.paperSize === 'Custom' ? 'Letter' : settings.paperSize
    });

    if (result.success) {
      showToast('PDF saved successfully', 'success');
      if (statusEl) statusEl.textContent = `PDF saved: ${saveResult.path}`;
    } else {
      showToast(`Failed to save PDF: ${result.error}`, 'error');
      if (statusEl) statusEl.textContent = 'Save failed';
    }
  } catch (error) {
    console.error('[Printer] Save PDF error:', error);
    showToast('Failed to save PDF: ' + error.message, 'error');
    if (statusEl) statusEl.textContent = 'Save failed';
  }
}

// Simple debounce helper
function debounce(fn, delay) {
  let timeout;
  return function (...args) {
    clearTimeout(timeout);
    timeout = setTimeout(() => fn.apply(this, args), delay);
  };
}

// ============================================================================
// PRINTER ARTWORK DATABASE BROWSER
// ============================================================================

const printerArtworkState = {
  artwork: [],
  categories: [],
  currentPage: 1,
  totalPages: 1,
  pageSize: 50,
  searchQuery: '',
  selectedCategory: '',
  handlersInitialized: false
};

// Initialize artwork browser handlers
function initPrinterArtworkHandlers() {
  if (printerArtworkState.handlersInitialized) return;

  console.log('[Printer] Initializing artwork handlers');

  // Tab switching
  const tabFile = document.getElementById('printerTabFile');
  const tabArtwork = document.getElementById('printerTabArtwork');
  const fileTab = document.getElementById('printerFileTab');
  const artworkTab = document.getElementById('printerArtworkTab');

  if (tabFile && tabArtwork) {
    tabFile.addEventListener('click', () => {
      tabFile.dataset.active = 'true';
      tabArtwork.dataset.active = 'false';
      tabFile.classList.add('primary');
      tabFile.classList.remove('secondary');
      tabArtwork.classList.add('secondary');
      tabArtwork.classList.remove('primary');
      if (fileTab) fileTab.style.display = 'block';
      if (artworkTab) artworkTab.style.display = 'none';
    });

    tabArtwork.addEventListener('click', () => {
      tabArtwork.dataset.active = 'true';
      tabFile.dataset.active = 'false';
      tabArtwork.classList.add('primary');
      tabArtwork.classList.remove('secondary');
      tabFile.classList.add('secondary');
      tabFile.classList.remove('primary');
      if (fileTab) fileTab.style.display = 'none';
      if (artworkTab) artworkTab.style.display = 'block';

      // Load artwork if not loaded yet
      if (printerArtworkState.artwork.length === 0) {
        loadPrinterArtwork();
      }
    });
  }

  // Search input
  const searchInput = document.getElementById('printerArtworkSearch');
  if (searchInput) {
    searchInput.addEventListener('input', debounce(() => {
      printerArtworkState.searchQuery = searchInput.value;
      printerArtworkState.currentPage = 1;
      loadPrinterArtwork();
    }, 300));
  }

  // Category filter
  const categorySelect = document.getElementById('printerArtworkCategory');
  if (categorySelect) {
    categorySelect.addEventListener('change', () => {
      printerArtworkState.selectedCategory = categorySelect.value;
      printerArtworkState.currentPage = 1;
      loadPrinterArtwork();
    });
  }

  // Refresh button
  const refreshBtn = document.getElementById('printerArtworkRefresh');
  if (refreshBtn) {
    refreshBtn.addEventListener('click', () => {
      loadPrinterArtwork();
    });
  }

  // Pagination - Previous
  const prevBtn = document.getElementById('printerArtworkPrev');
  if (prevBtn) {
    prevBtn.addEventListener('click', () => {
      if (printerArtworkState.currentPage > 1) {
        printerArtworkState.currentPage--;
        loadPrinterArtwork();
      }
    });
  }

  // Pagination - Next
  const nextBtn = document.getElementById('printerArtworkNext');
  if (nextBtn) {
    nextBtn.addEventListener('click', () => {
      if (printerArtworkState.currentPage < printerArtworkState.totalPages) {
        printerArtworkState.currentPage++;
        loadPrinterArtwork();
      }
    });
  }

  printerArtworkState.handlersInitialized = true;
}

// Load artwork from database
async function loadPrinterArtwork() {
  const grid = document.getElementById('printerArtworkGrid');
  const pageInfo = document.getElementById('printerArtworkPageInfo');
  const prevBtn = document.getElementById('printerArtworkPrev');
  const nextBtn = document.getElementById('printerArtworkNext');

  if (!grid) return;

  grid.innerHTML = '<div style="color:#999;text-align:center;grid-column:1/-1;padding:20px;">Loading artwork...</div>';

  try {
    // Build query params
    const params = {
      limit: printerArtworkState.pageSize,
      offset: (printerArtworkState.currentPage - 1) * printerArtworkState.pageSize
    };

    if (printerArtworkState.searchQuery) {
      params.search = printerArtworkState.searchQuery;
    }

    if (printerArtworkState.selectedCategory) {
      params.category = printerArtworkState.selectedCategory;
    }

    const result = await printStation.customArt.listArtwork(params);

    if (!result.success) {
      grid.innerHTML = `<div style="color:#ef4444;text-align:center;grid-column:1/-1;padding:20px;">Error: ${result.error || 'Failed to load artwork'}</div>`;
      return;
    }

    const artwork = result.artwork || [];
    printerArtworkState.artwork = artwork;
    printerArtworkState.totalPages = Math.ceil((result.total || artwork.length) / printerArtworkState.pageSize);

    // Load categories if not loaded
    if (printerArtworkState.categories.length === 0) {
      loadPrinterArtworkCategories();
    }

    // Update pagination
    if (pageInfo) {
      pageInfo.textContent = `Page ${printerArtworkState.currentPage} of ${printerArtworkState.totalPages}`;
    }
    if (prevBtn) {
      prevBtn.disabled = printerArtworkState.currentPage <= 1;
    }
    if (nextBtn) {
      nextBtn.disabled = printerArtworkState.currentPage >= printerArtworkState.totalPages;
    }

    if (artwork.length === 0) {
      grid.innerHTML = '<div style="color:#999;text-align:center;grid-column:1/-1;padding:20px;">No artwork found</div>';
      return;
    }

    // Render artwork grid
    grid.innerHTML = artwork.map(art => {
      const thumbnailUrl = art.thumbnailPath
        ? `file://${art.thumbnailPath.replace(/\\/g, '/')}`
        : (art.filePath ? `file://${art.filePath.replace(/\\/g, '/')}` : '');

      return `
        <div class="printer-artwork-item" data-path="${art.filePath || ''}" data-name="${art.name || art.title || 'Artwork'}"
             style="border:2px solid #ddd;border-radius:8px;padding:4px;cursor:pointer;transition:all 0.2s;background:#fff;"
             onmouseover="this.style.borderColor='#3b82f6';this.style.transform='scale(1.02)'"
             onmouseout="this.style.borderColor='#ddd';this.style.transform='scale(1)'">
          <img src="${thumbnailUrl}" alt="${art.name || ''}"
               style="width:100%;height:80px;object-fit:contain;background:#f5f5f5;border-radius:4px;"
               onerror="this.src='data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 width=%2280%22 height=%2280%22><rect fill=%22%23f0f0f0%22 width=%22100%25%22 height=%22100%25%22/><text x=%2250%25%22 y=%2250%25%22 text-anchor=%22middle%22 dy=%22.3em%22 fill=%22%23999%22>No Image</text></svg>'">
          <div style="font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:4px;color:#333;" title="${art.name || art.title || ''}">
            ${art.name || art.title || 'Untitled'}
          </div>
        </div>
      `;
    }).join('');

    // Add click handlers
    grid.querySelectorAll('.printer-artwork-item').forEach(item => {
      item.addEventListener('click', () => {
        selectPrinterArtwork(item.dataset.path, item.dataset.name);
      });
    });

    console.log('[Printer] Loaded', artwork.length, 'artwork items');

  } catch (error) {
    console.error('[Printer] Error loading artwork:', error);
    grid.innerHTML = `<div style="color:#ef4444;text-align:center;grid-column:1/-1;padding:20px;">Error: ${error.message}</div>`;
  }
}

// Load artwork categories
async function loadPrinterArtworkCategories() {
  const categorySelect = document.getElementById('printerArtworkCategory');
  if (!categorySelect) return;

  try {
    const result = await printStation.customArt.getArtworkCategories();

    if (result.success && result.categories) {
      printerArtworkState.categories = result.categories;

      categorySelect.innerHTML = '<option value="">All Categories</option>' +
        result.categories.map(cat => `<option value="${cat}">${cat}</option>`).join('');
    }
  } catch (error) {
    console.error('[Printer] Error loading categories:', error);
  }
}

// Select artwork for printing
function selectPrinterArtwork(filePath, name) {
  if (!filePath) {
    showToast('This artwork has no file path', 'error');
    return;
  }

  console.log('[Printer] Selected artwork:', filePath);

  // Get file size (approximate from path)
  const fs = window.require ? window.require('fs') : null;
  let fileSize = 0;

  // Use the handleFileSelected function to update UI
  handleFileSelected({
    success: true,
    path: filePath,
    name: name || filePath.split(/[\\/]/).pop(),
    size: fileSize
  });

  // Switch back to file tab to show preview
  const tabFile = document.getElementById('printerTabFile');
  const tabArtwork = document.getElementById('printerTabArtwork');
  const fileTab = document.getElementById('printerFileTab');
  const artworkTab = document.getElementById('printerArtworkTab');

  if (tabFile && tabArtwork) {
    tabFile.dataset.active = 'true';
    tabArtwork.dataset.active = 'false';
    tabFile.classList.add('primary');
    tabFile.classList.remove('secondary');
    tabArtwork.classList.add('secondary');
    tabArtwork.classList.remove('primary');
  }
  if (fileTab) fileTab.style.display = 'block';
  if (artworkTab) artworkTab.style.display = 'none';

  showToast(`Selected: ${name}`, 'success');
}

// Extend initPrinterView to also initialize artwork handlers
const _originalInitPrinterView = initPrinterView;
initPrinterView = async function() {
  await _originalInitPrinterView();
  initPrinterArtworkHandlers();
};

// ============================================================================
// AUTO-UPDATE UI
// ============================================================================

async function initAutoUpdateUI() {
  // Display current version
  const versionLabel = document.getElementById('appVersionLabel');
  if (versionLabel && printStation.update) {
    try {
      const version = await printStation.update.getVersion();
      versionLabel.textContent = version || 'Unknown';
    } catch (e) {
      versionLabel.textContent = 'Unknown';
    }
  }

  // Check for updates button
  const checkUpdatesBtn = document.getElementById('checkForUpdatesBtn');
  if (checkUpdatesBtn && printStation.update) {
    checkUpdatesBtn.addEventListener('click', async () => {
      // If update already downloaded, just install
      try {
        const currentStatus = await printStation.update.getStatus();
        if (currentStatus && currentStatus.downloaded) {
          showToast(`Update v${currentStatus.version} already downloaded. Restarting...`, 'success');
          setTimeout(() => printStation.update.install(), 1000);
          return;
        }
      } catch (e) { /* continue with check */ }

      checkUpdatesBtn.textContent = 'Checking...';
      checkUpdatesBtn.disabled = true;

      try {
        const result = await printStation.update.check();
        if (result.success && result.updateInfo) {
          showToast(`Update v${result.updateInfo.version} found. Downloading...`, 'success');
          checkUpdatesBtn.textContent = 'Downloading...';
          // Don't re-enable button — download in progress, status listener will update UI
          return;
        } else if (result.success) {
          showToast('You have the latest version', 'info');
        } else {
          showToast(`Update check failed: ${result.error}`, 'error');
        }
      } catch (e) {
        showToast('Could not check for updates', 'error');
      }

      checkUpdatesBtn.textContent = 'Check for Updates';
      checkUpdatesBtn.disabled = false;
    });
  }

  // Listen for update status changes (from main process)
  if (printStation.update?.onStatusChange) {
    printStation.update.onStatusChange((status) => {
      console.log('[Update] Status changed:', status);
      const btn = document.getElementById('checkForUpdatesBtn');

      if (status.error) {
        showToast(`Update error: ${status.error}`, 'error');
        if (btn) { btn.textContent = 'Check for Updates'; btn.disabled = false; }
      } else if (status.downloading && status.progress) {
        const percent = status.progress.percent?.toFixed(0) || 0;
        if (btn) { btn.textContent = `Downloading ${percent}%`; btn.disabled = true; }
      } else if (status.downloaded && status.version) {
        showToast(`Update v${status.version} ready. Restart to install.`, 'success');
        if (btn) { btn.textContent = 'Restart to Update'; btn.disabled = false; }
      }
    });
  }
}

// Initialize auto-update UI after a short delay
setTimeout(initAutoUpdateUI, 2000);

// ============================================================================
// TIKTOK SHOP MANAGER
// ============================================================================

const tiktokShopState = {
  initialized: false,
  activeTab: 'published', // 'published' or 'candidates'
  products: [],           // Currently on TikTok
  candidates: [],         // Available to add
  selectedProduct: null,  // Currently viewing in detail
  selectedIds: new Set(), // For bulk operations
  publicationId: null,
  loading: false
};

function debounce_tts(fn, ms) {
  let t;
  return (...args) => { clearTimeout(t); t = setTimeout(() => fn(...args), ms); };
}

async function initTikTokShopManager() {
  if (tiktokShopState.initialized && tiktokShopState.products.length > 0) return;

  if (!tiktokShopState.initialized) {
    tiktokShopState.initialized = true;

    // Source filter
    const sourceFilter = document.getElementById('tiktokShopSourceFilter');
    if (sourceFilter) sourceFilter.addEventListener('change', renderTikTokProductList);

    // Search
    const search = document.getElementById('tiktokShopSearch');
    if (search) search.addEventListener('input', debounce_tts(renderTikTokProductList, 300));

    // Refresh
    const refreshBtn = document.getElementById('tiktokShopRefreshBtn');
    if (refreshBtn) refreshBtn.addEventListener('click', () => loadTikTokShopData(true));

    // Clear All
    const clearBtn = document.getElementById('tiktokShopClearAllBtn');
    if (clearBtn) clearBtn.addEventListener('click', handleTikTokClearAll);

    // Select All
    const selectAll = document.getElementById('tiktokShopSelectAll');
    if (selectAll) selectAll.addEventListener('change', (e) => {
      const items = document.querySelectorAll('.tiktok-product-item');
      items.forEach(item => {
        const cb = item.querySelector('.tiktok-select-cb');
        if (cb) cb.checked = e.target.checked;
        const id = item.dataset.productId;
        if (id) {
          if (e.target.checked) tiktokShopState.selectedIds.add(id);
          else tiktokShopState.selectedIds.delete(id);
        }
      });
      updateTikTokBulkBar();
    });

    // Tabs
    document.getElementById('tiktokTabPublished')?.addEventListener('click', () => {
      tiktokShopState.activeTab = 'published';
      document.getElementById('tiktokTabPublished').classList.add('active');
      document.getElementById('tiktokTabCandidates').classList.remove('active');
      renderTikTokProductList();
    });
    document.getElementById('tiktokTabCandidates')?.addEventListener('click', () => {
      tiktokShopState.activeTab = 'candidates';
      document.getElementById('tiktokTabCandidates').classList.add('active');
      document.getElementById('tiktokTabPublished').classList.remove('active');
      renderTikTokProductList();
    });

    // Bulk actions
    document.getElementById('tiktokShopBulkPublishBtn')?.addEventListener('click', handleTikTokBulkPublish);
    document.getElementById('tiktokShopBulkUnpublishBtn')?.addEventListener('click', handleTikTokBulkUnpublish);
    document.getElementById('tiktokShopBulkScriptBtn')?.addEventListener('click', handleTikTokBulkScript);

    // Detail panel buttons
    document.getElementById('tiktokShopDetailPublishBtn')?.addEventListener('click', handleTikTokDetailPublish);
    document.getElementById('tiktokShopDetailUnpublishBtn')?.addEventListener('click', handleTikTokDetailUnpublish);
    document.getElementById('tiktokShopGenerateScriptBtn')?.addEventListener('click', handleTikTokGenerateScript);
    document.getElementById('tiktokShopResearchBtn')?.addEventListener('click', handleTikTokResearch);
  }

  await loadTikTokShopData();
}

function setTikTokStatus(msg, type) {
  const el = document.getElementById('tiktokShopStatus');
  if (el) {
    el.textContent = msg;
    el.className = 'catalog-status ' + (type === 'error' ? 'danger' : type === 'success' ? 'success' : 'muted');
  }
}

async function loadTikTokShopData(force) {
  if (tiktokShopState.loading && !force) return;
  tiktokShopState.loading = true;
  setTikTokStatus('Loading...', 'info');

  try {
    // Load products and stats in parallel
    const [productsRes, statsRes, candidatesRes] = await Promise.all([
      printStation.tiktokShop.getProducts(),
      printStation.tiktokShop.getStats(),
      printStation.tiktokShop.getCandidates('all')
    ]);

    if (productsRes?.success && productsRes.data) {
      tiktokShopState.products = productsRes.data.products || [];
      tiktokShopState.publicationId = productsRes.data.publicationId || null;
    }

    if (candidatesRes?.success && candidatesRes.data) {
      tiktokShopState.candidates = candidatesRes.data.candidates || [];
    }

    // Update capacity badge
    if (statsRes?.success && statsRes.data) {
      const cap = statsRes.data.capacity || {};
      const badge = document.getElementById('tiktokShopCapacity');
      if (badge) {
        badge.textContent = `${cap.current || 0}/100`;
        badge.className = 'badge' + ((cap.current || 0) >= 90 ? ' warning' : ' success');
      }
    }

    setTikTokStatus(`${tiktokShopState.products.length} on TikTok, ${tiktokShopState.candidates.length} candidates`, 'success');
    renderTikTokProductList();
  } catch (e) {
    setTikTokStatus('Error: ' + (e.message || e), 'error');
  } finally {
    tiktokShopState.loading = false;
  }
}

function renderTikTokProductList() {
  const container = document.getElementById('tiktokShopProductList');
  if (!container) return;

  const search = (document.getElementById('tiktokShopSearch')?.value || '').toLowerCase();
  const sourceFilter = document.getElementById('tiktokShopSourceFilter')?.value || 'all';
  const isPublished = tiktokShopState.activeTab === 'published';

  let items = isPublished ? tiktokShopState.products : tiktokShopState.candidates;

  // Apply search filter
  if (search) {
    items = items.filter(p => (p.title || '').toLowerCase().includes(search) || (p.handle || '').toLowerCase().includes(search));
  }

  // Apply source filter
  if (sourceFilter === 'multiboard') items = items.filter(p => p.source === 'multiboard');
  else if (sourceFilter === 'metal') items = items.filter(p => p.source === 'metal');
  else if (sourceFilter === 'published') items = isPublished ? items : [];
  else if (sourceFilter === 'unpublished') items = isPublished ? [] : items;

  // Update count
  const countEl = document.getElementById('tiktokShopCount');
  if (countEl) countEl.textContent = items.length;

  if (!items.length) {
    container.innerHTML = `<p class="placeholder">${isPublished ? 'No products on TikTok Shop' : 'No candidate products found'}</p>`;
    return;
  }

  container.innerHTML = items.map(p => {
    const isSelected = tiktokShopState.selectedIds.has(p.numericId || p.id);
    const sourceBadge = p.source === 'multiboard' ? 'multiboard' : p.source === 'metal' ? 'metal' : 'other';
    const sourceLabel = p.source === 'multiboard' ? 'Multiboard' : p.source === 'metal' ? 'Metal' : 'Other';
    const price = p.minPrice ? `$${parseFloat(p.minPrice).toFixed(2)}` : (p.price ? `$${p.price}` : '');
    const thumb = p.image ? `<img class="product-thumb" src="${p.image}" alt="" />` : `<div class="product-thumb" style="display:flex;align-items:center;justify-content:center;font-size:16px;color:var(--muted);">?</div>`;

    return `
      <div class="tiktok-product-item${isSelected ? ' selected' : ''}" data-product-id="${p.numericId || p.id}" data-source="${p.source || 'other'}">
        <input type="checkbox" class="tiktok-select-cb" ${isSelected ? 'checked' : ''} />
        ${thumb}
        <div class="product-info">
          <div class="product-title">${escapeHtml(p.title || 'Untitled')}</div>
          <div class="product-meta">${price} ${p.productType ? '&middot; ' + escapeHtml(p.productType) : ''}</div>
        </div>
        <span class="source-badge ${sourceBadge}">${sourceLabel}</span>
        ${isPublished ? '<span class="badge success" style="font-size:10px;">LIVE</span>' : '<span class="badge" style="font-size:10px;">Available</span>'}
      </div>
    `;
  }).join('');

  // Attach click handlers
  container.querySelectorAll('.tiktok-product-item').forEach(item => {
    item.addEventListener('click', (e) => {
      if (e.target.type === 'checkbox') {
        const id = item.dataset.productId;
        if (e.target.checked) tiktokShopState.selectedIds.add(id);
        else tiktokShopState.selectedIds.delete(id);
        item.classList.toggle('selected', e.target.checked);
        updateTikTokBulkBar();
        return;
      }
      selectTikTokProduct(item.dataset.productId);
    });
  });
}

function updateTikTokBulkBar() {
  const bar = document.getElementById('tiktokShopBulkBar');
  const count = tiktokShopState.selectedIds.size;
  if (bar) {
    bar.style.display = count > 0 ? 'flex' : 'none';
    const countEl = document.getElementById('tiktokShopSelectedCount');
    if (countEl) countEl.textContent = `${count} selected`;
  }
}

function selectTikTokProduct(productId) {
  const isPublished = tiktokShopState.activeTab === 'published';
  const list = isPublished ? tiktokShopState.products : tiktokShopState.candidates;
  const product = list.find(p => (p.numericId || p.id) === productId);
  if (!product) return;

  tiktokShopState.selectedProduct = product;

  // Show detail panel
  document.getElementById('tiktokShopDetailPlaceholder').style.display = 'none';
  document.getElementById('tiktokShopProductInfo').style.display = 'block';

  // Fill in product info
  const img = document.getElementById('tiktokShopDetailImage');
  if (img) { img.src = product.image || ''; img.style.display = product.image ? 'block' : 'none'; }

  const title = document.getElementById('tiktokShopDetailTitle');
  if (title) title.textContent = product.title || 'Untitled';

  const source = document.getElementById('tiktokShopDetailSource');
  if (source) {
    const src = product.source || 'other';
    source.textContent = src === 'multiboard' ? 'Multiboard' : src === 'metal' ? 'Metal Print' : 'Other';
    source.className = 'badge source-badge ' + (src === 'multiboard' ? 'multiboard' : src === 'metal' ? 'metal' : 'other');
  }

  const status = document.getElementById('tiktokShopDetailStatus');
  if (status) {
    status.textContent = isPublished ? 'LIVE on TikTok' : 'Not Published';
    status.className = isPublished ? 'badge success' : 'badge';
  }

  const price = document.getElementById('tiktokShopDetailPrice');
  if (price) {
    const p = product.minPrice || product.price;
    price.textContent = p ? `$${parseFloat(p).toFixed(2)}` : '';
  }

  // Toggle publish/unpublish buttons
  document.getElementById('tiktokShopDetailPublishBtn').style.display = isPublished ? 'none' : 'inline-block';
  document.getElementById('tiktokShopDetailUnpublishBtn').style.display = isPublished ? 'inline-block' : 'none';

  // Show existing script/research
  renderTikTokScript(product.videoScript);
  renderTikTokResearch(product.marketResearch);

  // Highlight in list
  document.querySelectorAll('.tiktok-product-item').forEach(el => {
    el.style.outline = el.dataset.productId === productId ? '2px solid var(--accent)' : 'none';
  });
}

function renderTikTokScript(scriptData) {
  const container = document.getElementById('tiktokShopScriptContent');
  if (!container) return;

  let script = scriptData;
  if (typeof script === 'string') {
    try { script = JSON.parse(script); } catch (_) { script = null; }
  }

  if (!script || script.raw) {
    container.innerHTML = script?.raw
      ? `<pre style="font-size:12px;white-space:pre-wrap;color:var(--text);">${escapeHtml(script.raw)}</pre>`
      : '<p class="placeholder" style="font-size:13px;">No script generated yet. Click "Generate Script" to create one.</p>';
    return;
  }

  let html = '';

  if (script.hook) {
    html += `<div class="script-section"><div class="script-section-label">Hook</div><div class="script-section-content">${escapeHtml(script.hook)}</div></div>`;
  }

  if (Array.isArray(script.scenes)) {
    html += '<div class="script-section"><div class="script-section-label">Scenes</div>';
    script.scenes.forEach((s, i) => {
      html += `<div class="script-scene">
        <div class="script-scene-duration">${escapeHtml(s.duration || `Scene ${i + 1}`)}</div>
        ${s.visual ? `<div style="margin-top:4px;"><strong>Visual:</strong> ${escapeHtml(s.visual)}</div>` : ''}
        ${s.text ? `<div><strong>Text:</strong> ${escapeHtml(s.text)}</div>` : ''}
        ${s.action ? `<div style="color:var(--muted);font-size:12px;"><em>${escapeHtml(s.action)}</em></div>` : ''}
      </div>`;
    });
    html += '</div>';
  }

  if (script.cta) {
    html += `<div class="script-section"><div class="script-section-label">Call to Action</div><div class="script-section-content">${escapeHtml(script.cta)}</div></div>`;
  }

  if (script.music) {
    html += `<div class="script-section"><div class="script-section-label">Music</div><div class="script-section-content">${escapeHtml(script.music)}</div></div>`;
  }

  if (Array.isArray(script.hashtags) && script.hashtags.length) {
    html += '<div class="script-section"><div class="script-section-label">Hashtags</div><div>';
    script.hashtags.forEach(h => { html += `<span class="script-hashtag">#${escapeHtml(h.replace(/^#/, ''))}</span>`; });
    html += '</div></div>';
  }

  if (script.estimatedLength) {
    html += `<div class="script-section"><div class="script-section-label">Duration</div><div class="script-section-content">${escapeHtml(script.estimatedLength)}</div></div>`;
  }

  if (script.notes) {
    html += `<div class="script-section"><div class="script-section-label">Notes</div><div class="script-section-content" style="color:var(--muted);">${escapeHtml(script.notes)}</div></div>`;
  }

  container.innerHTML = html;
}

function renderTikTokResearch(researchData) {
  const container = document.getElementById('tiktokShopResearchContent');
  if (!container) return;

  let research = researchData;
  if (typeof research === 'string') {
    try { research = JSON.parse(research); } catch (_) { research = null; }
  }

  if (!research || research.raw) {
    container.innerHTML = research?.raw
      ? `<pre style="font-size:12px;white-space:pre-wrap;color:var(--text);">${escapeHtml(research.raw)}</pre>`
      : '<p class="placeholder" style="font-size:13px;">No research yet. Click "Research" to analyze this product category.</p>';
    return;
  }

  let html = '';

  if (Array.isArray(research.trendingStyles) && research.trendingStyles.length) {
    html += '<div class="research-section"><div class="research-section-title">Trending Styles</div>';
    research.trendingStyles.forEach(s => { html += `<div class="research-item">${escapeHtml(s)}</div>`; });
    html += '</div>';
  }

  if (research.competitorInsights) {
    html += `<div class="research-section"><div class="research-section-title">Competitor Insights</div><div class="research-item">${escapeHtml(research.competitorInsights)}</div></div>`;
  }

  if (research.pricingBenchmark) {
    const pb = research.pricingBenchmark;
    html += `<div class="research-section"><div class="research-section-title">Pricing</div>
      <div class="research-item">Low: ${escapeHtml(pb.low || '?')} | Mid: ${escapeHtml(pb.mid || '?')} | High: ${escapeHtml(pb.high || '?')}</div>
      ${pb.recommendation ? `<div class="research-item" style="color:var(--accent);">${escapeHtml(pb.recommendation)}</div>` : ''}
    </div>`;
  }

  if (Array.isArray(research.contentStrategy)) {
    html += '<div class="research-section"><div class="research-section-title">Content Strategy</div>';
    research.contentStrategy.forEach(c => {
      html += `<div class="research-item"><strong>${escapeHtml(c.type || '')}:</strong> ${escapeHtml(c.description || '')} (${escapeHtml(c.frequency || '')})</div>`;
    });
    html += '</div>';
  }

  if (Array.isArray(research.hashtags) && research.hashtags.length) {
    html += '<div class="research-section"><div class="research-section-title">Hashtags</div><div>';
    research.hashtags.forEach(h => { html += `<span class="script-hashtag">#${escapeHtml(h.replace(/^#/, ''))}</span>`; });
    html += '</div></div>';
  }

  if (research.audienceInsights) {
    const ai = research.audienceInsights;
    html += '<div class="research-section"><div class="research-section-title">Audience</div>';
    if (ai.demographics) html += `<div class="research-item"><strong>Demographics:</strong> ${escapeHtml(ai.demographics)}</div>`;
    if (ai.peakTimes) html += `<div class="research-item"><strong>Peak Times:</strong> ${escapeHtml(ai.peakTimes)}</div>`;
    if (ai.interests) html += `<div class="research-item"><strong>Interests:</strong> ${escapeHtml(ai.interests)}</div>`;
    html += '</div>';
  }

  if (research.viralPotential) {
    html += `<div class="research-section"><div class="research-section-title">Viral Potential</div><div class="research-item">${escapeHtml(research.viralPotential)}</div></div>`;
  }

  if (Array.isArray(research.recommendations)) {
    html += '<div class="research-section"><div class="research-section-title">Recommendations</div>';
    research.recommendations.forEach(r => { html += `<div class="research-item">${escapeHtml(r)}</div>`; });
    html += '</div>';
  }

  container.innerHTML = html;
}

// --- TikTok Shop Action Handlers ---

async function handleTikTokClearAll() {
  const confirmed = await printStation.showConfirm('This will remove ALL products from TikTok Shop. Are you sure?', 'Clear TikTok Shop');
  if (!confirmed) return;

  setTikTokStatus('Clearing all products...', 'info');
  try {
    const res = await printStation.tiktokShop.clearAll();
    if (res?.success) {
      setTikTokStatus(`Cleared ${res.data?.removed || 0} products`, 'success');
      await loadTikTokShopData(true);
    } else {
      setTikTokStatus('Error: ' + (res?.error || 'Unknown'), 'error');
    }
  } catch (e) {
    setTikTokStatus('Error: ' + e.message, 'error');
  }
}

async function handleTikTokDetailPublish() {
  const p = tiktokShopState.selectedProduct;
  if (!p) return;
  setTikTokStatus('Publishing...', 'info');
  try {
    const res = await printStation.tiktokShop.publish(p.numericId || p.id, p.source);
    if (res?.success) {
      setTikTokStatus('Published!', 'success');
      await loadTikTokShopData(true);
    } else {
      setTikTokStatus('Error: ' + (res?.error || 'Unknown'), 'error');
    }
  } catch (e) {
    setTikTokStatus('Error: ' + e.message, 'error');
  }
}

async function handleTikTokDetailUnpublish() {
  const p = tiktokShopState.selectedProduct;
  if (!p) return;
  setTikTokStatus('Unpublishing...', 'info');
  try {
    const res = await printStation.tiktokShop.unpublish(p.numericId || p.id);
    if (res?.success) {
      setTikTokStatus('Unpublished!', 'success');
      await loadTikTokShopData(true);
    } else {
      setTikTokStatus('Error: ' + (res?.error || 'Unknown'), 'error');
    }
  } catch (e) {
    setTikTokStatus('Error: ' + e.message, 'error');
  }
}

async function handleTikTokBulkPublish() {
  const ids = Array.from(tiktokShopState.selectedIds);
  if (!ids.length) return;
  setTikTokStatus(`Publishing ${ids.length} products...`, 'info');
  try {
    const res = await printStation.tiktokShop.bulkPublish(ids);
    if (res?.success) {
      setTikTokStatus(`Published ${res.data?.published || 0}/${ids.length}`, 'success');
      tiktokShopState.selectedIds.clear();
      updateTikTokBulkBar();
      await loadTikTokShopData(true);
    } else {
      setTikTokStatus('Error: ' + (res?.error || 'Unknown'), 'error');
    }
  } catch (e) {
    setTikTokStatus('Error: ' + e.message, 'error');
  }
}

async function handleTikTokBulkUnpublish() {
  const ids = Array.from(tiktokShopState.selectedIds);
  if (!ids.length) return;
  setTikTokStatus(`Unpublishing ${ids.length} products...`, 'info');
  try {
    for (const id of ids) {
      await printStation.tiktokShop.unpublish(id);
    }
    setTikTokStatus(`Unpublished ${ids.length} products`, 'success');
    tiktokShopState.selectedIds.clear();
    updateTikTokBulkBar();
    await loadTikTokShopData(true);
  } catch (e) {
    setTikTokStatus('Error: ' + e.message, 'error');
  }
}

async function handleTikTokBulkScript() {
  const ids = Array.from(tiktokShopState.selectedIds);
  if (!ids.length) return;
  setTikTokStatus(`Generating scripts for ${ids.length} products...`, 'info');
  try {
    let done = 0;
    const allProducts = [...tiktokShopState.products, ...tiktokShopState.candidates];
    for (const id of ids) {
      const p = allProducts.find(x => (x.numericId || x.id) === id);
      if (p) {
        await printStation.tiktokShop.generateScript({
          productId: id,
          title: p.title,
          productType: p.productType,
          source: p.source,
          price: p.minPrice || p.price
        });
        done++;
        setTikTokStatus(`Generated ${done}/${ids.length} scripts...`, 'info');
      }
    }
    setTikTokStatus(`Generated ${done} scripts`, 'success');
    await loadTikTokShopData(true);
  } catch (e) {
    setTikTokStatus('Error: ' + e.message, 'error');
  }
}

async function handleTikTokGenerateScript() {
  const p = tiktokShopState.selectedProduct;
  if (!p) return;
  setTikTokStatus('Generating video script...', 'info');
  document.getElementById('tiktokShopScriptContent').innerHTML = '<p class="placeholder" style="font-size:13px;">Generating script...</p>';
  try {
    const res = await printStation.tiktokShop.generateScript({
      productId: p.numericId || p.id,
      title: p.title,
      productType: p.productType,
      source: p.source,
      price: p.minPrice || p.price
    });
    if (res?.success && res.data?.script) {
      renderTikTokScript(res.data.script);
      p.videoScript = res.data.script;
      setTikTokStatus('Script generated!', 'success');
    } else {
      setTikTokStatus('Error: ' + (res?.error || 'Unknown'), 'error');
    }
  } catch (e) {
    setTikTokStatus('Error: ' + e.message, 'error');
  }
}

async function handleTikTokResearch() {
  const p = tiktokShopState.selectedProduct;
  if (!p) return;
  setTikTokStatus('Researching market...', 'info');
  document.getElementById('tiktokShopResearchContent').innerHTML = '<p class="placeholder" style="font-size:13px;">Analyzing market...</p>';
  try {
    const res = await printStation.tiktokShop.marketResearch({
      productId: p.numericId || p.id,
      title: p.title,
      productType: p.productType,
      source: p.source,
      category: p.productType || p.source
    });
    if (res?.success && res.data?.research) {
      renderTikTokResearch(res.data.research);
      p.marketResearch = res.data.research;
      setTikTokStatus('Research complete!', 'success');
    } else {
      setTikTokStatus('Error: ' + (res?.error || 'Unknown'), 'error');
    }
  } catch (e) {
    setTikTokStatus('Error: ' + e.message, 'error');
  }
}

// =============== AI Sales Agent Dashboard ===============

let aiAgentInitialized = false;

async function aiAgentFetch(endpoint) {
  const serverUrl = window.APP_CONFIG?.serverUrl || 'https://store.swayzecustomvinyl.com';
  const res = await fetch(`${serverUrl}/api/agent/${endpoint}`, {
    headers: { 'x-api-key': window.APP_CONFIG?.internalKey || '' }
  });
  if (!res.ok) throw new Error(`Agent API ${endpoint}: ${res.status}`);
  return res.json();
}

async function aiAgentPost(endpoint, body) {
  const serverUrl = window.APP_CONFIG?.serverUrl || 'https://store.swayzecustomvinyl.com';
  const res = await fetch(`${serverUrl}/api/agent/${endpoint}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-api-key': window.APP_CONFIG?.internalKey || ''
    },
    body: JSON.stringify(body || {})
  });
  if (!res.ok) throw new Error(`Agent API POST ${endpoint}: ${res.status}`);
  return res.json();
}

async function loadAiAgentDashboard() {
  // Wire up buttons once
  if (!aiAgentInitialized) {
    aiAgentInitialized = true;
    const refreshBtn = document.getElementById('aiAgentRefreshBtn');
    const runBtn = document.getElementById('aiAgentRunNowBtn');
    if (refreshBtn) refreshBtn.addEventListener('click', () => loadAiAgentDashboard());
    if (runBtn) runBtn.addEventListener('click', async () => {
      runBtn.disabled = true;
      runBtn.textContent = 'Running...';
      try {
        await aiAgentPost('run');
        await loadAiAgentDashboard();
      } catch (e) {
        console.error('[AI Agent] Run cycle error:', e);
      } finally {
        runBtn.disabled = false;
        runBtn.textContent = 'Run Cycle Now';
      }
    });
  }

  try {
    const [status, engagement, strategy, calendar, categories, approvals, daily] = await Promise.allSettled([
      aiAgentFetch('status'),
      aiAgentFetch('engagement/summary'),
      aiAgentFetch('strategy'),
      aiAgentFetch('calendar'),
      aiAgentFetch('categories'),
      aiAgentFetch('approvals'),
      aiAgentFetch('report/daily')
    ]);

    if (status.status === 'fulfilled') renderAiAgentStatus(status.value);
    if (daily.status === 'fulfilled') renderAiDailyReport(daily.value);
    if (engagement.status === 'fulfilled') renderAiEngagement(engagement.value);
    if (strategy.status === 'fulfilled') renderAiStrategy(strategy.value);
    if (calendar.status === 'fulfilled') renderAiCalendar(calendar.value);
    if (categories.status === 'fulfilled') renderAiCategories(categories.value);
    if (approvals.status === 'fulfilled') renderAiApprovals(approvals.value);
  } catch (e) {
    console.error('[AI Agent] Dashboard load error:', e);
  }
}

function renderAiAgentStatus(data) {
  const indicator = document.getElementById('aiAgentStatusIndicator');
  const label = document.getElementById('aiAgentLastCycleLabel');
  if (indicator) {
    indicator.style.color = data.running ? '#22c55e' : '#94a3b8';
    indicator.title = data.running ? 'Agent running' : 'Agent stopped';
  }
  if (label && data.lastCycleAt) {
    const ago = Math.round((Date.now() - new Date(data.lastCycleAt).getTime()) / 60000);
    label.textContent = ago < 60 ? `Last cycle: ${ago}m ago` : `Last cycle: ${Math.round(ago / 60)}h ago`;
  }
}

function renderAiDailyReport(data) {
  const set = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val ?? '--'; };
  set('aiDailyPostsPublished', data.postsPublished || 0);
  set('aiDailyTotalLikes', data.totalLikes || 0);
  set('aiDailyTotalComments', data.totalComments || 0);
  set('aiDailyTotalShares', data.totalShares || 0);
  set('aiDailyQueueDepth', data.queueDepth || 0);
  set('aiDailyQueueDays', data.queueDays || 0);
}

function renderAiEngagement(data) {
  const tbody = document.getElementById('aiEngagementCategoryBody');
  const windowLabel = document.getElementById('aiEngagementWindow');
  if (windowLabel) windowLabel.textContent = `${data.windowDays || 30}d window`;
  if (!tbody) return;

  const cats = data.byCategory || [];
  if (!cats.length) {
    tbody.innerHTML = '<tr><td colspan="6" style="text-align:center;padding:20px;" class="muted">No engagement data yet</td></tr>';
    return;
  }
  tbody.innerHTML = cats.map(c => `
    <tr style="border-bottom:1px solid var(--border);">
      <td style="padding:8px;font-weight:600;">${escapeHtml(c.product_category || 'Unknown')}</td>
      <td style="text-align:right;padding:8px;">${c.post_count}</td>
      <td style="text-align:right;padding:8px;">${c.avg_weighted_score || c.avg_engagement || 0}</td>
      <td style="text-align:right;padding:8px;">${c.total_likes || 0}</td>
      <td style="text-align:right;padding:8px;">${c.total_comments || 0}</td>
      <td style="text-align:right;padding:8px;">${c.total_shares || 0}</td>
    </tr>
  `).join('');

  // Best times
  const timesEl = document.getElementById('aiBestTimes');
  if (timesEl && data.byHour && data.byHour.length) {
    timesEl.innerHTML = data.byHour.slice(0, 5).map(h =>
      `<span style="display:inline-block;padding:4px 10px;margin:3px;background:var(--surface);border:1px solid var(--border);border-radius:6px;font-size:0.85rem;">${String(h.posted_hour).padStart(2, '0')}:00 <span class="muted">(${h.avg_weighted_score || h.avg_engagement})</span></span>`
    ).join('');
  } else if (timesEl) {
    timesEl.innerHTML = '<span class="muted">Not enough data</span>';
  }
}

function renderAiStrategy(data) {
  const barsEl = document.getElementById('aiWeightBars');
  const decisionsEl = document.getElementById('aiDecisionsList');

  if (barsEl && data.currentWeights) {
    const entries = Object.entries(data.currentWeights);
    if (entries.length) {
      const maxW = Math.max(...entries.map(([_, v]) => v.weight || 0), 1);
      barsEl.innerHTML = entries.map(([name, v]) => {
        const pct = Math.round(((v.weight || 0) / maxW) * 100);
        return `<div style="margin-bottom:6px;">
          <div style="display:flex;justify-content:space-between;font-size:0.8rem;margin-bottom:2px;"><span>${escapeHtml(name)}</span><span>${v.weight || 0}</span></div>
          <div style="background:var(--surface);border-radius:4px;height:8px;overflow:hidden;"><div style="width:${pct}%;height:100%;background:var(--primary);border-radius:4px;"></div></div>
        </div>`;
      }).join('');
    } else {
      barsEl.innerHTML = '<span class="muted">No categories configured</span>';
    }
  }

  if (decisionsEl && data.recentDecisions) {
    if (data.recentDecisions.length) {
      decisionsEl.innerHTML = data.recentDecisions.map(d => {
        const ts = d.timestamp ? new Date(d.timestamp).toLocaleDateString() : '';
        const decisions = d.decisions_json;
        const summary = decisions ? (decisions.summary || JSON.stringify(decisions).slice(0, 120)) : 'No details';
        return `<div style="padding:8px;border-bottom:1px solid var(--border);font-size:0.85rem;">
          <div style="display:flex;justify-content:space-between;"><strong>${escapeHtml(d.strategy_type || 'Decision')}</strong><span class="muted">${ts}</span></div>
          <div class="muted" style="margin-top:4px;">${escapeHtml(String(summary))}</div>
        </div>`;
      }).join('');
    } else {
      decisionsEl.innerHTML = '<span class="muted">No recent decisions</span>';
    }
  }
}

function renderAiCalendar(data) {
  const el = document.getElementById('aiCalendarList');
  if (!el) return;
  const entries = data.data || [];
  if (!entries.length) {
    el.innerHTML = '<div class="muted" style="padding:12px;text-align:center;">No upcoming content planned</div>';
    return;
  }
  el.innerHTML = entries.map(e => {
    const date = e.planned_date || '';
    const time = e.planned_time || '';
    const status = e.status || 'planned';
    const statusColor = status === 'posted' ? '#22c55e' : status === 'failed' ? '#ef4444' : '#94a3b8';
    return `<div style="padding:8px 0;border-bottom:1px solid var(--border);font-size:0.85rem;display:flex;justify-content:space-between;align-items:center;">
      <div>
        <div style="font-weight:600;">${escapeHtml(e.product_category || '')} ${e.caption_style ? '/ ' + escapeHtml(e.caption_style) : ''}</div>
        <div class="muted">${date} ${time}</div>
      </div>
      <span style="color:${statusColor};font-size:0.8rem;text-transform:uppercase;">${escapeHtml(status)}</span>
    </div>`;
  }).join('');
}

function renderAiCategories(data) {
  const el = document.getElementById('aiCategorySettings');
  if (!el) return;
  const cats = data.categories || {};
  const entries = Object.entries(cats);
  if (!entries.length) {
    el.innerHTML = '<span class="muted">No categories configured</span>';
    return;
  }
  el.innerHTML = entries.map(([name, cfg]) => `
    <div style="padding:8px;border-bottom:1px solid var(--border);font-size:0.85rem;display:flex;justify-content:space-between;align-items:center;">
      <div>
        <span style="font-weight:600;">${escapeHtml(name)}</span>
        <span class="muted" style="margin-left:8px;">weight: ${cfg.postingWeight || 0}</span>
      </div>
      <span style="color:${cfg.enabled ? '#22c55e' : '#ef4444'};font-size:0.75rem;text-transform:uppercase;">${cfg.enabled ? 'Enabled' : 'Disabled'}</span>
    </div>
  `).join('');
}

function renderAiApprovals(data) {
  const el = document.getElementById('aiApprovalsList');
  const badge = document.getElementById('aiApprovalCount');
  if (!el) return;
  const items = data.data || [];
  const pending = items.filter(a => a.status === 'pending');

  if (badge) {
    badge.textContent = pending.length;
    badge.style.display = pending.length > 0 ? '' : 'none';
  }

  if (!items.length) {
    el.innerHTML = '<div class="muted" style="padding:12px;text-align:center;">No pending approvals</div>';
    return;
  }
  el.innerHTML = items.slice(0, 10).map(a => {
    const isPending = a.status === 'pending';
    return `<div style="padding:8px;border-bottom:1px solid var(--border);font-size:0.85rem;">
      <div style="display:flex;justify-content:space-between;">
        <span style="font-weight:600;">${escapeHtml(a.description || 'Approval')}</span>
        <span style="color:${isPending ? '#f59e0b' : a.status === 'approved' ? '#22c55e' : '#94a3b8'};font-size:0.75rem;text-transform:uppercase;">${escapeHtml(a.status)}</span>
      </div>
      ${isPending ? `<div style="margin-top:6px;display:flex;gap:6px;">
        <button class="secondary" style="font-size:0.75rem;padding:2px 10px;" onclick="aiAgentApproval('approve_${a.id}')">Approve</button>
        <button class="secondary" style="font-size:0.75rem;padding:2px 10px;" onclick="aiAgentApproval('deny_${a.id}')">Deny</button>
      </div>` : ''}
    </div>`;
  }).join('');
}

async function aiAgentApproval(command) {
  try {
    await aiAgentPost('approval-callback', { command: '/' + command });
    await loadAiAgentDashboard();
  } catch (e) {
    console.error('[AI Agent] Approval error:', e);
  }
}

init();

